#!/usr/bin/env python3
"""
AI-Toolbox — Aron Makkai
Run: python3 ai_toolbox.py
"""
import tkinter as tk
AMGM_LOGO_B64 = ""

# ── ADW-owned RIFE inference script ─────────────────────────────────
# Written next to the cloned Practical-RIFE repo and used INSTEAD of the
# repo's own inference_img.py. Reason, found the hard way: the upstream
# script is a moving target -- its current main HARD-RESIZES any PNG
# input pair to 448x256 before inference (only the EXR path keeps native
# resolution), has no --scale, and no --TTA. Since this app feeds PNG
# temp frames, a fresh clone silently interpolates at 448x256 and the
# app then upscales that back to plate resolution: output that LOOKS
# low-res with no error anywhere. Owning the script makes resolution
# handling deterministic regardless of what upstream does next. It also
# adds the two things the silent-VRAM-softness fight needed all along:
# an explicit --scale plumbed into model.inference() (upstream's own 4K
# guidance is scale 0.5), automatic scale fallback on out-of-memory
# instead of undefined behaviour, and a machine-readable run report
# (output/ADW_RUNINFO.json) so the app can SEE and SAY when a fallback
# happened rather than shipping mysteriously soft frames.
ADW_RIFE_SCRIPT_VERSION = "adw-rife-2"
ADW_RIFE_SCRIPT = r"""# ADW-Toolbox inference script (adw-rife-1) -- managed by ai_toolbox.py
# Do not edit: rewritten automatically whenever the app updates.
import os, sys, json
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import cv2
import torch
import argparse
from torch.nn import functional as F
import warnings
warnings.filterwarnings("ignore")

device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
torch.set_grad_enabled(False)
if torch.cuda.is_available():
    torch.backends.cudnn.enabled = True
    torch.backends.cudnn.benchmark = True

p = argparse.ArgumentParser(description="ADW RIFE pair interpolation")
p.add_argument("--img", dest="img", nargs=2, required=True)
p.add_argument("--exp", default=1, type=int)
p.add_argument("--n-total", dest="n_total", default=None, type=int,
               help="exact output frame count (e.g. 6 for 6x); "
                    "overrides --exp. Falls back to 2**exp if omitted.")
p.add_argument("--model", dest="modelDir", type=str, default="train_log")
p.add_argument("--scale", default=1.0, type=float,
               help="internal flow scale; auto-falls back on OOM")
p.add_argument("--TTA", dest="tta", action="store_true",
               help="average normal + horizontally-flipped inference")
args = p.parse_args()

try:
    try:
        from model.RIFE_HDv2 import Model
        model = Model(); model.load_model(args.modelDir, -1)
    except Exception:
        from train_log.RIFE_HDv3 import Model
        model = Model(); model.load_model(args.modelDir, -1)
except Exception:
    from model.RIFE_HD import Model
    model = Model(); model.load_model(args.modelDir, -1)
ver = getattr(model, "version", 0)
model.eval(); model.device()

def _load(path):
    im = cv2.imread(path, cv2.IMREAD_UNCHANGED)
    if im is None:
        sys.exit(3)
    if im.ndim == 2:
        im = cv2.cvtColor(im, cv2.COLOR_GRAY2BGR)
    if im.shape[2] == 4:
        im = im[:, :, :3]
    div = 65535.0 if im.dtype.itemsize == 2 else 255.0
    t = torch.tensor(im.transpose(2, 0, 1)).to(device).float() / div
    return t.unsqueeze(0)

# NO input resizing, ever -- frames are interpolated at exactly the
# resolution the app supplies. (The whole point of this script.)
img0 = _load(args.img[0])
img1 = _load(args.img[1])
n, c, h, w = img0.shape

def _pad_to(t, m):
    ph = ((h - 1) // m + 1) * m
    pw = ((w - 1) // m + 1) * m
    return F.pad(t, (0, pw - w, 0, ph - h))

def _empty_caches():
    try:
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
    except Exception:
        pass
    try:
        torch.mps.empty_cache()
    except Exception:
        pass

def _infer(a, b, t, s):
    if ver >= 3.9:
        out = model.inference(a, b, t, s)
        if args.tta:
            f = model.inference(torch.flip(a, [3]), torch.flip(b, [3]), t, s)
            out = (out + torch.flip(f, [3])) / 2
    else:
        out = model.inference(a, b, scale=s)
        if args.tta:
            f = model.inference(torch.flip(a, [3]), torch.flip(b, [3]),
                                scale=s)
            out = (out + torch.flip(f, [3])) / 2
    return out

def _generate(s):
    m = max(128, int(128 / s))
    a = _pad_to(img0, m)
    b = _pad_to(img1, m)
    # --n-total gives an EXACT output count (6x = 6 frames total,
    # including the two real ends); falls back to the classic
    # power-of-2 doubling (2**exp) when omitted, unchanged from before.
    total = args.n_total if args.n_total else (2 ** args.exp)
    if ver >= 3.9:
        # The modern (VFI) model takes an arbitrary timestep in [0,1],
        # not just the midpoint -- so any exact total works directly,
        # power-of-2 or not (this is what makes 6x possible at all).
        lst = [a]
        for i in range(total - 1):
            lst.append(_infer(a, b, (i + 1) * 1.0 / total, s))
        lst.append(b)
        return lst
    # Legacy model: only supports recursive midpoint-halving, which can
    # only ever double the count -- there's no way to ask it for a
    # timestep directly. For an exact non-power-of-2 total, generate
    # the smallest sufficient power-of-2 count via the model's own
    # mechanism, then evenly subsample down to exactly total+1 frames
    # (matching the modern path's own convention: total is the number
    # of SEGMENTS the gap is divided into, so the frame count -- both
    # real ends plus the segments between them -- is always total+1,
    # not total) -- a graceful approximation rather than refusing the
    # request outright. Both real ends are always kept.
    import math
    frames_needed = total + 1
    exp_needed = max(1, math.ceil(math.log2(max(2, frames_needed - 1))))
    lst = [a, b]
    for _ in range(exp_needed):
        tmp = []
        for j in range(len(lst) - 1):
            tmp.append(lst[j])
            tmp.append(_infer(lst[j], lst[j + 1], 0.5, s))
        tmp.append(b)
        lst = tmp
    if len(lst) == frames_needed:
        return lst
    idx = [round(i * (len(lst) - 1) / (frames_needed - 1))
           for i in range(frames_needed)]
    return [lst[i] for i in idx]

# OOM ladder: request the asked-for scale; on an out-of-memory error,
# drop to the next lower scale and retry the WHOLE pair rather than
# producing undefined output. Every fallback is recorded in the run
# report so the app can tell the person what happened and why frames
# might look softer -- the exact "degraded output with no indication
# memory was the cause" failure this replaces.
_ladder = []
for _s in (args.scale, 0.5, 0.25):
    if _s <= args.scale and _s not in _ladder and _s >= 0.25:
        _ladder.append(_s)
oom_retries = 0
img_list = None
scale_used = args.scale
for _s in _ladder:
    try:
        img_list = _generate(_s)
        scale_used = _s
        break
    except RuntimeError as e:
        msg = str(e).lower()
        if "out of memory" in msg or ("mps" in msg and "memory" in msg):
            oom_retries += 1
            _empty_caches()
            continue
        raise
if img_list is None:
    sys.exit(4)

if not os.path.exists("output"):
    os.mkdir("output")
for i in range(len(img_list)):
    arr = (img_list[i][0].clamp(0, 1) * 255).byte().cpu().numpy()
    cv2.imwrite("output/img{}.png".format(i),
                arr.transpose(1, 2, 0)[:h, :w])
try:
    with open(os.path.join("output", "ADW_RUNINFO.json"), "w") as fh:
        json.dump({"script": "adw-rife-1", "in_w": w, "in_h": h,
                   "scale_requested": args.scale, "scale_used": scale_used,
                   "tta": bool(args.tta), "oom_retries": oom_retries,
                   "model_version": ver,
                   "frames": len(img_list)}, fh)
except Exception:
    pass
"""


APP_VERSION = "v01"
from tkinter import filedialog, messagebox, ttk
import subprocess, threading, os, shutil, time, tempfile, sys
from datetime import datetime

# ── COLOURS ──────────────────────────────────────────────────────────
BG  = "#0A0A0A"
S   = "#111111"
S2  = "#181818"
BD  = "#242424"
R   = "#A03030"
RB  = "#C04040"
W   = "#DCDCDC"
G   = "#777777"
M   = "#3C3C3C"
GR  = "#4A8A4A"
FS  = ("Helvetica Neue", 11)
FSM = ("Helvetica Neue", 10)
FM  = ("Menlo", 10)

# ── SETUP STEP STATES ────────────────────────────────────────────────
ST_UNKNOWN    = "unknown"
ST_MISSING    = "missing"
ST_DETECTED   = "detected"
ST_TESTING    = "testing"
ST_WORKING    = "working"
ST_BROKEN     = "broken"
ST_INSTALLING = "installing"

STEP_CONF = {
    ST_UNKNOWN:    dict(dot="#404040", btn_text="Detecting…",   btn_bg="#0D0D0D", btn_fg="#444444", active=False),
    ST_MISSING:    dict(dot="#8A5500", btn_text="Install",      btn_bg="#0D0D0D", btn_fg=W,         active=True),
    ST_DETECTED:   dict(dot="#2A6A9A", btn_text="Test Install", btn_bg="#0D0D0D", btn_fg=W,         active=True),
    ST_TESTING:    dict(dot="#8A7700", btn_text="Testing…",     btn_bg="#0D0D0D", btn_fg="#444444", active=False),
    ST_WORKING:    dict(dot=GR,        btn_text="✓  Working",   btn_bg="#082008", btn_fg=GR,        active=True),
    ST_BROKEN:     dict(dot="#8A3030", btn_text="Reinstall",    btn_bg="#200808", btn_fg=RB,        active=True),
    ST_INSTALLING: dict(dot="#8A7700", btn_text="Installing…",  btn_bg="#0D0D0D", btn_fg="#444444", active=False),
}

def fmt(n):
    if n > 1e9: return f"{n/1e9:.1f} GB"
    if n > 1e6: return f"{n/1e6:.1f} MB"
    return f"{n/1e3:.0f} KB"

def ts():
    return datetime.now().strftime("%H:%M:%S")


class App(tk.Tk):
    def __init__(self, modules=None, title=None):
        """modules: optional list of tab keys to expose in the tab bar
        ('setup','exr','upscale','curve','area','rife','sam'). All tabs
        are still built internally so cross-module plumbing (shared
        caches, project save/load) keeps working; only the tab BUTTONS
        for other modules are hidden. None = full toolbox."""
        super().__init__()
        self._enabled_tabs = list(modules) if modules else None
        self.title(title or f"AI-Toolbox {APP_VERSION} — Aron Makkai")
        self.minsize(1020, 760)
        # Open maximised, filling the screen, instead of a fixed window.
        # Tk exposes this differently per platform, so try each and fall
        # back to sizing the geometry to the screen work area.
        self.geometry("1120x900")   # sensible size if maximise fails
        self._maximise_window()
        self.configure(bg=BG)
        self.exr_file     = None
        self._project_current_path = None  # last opened/saved project, for Save Version
        self.rife_folder  = None
        self.rife_frames  = []
        self.sam_folder   = None
        self._setup_steps = {}
        self._wipe_orig_raw  = None
        self._wipe_mask_raw  = None
        self._wipe_orig_base = None
        self._wipe_mask_base = None
        self._wipe_x         = 0.5
        self._wipe_tk        = None
        self._main_wipe_tk   = None
        self._sam_server     = None
        self._prog_value     = 0.0
        self._prog_pulsing   = False
        self._prog_pulse_pos = 0.0
        self._sam_zoom       = 1.0
        self._sam_pan_x      = 0
        self._sam_pan_y      = 0
        self._sam_pan_start  = None
        self._wipe_loading   = False
        self.protocol("WM_DELETE_WINDOW", self._on_close)
        self._build()
        # First-run: launch demo; thereafter default to SAM 3
        self._first_run_check()

    # ── BUILD ─────────────────────────────────────────────────────────
    def _on_close(self):
        if self._sam_server and self._sam_server.poll() is None:
            try: self._sam_server.terminate()
            except Exception: pass
        self.destroy()

    def _build(self):
        self._add_venv_to_path()
        self._header()
        self._clear_startup_cache()
        self._tabbar()
        self._build_progress_bar()          # side=bottom → bottommost
        self._build_timeline_bar()          # side=bottom → above progress bar
        self.body = tk.Frame(self, bg=BG)
        self.body.pack(fill="both", expand=True)
        self._tab_setup()
        self._tab_exr()
        self._tab_upstudio()
        self._tab_upscale()
        self._tab_fixframes()
        self._tab_curve()
        self._tab_area()
        self._tab_rife()
        self._tab_interp()
        self._tab_smudge()
        self._tab_organic()
        self._tab_sam()
        self._viewer_info_attach_all()
        # Range sync map for playback
        if not hasattr(self, "_range_synced"):
            self._range_synced = set()
        if self._enabled_tabs:
            # Open on the tool's own module, not a support tab
            _prefer = [k for k in ("rife","curve","area","smudge","sam",
                                   "upscale","upstudio","fixframes","exr",
                                   "setup")
                       if k in self._enabled_tabs]
            self.show(_prefer[0] if _prefer else self._enabled_tabs[0])
        else:
            self.show("sam")

    def _add_venv_to_path(self):
        """Add ~/RifeApp/venv site-packages and Homebrew to PATH."""
        import glob, sys
        for lib in glob.glob(os.path.expanduser(
                "~/RifeApp/venv/lib/python*/site-packages")):
            if lib not in sys.path:
                sys.path.insert(0, lib)
        # Ensure Homebrew and common tool paths are in os.environ PATH.
        # os.pathsep, not a literal ":" -- Windows uses ";", and a
        # hardcoded POSIX separator here would corrupt PATH entirely
        # on Windows, breaking every subprocess call (ffmpeg included)
        # that relies on it to find anything at all. The extra
        # locations themselves are platform-specific too: Homebrew and
        # /usr/local mean nothing on Windows, and a typical Windows
        # ffmpeg install is usually already on PATH via its installer,
        # or sits in one of a small number of common locations.
        if sys.platform == "win32":
            extra = [os.path.expanduser(r"~\ffmpeg\bin"),
                     r"C:\ffmpeg\bin",
                     r"C:\Program Files\ffmpeg\bin"]
        else:
            extra = ["/opt/homebrew/bin", "/opt/homebrew/sbin",
                     "/usr/local/bin", "/usr/local/sbin", "/usr/bin", "/bin"]
        env_path = os.environ.get("PATH", "")
        for p in extra:
            if p not in env_path:
                env_path = p + os.pathsep + env_path
        os.environ["PATH"] = env_path

    def _clear_startup_cache(self):
        """Clear all RIFE/SAM temp files on startup to prevent stale cache issues."""
        import shutil, glob, tempfile, os
        dirs_to_clear = [
            os.path.expanduser("~/RifeApp/practical-RIFE/output"),
            os.path.expanduser("~/RifeApp/_rife_pair_tmp"),
        ]
        for d in dirs_to_clear:
            if os.path.isdir(d):
                try:
                    for f in os.listdir(d):
                        fp = os.path.join(d, f)
                        try:
                            if os.path.isfile(fp): os.remove(fp)
                            elif os.path.isdir(fp): shutil.rmtree(fp)
                        except Exception: pass
                except Exception: pass

        # Clear any stale rife_prev_* and rife_full_* temp dirs in /tmp
        tmp = tempfile.gettempdir()
        for pattern in ["rife_prev_in_*","rife_prev_out_*","rife_full_in_*",
                        "rife_pair_*","sam_prev_*"]:
            for d in glob.glob(os.path.join(tmp, pattern)):
                try: shutil.rmtree(d)
                except Exception: pass

    def _build_timeline_bar(self):
        """Shared timeline strip above the progress bar, one sub-frame per tab."""
        self._tl_bar = tk.Frame(self, bg=BG)
        self._tl_bar.pack(side="bottom", fill="x")
        tk.Frame(self._tl_bar, bg=BD, height=1).pack(fill="x")
        self._tl_frames = {}
        for key in ("rife","sam","upscale","upstudio","curve","area","smudge",
                    "interp","organic","fixframes","exr"):
            f = tk.Frame(self._tl_bar, bg=BG)
            self._tl_frames[key] = f
            # Not packed yet — show() manages visibility

    def _build_progress_bar(self):
        """The window's progress bar, pinned to the very bottom.

        Pixelated: the same dither grid the per-tab bars use, so there
        is ONE progress look in the app. Studios no longer carry a
        second bar under their Run button -- they report here."""
        tk.Frame(self, bg=BD, height=1).pack(fill="x", side="bottom")
        bar_frame = tk.Frame(self, bg="#0D0D0D", height=32)
        bar_frame.pack(fill="x", side="bottom")
        bar_frame.pack_propagate(False)
        self._prog_label = tk.Label(bar_frame, text="", font=FM,
                                    bg="#0D0D0D", fg=G, anchor="w")
        self._prog_label.pack(side="left", padx=(10, 8))
        cv_wrap = tk.Frame(bar_frame, bg="#0D0D0D")
        cv_wrap.pack(side="left", fill="x", expand=True, padx=(0, 10), pady=7)
        self._prog_dither = self._dither_bar(cv_wrap, rows=6, cell=3,
                                             pady=(0, 0), show_label=False)
        self._prog_pulse_src = None   # None / "indeterminate" / "explicit"

    def _global_bar_proxy(self):
        """A per-tab bar object (.set / .reset / .pulse) that drives the
        window's own bar instead of a widget of its own -- so code that
        reported to a tab's bar keeps working unchanged."""
        app = self

        class _Bar:
            @staticmethod
            def set(frac, text=""):
                app.progress(frac, text)

            @staticmethod
            def reset():
                app.progress(-1)

            @staticmethod
            def pulse(on):
                app._prog_pulse(on)
        return _Bar

    def _prog_pulse(self, on):
        """Explicit shimmer on the lit part (a render with no progress
        of its own). Survives determinate updates -- the render clock
        keeps setting the fraction while the shimmer runs."""
        bar = getattr(self, "_prog_dither", None)
        if bar is None:
            return
        self._prog_pulsing = bool(on)
        self._prog_pulse_src = "explicit" if on else None
        bar.pulse(bool(on))

    # ── waiting on fal ──
    # Class-level defaults: read before any instance sets them, and a
    # class attribute never falls through to Tk's __getattr__.
    _fal_hold_n = 0
    _fal_hold_t0 = None
    _prog_last_label = ""
    _usc_prev_cancelled = False

    # Counted, not a flag: an upload, the render and the download are
    # separate fal calls, and a job may hold more than one at a time.
    def _fal_hold_begin(self):
        n = getattr(self, "_fal_hold_n", 0) + 1
        self._fal_hold_n = n
        if n != 1:
            return
        import time as _t
        self._fal_hold_t0 = _t.time()
        bar = getattr(self, "_prog_dither", None)
        if bar is not None and hasattr(bar, "hold"):
            bar.hold(True)
        self._fal_hold_tick()

    def _fal_hold_end(self):
        n = max(0, getattr(self, "_fal_hold_n", 0) - 1)
        self._fal_hold_n = n
        if n:
            return
        bar = getattr(self, "_prog_dither", None)
        if bar is not None and hasattr(bar, "hold"):
            bar.hold(False)
        lbl = getattr(self, "_prog_label", None)
        if lbl is not None:
            lbl.configure(text=getattr(self, "_prog_last_label", ""))

    def _fal_hold_text(self, label):
        """The bar's label while held: whose turn it is, and for how
        long, ahead of whatever the job last said about itself."""
        import time as _t
        el = int(_t.time() - (getattr(self, "_fal_hold_t0", None)
                              or _t.time()))
        head = f"waiting on fal.ai  {el // 60}:{el % 60:02d}"
        return f"{head}  \u00b7  {label}" if label else head

    def _fal_hold_tick(self):
        if not getattr(self, "_fal_hold_n", 0):
            return
        lbl = getattr(self, "_prog_label", None)
        if lbl is not None:
            lbl.configure(text=self._fal_hold_text(
                getattr(self, "_prog_last_label", "")))
        self.after(1000, self._fal_hold_tick)

    def progress(self, value, label=""):
        """Update progress bar.  value: 0.0–1.0 determinate, None = pulse, -1 = reset."""
        bar = getattr(self, "_prog_dither", None)
        # Expansion Studio names the model a job belongs to; every update
        # that lands here while one is running carries that name, however
        # deep in the call it came from.
        pre = getattr(self, "_usc_bar_prefix", "") or ""
        if pre and label and not str(label).startswith(pre):
            label = f"{pre}  \u00b7  {label}"
        # Kept to a length that always leaves the bar itself room to draw.
        label = str(label or "")
        if len(label) > 90:
            label = label[:89] + "\u2026"
        if value is not None and value < 0:
            # a reset ends any fal hold along with everything else
            self._fal_hold_n = 0
        self._prog_last_label = label
        if getattr(self, "_fal_hold_n", 0):
            label = self._fal_hold_text(label)
        if value is None:
            # Already pulsing? Only refresh the label -- starting the
            # shimmer again on every call (callers hit this once a
            # second) would stack animation loops.
            self._prog_label.configure(text=label or "Working…")
            if not self._prog_pulsing and bar is not None:
                self._prog_pulsing = True
                self._prog_pulse_src = "indeterminate"
                if self._prog_value < 0.05:
                    # nothing lit yet: light the whole bar, so the
                    # shimmer has something to sweep across
                    bar.set(1.0)
                bar.pulse(True)
            return
        if getattr(self, "_prog_pulse_src", None) == "indeterminate":
            self._prog_pulsing = False
            self._prog_pulse_src = None
            if bar is not None:
                bar.pulse(False)
        if value < 0:
            self._prog_label.configure(text="")
            self._prog_value = 0.0
            self._prog_pulsing = False
            self._prog_pulse_src = None
            if bar is not None:
                bar.reset()
            return
        value = max(0.0, min(1.0, value))
        self._prog_value = value
        self._prog_label.configure(text=label)
        if bar is not None:
            bar.set(value)

    def _header(self):
        h = tk.Frame(self, bg=BG, height=50)
        h.pack(fill="x")
        h.pack_propagate(False)
        tk.Frame(self, bg=R, height=1).pack(fill="x")
        l = tk.Frame(h, bg=BG)
        l.pack(side="left", padx=20, fill="y")
        tk.Label(l, text="AI-Toolbox", font=("Futura", 17, "bold"), bg=BG, fg=W).pack(side="left", pady=13)
        tk.Label(l, text=APP_VERSION, font=("Futura", 11, "bold"), bg=BG, fg="#CC4444").pack(side="left", padx=(5,0), pady=13)
        tk.Label(l, text="  by ", font=FSM, bg=BG, fg=M).pack(side="left")
        tk.Label(l, text="Aron Makkai", font=FSM, bg=BG, fg=R).pack(side="left")
        tk.Label(l, text="  for ", font=FSM, bg=BG, fg=M).pack(side="left")
        try:
            import base64 as _b64, io as _io
            from PIL import Image as _PI, ImageTk as _ITK
            _img_data = _b64.b64decode(AMGM_LOGO_B64)
            _img_pil  = _PI.open(_io.BytesIO(_img_data)).convert("RGBA")
            self._amgm_photo = _ITK.PhotoImage(_img_pil)
            tk.Label(l, image=self._amgm_photo, bg=BG,
                     borderwidth=0).pack(side="left", pady=12)
        except Exception as _ex:
            tk.Label(l, text="Amazon MGM Studios", font=FSM,
                     bg=BG, fg="#B8860B").pack(side="left")
        # VRAM / unified-memory bar
        _mem_wrap = tk.Frame(h, bg=BG)
        _mem_wrap.pack(side="right", padx=(0,10), pady=0, fill="y")
        self._mem_lbl = tk.Label(_mem_wrap, text="MEM —", font=FM,
            bg=BG, fg="#555555", anchor="e")
        self._mem_lbl.pack(side="top", anchor="e", pady=(10,1))
        _mem_bg = tk.Frame(_mem_wrap, bg="#1A1A1A", height=5,
            highlightthickness=1, highlightbackground="#2A2A2A")
        _mem_bg.pack(side="top", fill="x", anchor="e")
        _mem_bg.pack_propagate(False)
        self._mem_cv = tk.Canvas(_mem_bg, bg="#1A1A1A", height=5,
            width=120, highlightthickness=0)
        self._mem_cv.pack(fill="both", expand=True)
        self._mem_bar = self._mem_cv.create_rectangle(
            0, 0, 0, 5, fill="#4A8A4A", outline="")
        self._mem_update()  # start polling

        pill = tk.Frame(h, bg=S, highlightthickness=1, highlightbackground=BD)
        pill.pack(side="right", padx=(0,8), pady=14)
        self.dot_cv = tk.Canvas(pill, width=8, height=8, bg=S, highlightthickness=0)
        self.dot_cv.pack(side="left", padx=(10, 4), pady=6)
        self.dot = self.dot_cv.create_oval(0, 0, 8, 8, fill=GR, outline="")
        self.sv = tk.StringVar(value="Ready")
        tk.Label(pill, textvariable=self.sv, font=FSM, bg=S, fg=G).pack(side="left", padx=(0, 12))

    def _mem_update(self):
        """Poll system/GPU memory every 2s and update the MEM pill."""
        def _query():
            """macOS vm_stat: active+wired+compressed = actually in use."""
            try:
                import subprocess as _sp, re as _re
                out  = _sp.run(["vm_stat"], capture_output=True, text=True).stdout
                page = int(_re.search(r"page size of (\d+)", out).group(1))
                def _pg(key):
                    m = _re.search(rf"{key}:\s+(\d+)", out)
                    return int(m.group(1)) * page if m else 0
                active     = _pg("Pages active")
                wired      = _pg("Pages wired down")
                compressed = _pg("Pages occupied by compressor")
                # Truly in-use = active + wired + compressed
                used  = (active + wired + compressed) / 1_073_741_824
                total = int(_sp.run(["sysctl","-n","hw.memsize"],
                    capture_output=True, text=True).stdout.strip()) / 1_073_741_824
                pct   = min(100, used / total * 100)
                label = f"MEM  {used:.1f} / {total:.0f} GB"
                color = "#4A8A4A" if pct < 60 else "#CC8800" if pct < 80 else "#CC4444"
                return label, color, pct
            except Exception:
                return "MEM —", "#444444", 0

        try:
            label, color, pct = _query()
            self._mem_lbl.configure(text=label, fg="#888888")
            w = self._mem_cv.winfo_width() or 120
            fill_w = max(0, int(w * pct / 100))
            self._mem_cv.coords(self._mem_bar, 0, 0, fill_w, 5)
            self._mem_cv.itemconfig(self._mem_bar, fill=color)
        except Exception:
            pass
        self.after(2000, self._mem_update)

    def setstatus(self, t, c=GR):
        self.sv.set(t)
        self.dot_cv.itemconfig(self.dot, fill=c)

    # ── TAB BAR ───────────────────────────────────────────────────────
    def _tabbar(self):
        self.bar = tk.Frame(self, bg=BG, height=36)
        self.bar.pack(fill="x")
        self.bar.pack_propagate(False)
        tk.Frame(self, bg=BD, height=1).pack(fill="x")
        self.tabs     = {}
        self.tab_btns = {}
        for lbl, key in [
            ("Setup & Install",    "setup"),
            ("MOV ↔ EXR",         "exr"),
            # Upscale before Expansion: the order they should be used
            # in. The expansion module keeps its historical key
            # "upscale" (and _usc_* names) so saved projects, launchers
            # and the output hand-off keep finding it; the new upscale-
            # only module is "upstudio".
            ("Upscale Studio",     "upstudio"),
            ("Expansion Studio",   "upscale"),
            # The studios sit together. Lens Studio was ADW-Organic and
            # Paint Studio was ADW-Paint; like Expansion Studio they keep
            # their historical keys ("organic", "smudge") and _organic_* /
            # _smudge_* names, so saved projects, launchers and the
            # output hand-off keep finding them.
            ("Lens Studio",        "organic"),
            ("Paint Studio",       "smudge"),
            ("Fix Missing Frames", "fixframes"),
            ("ADW-CurveLock",      "curve"),
            ("ADW-AreaLock",       "area"),
            ("ADW-Blur",              "rife"),
            ("ADW-Interpolate",    "interp"),
            ("SAM 3 — Segment",    "sam"),
        ]:
            b = tk.Label(self.bar, text=lbl, font=FSM, bg=BG, fg=G,
                         cursor="hand2", padx=14, pady=9)
            b.pack(side="left")
            b.bind("<Button-1>", lambda e, k=key: self.show(k))
            self.tab_btns[key] = b
            if self._enabled_tabs is not None and key not in self._enabled_tabs:
                b.pack_forget()   # tab still built, just not exposed

        _load_btn = tk.Label(self.bar, text="Load Project", font=FSM, bg=BG, fg=G,
                              cursor="hand2", padx=12, pady=9)
        _load_btn.pack(side="right")
        _load_btn.bind("<Button-1>", lambda e: self._project_load())
        _load_btn.bind("<Enter>", lambda e: _load_btn.configure(fg=W))
        _load_btn.bind("<Leave>", lambda e: _load_btn.configure(fg=G))
        _save_btn = tk.Label(self.bar, text="Save Project", font=FSM, bg=BG, fg=G,
                              cursor="hand2", padx=12, pady=9)
        _save_btn.pack(side="right")
        _save_btn.bind("<Button-1>", lambda e: self._project_save())
        _save_btn.bind("<Enter>", lambda e: _save_btn.configure(fg=W))
        _save_btn.bind("<Leave>", lambda e: _save_btn.configure(fg=G))
        _version_btn = tk.Label(self.bar, text="Save Version", font=FSM, bg=BG, fg=G,
                              cursor="hand2", padx=12, pady=9)
        _version_btn.pack(side="right")
        _version_btn.bind("<Button-1>", lambda e: self._project_save_version())
        _version_btn.bind("<Enter>", lambda e: _version_btn.configure(fg=W))
        _version_btn.bind("<Leave>", lambda e: _version_btn.configure(fg=G))

    def show(self, key):
        for k, f in self.tabs.items():
            f.pack_forget()
            self.tab_btns[k].configure(fg=G)
        # Toggle timeline bar sub-frames
        for k, tf in getattr(self,"_tl_frames",{}).items():
            tf.pack_forget()
        if key in getattr(self,"_tl_frames",{}):
            self._tl_frames[key].pack(fill="x", padx=12, pady=4)
        self.tabs[key].pack(fill="both", expand=True)
        self.tab_btns[key].configure(fg=R)
        self.tabs[key].update_idletasks()
        # Auto-start SAM server when switching to the SAM tab
        if key == "rife":
            self.after(80,  self._rife_reset_sash)
            self.after(300, self._rife_reset_sash)  # second pass for layout settle
        if key == "upscale":
            self.after(150, self._usc_reset_sash)
        if key == "upstudio":
            self.after(150, self._ups_reset_sash)
        if key == "exr":
            self.after(150, self._exr_reset_sash)
        if key == "sam" and hasattr(self, "_sam_status_dot"):
            proc = getattr(self, "_sam_server", None)
            if proc is None or proc.poll() is not None:
                threading.Thread(target=self._sam_auto_start,
                                 daemon=True).start()

    # ── PROJECT SAVE / LOAD ──────────────────────────────────────────
    # Saves a .adwproj file (a zip archive) capturing every module's
    # input folder, all its slider/checkbox settings, and the actual
    # tracking data (AreaLock's masks/keyframes, CurveLock's curves/
    # keyframes, SAM3's points/objects) so a session can be closed and
    # picked back up exactly where it was left.
    #
    # Settings are captured generically by reflection rather than a
    # hand-maintained list: every self.<prefix>_..._var (or
    # self._<prefix>_..._var) that's a tk.Variable gets snapshotted
    # automatically. This means newly added sliders are included
    # without remembering to update this code -- the alternative
    # (manually listing every variable name) silently goes stale the
    # next time a setting is added.
    #
    # Masks are the one thing that doesn't fit cleanly into JSON --
    # AreaLock's keyframe masks are full-resolution boolean arrays,
    # which would bloat a JSON file badly even as nested lists. They're
    # stored as separate PNGs inside the zip instead (mask images
    # compress extremely well, being mostly flat regions), referenced
    # by filename from project.json.
    _PROJECT_VAR_TYPES = None  # set lazily once tk is available

    def _project_var_types(self):
        if self._PROJECT_VAR_TYPES is None:
            self._PROJECT_VAR_TYPES = (tk.IntVar, tk.DoubleVar, tk.BooleanVar, tk.StringVar)
        return self._PROJECT_VAR_TYPES

    def _project_collect_vars(self, prefix):
        """Snapshot every tk.Variable belonging to this module prefix."""
        out = {}
        types = self._project_var_types()
        for attr_name in dir(self):
            if not (attr_name.startswith(prefix + "_") or attr_name.startswith("_" + prefix + "_")):
                continue
            try:
                val = getattr(self, attr_name)
            except Exception:
                continue
            if isinstance(val, types):
                try:
                    out[attr_name] = val.get()
                except Exception:
                    pass
        return out

    def _project_restore_vars(self, data):
        """Restore a {attr_name: value} dict of tk.Variable values.
        Tolerant of variables that no longer exist (older project
        files) or values of the wrong type (skip, don't crash)."""
        types = self._project_var_types()
        for attr_name, value in (data or {}).items():
            var = getattr(self, attr_name, None)
            if isinstance(var, types):
                try:
                    var.set(value)
                except Exception:
                    pass

    def _project_pts_to_list(self, pts):
        """Nx2 array or list of (x,y) pairs -> plain JSON-able list."""
        if pts is None:
            return None
        try:
            import numpy as np
            arr = np.asarray(pts, dtype=float)
            return arr.tolist()
        except Exception:
            return None

    def _project_save_mask_png(self, mask_bool, zf, arcname):
        """Write a boolean mask into the zip as a 1-bit-ish PNG
        (stored as 8-bit 0/255 for compatibility), returns the arcname
        used so project.json can reference it, or None on failure."""
        try:
            import numpy as np, cv2
            img = (np.asarray(mask_bool, dtype=bool).astype(np.uint8))*255
            ok, buf = cv2.imencode(".png", img)
            if not ok:
                return None
            zf.writestr(arcname, buf.tobytes())
            return arcname
        except Exception:
            return None

    def _project_load_mask_png(self, zf, arcname):
        try:
            import numpy as np, cv2
            data = zf.read(arcname)
            arr = np.frombuffer(data, dtype=np.uint8)
            img = cv2.imdecode(arr, cv2.IMREAD_GRAYSCALE)
            if img is None:
                return None
            return img > 127
        except Exception:
            return None

    def _project_serialize_area_entry(self, a_, idx, zf, mask_files):
        """One area_list entry -> JSON-able dict. mask_files is a
        shared counter dict used to generate unique PNG names inside
        the zip across all areas/keyframes."""
        out = {}
        for k, v in a_.items():
            if k in ("mask_path", "ref_mask", "ref_features", "keyframes"):
                continue
            out[k] = v
        out["mask_path"] = self._project_pts_to_list(a_.get("mask_path"))
        ref_mask = a_.get("ref_mask")
        if ref_mask is not None:
            arcname = f"masks/area{idx}_ref.png"
            if self._project_save_mask_png(ref_mask, zf, arcname):
                out["ref_mask_file"] = arcname
        out["ref_features"] = self._project_pts_to_list(a_.get("ref_features"))
        kfs = a_.get("keyframes")
        out_kfs = {}
        if kfs:
            for fidx, kf in kfs.items():
                kf_out = {
                    "mask_path": self._project_pts_to_list(kf.get("mask_path")),
                    "ref_features": self._project_pts_to_list(kf.get("ref_features")),
                    "src_frame": kf.get("src_frame"),
                    "anchor": bool(kf.get("anchor", False)),
                    # (scale, rotation) actually applied from src_frame
                    # to this anchor -- anchor_rgb itself isn't
                    # serialisable, but this lets it be rebuilt at the
                    # right size/angle on load instead of snapping back
                    # to the source's original scale/rotation.
                    "srt": list(kf.get("srt", (1.0, 0.0))),
                }
                kf_mask = kf.get("ref_mask")
                if kf_mask is not None:
                    arcname = f"masks/area{idx}_kf{fidx}.png"
                    if self._project_save_mask_png(kf_mask, zf, arcname):
                        kf_out["ref_mask_file"] = arcname
                out_kfs[str(fidx)] = kf_out
        out["keyframes"] = out_kfs if out_kfs else None
        return out

    def _project_deserialize_area_entry(self, d, zf):
        import numpy as np
        out = dict(d)
        mp = out.get("mask_path")
        out["mask_path"] = [tuple(p) for p in mp] if mp else None
        rf = out.pop("ref_features", None)
        out["ref_features"] = np.asarray(rf, dtype=np.float32) if rf else None
        rmf = out.pop("ref_mask_file", None)
        out["ref_mask"] = self._project_load_mask_png(zf, rmf) if rmf else None
        kfs_in = out.get("keyframes") or {}
        kfs_out = {}
        for fidx_str, kf in kfs_in.items():
            kf_mp = kf.get("mask_path")
            kf_rf = kf.get("ref_features")
            kf_rmf = kf.get("ref_mask_file")
            kfs_out[int(fidx_str)] = {
                "mask_path": [tuple(p) for p in kf_mp] if kf_mp else None,
                "ref_features": np.asarray(kf_rf, dtype=np.float32) if kf_rf else None,
                "ref_mask": self._project_load_mask_png(zf, kf_rmf) if kf_rmf else None,
                "src_frame": kf.get("src_frame"),
                "anchor": bool(kf.get("anchor", False)),
                "anchor_rgb": None,   # reconstructed on first use
                "srt": tuple(kf.get("srt", (1.0, 0.0))),
            }
        out["keyframes"] = kfs_out if kfs_out else None
        return out

    def _project_serialize_curve_entry(self, cv_):
        out = {}
        for k, v in cv_.items():
            if k in ("points", "points_raw", "brush_path", "keyframes",
                     "search_bias_keyframes", "_prev_s"):
                continue
            out[k] = v
        out["points"] = self._project_pts_to_list(cv_.get("points"))
        out["points_raw"] = self._project_pts_to_list(cv_.get("points_raw"))
        out["brush_path"] = self._project_pts_to_list(cv_.get("brush_path"))
        kfs = cv_.get("keyframes")
        out["keyframes"] = ({str(fidx): self._project_pts_to_list(pts)
                              for fidx, pts in kfs.items()} if kfs else None)
        bkfs = cv_.get("search_bias_keyframes")
        out["search_bias_keyframes"] = ({str(fidx): float(bv)
                              for fidx, bv in bkfs.items()} if bkfs else None)
        return out

    def _project_deserialize_curve_entry(self, d):
        import numpy as np
        out = dict(d)
        for key in ("points", "points_raw"):
            v = out.get(key)
            out[key] = np.asarray(v, dtype=np.float64) if v else None
        bp = out.get("brush_path")
        out["brush_path"] = [tuple(p) for p in bp] if bp else None
        kfs_in = out.get("keyframes") or {}
        out["keyframes"] = ({int(fidx): np.asarray(pts, dtype=np.float64)
                              for fidx, pts in kfs_in.items()} if kfs_in else None)
        bkfs_in = out.get("search_bias_keyframes") or {}
        out["search_bias_keyframes"] = ({int(fidx): float(bv)
                              for fidx, bv in bkfs_in.items()} if bkfs_in else None)
        out["_prev_s"] = None
        return out

    def _project_save(self, path=None):
        import json, zipfile, time
        if path is None:
            path = filedialog.asksaveasfilename(
                title="Save Project", defaultextension=".adwproj",
                filetypes=[("AI-Toolbox Project", "*.adwproj")])
            if not path: return
        try:
            with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as zf:
                data = {"version": 1, "saved": time.strftime("%Y-%m-%d %H:%M:%S"),
                        "modules": {}}

                data["modules"]["area"] = {
                    "folder": self.area_folder,
                    "vars": self._project_collect_vars("area"),
                    "active": self.area_active,
                    "area_list": [self._project_serialize_area_entry(a_, i, zf, {})
                                  for i, a_ in enumerate(self.area_list)],
                }
                data["modules"]["curve"] = {
                    "folder": self.curve_folder,
                    "vars": self._project_collect_vars("curve"),
                    "active": self.curve_active,
                    "curve_list": [self._project_serialize_curve_entry(cv_)
                                  for cv_ in self.curve_list],
                }
                data["modules"]["rife"] = {
                    "folder": self.rife_folder,
                    "vars": self._project_collect_vars("rife"),
                }
                data["modules"]["upscale"] = {
                    "folder": getattr(self, "_usc_folder", None),
                    "vars": self._project_collect_vars("usc"),
                }
                data["modules"]["upstudio"] = {
                    "folder": getattr(self, "_ups_folder", None),
                    "vars": self._project_collect_vars("ups"),
                }
                data["modules"]["sam"] = {
                    "folder": getattr(self, "sam_folder", None),
                    "vars": self._project_collect_vars("sam"),
                    "objects": getattr(self, "sam_objects", None),
                    "active_obj": getattr(self, "sam_active_obj", 0),
                }
                zf.writestr("project.json", json.dumps(data, indent=1))
            self._project_current_path = path
            self.setstatus(f"Project saved — {os.path.basename(path)}", GR)
        except Exception as ex:
            self.setstatus("Save failed", RB)
            messagebox.showerror("Save Failed", str(ex))

    def _project_save_version(self):
        """Save without ever asking for a name: versions off whichever
        project file was most recently opened or saved this session,
        appending/incrementing a _vNN suffix -- so repeatedly hitting
        this button just produces _v01, _v02, _v03... neatly, with no
        dialog in the way. The next version number comes from actually
        scanning the folder for existing _vNN files with this base
        name (not just an in-memory counter), so it stays correct even
        across app restarts and never collides with or skips past a
        version that's already sitting on disk."""
        import os, re
        base_path = getattr(self, "_project_current_path", None)
        if not base_path:
            # nothing opened or saved yet this session -- ask once,
            # exactly like Save Project. Every subsequent click then
            # versions off of this.
            path = filedialog.asksaveasfilename(
                title="Save Project", defaultextension=".adwproj",
                filetypes=[("AI-Toolbox Project", "*.adwproj")])
            if not path: return
            self._project_save(path)
            return

        folder = os.path.dirname(base_path) or "."
        fname = os.path.basename(base_path)
        stem, ext = os.path.splitext(fname)
        m = re.match(r'^(.*)_v(\d+)$', stem)
        base_stem = m.group(1) if m else stem

        highest = 0
        try:
            for f in os.listdir(folder):
                fstem, fext = os.path.splitext(f)
                if fext.lower() != ext.lower():
                    continue
                mm = re.match(r'^(.*)_v(\d+)$', fstem)
                if mm and mm.group(1) == base_stem:
                    highest = max(highest, int(mm.group(2)))
        except Exception:
            pass

        new_path = os.path.join(folder, f"{base_stem}_v{highest+1:02d}{ext}")
        self._project_save(new_path)

    def _project_load(self, path=None):
        import json, zipfile
        if path is None:
            path = filedialog.askopenfilename(
                title="Load Project",
                filetypes=[("AI-Toolbox Project", "*.adwproj")])
            if not path: return
        try:
            with zipfile.ZipFile(path, "r") as zf:
                data = json.loads(zf.read("project.json").decode("utf-8"))
                mods = data.get("modules", {})

                am = mods.get("area")
                if am:
                    if am.get("folder") and os.path.isdir(am["folder"]):
                        self._area_load_folder(am["folder"])
                    elif am.get("folder"):
                        self.log(self.area_log_txt,
                            f"Project's AreaLock folder no longer exists: {am['folder']}", "err")
                    self.area_list = [self._project_deserialize_area_entry(d, zf)
                                       for d in am.get("area_list", [])] or self.area_list
                    self.area_active = min(am.get("active", 0), len(self.area_list)-1)
                    self._project_restore_vars(am.get("vars"))
                    if hasattr(self, "_area_load_current_fn"):
                        self._area_load_current_fn()
                    if hasattr(self, "_area_rebuild_tabs_fn"):
                        self._area_rebuild_tabs_fn()
                    self._area_redraw()

                cm = mods.get("curve")
                if cm:
                    if cm.get("folder") and os.path.isdir(cm["folder"]):
                        self._curve_load_folder(cm["folder"])
                    elif cm.get("folder"):
                        self.log(self.curve_log_txt,
                            f"Project's CurveLock folder no longer exists: {cm['folder']}", "err")
                    self.curve_list = [self._project_deserialize_curve_entry(d)
                                        for d in cm.get("curve_list", [])] or self.curve_list
                    self.curve_active = min(cm.get("active", 0), len(self.curve_list)-1)
                    self._project_restore_vars(cm.get("vars"))
                    if hasattr(self, "_curve_load_current_fn"):
                        self._curve_load_current_fn()
                    if hasattr(self, "_curve_rebuild_tabs_fn"):
                        self._curve_rebuild_tabs_fn()
                    self._curve_redraw()

                rm = mods.get("rife")
                if rm:
                    if rm.get("folder") and os.path.isdir(rm["folder"]):
                        self._rpick_load(rm["folder"])
                    self._project_restore_vars(rm.get("vars"))

                um = mods.get("upscale")
                if um:
                    if um.get("folder") and os.path.isdir(um["folder"]):
                        self._usc_load_folder(um["folder"])
                    self._project_restore_vars(um.get("vars"))

                pm = mods.get("upstudio")
                if pm:
                    if pm.get("folder") and os.path.isdir(pm["folder"]):
                        self._ups_load_folder(pm["folder"])
                    self._project_restore_vars(pm.get("vars"))
                elif um and um.get("vars"):
                    # A project saved before the split: its resolution
                    # settings belonged to the old combined tab.
                    _uv = um["vars"]
                    self._project_restore_vars({
                        new: _uv[old] for new, old in (
                            ("ups_res_var", "usc_res_var"),
                            ("ups_fac_var", "usc_fac_var"),
                            ("ups_fmt_var", "usc_fmt_var"))
                        if _uv.get(old) is not None})

                sm = mods.get("sam")
                if sm:
                    if sm.get("folder") and os.path.isdir(sm["folder"]):
                        self._sam_load_folder(sm["folder"])
                    if sm.get("objects"):
                        self.sam_objects = sm["objects"]
                        self.sam_active_obj = min(sm.get("active_obj", 0),
                                                   len(self.sam_objects)-1)
                    self._project_restore_vars(sm.get("vars"))

            self._project_current_path = path
            self.setstatus(f"Project loaded — {os.path.basename(path)}", GR)
        except Exception as ex:
            import traceback
            self.setstatus("Load failed", RB)
            messagebox.showerror("Load Failed", f"{ex}\n\n{traceback.format_exc()[-500:]}")

    # ── SHARED WIDGETS ────────────────────────────────────────────────
    def _frame(self, key):
        f = tk.Frame(self.body, bg=BG)
        self.tabs[key] = f
        return f

    def _make_paned(self, parent, orient, **kwargs):
        """PanedWindow with a visible triple-line drag handle drawn on the sash."""
        pw = tk.PanedWindow(parent, orient=orient, bg="#1C1C1C",
                            sashwidth=10, sashrelief="flat",
                            handlesize=0,   # we draw our own
                            **kwargs)
        pw.pack(fill="both", expand=True)

        def _draw_handles(e=None):
            try:
                npanes = len(pw.panes())
                for i in range(npanes - 1):
                    sx, sy = pw.sash_coord(i)
                    cw = pw.winfo_width()
                    ch = pw.winfo_height()
                    if orient == "horizontal":
                        # Vertical sash — draw ⋮ centred
                        lbl = _sash_labels[i]
                        lbl.place(x=sx, y=ch//2 - 14, width=10, height=28)
                    else:
                        lbl = _sash_labels[i]
                        lbl.place(x=cw//2 - 14, y=sy, width=28, height=10)
            except Exception:
                pass

        _sash_labels = []

        # Continuous poll — repositions handles every 50ms no matter what moved the sash
        def _poll():
            try:
                if pw.winfo_exists():
                    _draw_handles()
                    pw.after(50, _poll)
            except Exception:
                pass

        def _add_handle(i):
            if orient == "horizontal":
                txt = "⋮\n⋮\n⋮"
                lbl = tk.Label(pw, text=txt, font=("Helvetica Neue", 7),
                               bg="#2A2A2A", fg="#666666",
                               cursor="sb_h_double_arrow")
            else:
                txt = "···"
                lbl = tk.Label(pw, text=txt, font=("Helvetica Neue", 7),
                               bg="#2A2A2A", fg="#666666",
                               cursor="sb_v_double_arrow")
            lbl.bind("<Enter>", lambda e, l=lbl: l.configure(bg="#383838", fg="#AAAAAA"))
            lbl.bind("<Leave>", lambda e, l=lbl: l.configure(bg="#2A2A2A", fg="#666666"))

            def _do_drag(e, idx=i):
                pw.sash_place(idx,
                    e.x_root - pw.winfo_rootx(),
                    e.y_root - pw.winfo_rooty())

            lbl.bind("<B1-Motion>", _do_drag)
            _sash_labels.append(lbl)

        def _bind_pane_configure(pane):
            pass   # no longer needed — poll handles it

        pw._add_handle          = _add_handle
        pw._bind_pane_configure = _bind_pane_configure
        pw._draw_handles        = _draw_handles
        pw.after(100, _poll)   # start poll after widget is mapped
        return pw

    def _two_col(self, parent, title, sub, lw=360):
        paned = self._make_paned(parent, "horizontal")

        lf = tk.Frame(paned, bg=BG, width=lw)
        lf.pack_propagate(False)
        paned.add(lf, minsize=220, stretch="never")
        paned._add_handle(0)
        paned._bind_pane_configure(lf)

        rf = tk.Frame(paned, bg=BG)
        paned.add(rf, minsize=200, stretch="always")
        paned._bind_pane_configure(rf)

        if title:
            tk.Label(lf, text=title, font=("Futura", 14), bg=BG, fg=W,
                     anchor="w").pack(anchor="w", padx=16, pady=(14, 2))
        if sub:
            tk.Label(lf, text=sub, font=FSM, bg=BG, fg=G,
                     anchor="w").pack(anchor="w", padx=16, pady=(0, 10))
        self.after(50, paned._draw_handles)
        return lf, rf

    def _scroll_column(self, container, width=10):
        """Turn a fixed-width column into a vertically scrolling one.

        Returns (inner, bottom) -- pack controls into `inner`, and
        anything that must stay put (run buttons) into `bottom`, which
        is reserved before the canvas and so never scrolls away.

        Same Canvas-holding-a-Frame construction the other tabs each
        grew their own copy of; extracted here so a fourth copy did not
        have to exist. One behavioural difference, deliberately: the
        wheel handler falls back to a one-unit step when the platform
        reports a small delta. int(-1/120) is 0, which silently means no
        scrolling at all on a trackpad that reports +/-1 per notch."""
        bottom = tk.Frame(container, bg=BG)
        bottom.pack(side="bottom", fill="x")

        cv = tk.Canvas(container, bg=BG, highlightthickness=0)
        vsb = self._mk_scrollbar(container, cv, width=width)
        vsb.pack(side="right", fill="y")
        cv.pack(side="left", fill="both", expand=True)

        inner = tk.Frame(cv, bg=BG)
        win = cv.create_window((0, 0), window=inner, anchor="nw")
        cv.bind("<Configure>", lambda e: cv.itemconfig(win, width=e.width))
        # Follows the inner frame's real size, so collapsing or opening
        # a disclosure group re-measures the scrollregion for free.
        inner.bind("<Configure>",
                   lambda e: cv.configure(scrollregion=cv.bbox("all")))

        def _wheel(e):
            try:
                if not cv.winfo_ismapped():
                    return
                x, y = cv.winfo_rootx(), cv.winfo_rooty()
                w, h = cv.winfo_width(), cv.winfo_height()
                if not (x <= e.x_root <= x + w and y <= e.y_root <= y + h):
                    return
                d = e.delta
                step = int(-d / 120) or (-1 if d > 0 else 1)
                cv.yview_scroll(step, "units")
            except Exception:
                pass
        cv.bind_all("<MouseWheel>", _wheel, add="+")
        return inner, bottom

    @staticmethod
    def _typing_in_field(w):
        """Is keyboard focus somewhere a letter key should TYPE? Hotkeys
        stand down only then.

        Not simply isinstance(w, tk.Entry): ttk.Combobox IS a tk.Entry
        subclass, so a read-only dropdown that was clicked once -- and
        keeps the focus, since clicking a canvas does not take it --
        silenced every hotkey on the tab until something else was
        focused. A read-only or disabled field cannot be typed into, so
        it does not count."""
        if not isinstance(w, (tk.Entry, tk.Text)):
            return False
        try:
            st = str(w.cget("state"))
        except Exception:
            return True
        return st not in ("readonly", "disabled")

    # ── file info on every viewer ─────────────────────────────────────
    # Resolution and FILE bit depth in the lower-left corner of each
    # preview canvas. The viewers all show an 8-bit picture whatever the
    # source is, so the picture itself cannot say whether the file behind
    # it is an 8-bit PNG or a 32-bit float EXR -- and that is the first
    # thing to know before grading, expanding or delivering it.
    _FILE_INFO_MOVIES = (".mov", ".mp4", ".mxf", ".avi", ".mkv", ".mpg",
                         ".mpeg", ".m4v", ".webm")

    @classmethod
    def _file_info(cls, path):
        """(width, height, depth text, format) read off the file's own
        header -- never off a decoded picture, which is 8-bit by the time
        this app shows it. None if it cannot be read."""
        import struct
        ext = os.path.splitext(str(path))[1].lower()
        try:
            if ext == ".exr":
                import OpenEXR
                hdr = OpenEXR.InputFile(path).header()
                win = hdr.get("displayWindow") or hdr["dataWindow"]
                w = win.max.x - win.min.x + 1
                h = win.max.y - win.min.y + 1
                chans = hdr.get("channels", {})
                ch = chans.get("R") or (chans[sorted(chans)[0]]
                                        if chans else None)
                t = str(getattr(ch, "type", ch)).upper()
                depth = ("16-bit half float" if "HALF" in t else
                         "32-bit float" if "FLOAT" in t else
                         "32-bit integer" if "UINT" in t else "float")
                fmt = "EXR"
                if cls._exr_is_aces(path):
                    fmt += " \u00b7 ACES2065-1"
                return w, h, depth, fmt
            if ext == ".png":
                with open(path, "rb") as fh:
                    head = fh.read(26)
                if head[:8] != b"\x89PNG\r\n\x1a\n":
                    return None
                w, h = struct.unpack(">II", head[16:24])
                return w, h, f"{head[24]}-bit", "PNG"
            if ext == ".dpx":
                with open(path, "rb") as fh:
                    head = fh.read(804)
                e = ">" if head[:4] == b"SDPX" else "<"
                w, h = struct.unpack(e + "II", head[772:780])
                return w, h, f"{head[803]}-bit", "DPX"
            if ext in cls._FILE_INFO_MOVIES:
                r = subprocess.run(
                    ["ffprobe", "-v", "error", "-select_streams", "v:0",
                     "-show_entries",
                     "stream=codec_name,width,height,pix_fmt,"
                     "bits_per_raw_sample", "-of", "default=nw=1",
                     str(path)], capture_output=True, text=True)
                d = dict(l.split("=", 1) for l in (r.stdout or "").splitlines()
                         if "=" in l)
                w, h = int(d["width"]), int(d["height"])
                bits = d.get("bits_per_raw_sample", "")
                if not bits.isdigit():
                    import re
                    mt = re.search(r"p(\d\d)(?:le|be)?$|(\d\d)(?:le|be)$",
                                   d.get("pix_fmt", ""))
                    bits = (mt.group(1) or mt.group(2)) if mt else "8"
                fmt = (d.get("codec_name", "") or ext.lstrip(".")).upper()
                return w, h, f"{int(bits)}-bit", \
                    f"{fmt} ({ext.lstrip('.').upper()})"
            from PIL import Image
            with Image.open(path) as im:
                w, h = im.size
                mode = im.mode
                bits = None
                if ext in (".tif", ".tiff"):
                    try:
                        bps = im.tag_v2.get(258)
                        bits = int(bps[0] if isinstance(bps, (tuple, list))
                                   else bps)
                        if int(im.tag_v2.get(339, 1) if not isinstance(
                                im.tag_v2.get(339, 1), (tuple, list))
                                else im.tag_v2.get(339)[0]) == 3:
                            return w, h, f"{bits}-bit float", "TIFF"
                    except Exception:
                        bits = None
            if bits is None:
                bits = (16 if "16" in mode else 32 if mode in ("I", "F")
                        else 8)
            return w, h, f"{bits}-bit", \
                {".jpg": "JPEG", ".jpeg": "JPEG", ".tif": "TIFF",
                 ".tiff": "TIFF", ".hdr": "HDR"}.get(ext,
                                                     ext.lstrip(".").upper())
        except Exception:
            return None

    def _file_info_text(self, path):
        """'3840\u00d72160  \u00b7  16-bit half float  \u00b7  EXR', cached per
        file (and its modification time)."""
        if not path:
            return ""
        cache = getattr(self, "_file_info_cache", None)
        if cache is None:
            cache = self._file_info_cache = {}
        try:
            key = (str(path), os.path.getmtime(path))
        except OSError:
            return ""
        if key not in cache:
            if len(cache) > 4000:
                cache.clear()
            info = self._file_info(path)
            cache[key] = ("" if not info else
                          f"{info[0]}\u00d7{info[1]}  \u00b7  {info[2]}"
                          f"  \u00b7  {info[3]}")
        return cache[key]

    @staticmethod
    def _viewer_frame_path(folder, frames, idx):
        """The file behind a viewer: frames[idx] under folder (frame
        lists hold names in some modules and full paths in others)."""
        try:
            if not frames:
                return None
            idx = max(0, min(int(idx or 0), len(frames) - 1))
            name = str(frames[idx])
            p = name if os.path.isabs(name) else os.path.join(str(folder),
                                                              name)
            return p if os.path.isfile(p) else None
        except Exception:
            return None

    def _viewer_info_attach(self, cv, get_path):
        """Keep the info line in the lower-left corner of canvas `cv`.

        Every viewer redraws in its own way (most wipe the canvas and
        draw again), so rather than edit a dozen draw routines this
        watches the canvas itself: after anything that redraws the
        picture -- delete("all"), a new image, an image swapped in place,
        a resize -- the line is put back, once, at idle, on top."""
        if cv is None or getattr(cv, "_viewer_info", False):
            return
        cv._viewer_info = True
        o_delete, o_image = cv.delete, cv.create_image
        o_itemcfg = cv.itemconfigure
        st = {"pending": False}

        def _draw():
            st["pending"] = False
            try:
                o_delete("viewer_info")
                txt = self._file_info_text(get_path())
                if not txt:
                    return
                h = cv.winfo_height()
                if h < 40:
                    return
                t = cv.create_text(8, h - 7, anchor="sw", text=txt, font=FM,
                                   fill="#D8D8D8", tags="viewer_info")
                bb = cv.bbox(t)
                if bb:
                    r = cv.create_rectangle(
                        bb[0] - 4, bb[1] - 2, bb[2] + 4, bb[3] + 2,
                        fill="#0A0A0A", outline="#2A2A2A",
                        tags="viewer_info")
                    cv.tag_raise(t, r)
            except Exception:
                pass

        def _sched(*_a):
            if not st["pending"]:
                st["pending"] = True
                try:
                    cv.after_idle(_draw)
                except Exception:
                    st["pending"] = False

        def _delete(*a):
            r = o_delete(*a)
            if a and a[0] == "all":
                _sched()
            return r

        def _create_image(*a, **k):
            r = o_image(*a, **k)
            _sched()
            return r

        def _itemconfigure(*a, **k):
            r = o_itemcfg(*a, **k)
            if "image" in k:
                _sched()
            return r

        cv.delete = _delete
        cv.create_image = _create_image
        cv.itemconfigure = cv.itemconfig = _itemconfigure
        cv.bind("<Configure>", _sched, add="+")
        cv._viewer_info_refresh = _sched
        _sched()

    def _viewer_info_attach_all(self):
        """One line per module: its viewer, and the file that viewer is
        showing. A movie-sourced module reports the MOVIE (its decoded
        scratch frames are PNGs this app made, which would say nothing
        true about the source)."""
        g = lambda n, d=None: getattr(self, n, d)
        fp = self._viewer_frame_path

        def _cur(cb_name):
            try:
                return g(cb_name).current()
            except Exception:
                return 0

        def _exr():
            if g("exr_mode") == "to_exr":
                return g("exr_file")
            if g("e2m_video_src"):
                return g("e2m_video_src")
            d = g("e2m_folder")
            try:
                fs = sorted(f for f in os.listdir(d)
                            if f.lower().endswith(".exr"))
                return os.path.join(d, fs[len(fs) // 2]) if fs else None
            except Exception:
                return None

        def _ff():
            if g("ff_is_movie") and g("ff_input"):
                return g("ff_input")
            return fp(g("ff_input"), g("ff_names"), g("_ff_idx", 0))

        specs = (
            ("e2m_preview_canvas", _exr),
            ("ups_canvas", lambda: (g("_ups_src_movie") if g("_ups_is_movie")
                                    else fp(g("_ups_folder"), g("_ups_frames"),
                                            g("_ups_tl_idx", 0)))),
            ("usc_canvas", lambda: (g("_usc_src_movie") if g("_usc_is_movie")
                                    else fp(g("_usc_folder"), g("_usc_frames"),
                                            g("_usc_tl_idx", 0)))),
            ("organic_canvas", lambda: fp(g("organic_folder"),
                                          g("organic_frames"),
                                          g("_organic_idx", 0))),
            ("sm_canvas", lambda: fp(g("sm_folder"), g("sm_frames"),
                                     g("sm_idx", 0))),
            ("ff_canvas", _ff),
            ("curve_canvas", lambda: fp(g("curve_folder"), g("curve_frames"),
                                        _cur("curve_frame_cb"))),
            ("area_canvas", lambda: fp(g("area_folder"), g("area_frames"),
                                       _cur("area_frame_cb"))),
            ("rife_wipe_canvas", lambda: fp(g("rife_folder"),
                                            g("rife_frames"),
                                            _cur("rife_frame_cb"))),
            ("ip_canvas", lambda: fp(g("ip_folder"), g("ip_frames"),
                                     g("ip_idx", 0))),
            ("sam_canvas", lambda: fp(g("sam_folder"), g("sam_frames"),
                                      _cur("sam_frame_cb"))),
        )
        for name, getter in specs:
            try:
                self._viewer_info_attach(g(name), getter)
            except Exception:
                pass

    def _card(self, parent, title):
        w = tk.Frame(parent, bg=S, highlightthickness=1, highlightbackground=BD, highlightcolor=BD)
        w.pack(fill="x", padx=16, pady=(4, 0))
        tk.Label(w, text=title, font=FSM, bg=S, fg=G).pack(anchor="w", padx=10, pady=(5, 0))
        inner = tk.Frame(w, bg=S)
        inner.pack(fill="x", padx=10, pady=(2, 8))
        return inner

    # ── preset storage, kept out of the widget closure so it can be
    # exercised without a window ──────────────────────────────────────

    @staticmethod
    def _preset_path(store):
        import pathlib
        return pathlib.Path.home() / ".ai_toolbox" / store

    @classmethod
    def _preset_load_file(cls, store):
        """Saved presets as [{"name":…, "settings":{…}}]. A missing or
        unreadable file is an empty list, never an exception -- a
        corrupt preset file must not take a tab down on build."""
        import json
        try:
            p = cls._preset_path(store)
            if p.exists():
                data = json.loads(p.read_text())
                if isinstance(data, list):
                    return [d for d in data if isinstance(d, dict)]
        except Exception:
            pass
        return []

    @classmethod
    def _preset_save_file(cls, store, lst):
        import json
        try:
            p = cls._preset_path(store)
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(json.dumps(lst, indent=2))
            return True
        except Exception:
            return False

    # ── preset interchange ────────────────────────────────────────────
    # Exported files carry a small header naming the store they came
    # from. A bare list is still accepted on import, because the file in
    # ~/.ai_toolbox IS a bare list and copying one straight out of there
    # is the obvious thing to try.

    PRESET_EXPORT_TAG = "adw-presets"

    @classmethod
    def _preset_export_blob(cls, store, presets):
        return {"format": cls.PRESET_EXPORT_TAG, "version": 1,
                "store": store, "presets": list(presets)}

    @staticmethod
    def _preset_parse_import(data):
        """(presets, store_or_None) from either an exported blob or a
        bare list. Raises ValueError with something worth reading --
        this is the one place a user hands the app a file it did not
        write, so "invalid" on its own is not good enough."""
        if isinstance(data, dict):
            store = data.get("store")
            presets = data.get("presets")
            if not isinstance(presets, list):
                raise ValueError("no preset list in that file")
        elif isinstance(data, list):
            store, presets = None, data
        else:
            raise ValueError("not a preset file")
        out = []
        for d in presets:
            if not isinstance(d, dict):
                continue
            settings = d.get("settings")
            if not isinstance(settings, dict):
                continue
            out.append({"name": str(d.get("name") or "Imported"),
                        "settings": settings})
        if not out:
            raise ValueError("that file contains no presets")
        return out, store

    @staticmethod
    def _preset_match_score(presets, var_map):
        """Fraction of the incoming keys this tab actually understands.

        Importing ADW-Blur presets into ADW-Organic would otherwise
        "succeed" and change nothing, because apply skips keys it does
        not know -- a silent no-op is the worst possible outcome here."""
        keys = set()
        for d in presets:
            keys |= set(d.get("settings") or {})
        if not keys:
            return 0.0
        return len(keys & set(var_map)) / float(len(keys))

    @staticmethod
    def _preset_merge(existing, incoming):
        """Append imported presets, renaming collisions rather than
        overwriting: an import must never silently destroy a look the
        user already had."""
        out = list(existing)
        taken = {d.get("name") for d in out}
        added = []
        for d in incoming:
            name = d["name"]
            if name in taken:
                n = 2
                while f"{name} ({n})" in taken:
                    n += 1
                name = f"{name} ({n})"
            taken.add(name)
            rec = {"name": name, "settings": d["settings"]}
            out.append(rec)
            added.append(name)
        return out, added

    def _preset_collect(self, var_map):
        """Current values of the mapped Tk variables. Anything missing
        is skipped rather than stored as None, so a preset saved by an
        older build stays loadable by a newer one."""
        d = {}
        for k, attr in var_map.items():
            v = getattr(self, attr, None)
            if v is None:
                continue
            try:
                d[k] = v.get()
            except Exception:
                pass
        return d

    def _preset_apply_values(self, var_map, d):
        """Push a settings dict back into the mapped variables. Keys the
        map does not know about are ignored, and so are keys the preset
        does not carry -- which is what lets the factory looks, which
        hold twelve of the fourteen organic keys, load cleanly."""
        applied = []
        for k, attr in var_map.items():
            if k not in d:
                continue
            v = getattr(self, attr, None)
            if v is None:
                continue
            try:
                v.set(d[k])
                applied.append(k)
            except Exception:
                pass
        return applied

    @staticmethod
    def _preset_next_name(lst):
        """First free Preset_NN, so deleting from the middle reuses the
        gap instead of counting forever upward."""
        existing = {p.get("name") for p in lst}
        n = 1
        while f"Preset_{n:02d}" in existing:
            n += 1
        return f"Preset_{n:02d}"

    def _tooltip(self, tip):
        """Hover tooltip. The same pattern three tabs already define
        locally; this is the shared one, so a fourth copy did not have
        to exist."""
        def _attach(widget):
            _pop = [None]

            def _show(e):
                if _pop[0]:
                    try:
                        _pop[0].destroy()
                    except Exception:
                        pass
                pop = tk.Toplevel(self)
                pop.overrideredirect(True)
                pop.configure(bg=BD)
                pop.attributes("-topmost", True)
                tk.Label(pop, text=tip, font=FM, bg=BD, fg=W,
                         justify="left", padx=12, pady=10,
                         wraplength=280).pack()
                pop.update_idletasks()
                x = min(e.x_root + 4,
                        self.winfo_screenwidth() - pop.winfo_width() - 8)
                pop.geometry(f"+{x}+{e.y_root + 16}")
                _pop[0] = pop

            def _hide(_e=None):
                if _pop[0]:
                    try:
                        _pop[0].destroy()
                    except Exception:
                        pass
                    _pop[0] = None
            widget.bind("<Enter>", _show, add="+")
            widget.bind("<Leave>", _hide, add="+")
        return _attach

    def _tooltip_dynamic(self, widget, text_fn):
        """Tooltip whose text is fetched when it opens.

        The static _tooltip captures its string at build time, which is
        wrong for anything that describes the CURRENT settings -- it
        would keep explaining whatever was selected when the tab was
        created."""
        def _show(e):
            try:
                txt = text_fn()
            except Exception:
                return
            if not txt:
                return
            pop = tk.Toplevel(self)
            pop.overrideredirect(True)
            pop.configure(bg=BD)
            pop.attributes("-topmost", True)
            tk.Label(pop, text=txt, font=FM, bg=BD, fg=W, justify="left",
                     padx=12, pady=10, wraplength=300).pack()
            pop.update_idletasks()
            x = min(e.x_root + 4,
                    self.winfo_screenwidth() - pop.winfo_width() - 8)
            pop.geometry(f"+{x}+{e.y_root + 16}")
            widget._tip_pop = pop

        def _hide(_e=None):
            pop = getattr(widget, "_tip_pop", None)
            if pop is not None:
                try:
                    pop.destroy()
                except Exception:
                    pass
                widget._tip_pop = None
        widget.bind("<Enter>", _show, add="+")
        widget.bind("<Leave>", _hide, add="+")
        return _hide

    def _disclosure(self, parent, title, opened=False):
        """A collapsible sub-group inside a card. Returns the body
        frame. Used where one effect has more controls than fit on
        screen at once -- the bloom kernel alone has sixteen."""
        holder = tk.Frame(parent, bg=S)
        holder.pack(fill="x", pady=(5, 0))
        hdr = tk.Frame(holder, bg=S, cursor="hand2")
        hdr.pack(fill="x")
        arrow = tk.Label(hdr, text=("▾" if opened else "▸"), font=FSM,
                         bg=S, fg="#666666", width=2, cursor="hand2")
        arrow.pack(side="left")
        lbl = tk.Label(hdr, text=title, font=FSM, bg=S, fg="#999999",
                       anchor="w", cursor="hand2")
        lbl.pack(side="left", fill="x", expand=True)
        body = tk.Frame(holder, bg=S)
        state = {"open": bool(opened)}
        if opened:
            body.pack(fill="x", pady=(2, 0))

        def _toggle(_e=None):
            state["open"] = not state["open"]
            arrow.configure(text="▾" if state["open"] else "▸")
            if state["open"]:
                body.pack(fill="x", pady=(2, 0))
            else:
                body.pack_forget()
        for w in (hdr, arrow, lbl):
            w.bind("<Button-1>", _toggle)
        return body

    def _preset_bar(self, parent, store, var_map, on_apply=None,
                    builtins=None, side="right"):
        """The name-label + `+` preset control, as first built for
        ADW-Blur and now shared.

        Extracted rather than copied: the ADW-Blur version had already
        grown a second copy of its own variable map at class level
        (ADW_PRESET_VARS), which is exactly how two readers of the same
        JSON file end up disagreeing about what is in it.

        store     filename under ~/.ai_toolbox, e.g. "presets_adw.json"
        var_map   {json key: attribute name of a Tk variable on self}
        on_apply  optional callback after a preset is loaded, for UI
                  that needs an explicit redraw
        builtins  optional {name: settings} shown above a divider,
                  load-only -- factory looks are starting points, not
                  something the user should be able to delete

        Returns (name_button, plus_button, name_var). On-disk format is
        [{"name":…, "settings":{…}}], matching ADW-Blur's file so
        _adw_presets and friends keep working unchanged.
        """
        _builtins = dict(builtins or {})

        def _read():
            return self._preset_load_file(store)

        def _write(lst):
            self._preset_save_file(store, lst)

        def _apply(d):
            self._preset_apply_values(var_map, d)
            if on_apply is not None:
                try:
                    on_apply()
                except Exception:
                    pass

        name_var = tk.StringVar(value="Presets")
        name_btn = tk.Label(parent, textvariable=name_var,
            font=FSM, bg="#1A1A1A", fg="#888888",
            cursor="hand2", padx=7, pady=2,
            highlightthickness=1, highlightbackground=BD)
        name_btn.pack(side=side, padx=(0, 0))

        plus_btn = tk.Label(parent, text="+", font=("Futura", 14),
            bg="#1A1A1A", fg="#888888", cursor="hand2",
            padx=6, pady=1,
            highlightthickness=1, highlightbackground=BD)
        plus_btn.pack(side=side, padx=(0, 4))

        def _close_popup():
            p = getattr(self, "_preset_popup", None)
            if p:
                try:
                    p.unbind_all("<Button-1>")
                except Exception:
                    pass
                try:
                    p.destroy()
                except Exception:
                    pass
            self._preset_popup = None

        def _row(pop, label, loader, ctx=None, fg=W):
            r = tk.Frame(pop, bg=S)
            r.pack(fill="x")
            lbl = tk.Label(r, text=label, font=FSM, bg=S, fg=fg,
                           anchor="w", padx=10, pady=6, cursor="hand2")
            lbl.pack(fill="x", expand=True)
            lbl.bind("<Enter>", lambda _e: (r.configure(bg="#222222"),
                                            lbl.configure(bg="#222222")))
            lbl.bind("<Leave>", lambda _e: (r.configure(bg=S),
                                            lbl.configure(bg=S)))
            lbl.bind("<Button-1>", loader)
            if ctx is not None:
                lbl.bind("<Button-2>", ctx)
                lbl.bind("<Button-3>", ctx)
            return r

        def _edit_menu(x, y, idx, pr):
            """Rename/Delete for one saved preset. Re-reads the file
            inside each command rather than trusting the list captured
            when the menu was built."""
            def _show():
                import tkinter.simpledialog as _sd
                m = tk.Menu(self, tearoff=0, bg=S, fg=W,
                            activebackground=BD, activeforeground=W, font=FM)

                def _rename():
                    nm = _sd.askstring("Rename", "Preset name:",
                                       initialvalue=pr["name"], parent=self)
                    if nm and nm.strip():
                        lst = _read()
                        if idx < len(lst):
                            lst[idx]["name"] = nm.strip()
                            _write(lst)
                            if name_var.get() == pr["name"]:
                                name_var.set(nm.strip())

                def _delete():
                    lst = _read()
                    if idx < len(lst):
                        old = lst[idx]["name"]
                        lst.pop(idx)
                        _write(lst)
                        if name_var.get() == old:
                            name_var.set("Presets")

                m.add_command(label="Rename…", command=_rename)
                m.add_command(label="Delete", command=_delete)
                try:
                    m.tk_popup(x, y)
                finally:
                    m.grab_release()
            self.after(0, _show)

        def _open_dropdown(_e=None):
            _close_popup()
            presets = _read()
            pop = tk.Toplevel(self)
            pop.overrideredirect(True)
            pop.configure(bg=S, highlightthickness=1, highlightbackground=BD)
            pop.attributes("-topmost", True)
            self._preset_popup = pop

            for bname, bset in _builtins.items():
                def _load_b(_e, d=bset, nm=bname):
                    _apply(dict(d))
                    name_var.set(nm)
                    _close_popup()
                _row(pop, bname, _load_b, ctx=None, fg=G)
            if _builtins:
                tk.Frame(pop, bg=BD, height=1).pack(fill="x")

            if not presets:
                tk.Label(pop, text="No saved presets — click + to save",
                         font=FM, bg=S, fg="#555555",
                         padx=12, pady=8).pack()
            else:
                for _i, _pr in enumerate(presets):
                    def _load(_e, d=_pr.get("settings", {}),
                              nm=_pr.get("name", "?")):
                        _apply(d)
                        name_var.set(nm)
                        _close_popup()

                    def _ctx(e, i=_i, p=_pr):
                        ex, ey = e.x_root, e.y_root  # before the popup goes
                        _close_popup()
                        _edit_menu(ex, ey, i, p)
                    _row(pop, _pr.get("name", "?"), _load, _ctx)
                tk.Frame(pop, bg=BD, height=1).pack(fill="x")

            _row(pop, "Import\u2026", lambda _e: (_close_popup(), _import()),
                 fg=G)
            _row(pop, "Export all\u2026", lambda _e: (_close_popup(),
                                                      _export()), fg=G)

            pop.update_idletasks()
            bx = name_btn.winfo_rootx()
            by = name_btn.winfo_rooty() + name_btn.winfo_height() + 2
            sw = self.winfo_screenwidth()
            pw = max(180, pop.winfo_width())
            pop.geometry(f"+{min(bx, sw - pw - 8)}+{by}")

            def _outside(e):
                try:
                    inx = (pop.winfo_rootx() <= e.x_root
                           <= pop.winfo_rootx() + pop.winfo_width())
                    iny = (pop.winfo_rooty() <= e.y_root
                           <= pop.winfo_rooty() + pop.winfo_height())
                    if not (inx and iny):
                        _close_popup()
                except Exception:
                    pass
            pop.bind_all("<Button-1>", _outside, add="+")

        def _export(_e=None):
            import json as _json
            lst = _read()
            if not lst:
                messagebox.showinfo("Nothing to export",
                    "Save a preset with + first — the built-in looks are "
                    "part of the app and travel with it.")
                return
            path = filedialog.asksaveasfilename(
                title="Export presets", defaultextension=".json",
                initialfile=os.path.splitext(store)[0] + "_export.json",
                filetypes=[("Preset file", "*.json")])
            if not path:
                return
            try:
                with open(path, "w", encoding="utf-8") as fh:
                    _json.dump(self._preset_export_blob(store, lst), fh,
                               indent=2)
            except Exception as ex:
                messagebox.showerror("Export failed", str(ex))
                return
            messagebox.showinfo("Exported",
                f"{len(lst)} preset(s) written to\n{os.path.basename(path)}")

        def _import(_e=None):
            import json as _json
            path = filedialog.askopenfilename(
                title="Import presets",
                filetypes=[("Preset file", "*.json"), ("All files", "*.*")])
            if not path:
                return
            try:
                with open(path, encoding="utf-8") as fh:
                    incoming, src_store = self._preset_parse_import(
                        _json.load(fh))
            except ValueError as ex:
                messagebox.showerror("Import failed", str(ex))
                return
            except Exception as ex:
                messagebox.showerror("Import failed",
                                     f"Could not read that file:\n{ex}")
                return
            # A file from another tab would import cleanly and then do
            # nothing, because apply skips keys it does not recognise.
            # Better to say so than to leave a preset that silently has
            # no effect.
            score = self._preset_match_score(incoming, var_map)
            if score < 0.2:
                messagebox.showerror("Wrong module",
                    "Those presets are for a different tab"
                    + (f" ({src_store})" if src_store else "")
                    + " — almost none of their settings apply here.")
                return
            if score < 0.9:
                if not messagebox.askyesno("Partial match",
                        f"Only {score * 100:.0f}% of the settings in that "
                        "file apply here. Import anyway?"):
                    return
            merged, added = self._preset_merge(_read(), incoming)
            _write(merged)
            messagebox.showinfo("Imported",
                f"Added {len(added)} preset(s):\n" + ", ".join(added[:8])
                + ("\u2026" if len(added) > 8 else ""))

        def _save(_e=None):
            """Save instantly as Preset_NN — no dialog. Rename is a
            right-click away, and a dialog on every save turns a quick
            'keep this' into an interruption."""
            lst = _read()
            nm = self._preset_next_name(lst)
            lst.append({"name": nm, "settings": self._preset_collect(var_map)})
            _write(lst)
            name_var.set(nm)

        def _name_ctx(e):
            """Right-click the name button — edit the current preset.
            Built-ins are skipped: they are not the user's to change."""
            cur = name_var.get()
            if cur == "Presets" or cur in _builtins:
                return
            lst = _read()
            idx = next((i for i, p in enumerate(lst)
                        if p.get("name") == cur), None)
            if idx is None:
                return
            _edit_menu(e.x_root, e.y_root, idx, lst[idx])

        name_btn.bind("<Button-1>", _open_dropdown)
        name_btn.bind("<Button-2>", _name_ctx)
        name_btn.bind("<Button-3>", _name_ctx)
        plus_btn.bind("<Button-1>", _save)
        return name_btn, plus_btn, name_var

    def _build_monitor_calibration_panel(self, parent, s2, bd2):
        """A "does my monitor look right" panel -- purely diagnostic,
        no actual calibration/adjustment function at all. Just the
        classic test patterns people have eyeballed monitors against
        for decades: a PLUGE bar for black-level/brightness, a
        greyscale ramp for banding and overall gamma response, SMPTE
        colour bars for hue/saturation reference, and a chequerboard
        gamma-matching patch (the same idea as a physical Shirley
        card's tonal reference, but generated rather than reproducing
        an actual archival photograph). Generated fresh each time this
        tab builds, at runtime, via PIL -- no embedded image assets to
        keep in sync, and they naturally render at whatever size this
        panel actually has room for."""
        import numpy as np
        from PIL import Image, ImageTk, ImageDraw

        outer = tk.Frame(parent, bg=s2, highlightthickness=1,
                         highlightbackground=bd2)

        # Standard Tk scrollable-frame pattern: a Canvas holding an
        # inner Frame, with scrollregion following the inner frame's
        # actual size, since there are several patterns stacked here.
        cv = tk.Canvas(outer, bg=BG, highlightthickness=0)
        sb = tk.Scrollbar(outer, orient="vertical", command=cv.yview)
        cv.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        cv.pack(side="left", fill="both", expand=True)
        body = tk.Frame(cv, bg=BG)
        _win = cv.create_window((0, 0), window=body, anchor="nw")
        def _on_body_config(e):
            cv.configure(scrollregion=cv.bbox("all"))
        body.bind("<Configure>", _on_body_config)
        def _on_canvas_config(e):
            cv.itemconfig(_win, width=e.width)
        cv.bind("<Configure>", _on_canvas_config)
        def _on_wheel(e):
            cv.yview_scroll(int(-1 * (e.delta / 40)), "units")
        cv.bind_all("<MouseWheel>", _on_wheel, add="+")

        self._sm_calib_imgs = []  # keep PhotoImage refs alive

        def _add_section(title, desc):
            tk.Label(body, text=title, font=("Helvetica-Bold", 12),
                     bg=BG, fg=W, anchor="w").pack(
                fill="x", padx=16, pady=(16, 2))
            tk.Label(body, text=desc, font=FSM, bg=BG, fg=G,
                     anchor="w", justify="left", wraplength=560).pack(
                fill="x", padx=16, pady=(0, 8))

        def _show(pil_img):
            photo = ImageTk.PhotoImage(pil_img)
            self._sm_calib_imgs.append(photo)
            lbl = tk.Label(body, image=photo, bg="black",
                           highlightthickness=1, highlightbackground=bd2)
            lbl.pack(padx=16, pady=(0, 4))
            return lbl

        W_, H_ = 560, 90

        # ── PLUGE: below-black / black / above-black ─────────────────
        _add_section(
            "Black Level (PLUGE)",
            "Classic broadcast pattern. The left and right patches "
            "should be nearly indistinguishable from the black "
            "background -- if you can clearly see the LEFT patch, "
            "brightness is set too high; if you can't see the RIGHT "
            "patch at all, it's set too low.")
        pluge = Image.new("RGB", (W_, H_), (16, 16, 16))
        d = ImageDraw.Draw(pluge)
        bw = W_ // 5
        levels = [4, 16, 16, 16, 28]  # below-black, black, black, black, above-black
        for i, lv in enumerate(levels):
            d.rectangle([i * bw, 0, (i + 1) * bw, H_], fill=(lv, lv, lv))
        _show(pluge)

        # ── Greyscale ramp ────────────────────────────────────────────
        _add_section(
            "Greyscale Ramp",
            "A smooth linear ramp from black to white. Look for even, "
            "gradual brightness with no visible banding or sudden "
            "steps, and check that the far-left stays a true black and "
            "the far-right a true white rather than crushing or "
            "blowing out early.")
        ramp = np.tile(np.linspace(0, 255, W_, dtype=np.uint8), (H_, 1))
        ramp_img = Image.fromarray(np.stack([ramp] * 3, axis=-1), "RGB")
        _show(ramp_img)

        # ── SMPTE-style colour bars ───────────────────────────────────
        _add_section(
            "Colour Bars",
            "Standard reference bars at 75% intensity. Each bar should "
            "read as a clean, distinct hue -- if colours look shifted, "
            "muddy, or two adjacent bars are hard to tell apart, colour "
            "temperature or saturation may be off.")
        bar_colors = [
            (191, 191, 191), (191, 191, 0), (0, 191, 191), (0, 191, 0),
            (191, 0, 191), (191, 0, 0), (0, 0, 191),
        ]
        bars = Image.new("RGB", (W_, H_), (0, 0, 0))
        d = ImageDraw.Draw(bars)
        bw = W_ / len(bar_colors)
        for i, c in enumerate(bar_colors):
            d.rectangle([int(i * bw), 0, int((i + 1) * bw), H_], fill=c)
        _show(bars)

        # ── Gamma-matching chequerboard patches ───────────────────────
        _add_section(
            "Gamma Check",
            "Each square patch is a black/white chequerboard dithered "
            "to average out to a specific grey level; the solid bar "
            "beside it is that same grey level rendered directly. "
            "Viewed from a normal distance (so the dither blurs "
            "together), each chequerboard patch should visually match "
            "its solid neighbour -- a mismatch either way suggests the "
            "display's gamma differs from the standard 2.2.")
        gam_levels = [32, 64, 128, 192, 224]
        patch = 70
        gam = Image.new("RGB", (patch * len(gam_levels) * 2 +
                                 10 * (len(gam_levels) - 1), patch),
                        (16, 16, 16))
        d = ImageDraw.Draw(gam)
        x = 0
        for lv in gam_levels:
            # dithered chequerboard averaging to lv (2.2-gamma matched
            # pair: alternate between the levels that straddle lv in
            # linear light, giving each square a fine checker texture)
            hi = min(255, int(round((2 * (lv / 255.0) ** 2.2) ** (1 / 2.2) * 255)))
            for yy in range(patch):
                for xx in range(patch):
                    v = hi if (xx // 5 + yy // 5) % 2 == 0 else 0
                    gam.putpixel((x + xx, yy), (v, v, v))
            d.rectangle([x + patch + 4, 0, x + 2 * patch + 4, patch],
                       fill=(lv, lv, lv))
            x += 2 * patch + 10
        _show(gam)

        tk.Label(body, text="These are reference images only -- there's "
                 "no calibration or adjustment applied here. If "
                 "something looks off, that's telling you about your "
                 "monitor's own settings, not this app.",
                 font=FSM, bg=BG, fg="#666666", anchor="w",
                 justify="left", wraplength=560).pack(
            fill="x", padx=16, pady=(16, 20))

        return outer

    # ── dithered progress bar ─────────────────────────────────────────
    # A bar that resolves into existence rather than sliding across.
    # Cells light up in Bayer order, so the leading edge is a stipple
    # that condenses into solid rather than a hard line -- which reads
    # as work happening across the whole span rather than a boundary
    # being pushed.

    # Ordered 4x4 Bayer. Its property is that the 16 values are spread
    # as evenly as possible in space AND in order, so at any threshold
    # the lit cells look scattered rather than clustered -- a random
    # matrix would clump and read as noise.
    _BAYER4 = ((0, 8, 2, 10),
               (12, 4, 14, 6),
               (3, 11, 1, 9),
               (15, 7, 13, 5))

    # How many cells the dissolving edge is spread across. Spreading it
    # over ONE column -- the obvious reading of an ordered dither -- put
    # the whole stipple inside a single 3px column, which is invisible:
    # it just looked like a hard edge with a ragged pixel on it. The
    # edge has to be wide enough to actually see resolving.
    _DITHER_EDGE = 9

    @classmethod
    def _dither_lit(cls, col, row, cols, frac, edge=None):
        """Is this cell lit at `frac` (0..1)?

        Cells within `edge` columns of the leading edge light up in
        Bayer order, so the front is a stipple that condenses into solid
        behind it rather than a boundary being pushed along."""
        if cols <= 0:
            return False
        f = min(1.0, max(0.0, float(frac)))
        if f <= 0.0:
            return False
        if f >= 1.0:
            return True
        e = float(cls._DITHER_EDGE if edge is None else edge)
        t = cls._BAYER4[row % 4][col % 4] / 16.0
        return (f * cls._dither_span(cols, e) - col) >= e * t

    @classmethod
    def _dither_span(cls, cols, e):
        """The value f*span must reach for the LAST cell to light.

        Computed as the true maximum over the pattern rather than
        assumed. Two earlier guesses both completed early -- running the
        edge off the end by a full `e` went solid near 0.98, and
        assuming the last cell sits in the final column at the highest
        Bayer threshold was wrong because the matrix phase means it
        usually does not. The real straggler can be several columns
        back, so the maximum is measured over the last repeat of the
        matrix. A progress bar that reads full before it is full is a
        small lie, and this is what it costs to not tell it."""
        return max(c + e * cls._BAYER4[r][c % 4] / 16.0
                   for c in range(max(0, cols - 4), cols)
                   for r in range(4))

    def _dither_bar(self, parent, rows=4, cell=3, pady=(6, 0),
                    show_label=True):
        """Returns an object with .set(frac, text) and .reset().

        The grid is built once and only CHANGED cells are recoloured on
        each update -- redrawing every cell per tick would cost more
        than the work being reported on."""
        holder = tk.Frame(parent, bg=BG)
        holder.pack(fill="x", pady=pady)
        cv = tk.Canvas(holder, bg="#0A0A0A", height=rows * cell,
                       highlightthickness=1, highlightbackground=BD)
        cv.pack(fill="x")
        lbl = tk.Label(holder, text="", font=FM, bg=BG, fg="#666666",
                       anchor="w")

        st = {"cols": 0, "ids": [], "on": [], "frac": 0.0, "shown": False}

        def _build(_e=None):
            # Forces Tk to compute current geometry synchronously
            # rather than trusting whatever winfo_width() last cached.
            # Without this, a canvas built while its parent frame sits
            # hidden behind a grid-stacked sibling (as exr_f_to_mov and
            # exr_f_to_exr are) can report a width of 1 forever -- <8
            # bails every single call, so .set() never draws anything,
            # even once the frame is actually on screen and a
            # conversion is genuinely running.
            cv.update_idletasks()
            w = cv.winfo_width()
            if w < 8:
                return
            cols = max(1, w // cell)
            if cols == st["cols"]:
                return
            cv.delete("all")
            st["cols"] = cols
            st["ids"] = [[None] * cols for _ in range(rows)]
            st["on"] = [[False] * cols for _ in range(rows)]
            for r in range(rows):
                for c in range(cols):
                    st["ids"][r][c] = cv.create_rectangle(
                        c * cell, r * cell, c * cell + cell - 1,
                        r * cell + cell - 1, outline="", fill="#0A0A0A")
            _paint(force=True)

        def _paint(force=False):
            if not st["cols"]:
                return
            f = st["frac"]
            for r in range(rows):
                for c in range(st["cols"]):
                    lit = self._dither_lit(c, r, st["cols"], f)
                    if lit == st["on"][r][c] and not force:
                        continue
                    st["on"][r][c] = lit
                    cv.itemconfigure(st["ids"][r][c],
                                     fill="#CC4444" if lit else "#141414")

        def _set(frac, text=""):
            frac = min(1.0, max(0.0, float(frac)))
            if show_label and not st["shown"]:
                lbl.pack(fill="x", pady=(2, 0))
                st["shown"] = True
            lbl.configure(text=text)
            if st.get("hold"):
                # Standing still while fal holds the job: remember where
                # the bar should be, paint it once the hold lifts.
                st["held_frac"] = frac
                return
            st["frac"] = frac
            _build()
            _paint()

        # ── fal hold ──
        # While the job sits on fal's side (queued, rendering, nothing
        # this app can do to move it on) the bar freezes and fal's mark,
        # in red on black, sits at the end of the lit part: the job is
        # not stuck HERE, it is waiting THERE.
        st["hold"] = False
        st["mark"] = []

        def _draw_mark():
            for cid in st["mark"]:
                cv.delete(cid)
            st["mark"] = []
            if not st["hold"] or not st["cols"]:
                return
            mcell = max(1, (rows * cell) // len(self._FAL_PIXELS))
            mw = len(self._FAL_PIXELS[0]) * mcell
            mh = len(self._FAL_PIXELS) * mcell
            x0 = int(round(st["frac"] * st["cols"])) * cell + 2
            x0 = max(0, min(x0, st["cols"] * cell - mw - 2))
            y0 = max(0, (rows * cell - mh) // 2)
            st["mark"].append(cv.create_rectangle(
                x0 - 3, 0, x0 + mw + 3, rows * cell + 2, outline="",
                fill="#000000"))
            for r, line in enumerate(self._FAL_PIXELS):
                for c, ch in enumerate(line):
                    if ch != "#":
                        continue
                    st["mark"].append(cv.create_rectangle(
                        x0 + c * mcell, y0 + r * mcell,
                        x0 + c * mcell + mcell,
                        y0 + r * mcell + mcell,
                        outline="", fill="#FF2A2A"))   # solid, no gaps

        def _set_hold(on):
            on = bool(on)
            if on == st["hold"]:
                return
            st["hold"] = on
            if on:
                st["held_frac"] = st["frac"]
                _build()
                _paint(force=True)       # drop any shimmer mid-sweep
                _draw_mark()
                return
            _draw_mark()                 # clears it
            st["frac"] = st.get("held_frac", st["frac"])
            _build()
            _paint(force=True)
            if st["pulse"]:
                self.after(60, _pulse_tick)

        def _reset():
            st["pulse"] = False
            if st.get("hold"):
                st["hold"] = False
                _draw_mark()
            st["frac"] = 0.0
            _paint(force=True)
            if st["shown"]:
                lbl.pack_forget()
                st["shown"] = False

        # ── activity pulse ──
        # For a phase with no progress of its own -- waiting on a
        # render that reports nothing until it is done -- a bright band
        # sweeps the part already lit. No cell ever turns off and the
        # fraction never moves, so this says "still working" without
        # claiming advancement. A bar that creeps forward on a timer
        # during the one phase that takes minutes is the one most
        # likely to be believed, and the one most likely to be lying.
        st["pulse"] = False
        st["sweep"] = 0

        def _pulse_tick():
            if not st["pulse"] or not st["cols"]:
                return
            if st.get("hold"):
                # Held on fal: the bar stands still. The tick is simply
                # not rescheduled; release restarts it.
                return
            st["sweep"] = (st["sweep"] + 1) % max(1, st["cols"])
            edge = st["sweep"]
            for r in range(rows):
                for c in range(st["cols"]):
                    if not st["on"][r][c]:
                        continue
                    near = abs(c - edge) <= 2
                    cv.itemconfigure(st["ids"][r][c],
                                     fill="#FF8866" if near else "#CC4444")
            self.after(60, _pulse_tick)

        def _set_pulse(on):
            was = st["pulse"]
            st["pulse"] = bool(on)
            if on and not was:
                self.after(60, _pulse_tick)
            elif not on and not st.get("hold"):
                _paint(force=True)

        def _configure(_e=None):
            _build()
            _draw_mark()

        cv.bind("<Configure>", _configure)

        class _Bar:
            set = staticmethod(_set)
            reset = staticmethod(_reset)
            pulse = staticmethod(_set_pulse)
            hold = staticmethod(_set_hold)
            held = staticmethod(lambda: bool(st["hold"]))
            frac = staticmethod(lambda: st["frac"])   # what is painted
            canvas = cv
        return _Bar

    # fal's mark, 17x17: a rounded square with a notch in each side and
    # a round hole -- one pixel per cell so it fits the bar's height, in
    # red on black.
    _FAL_PIXELS = (
        ".#####.....#####.",
        "#######...#######",
        "#################",
        "#################",
        "#################",
        "#######...#######",
        ".#####.....#####.",
        "..###.......###..",
        "..###.......###..",
        "..###.......###..",
        ".#####.....#####.",
        "#######...#######",
        "#################",
        "#################",
        "#################",
        "#######...#######",
        ".#####.....#####.",
    )

    # ── pixelated robot toggle ────────────────────────────────────────
    # Drawn from a bitmap at the same cell size as the dither bar, so
    # the two read as the same family rather than as an icon borrowed
    # from somewhere else.
    # Eyes and mouth are GAPS in a solid head rather than drawn marks:
    # at three pixels a cell, a drawn feature on a hollow outline turns
    # to mush, while a hole in a solid shape stays legible.
    _ROBOT_PIXELS = (
        ".....#.....",
        ".....#.....",
        "..#######..",
        ".#########.",
        ".##.###.##.",
        ".#########.",
        ".###...###.",
        ".#########.",
        "..#######..",
        "...#...#...",
        "...#...#...",
    )

    def _robot_badge(self, parent, cell=2):
        """Just the pixel glyph, no label, no click handler.

        _robot_toggle draws the same bitmap as part of a full latching
        button; this is the bare glyph for marking a SEPARATE control
        (a dropdown) as currently pointed at something that costs
        money, reusing the one drawing routine rather than a second
        copy of the pixel pattern.

        Returns an object with .set_lit(bool)."""
        rows = len(self._ROBOT_PIXELS)
        cols = len(self._ROBOT_PIXELS[0])
        cv = tk.Canvas(parent, width=cols * cell, height=rows * cell,
                       bg=parent.cget("bg"), highlightthickness=0)
        cells = []
        for r, line in enumerate(self._ROBOT_PIXELS):
            for c, ch in enumerate(line):
                if ch != "#":
                    continue
                cells.append(cv.create_rectangle(
                    c * cell, r * cell, c * cell + cell - 1,
                    r * cell + cell - 1, outline="", fill="#333333"))

        def _set_lit(on):
            fg = "#DDAA44" if on else "#333333"
            for cid in cells:
                cv.itemconfigure(cid, fill=fg)

        class _Badge:
            widget = cv
            set_lit = staticmethod(_set_lit)
        return _Badge

    def _tonemap_badge(self, parent, cell=3):
        """A hockey-stick tone curve glyph, the same footprint as the
        pixel robot (_robot_badge) but drawn as an actual chart rather
        than a bitmap -- the visual distinction between "this app's own
        maths" and "an external model" is deliberate: one is pixelated
        and yellow (spends money), the other is a plotted curve (free,
        local).

        A framing box (a small chart, not a free-floating squiggle), a
        DOTTED horizontal line marking the threshold, and the curve
        itself: a shallow rise up to the threshold -- everything below
        it passes through close to unchanged -- then a sharp corner
        into a steep straight rise for everything above it. That
        visible KINK is the point: it is what "boosted above a
        threshold" actually looks like, which a smooth, continuously-
        bending curve does not read as clearly at this size.

        Returns an object with .set_lit(bool), matching _robot_badge's
        own interface so both can sit in the same button-building
        code."""
        rows = len(self._ROBOT_PIXELS)
        cols = len(self._ROBOT_PIXELS[0])
        w, h = cols * cell, rows * cell
        cv = tk.Canvas(parent, width=w, height=h, bg=parent.cget("bg"),
                       highlightthickness=0)
        margin = max(2, cell)
        knee = 0.6   # matches this app's own default Knee setting

        # The framing box -- a static border, not part of what changes
        # with selection, so the curve stays the one thing the eye
        # reads as "on/off".
        cv.create_rectangle(margin, margin, w - margin, h - margin,
                            outline="#444444", width=1)

        def _xy(t, y):
            return (margin + t * (w - 2 * margin),
                    (h - margin) - y * (h - 2 * margin))

        # Two straight segments meeting at a visible corner, not a
        # smooth blend: a shallow base (values near and below the
        # threshold move very little) then a steep, near-linear rise
        # (the boost applied above it).
        base_y = knee * 0.35

        # The dotted threshold line, at the SAME height the curve's
        # own corner sits at (base_y, not knee -- a horizontal line
        # marks a Y-height, and the only height that means anything
        # here is where the kink actually is). Drawn first so the
        # curve sits visually on top of it.
        _, ty = _xy(0.0, base_y)
        thresh_id = cv.create_line(margin, ty, w - margin, ty,
                                   dash=(2, 2), width=1, fill="#333333")

        pts = []
        pts.extend(_xy(0.0, 0.0))
        pts.extend(_xy(knee, base_y))
        pts.extend(_xy(1.0, 1.0))
        curve_id = cv.create_line(*pts, width=2, fill="#333333",
                                  joinstyle="miter")

        def _set_lit(on):
            colour = "#DDAA44" if on else "#333333"
            cv.itemconfigure(curve_id, fill=colour)
            cv.itemconfigure(thresh_id, fill=colour)

        class _Badge:
            widget = cv
            set_lit = staticmethod(_set_lit)
        return _Badge

    def _robot_toggle(self, parent, text, command, cell=3):
        """A latching button: pixel robot, then a label.

        Returns an object with .set(on) and .get(). Latching rather than
        momentary because it selects a MODE -- and a mode control that
        does not show its state is how people run a job twice before
        noticing which one they ran."""
        st = {"on": False}
        wrap = tk.Frame(parent, bg=S2, highlightthickness=1,
                        highlightbackground=BD, cursor="hand2")
        wrap.pack(fill="x", pady=(4, 0))
        rows = len(self._ROBOT_PIXELS)
        cols = len(self._ROBOT_PIXELS[0])
        cv = tk.Canvas(wrap, width=cols * cell, height=rows * cell,
                       bg=S2, highlightthickness=0)
        cv.pack(side="left", padx=10, pady=7)
        cells = []
        for r, line in enumerate(self._ROBOT_PIXELS):
            for c, ch in enumerate(line):
                if ch != "#":
                    continue
                cells.append(cv.create_rectangle(
                    c * cell, r * cell, c * cell + cell - 1,
                    r * cell + cell - 1, outline="", fill=G))
        lbl = tk.Label(wrap, text=text, font=FSM, bg=S2, fg=G, anchor="w")
        lbl.pack(side="left", fill="x", expand=True, pady=7)

        def _paint():
            on = st["on"]
            bg = "#2A1A00" if on else S2
            fg = "#DDAA44" if on else G
            wrap.configure(bg=bg, highlightbackground="#DDAA44" if on else BD)
            cv.configure(bg=bg)
            lbl.configure(bg=bg, fg=fg)
            for cid in cells:
                cv.itemconfigure(cid, fill=fg)

        def _set(on):
            st["on"] = bool(on)
            _paint()

        def _click(_e=None):
            _set(not st["on"])
            if command:
                command(st["on"])

        for w in (wrap, cv, lbl):
            w.bind("<Button-1>", _click)
        _paint()

        class _Toggle:
            set = staticmethod(_set)
            get = staticmethod(lambda: st["on"])
        return _Toggle

    def _picker(self, parent, text):
        f = tk.Frame(parent, bg=S2, highlightthickness=1, highlightbackground=BD, highlightcolor=BD)
        f.pack(fill="x")
        l = tk.Label(f, text=text, font=FSM, bg=S2, fg=G, pady=11, cursor="hand2")
        l.pack(fill="x")
        return f, l

    # ── macOS-SAFE BUTTON ─────────────────────────────────────────────
    # tk.Button ignores bg on macOS Aqua.  Frame + Label always shows the
    # right colour.  The returned frame has a .configure() shim that handles
    # state / text / bg / fg just like a real Button.
    def _mkbtn(self, parent, text, cmd, bg="#0D0D0D", fg=W):
        f = tk.Frame(parent, cursor="hand2")
        tk.Frame.configure(f, bg=bg)
        l = tk.Label(f, text=text, font=FSM, cursor="hand2", anchor="center")
        tk.Label.configure(l, bg=bg, fg=fg, pady=8, padx=10, width=13)
        l.pack(fill="both", expand=True)

        _st = {"on": True, "bg": bg, "fg": fg, "cmd": cmd}

        def _enter(e):
            if _st["on"]:
                tk.Frame.configure(f, bg="#1E1E1E")
                tk.Label.configure(l, bg="#1E1E1E")

        def _leave(e):
            tk.Frame.configure(f, bg=_st["bg"])
            tk.Label.configure(l,  bg=_st["bg"])

        def _click(e):
            if _st["on"] and _st["cmd"]:
                _st["cmd"]()

        for w in (f, l):
            w.bind("<Enter>", _enter)
            w.bind("<Leave>", _leave)
            w.bind("<Button-1>", _click)

        def configure(**kw):
            if "state" in kw:
                enabled = kw["state"] == "normal"
                _st["on"] = enabled
                nb  = _st["bg"] if enabled else "#090909"
                nfg = _st["fg"] if enabled else "#333333"
                nc  = "hand2" if enabled else "arrow"
                tk.Frame.configure(f, bg=nb, cursor=nc)
                tk.Label.configure(l, bg=nb, fg=nfg, cursor=nc)
            if "text" in kw:
                tk.Label.configure(l, text=kw["text"])
            if "bg" in kw:
                _st["bg"] = kw["bg"]
                tk.Frame.configure(f, bg=kw["bg"])
                tk.Label.configure(l, bg=kw["bg"])
            if "fg" in kw:
                _st["fg"] = kw["fg"]
                tk.Label.configure(l, fg=kw["fg"])
            if "command" in kw:
                _st["cmd"] = kw["command"]

        f.configure = configure
        f._lbl = l
        f._st  = _st
        return f

    def _mk_progress_btn(self, parent, text, cmd, bg="#0D0D0D", fg="#555555",
                          fill_color="#5A1414", dim_fill_color="#3A1414"):
        """Like _mkbtn, but with an integrated left-to-right progress
        fill drawn directly on the button's own background, instead
        of relying on a separate progress bar elsewhere. Built on a
        bare Canvas, since Tkinter has no native way to partially
        fill a widget's background -- a Frame+Label can only ever be
        one solid colour at a time. Same configure(text=...,
        command=..., bg=..., fg=...) interface as _mkbtn, plus
        configure(progress=0.0-1.0). fill_color/dim_fill_color let
        different callers use a colour other than the default dark
        red (e.g. green, to match a different part of the UI)."""
        cv = tk.Canvas(parent, height=34, highlightthickness=0,
                        bg=bg, cursor="hand2")
        _st = {"on": True, "bg": bg, "fg": fg, "cmd": cmd,
               "progress": 0.0, "text": text,
               "fill": fill_color, "dim_fill": dim_fill_color}
        _fill = cv.create_rectangle(0, 0, 0, 0, fill=fill_color, outline="")
        _txt  = cv.create_text(0, 0, text=text, font=FSM, fill=fg, anchor="center")

        def _redraw(*_):
            w = cv.winfo_width() or 200
            h = cv.winfo_height() or 34
            tk.Canvas.itemconfig(cv, _fill,
                fill=_st["fill"] if _st["on"] else _st["dim_fill"])
            cv.coords(_fill, 0, 0, int(w * _st["progress"]), h)
            cv.coords(_txt, w/2, h/2)
            cv.itemconfig(_txt, text=_st["text"],
                fill=(_st["fg"] if _st["on"] else "#333333"))
            tk.Canvas.configure(cv, bg=_st["bg"])

        def _enter(e):
            if _st["on"]:
                tk.Canvas.configure(cv, bg="#1E1E1E")
        def _leave(e):
            tk.Canvas.configure(cv, bg=_st["bg"])
        def _click(e):
            if _st["on"] and _st["cmd"]:
                _st["cmd"]()

        cv.bind("<Enter>", _enter)
        cv.bind("<Leave>", _leave)
        cv.bind("<Button-1>", _click)
        cv.bind("<Configure>", _redraw)

        def configure(**kw):
            if "state" in kw:
                _st["on"] = kw["state"] == "normal"
                cv.configure_native(cursor="hand2" if _st["on"] else "arrow")
            if "text" in kw: _st["text"] = kw["text"]
            if "command" in kw: _st["cmd"] = kw["command"]
            if "bg" in kw: _st["bg"] = kw["bg"]
            if "fg" in kw: _st["fg"] = kw["fg"]
            if "progress" in kw: _st["progress"] = max(0.0, min(1.0, kw["progress"]))
            _redraw()

        cv.configure_native = lambda **kw: tk.Canvas.configure(cv, **kw)
        cv.configure = configure
        cv._st = _st
        _redraw()
        return cv

    def _maximise_window(self):
        """Open the window maximised to fill the screen. Tk has no single
        cross-platform maximise, so try the known mechanisms in order and
        fall back to sizing geometry to the screen. macOS (Aron's build)
        has no 'zoomed' state, so there the geometry fallback does the
        work; Windows/Linux use the native zoomed state."""
        import sys
        try:
            # Windows and most Linux WMs
            self.state("zoomed")
            self.update_idletasks()
            if self.winfo_width() > 1200:
                return
        except Exception:
            pass
        try:
            # Many Linux window managers
            self.attributes("-zoomed", True)
            self.update_idletasks()
            if self.winfo_width() > 1200:
                return
        except Exception:
            pass
        # Fallback (incl. macOS): size to the screen work area, leaving a
        # small margin and offsetting for the menu bar / dock.
        try:
            sw = self.winfo_screenwidth()
            sh = self.winfo_screenheight()
            margin_top = 40 if sys.platform == "darwin" else 0
            w = sw
            h = max(760, sh - margin_top)
            self.geometry(f"{w}x{h}+0+{margin_top}")
        except Exception:
            pass

    def _mk_scrollbar(self, parent, target, width=14):
        """Custom Canvas-based scrollbar matching the app's dark-red style.

        Replaces tk.Scrollbar everywhere: the macOS Aqua backend ignores
        bg/color kwargs on the native widget so it always renders system-
        white regardless of what's set. This gives full control.

        Usage:
            # For a Text widget:
            t = tk.Text(frame, ...)
            t.pack(side="left", fill="both", expand=True)
            self._mk_scrollbar(frame, t).pack(side="right", fill="y")

            # For a Canvas widget:
            cv = tk.Canvas(frame, ...)
            cv.pack(side="left", fill="both", expand=True)
            self._mk_scrollbar(frame, cv).pack(side="right", fill="y")

        Returns the scrollbar Canvas widget (already configured and bound;
        the caller just needs to pack/grid it).
        """
        SB_BG    = "#0D0D0D"
        SB_THUMB = "#7A1A1A"   # dark red at rest
        SB_HOVER = "#CC4444"   # bright red on hover
        SB_MIN_H = 20

        sb = tk.Canvas(parent, width=width, bg=SB_BG,
                       highlightthickness=0, cursor="arrow")
        _st = {"top": 0.0, "bot": 1.0, "drag": None, "hover": False}

        def _draw():
            h = sb.winfo_height() or 200
            tt = max(0, int(_st["top"] * h))
            tb = min(h, max(tt + SB_MIN_H, int(_st["bot"] * h)))
            sb.delete("all")
            sb.create_rectangle(0, 0, width, h, fill=SB_BG, outline="")
            col = SB_HOVER if _st["hover"] else SB_THUMB
            r = 3
            if tb - tt >= 2 * r:
                sb.create_rectangle(r, tt, width - r, tb, fill=col, outline="")
                sb.create_rectangle(0, tt + r, width, tb - r, fill=col, outline="")
                for ty in (tt, tb - 2 * r):
                    sb.create_oval(0, ty, 2*r, ty+2*r, fill=col, outline="")
                    sb.create_oval(width-2*r, ty, width, ty+2*r, fill=col, outline="")
            else:
                sb.create_rectangle(0, tt, width, tb, fill=col, outline="")

        def _set(top, bot):
            _st["top"] = float(top); _st["bot"] = float(bot); _draw()

        def _press(e):
            h = sb.winfo_height() or 200
            tt = max(0, int(_st["top"] * h))
            tb = min(h, max(tt + SB_MIN_H, int(_st["bot"] * h)))
            if tt <= e.y <= tb:
                _st["drag"] = e.y - tt
            else:
                target.yview_moveto(e.y / h)

        def _motion(e):
            if _st["drag"] is None: return
            h = sb.winfo_height() or 200
            target.yview_moveto(max(0.0, (e.y - _st["drag"]) / h))

        def _wheel(e):
            target.yview_scroll(int(-1 * (e.delta / 120)), "units")

        sb.bind("<ButtonPress-1>",  _press)
        sb.bind("<B1-Motion>",      _motion)
        sb.bind("<ButtonRelease-1>", lambda e: _st.update(drag=None))
        sb.bind("<Enter>",  lambda e: (_st.update(hover=True),  _draw()))
        sb.bind("<Leave>",  lambda e: (_st.update(hover=False), _draw()))
        sb.bind("<Configure>", lambda e: _draw())
        sb.bind("<MouseWheel>", _wheel)
        sb.bind("<Button-4>", lambda e: target.yview_scroll(-2, "units"))
        sb.bind("<Button-5>", lambda e: target.yview_scroll(2, "units"))

        target.configure(yscrollcommand=_set)
        return sb

    # ── SHARED PREVIEW-FRAME CACHE (Curve / Area modules) ─────────────
    # Both paint modules decoded EXRs by spawning ffmpeg on EVERY frame
    # change -- and Area Look additionally re-decoded its reference frame
    # on every slider tweak. On 4K EXRs that's 0.5-1.5s per interaction.
    # This LRU caches the decoded PIL frames keyed by (path, mtime); the
    # decode itself on a miss is byte-identical to the old inline code
    # (same ffmpeg reinhard call), so appearance is unchanged -- only
    # the repeat cost disappears.
    _PV_CACHE_BUDGET = 500 * 1024 * 1024   # ~500 MB of decoded frames

    def _pv_frame(self, path):
        """Decoded PIL RGB for any frame (EXR via ffmpeg), LRU-cached."""
        from PIL import Image
        import collections
        if not hasattr(self, "_pv_lru"):
            self._pv_lru = collections.OrderedDict()
            self._pv_lru_bytes = 0
        try: mt = os.path.getmtime(path)
        except OSError: mt = 0
        key = (path, mt)
        lru = self._pv_lru
        if key in lru:
            lru.move_to_end(key)
            return lru[key]
        ext = os.path.splitext(path)[1].lower()
        cs_tag = (self._adw_read_colorspace(os.path.dirname(path))
                 if ext == ".exr" else None)
        if ext == ".exr" and cs_tag is not None:
            # A sidecar left by one of this app's OWN writers (ADW-
            # Organic, Upscale & Expand, and now MOV -> EXR) says
            # definitively whether this sequence is scene-linear or
            # already display-encoded -- real evidence, unlike the
            # tonemap=reinhard guess in the branch below.
            # tonemap=reinhard is an HDR-to-SDR COMPRESSOR, not an
            # OETF: it does nothing to gamma-encode ordinary linear
            # data for display, which is why a genuinely linear EXR
            # from this app's own MOV -> EXR conversion showed
            # "extremely dark" here, with no sidecar to correct it.
            #
            # Every EXR this branch has ever handled until now has no
            # sidecar at all, so this only changes behaviour for
            # output this app tags itself -- everything else falls
            # through to the unchanged ffmpeg path below exactly as
            # before.
            arr = self._ff_read_frame(path)
            if arr is not None:
                if cs_tag == "scene-linear":
                    disp = self._organic_linear_to_display(arr)
                else:
                    import numpy as _np_pv
                    disp = (_np_pv.clip(arr, 0.0, 1.0) * 255.0
                           + 0.5).astype(_np_pv.uint8)
                img = Image.fromarray(disp, "RGB")
            else:
                img = None   # unreadable -- fall through below
        else:
            img = None
        if img is None and ext == ".exr":
            import tempfile
            tf = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
            tf.close()
            r = subprocess.run(
                ["ffmpeg", "-y", "-i", path, "-vf", "tonemap=reinhard",
                 tf.name], capture_output=True)
            if r.returncode != 0:
                subprocess.run(["ffmpeg", "-y", "-i", path, tf.name],
                               capture_output=True)
            img = Image.open(tf.name).convert("RGB")
            img.load()
            try: os.unlink(tf.name)
            except OSError: pass
        elif img is None:
            img = Image.open(path).convert("RGB")
            img.load()
        nbytes = img.size[0] * img.size[1] * 3
        lru[key] = img
        self._pv_lru_bytes += nbytes
        while self._pv_lru_bytes > self._PV_CACHE_BUDGET and len(lru) > 1:
            _, old = lru.popitem(last=False)
            self._pv_lru_bytes -= old.size[0] * old.size[1] * 3
        return img

    def _pv_gray(self, path):
        """Grayscale numpy of a frame for tracking, cached separately
        (1 byte/px, cheap to keep many)."""
        import numpy as np, cv2
        if not hasattr(self, "_pv_gray_lru"):
            import collections
            self._pv_gray_lru = collections.OrderedDict()
        try: mt = os.path.getmtime(path)
        except OSError: mt = 0
        key = (path, mt)
        g = self._pv_gray_lru
        if key in g:
            g.move_to_end(key)
            return g[key]
        rgb = np.array(self._pv_frame(path))
        gray = cv2.cvtColor(rgb, cv2.COLOR_RGB2GRAY)
        g[key] = gray
        while len(g) > 64:
            g.popitem(last=False)
        return gray

    def _pv_prefetch(self, folder, frames, idx):
        """Warm the cache with the frames around idx in a background
        thread, so stepping to the next/previous frame is instant."""
        import threading
        if getattr(self, "_pv_prefetching", False):
            return
        targets = []
        for off in (1, -1, 2, -2, 3, -3, 4, -4):
            j = idx + off
            if 0 <= j < len(frames):
                targets.append(os.path.join(folder, frames[j]))
        if not targets:
            return
        self._pv_prefetching = True
        def _go():
            try:
                for p in targets:
                    self._pv_frame(p)
            except Exception:
                pass
            finally:
                self._pv_prefetching = False
        threading.Thread(target=_go, daemon=True).start()

    def _runbtn(self, parent, text, cmd):
        b = self._mkbtn(parent, text.upper(), cmd, bg="#2A0A0A", fg="#CC4444")
        tk.Label.configure(b._lbl, width=0, pady=9, padx=0)
