    def _logw(self, parent, label="Activity Log"):
        tk.Label(parent, text=label, font=FSM, bg=BG, fg=G).pack(
            anchor="w", padx=16, pady=(10, 2))
        f = tk.Frame(parent, bg=S2, highlightthickness=1, highlightbackground=BD, highlightcolor=BD)
        f.pack(fill="both", expand=True, padx=16, pady=(0, 10))
        t = tk.Text(f, bg=S2, fg=G, font=FM, bd=0, highlightthickness=0,
                    wrap="word", state="disabled", padx=8, pady=6)
