    def _path_bar(self, parent):
        """Small dark bar showing the current input path."""
        f = tk.Frame(parent, bg="#090909",
                     highlightthickness=1, highlightbackground=BD)
        f.pack(fill="x", padx=16, pady=(6, 0))
        lbl = tk.Label(f, text="No file selected", font=FM,
                       bg="#090909", fg="#444444", anchor="w",
                       padx=8, pady=4)
        lbl.pack(fill="x")
        return lbl

    def _jump_btn_widget(self, parent, path_fn):
        """Button that opens the output folder; hidden until run completes."""
        b = self._mkbtn(parent, "⇢  Open output folder",
                        lambda: self._reveal(path_fn()),
                        bg="#0D0D0D", fg=G)
        tk.Label.configure(b._lbl, width=0, pady=6)
        b.pack(fill="x", padx=16, pady=(2, 4))
        b._st["on"] = False
        tk.Frame.configure(b, cursor="arrow")
        tk.Label.configure(b._lbl, fg="#333333", cursor="arrow")
        return b

    # ── TAB: MOV ↔ EXR ───────────────────────────────────────────────
    def _ev_toolbar(self, parent, ev_var, gm_var, redraw_fn=None):
        """Add Exposure + Gamma sliders at bottom of a canvas pane."""
        bar = tk.Frame(parent, bg="#181818")
        bar.pack(fill="x", side="bottom", padx=16, pady=(0, 4))
        _sl = dict(orient="horizontal", bg="#181818", fg="#888888",
                   troughcolor="#2A2A2A", highlightthickness=0,
                   bd=0, showvalue=False, activebackground="#555555")
        tk.Label(bar, text="Exposure", font=FM, bg="#181818",
                 fg="#888888").pack(side="left", padx=(6,2))
        ev_lbl = tk.Label(bar, text=f"{ev_var.get():+.1f}",
                          font=FM, bg="#181818", fg="#AAAAAA", width=4)
        ev_lbl.pack(side="left")
        def _upd_ev(*_):
            ev_lbl.configure(text=f"{ev_var.get():+.1f}")
        ev_var.trace_add("write", _upd_ev)
        # +-5 stops: an expansion puts detail many stops above display
        # white, and +-3 could not stop down far enough to see the top
        # of it. Sliders stretch with the viewer (never shorter than
        # 240px) so a stop is a usable distance to drag.
        tk.Scale(bar, variable=ev_var, from_=-5.0, to=5.0,
                 resolution=0.1, length=240, **_sl).pack(
                     side="left", padx=(0,10), fill="x", expand=True)
        tk.Label(bar, text="Gamma", font=FM, bg="#181818",
                 fg="#888888").pack(side="left", padx=(0,2))
        gm_lbl = tk.Label(bar, text=f"{gm_var.get():.2f}",
                          font=FM, bg="#181818", fg="#AAAAAA", width=4)
        gm_lbl.pack(side="left")
        def _upd_gm(*_):
            gm_lbl.configure(text=f"{gm_var.get():.2f}")
        gm_var.trace_add("write", _upd_gm)
        tk.Scale(bar, variable=gm_var, from_=0.2, to=3.0,
                 resolution=0.05, length=240, **_sl).pack(
                     side="left", fill="x", expand=True)
        def _run_ev(label="Applying…"):
            if not redraw_fn: return
            # Animate progress 0→1 in steps, do work at midpoint
            steps = 12; interval = 30
            def _step(i):
                if i <= steps // 2:
                    self.progress(i / steps, label)
                    if i == steps // 2:
                        self.update_idletasks()
                        redraw_fn()
                    self.after(interval, lambda: _step(i + 1))
                elif i <= steps:
                    self.progress(i / steps, label)
                    self.after(interval, lambda: _step(i + 1))
                else:
                    self.after(200, lambda: self.progress(-1))
            _step(0)

        _calc = self._mkbtn(bar, "Calculate",
            lambda: _run_ev("Applying exposure / gamma…"),
            bg="#2A0A0A", fg="#CC4444")
        tk.Label.configure(_calc._lbl, width=0, pady=3, padx=8)
        _calc.pack(side="left", padx=(8,4))
        _rst = self._mkbtn(bar, "Reset",
            lambda: (ev_var.set(0.0), gm_var.set(1.0),
                     _run_ev("Resetting to neutral…")),
            bg="#2A0A0A", fg="#CC4444")
        tk.Label.configure(_rst._lbl, width=0, pady=3, padx=8)
        _rst.pack(side="left", padx=(0,4))
        return bar

    def _apply_ev_gamma(self, arr_u8, ev, gamma):
        """Apply exposure (stops) and gamma to a uint8 RGB/RGBA numpy array."""
        import numpy as np
        a = arr_u8.astype(np.float32) / 255.0
        a = np.clip(a * (2.0 ** ev), 0, 1)
        if gamma != 1.0:
            a = np.power(np.clip(a, 1e-6, 1.0), 1.0 / gamma)
        return np.clip(a * 255, 0, 255).astype(np.uint8)

    def _apply_ev_gamma_float(self, arr, ev, gamma, peak=1.0):
        """Exposure and gamma on FLOAT data, clipped only at the end.

        The uint8 version above divides by 255 and clips to 0..1 before
        anything else, so stopping down on it reveals nothing: the
        highlights were destroyed by the 8-bit quantise long before the
        exposure was applied. That is exactly why the slider felt dead
        while testing an expansion -- the whole point of which is the
        detail living ABOVE 1.0.

        `peak` normalises the incoming range, so nits from an expansion
        can be viewed against the display white they were expanded
        from."""
        import numpy as np
        a = np.asarray(arr, dtype=np.float32)
        if peak and peak != 1.0:
            a = a / float(peak)
        a = np.clip(a * (2.0 ** float(ev)), 0.0, 1.0)
        # Display encode. This was missing, and its absence is what made
        # the expanded side dark with crushed blacks: the data here is
        # LINEAR LIGHT, and writing linear values straight to 8-bit
        # shows 18% grey at code 46 instead of 118. The uint8 sibling
        # needs no curve because its input is already encoded -- which
        # is exactly why copying its shape was wrong.
        a = self._linear_to_srgb(a)
        if gamma != 1.0:
            a = np.power(np.clip(a, 1e-6, 1.0), 1.0 / float(gamma))
        return (a * 255.0 + 0.5).astype(np.uint8)

    @staticmethod
    def _linear_to_srgb(a):
        """sRGB OETF on 0..1 float, staying in float.

        The piecewise form, not a plain 1/2.2 power: the linear segment
        near black is the whole difference between lifted shadows and
        correct ones, and shadows are where this was being judged."""
        import numpy as np
        a = np.clip(np.asarray(a, dtype=np.float32), 0.0, 1.0)
        return np.where(a <= 0.0031308, a * 12.92,
                        1.055 * np.power(np.maximum(a, 1e-8), 1.0 / 2.4)
                        - 0.055).astype(np.float32)

    def _exr_redraw_preview(self):
        """What "Calculate" and "Reset" on the Exposure/Gamma toolbar
        actually call -- and, now, what dragging either slider calls
        directly too, for live feedback rather than a value that only
        moves once a separate button is pressed.

        If a source has been picked, this re-applies the CURRENT
        slider values to its stored representative linear frame and
        redraws BOTH the preview and the histogram from the result.

        The histogram call here matters specifically:
        _e2m_sample_and_draw_histogram RECOMPUTES the channel counts
        from the current exposure before drawing; the plain
        _exr_draw_histogram only redraws whatever was already stored,
        from whenever the source was first picked. Calling the latter
        here was the exact bug -- the preview visibly changed (it
        always recomputes fresh) while the histogram sat on stale
        data, looking like exposure was not doing anything real."""
        if self._exr_use_m2e():
            # MOV -> EXR: the stored frame, re-shown at the new exposure
            self._e2m_draw_preview()
            self._exr_draw_histogram()
            return
        lin = getattr(self, "_e2m_lin", None)
        if lin is not None:
            self._e2m_draw_preview()
            self._e2m_sample_and_draw_histogram()
        else:
            self._exr_draw_histogram()

    # Class-level defaults: read before the tab builds them.
    exr_mode = "to_exr"
    _m2e = None
    _exr_clip_on = False
    exr_freq_canvas = None
    exr_clip_lbl = None
    exr_view_lbl = None
    _exr_view_cache = None

    def _exr_use_m2e(self):
        """Is the viewer showing the MOV -> EXR frame (rather than the
        EXR -> MOV / transcode source)?"""
        return self.exr_mode == "to_exr" and self._m2e is not None

    def _exr_view_data(self):
        """(vals, disp) for whatever the viewer is on: `vals` the float
        RGB the analysis reads -- for MOV -> EXR the exact values the
        file will hold -- and `disp` the 8-bit picture. (None, None)
        with nothing loaded."""
        import numpy as np
        if self._exr_use_m2e():
            m = self._m2e
            vals = m["vals"]
            if m["display"]:
                disp = (np.clip(vals, 0.0, 1.0) * 255.0 + 0.5).astype(np.uint8)
            else:
                lin = m["lin709"]
                disp = self._e2m_exposed_display(lin)
            return vals, disp
        lin = getattr(self, "_e2m_lin", None)
        if lin is None:
            return None, None
        ev = float(self.exr_ev_var.get()) if hasattr(self, "exr_ev_var") else 0.0
        vals = np.asarray(lin, np.float32) * (2.0 ** ev)
        disp = self._e2m_exposed_display(lin)
        return vals, disp

    @staticmethod
    def _clip_overlay(vals, disp):
        """Clipping view: the picture dimmed to grey, with every pixel
        the file holds ABOVE 1.0 in red and every pixel AT OR BELOW 0 in
        blue (both: white). Any channel counts -- one clipped channel is
        a clipped pixel. Returns (rgb8, fraction above, fraction below)."""
        import numpy as np
        v = np.asarray(vals, np.float32)
        over = (v > 1.0).any(axis=2)
        under = (v <= 0.0).any(axis=2)
        g = np.asarray(disp, np.float32) @ np.array(
            [0.2126, 0.7152, 0.0722], np.float32)
        out = np.repeat((g * 0.35 + 18.0)[:, :, None], 3, 2)
        out[under] = (40, 110, 255)
        out[over] = (255, 40, 40)
        out[over & under] = (255, 255, 255)
        n = float(over.size) or 1.0
        return (np.clip(out, 0, 255).astype(np.uint8),
                float(over.sum()) / n, float(under.sum()) / n)

    def _exr_toggle_clip(self):
        self._exr_clip_on = not self._exr_clip_on
        try:
            self.exr_clip_btn.configure(
                bg="#2A0A0A" if self._exr_clip_on else "#0D0D0D",
                fg="#CC4444" if self._exr_clip_on else G)
        except Exception:
            pass
        self._e2m_draw_preview()

    def _exr_reset_sash(self):
        """Viewer on top, graphs and log at their own heights below --
        so the log is on screen however short the window is."""
        try:
            vp = self._exr_vpaned
            vp.update()
            total = vp.winfo_height()
            if total > 320:
                log_h, graph_h = 140, 150
                vp.sash_place(1, 0, total - log_h)
                vp.sash_place(0, 0, max(120, total - log_h - graph_h))
            self._e2m_draw_preview()
        except Exception:
            pass

    def _e2m_draw_preview(self):
        """Draw the viewer: the picture at the current exposure/gamma,
        or -- with Clipping on -- the clipping view of it. For MOV ->
        EXR the frame is the one the conversion will write; otherwise
        the source's representative linear frame."""
        from PIL import Image, ImageTk
        cv = getattr(self, "e2m_preview_canvas", None)
        if cv is None:
            return
        if getattr(self, "exr_mode", "to_exr") == "cut":
            self._cut_draw_preview()
            return
        lin = getattr(self, "_e2m_lin", None)
        m2e = self._exr_use_m2e()
        cv.delete("all")
        if lin is None and not m2e:
            cv.update_idletasks()
            cw = cv.winfo_width() or 400
            ch = cv.winfo_height() or 180
            cv.create_text(cw // 2, ch // 2,
                text="Select a source to see a preview", font=FSM, fill=G)
            self._exr_set_view_labels(None)
            return
        if m2e:
            vals, disp = self._exr_view_data()
        else:
            disp = self._e2m_exposed_display(lin)
            vals = None
        stats = None
        if self._exr_clip_on or m2e:
            if vals is None:
                vals, _d = self._exr_view_data()
            clip, fo, fu = self._clip_overlay(vals, disp)
            stats = (fo, fu)
            if self._exr_clip_on:
                disp = clip
        self._exr_set_view_labels(stats)
        cv.update_idletasks()
        cw = cv.winfo_width() or 400
        ch = cv.winfo_height() or 180
        h, w = disp.shape[:2]
        scale = min(cw / w, ch / h, 1.0) if w and h else 1.0
        img = Image.fromarray(disp)
        if scale < 1.0:
            img = img.resize((max(1, int(w * scale)), max(1, int(h * scale))))
        tkimg = ImageTk.PhotoImage(img)
        self._e2m_preview_img = tkimg   # keep a reference or Tk drops it
        cv.create_image(cw // 2, ch // 2, image=tkimg, anchor="center")
        if self._exr_clip_on:
            cv.create_text(8, 8, anchor="nw", font=FM, fill="#FF5050",
                           text="\u25a0 above 1.0")
            cv.create_text(8, 24, anchor="nw", font=FM, fill="#5A8CFF",
                           text="\u25a0 at or below 0")

    def _exr_set_view_labels(self, stats):
        try:
            if self.exr_view_lbl is not None:
                if self._exr_use_m2e():
                    txt = "Preview  \u2014  " + self._m2e["desc"]
                else:
                    txt = "Preview  (exposure and target applied)"
                self.exr_view_lbl.configure(text=txt)
            if self.exr_clip_lbl is not None:
                if stats is None:
                    self.exr_clip_lbl.configure(text="")
                else:
                    fo, fu = stats
                    self.exr_clip_lbl.configure(
                        text=f">1: {fo * 100:.2f}%  \u00b7  "
                             f"\u22640: {fu * 100:.2f}%",
                        fg="#DDAA44" if (fo > 0 or fu > 0) else "#777777")
        except Exception:
            pass

    # ── MOV -> EXR preview ──
    @staticmethod
    def _m2e_filter(csp, out_choice):
        """(vf, want_linear, want_aces) for a MOV -> EXR conversion --
        the same decision _erun makes, so the preview shows the values
        the run will write."""
        out_choice = out_choice or "Scene-linear"
        want_aces = out_choice.startswith("ACES2065-1")
        want_linear = want_aces or out_choice.startswith("Scene-linear")
        if not want_linear:
            vf = ""
        elif "Rec.709" in csp or (want_aces and "sRGB" not in csp):
            vf = "zscale=tin=709:t=linear:rangein=limited:range=full"
        elif "sRGB" in csp:
            vf = "zscale=tin=iec61966-2-1:t=linear:range=full"
        else:
            vf = ""
        return vf, want_linear, want_aces

    def _m2e_frame_values(self, path, csp, out_choice, depth, at=None):
        """One frame of `path` as the conversion would write it: float
        RGB, values untouched (above 1.0 and below 0 included)."""
        import numpy as np
        import tempfile, shutil as _sh
        vf, want_linear, want_aces = self._m2e_filter(csp, out_choice)
        tmp = tempfile.mkdtemp(prefix="m2e_pv_")
        try:
            if at is None:
                try:
                    dur = float(self._x264_probe(path).get("duration") or 0.0)
                except Exception:
                    dur = 0.0
                at = max(0.0, dur / 2.0)
            seek = ["-ss", f"{at:.3f}"] if at > 0 else []
            if "8-bit" in depth:
                png = os.path.join(tmp, "f.png")
                r = subprocess.run(["ffmpeg", "-y", "-v", "error"] + seek
                                   + ["-i", path, "-frames:v", "1",
                                      "-pix_fmt", "rgb24", png],
                                   capture_output=True)
                if not os.path.exists(png):
                    raise RuntimeError(
                        r.stderr.decode("utf-8", "replace")[-200:]
                        or "ffmpeg wrote no frame")
                from PIL import Image
                img = np.asarray(Image.open(png).convert("RGB"),
                                 np.float32) / 255.0
                lin = (np.power(np.maximum(img, 0), 2.2).astype(np.float32)
                       if want_linear else img)
            else:
                exr = os.path.join(tmp, "f.exr")
                cmd = ["ffmpeg", "-y", "-v", "error"] + seek + ["-i", path]
                if vf:
                    cmd += ["-vf", vf]
                cmd += ["-frames:v", "1", "-pix_fmt", "gbrpf32le", exr]
                r = subprocess.run(cmd, capture_output=True)
                if not os.path.exists(exr):
                    raise RuntimeError(
                        r.stderr.decode("utf-8", "replace")[-200:]
                        or "ffmpeg wrote no frame")
                lin = np.asarray(self._ff_read_frame(exr), np.float32)
                want_linear = bool(vf)
        finally:
            _sh.rmtree(tmp, ignore_errors=True)
        vals = self._lin709_to_aces(lin) if want_aces else lin
        desc = ("ACES2065-1" if want_aces else
                "scene-linear" if want_linear else "display-encoded")
        return {"vals": vals, "lin709": lin, "display": not want_linear,
                "aces": want_aces,
                "desc": f"frame at {at:.1f}s as written ({desc})"}

    def _m2e_refresh_preview(self):
        """(Re)make the MOV -> EXR preview frame, off the UI thread.
        Called when a movie is picked and whenever Input space, Output
        or Bit depth changes."""
        path = getattr(self, "exr_file", None)
        if not path or not os.path.isfile(str(path)):
            return
        csp, out_choice, depth = (self.exr_csp_var.get(),
                                  self.exr_out_var.get(),
                                  self.exr_depth_var.get())
        self._m2e_seq = getattr(self, "_m2e_seq", 0) + 1
        seq = self._m2e_seq

        def go():
            try:
                m = self._m2e_frame_values(path, csp, out_choice, depth)
            except Exception as ex:
                self.after(0, lambda e=str(ex): self.log(
                    self.elog, f"Preview failed: {e}", "err"))
                return

            def _apply():
                if seq != self._m2e_seq:
                    return            # a newer setting overtook this one
                self._m2e = m
                self._exr_redraw_preview()
            self.after(0, _apply)
        threading.Thread(target=go, daemon=True).start()

    def _exr_freq_refresh(self):
        """Frequency distribution of what the viewer shows: how much of
        the picture sits at each level of detail, coarse (left) to the
        finest the frame can hold (right). A curve that falls away well
        before the right edge is a soft or upscaled source."""
        cv = self.exr_freq_canvas
        if cv is None:
            return
        try:
            cv.delete("all")
            w = max(1, cv.winfo_width())
            h = max(1, cv.winfo_height())
        except Exception:
            return
        try:
            _vals, disp = self._exr_view_data()
        except Exception:
            disp = None
        if disp is None:
            cv.create_text(w // 2, h // 2, text="no frame yet",
                           fill="#444444", font=FSM)
            return
        import numpy as np
        key = (id(self._m2e) if self._exr_use_m2e()
               else id(getattr(self, "_e2m_lin", None)),
               float(self.exr_ev_var.get()), float(self.exr_gm_var.get()))
        hit = self._exr_view_cache
        if hit is None or hit[0] != key:
            f, p = self._ups_spectrum(np.asarray(disp, np.float32) / 255.0)
            self._exr_view_cache = hit = (key, f, p)
        _k, f, p = hit
        base = h - 12
        lo = float(np.percentile(p[1:], 2))
        hi = float(p[1:].max())
        span = max(1e-6, hi - lo)
        pts = [0, base]
        for fq, v in zip(f[1:], p[1:]):
            pts.extend((int(fq / 0.5 * (w - 1)),
                        base - (min(max(v, lo), hi) - lo) / span * (base - 6)))
        pts.extend((w - 1, base))
        if len(pts) >= 8:
            cv.create_polygon(*pts, fill="#1B3550", outline="")
            cv.create_line(*pts[2:-2], fill="#6FA8DC", width=1)
        cv.create_line(0, base, w, base, fill="#333333")
        cv.create_text(2, base + 1, text="coarse", anchor="nw",
                       font=("Futura", 8), fill="#666666")
        cv.create_text(w - 2, base + 1, text="fine", anchor="ne",
                       font=("Futura", 8), fill="#666666")
        cv.create_text(w // 2, base + 1, text="half resolution", anchor="n",
                       font=("Futura", 8), fill="#555555")
        cv.create_line(w // 2, 0, w // 2, base, fill="#444444", dash=(3, 2))

    def _e2m_target_changed(self):
        preset = self.AI_EXPORT_PRESETS.get(self.e2m_target_var.get())
        self.e2m_target_note.configure(
            text=preset["note"] if preset else
            "Uses the Colour Management / MOV Settings cards below, "
            "exactly as this tab has always worked.")
        for c in getattr(self, "_e2m_standard_cards", ()):
            self._usc_set_enabled(c, preset is None)

    def _e2m_auto_ev_toggle(self):
        on = not self.e2m_auto_ev_var.get()
        self.e2m_auto_ev_var.set(on)
        self.e2m_auto_ev_btn.configure(
            bg="#2A1A00" if on else "#1A1A1A",
            fg="#DDAA44" if on else G)

    def _e2m_refresh_preview(self, path, kind):
        """Read the representative frame, (re-)apply auto exposure if
        it is on, and draw the preview + histogram from it. Called
        once whenever a new source is picked."""
        def go():
            lin = self._e2m_representative_frame(path, kind)
            if lin is None:
                return
            self._e2m_lin = lin
            if self.e2m_auto_ev_var.get():
                ev = self._e2m_auto_ev(lin)
                self.after(0, lambda: self.exr_ev_var.set(
                    round(max(-5.0, min(5.0, ev)), 1)))
            self.after(0, self._e2m_draw_preview)
            self.after(0, self._e2m_sample_and_draw_histogram)
        threading.Thread(target=go, daemon=True).start()

    def _e2m_sample_and_draw_histogram(self):
        """Feeds the EXISTING histogram drawer with a real RGB channel
        count from the CURRENT exposed preview frame -- accurate to
        what will actually be sent, not ffmpeg's separate sampling."""
        import numpy as np
        lin = getattr(self, "_e2m_lin", None)
        if lin is None:
            return
        disp = self._e2m_exposed_display(lin)
        a = np.asarray(disp)
        R = np.bincount(a[..., 0].ravel(), minlength=256).astype(float)
        G_ = np.bincount(a[..., 1].ravel(), minlength=256).astype(float)
        B = np.bincount(a[..., 2].ravel(), minlength=256).astype(float)
        self._exr_hist_data = (list(R), list(G_), list(B), 1)
        self._exr_draw_histogram()

    # ── GEN AI HISTORY TAB ────────────────────────────────────────────────
    def _tab_exr(self):
        p = self._frame("exr")
        lf, rf = self._two_col(p, "", "", lw=420)
        # Scrolls, like the studios' columns: the three conversion
