    def _reinhard_anchor(self, blended, source, strength):
        """Match blended frame channel statistics to source frame.
        blended, source: float32 BGR arrays, values 0-255.
        strength: 0.0 = no change, 1.0 = full match.
        Returns float32 BGR array.
        """
        import numpy as np
        if strength <= 0.0: return blended
        out = blended.astype(np.float32)
        src = source.astype(np.float32)
        for c in range(3):
            m_s = src[:,:,c].mean(); sd_s = src[:,:,c].std() + 1e-6
            m_b = out[:,:,c].mean(); sd_b = out[:,:,c].std() + 1e-6
            # Reinhard: shift mean and std to match source
            anchored = (out[:,:,c] - m_b) * (sd_s / sd_b) + m_s
            # Blend between original pixels and anchored pixels (not grey mean)
            out[:,:,c] = out[:,:,c] * (1 - strength) + anchored * strength
        return np.clip(out, 0, 255)

    def _adw_generate_extra_pairs(self, bias):
        """Generate extra neighbouring RIFE pairs for positive Blend Bias.
        Updates green boxes as each pair completes, then re-runs blend."""
        import threading
        def go():
            import math,os,shutil,subprocess,tempfile
            src_frames=getattr(self,"rife_frames",[])
            src_idx=getattr(self,"_rife_adw_src_idx",None)
            folder=getattr(self,"rife_folder",None)
            if not src_frames or src_idx is None or not folder: return
            em={"2x":2,"4x":4,"6x":6,"8x":8}
            total=em.get(getattr(self,"rmult_var",type("V",(),{"get":lambda s:"4x"})()).get(),4)
            step=total
            extra=max(0,math.ceil(bias/step))
            if extra==0: self.after(0,self._rife_retime_blend_only); return
            self.after(0,lambda n=extra,b=bias: self.log(self.rlog,
                f"Bias +{b}: generating {n} extra pair(s) each side…","dim"))
            venv=os.path.expanduser("~/RifeApp/venv/bin/python3")
            script=self._rife_inference_script()
            sdir=os.path.expanduser("~/RifeApp/practical-RIFE")
            n_src=len(src_frames)
            def exr2png(src,dst):
                if not src.lower().endswith(".exr"):
                    if os.path.abspath(src)!=os.path.abspath(dst): shutil.copy(src,dst)
                    return True
                for args in [
                    ["ffmpeg","-y","-i",src,"-vf","tonemap=reinhard:desat=0,format=rgb24",dst],
                    ["ffmpeg","-y","-i",src,"-pix_fmt","rgb24",dst]]:
                    try:
                        if subprocess.run(args,capture_output=True,timeout=90).returncode==0 \
                                and os.path.exists(dst) and os.path.getsize(dst)>100:
                            return True
                    except: pass
                return False
            def run_pair(a,b):
                fa=os.path.join(folder,src_frames[max(0,min(n_src-1,a))])
                fb=os.path.join(folder,src_frames[max(0,min(n_src-1,b))])
                tin=tempfile.mkdtemp(prefix="adw_xin_")
                f1=os.path.join(tin,"f1.png"); f2=os.path.join(tin,"f2.png")
                if not exr2png(fa,f1) or not exr2png(fb,f2):
                    shutil.rmtree(tin,ignore_errors=True); return [],None
                scr_out=os.path.join(sdir,"output")
                os.makedirs(scr_out,exist_ok=True)
                for _f in os.listdir(scr_out):
                    try: os.remove(os.path.join(scr_out,_f))
                    except: pass
                r=subprocess.run(f'cd "{sdir}" && "{venv}" "{script}" '
                    f'--img "{f1}" "{f2}" --n-total {total}'+self._rife_extra_flags(),
                    shell=True,capture_output=True)
                shutil.rmtree(tin,ignore_errors=True)
                if r.returncode==0:
                    fs=sorted(os.path.join(scr_out,f) for f in os.listdir(scr_out)
                        if os.path.splitext(f)[1].lower() in {".png",".exr"})
                    if fs:
                        tout=tempfile.mkdtemp(prefix="adw_xout_")
                        for _fp in fs: shutil.copy2(_fp,os.path.join(tout,os.path.basename(_fp)))
                        return sorted(os.path.join(tout,f) for f in os.listdir(tout)),tout
                err=r.stderr.decode("utf-8","replace")[-200:]
                self.after(0,lambda e=err: self.log(self.rlog,f"  RIFE pair failed: {e}","err"))
                return [],None
            adw=self._rife_frames_dir(folder)
            existing=([os.path.join(adw,f) for f in sorted(os.listdir(adw))
                if os.path.splitext(f)[1].lower() in {".png",".exr"}]
                if os.path.isdir(adw) else [])
            all_paths=[]; temps=[]
            for ep in range(extra,0,-1):
                fa_i=src_idx-ep-1
                fs,t=run_pair(fa_i,src_idx-ep)
                all_paths.extend(fs[:-1] if fs else [])
                if t: temps.append(t)
                if fs:
                    self.after(0,lambda a=fa_i: self.log(self.rlog,
                        f"  ✓ left {a+1}→{a+2}","dim"))
                    if hasattr(self,"_rife_dual_tl"):
                        self.after(0,lambda i=fa_i:
                            self._rife_dual_tl.add_os_pair(i))
            all_paths.extend(existing)
            for ep in range(1,extra+1):
                fa_i=src_idx+ep
                fs,t=run_pair(fa_i,src_idx+ep+1)
                all_paths.extend(fs[1:] if fs else [])
                if t: temps.append(t)
                if fs:
                    self.after(0,lambda a=fa_i: self.log(self.rlog,
                        f"  ✓ right {a+1}→{a+2}","dim"))
                    if hasattr(self,"_rife_dual_tl"):
                        self.after(0,lambda i=fa_i:
                            self._rife_dual_tl.add_os_pair(i))
            if all_paths:
                asm=tempfile.mkdtemp(prefix="adw_asm_")
                for fi,fp in enumerate(all_paths):
                    dst=os.path.join(asm,f"{fi+1:05d}{os.path.splitext(fp)[1]}")
                    if not os.path.exists(fp):
                        shutil.rmtree(asm,ignore_errors=True)
                        self.after(0,lambda f=fp: self.log(self.rlog,
                            f"Extra pairs: source frame missing ({os.path.basename(f)}) — skipping","dim"))
                        for t in temps: shutil.rmtree(t,ignore_errors=True)
                        return
                    if os.path.abspath(fp)!=os.path.abspath(dst): shutil.copy2(fp,dst)
                # Abort if a full run started while we were generating
                if getattr(self,"_adw_run_active",False):
                    self.after(0,lambda: self.log(self.rlog,
                        "Extra pairs: full run active — assembly skipped","dim"))
                    for t in temps: shutil.rmtree(t,ignore_errors=True)
                    shutil.rmtree(asm,ignore_errors=True)
                    return
                if os.path.isdir(adw): shutil.rmtree(adw)
                shutil.copytree(asm,adw); shutil.rmtree(asm,ignore_errors=True)
                # _rife_adw_center_override may be None after Clear ADW cache — treat as step
                old_c = getattr(self,"_rife_adw_center_override",None)
                if old_c is None: old_c = step
                self._rife_adw_dir=adw
                self._rife_adw_center_override=extra*step+old_c
                n_tot=len([f for f in os.listdir(adw)
                    if os.path.splitext(f)[1].lower() in {".png",".exr"}])
                self.after(0,lambda n=n_tot,e=extra: self.log(self.rlog,
                    f"Bias ready: {n} frames ({e} extra pair(s) each side)","ok"))
            for t in temps: shutil.rmtree(t,ignore_errors=True)
            self.after(0,self._rife_retime_blend_only)
        threading.Thread(target=go,daemon=True).start()

    def _set_retime_btn(self, state):
        """No-op — Recalc button removed."""
        pass

    def _set_preview_phase(self, text, done=False):
        """Update the phase status label. Always safe to call from any thread."""
        def _update():
            lbl = getattr(self, "_preview_phase_lbl", None)
            if not lbl: return
            if done:
                lbl.configure(text="✓  DONE", fg="#2A7A2A",
                              font=(FM[0], FM[1], "bold"))
            elif text:
                lbl.configure(text=text, fg="#FF4444",
                              font=FM)
            else:
                lbl.configure(text="", fg="#555555", font=FM)
        self.after(0, _update)



    def _rife_retime_blend_only(self):
        """Re-apply retime blend on cached RIFE/ frames. No RIFE re-run."""
        if not getattr(self,"rife_folder",None):
            self.log(self.rlog,"Blend-only: no rife_folder","dim"); return
        if not getattr(self,"rife_frames",[]):
            self.log(self.rlog,"Blend-only: no rife_frames","dim"); return
        if not getattr(self,"_rife_wipe_orig_base",None):
            self.log(self.rlog,"Blend-only: no orig_base — run Preview first","dim"); return
        # Use stored ADW dir from last successful run if available
        _stored = getattr(self,"_rife_adw_dir",None)
        if _stored and os.path.isdir(_stored):
            riff_dir = _stored
        else:
            riff_dir = self._rife_frames_dir(self.rife_folder)
        # Fallback: scan for any subfolder containing an image sequence
        if not os.path.isdir(riff_dir):
            _img_exts = {".png",".exr",".tif",".tiff",".jpg",".jpeg"}
            _found = None
            # Check known legacy names first
            for _name in ["Riffled", "RIFE", "rife", "adw", "output"]:
                _p = os.path.join(self.rife_folder, _name)
                if os.path.isdir(_p):
                    _found = _p; break
            # Then scan all subfolders — skip output/retimed folders
            _skip_suffixes = ("_Retimed","_retimed","_MOV","_mov",
                              "_EXR","_SAM","_UPSCALE","_ADW")
            if not _found:
                try:
                    _n_src = len(self.rife_frames) if self.rife_frames else 0
                    for _sub in sorted(os.listdir(self.rife_folder)):
                        if any(_sub.endswith(s) for s in _skip_suffixes): continue
                        _p = os.path.join(self.rife_folder, _sub)
                        if os.path.isdir(_p):
                            _imgs = [f for f in os.listdir(_p)
                                if os.path.splitext(f)[1].lower() in _img_exts]
                            # Must have MORE frames than source = interpolated
                            if len(_imgs) > max(2, _n_src):
                                _found = _p; break
                except Exception: pass
            if _found:
                riff_dir = _found
                self.log(self.rlog,
                    f"Using existing folder: {os.path.basename(riff_dir)}/", "dim")
            else:
                # Log what subfolders exist for diagnosis
                try:
                    _subs = [(d, len([f for f in os.listdir(
                        os.path.join(self.rife_folder,d))
                        if os.path.splitext(f)[1].lower() in _img_exts]))
                        for d in os.listdir(self.rife_folder)
                        if os.path.isdir(os.path.join(self.rife_folder,d))]
                    self.log(self.rlog,
                        f"Subfolders: {_subs}  src_count={_n_src}", "dim")
                except Exception: pass
                # Relax: any subfolder with >2 images, still skipping output folders
                try:
                    for _sub in sorted(os.listdir(self.rife_folder)):
                        if any(_sub.endswith(s) for s in _skip_suffixes): continue
                        _p = os.path.join(self.rife_folder, _sub)
                        if os.path.isdir(_p):
                            _imgs = [f for f in os.listdir(_p)
                                if os.path.splitext(f)[1].lower() in _img_exts]
                            if len(_imgs) > 2:
                                _found = _p
                                self.log(self.rlog,
                                    f"Found ADW folder: {_sub}/ ({len(_imgs)} frames)", "dim")
                                break
                except Exception: pass
            if _found:
                riff_dir = _found
            else:
                self.log(self.rlog,
                    "ADW/ folder missing — hit Run ADW-Blur to regenerate it.","err")
                _rb2 = getattr(self,"rb2",None)
                if _rb2:
                    self.after(0, lambda: _rb2.configure(bg="#3A1A00",fg="#FF8800"))
                    self.after(1500, lambda: _rb2.configure(bg="#2A0A0A",fg="#CC4444"))
                self._set_retime_btn("stale"); return

        # ── Read ALL Tkinter state on main thread ──
        idx        = max(0, self.rife_frame_cb.current())
        em         = {"2x — Smooth":2,"4x — Very smooth":4,
                       "6x — Extra smooth":6,"8x — Maximum":8}
        _speedup_str = getattr(self,"rife_speedup_var",
            type("V",(),{"get":lambda s:"1x"})()).get()
        _speedup_bo = {"1x":1,"2x":2,"3x":3,"4x":4}.get(_speedup_str, 1)
        if _speedup_bo <= 1:
            _speedup_bo = 0   # 1x is a no-op, same as off
        total      = em.get(self.rmult.get(), 4)
        if _speedup_bo:
            idx = (idx // _speedup_bo) * _speedup_bo  # snap to nearest kept frame
        _flowq     = getattr(self,"rife_flow_var",None)
        _flowq     = _flowq.get() if _flowq else "Quality"
        _blend_str = getattr(self,"rife_blend_str_var",None)
        _blend_str = float(_blend_str.get())/100.0 if _blend_str else 1.0
        _falloff   = getattr(self,"rife_blend_falloff_var",None)
        _falloff   = _falloff.get() if _falloff else "Hann"
        _motion_lo = getattr(self,"rife_motion_thresh_var",None)
        _motion_lo = float(_motion_lo.get()) if _motion_lo else 2.0
        _motion_on = getattr(self,"rife_motion_mask_var",None)
        _motion_on = _motion_on.get() if _motion_on else True
        if getattr(self,"_blend_running",False):
            self.log(self.rlog,"Blend-only: already running, skipping","dim"); return
        self._blend_running = True
        self._set_preview_phase("Retime blend")
        self._set_retime_btn("running")
        self.rife_preview_btn.configure(state="disabled")

        def go():
            try:
                import cv2, numpy as np
                from PIL import Image

                _raw_rf = sorted(f for f in os.listdir(riff_dir)
                    if os.path.splitext(f)[1].lower() in {".png",".exr"})
                # Deduplicate: if both .exr and .png exist for same base, prefer .exr
                _rf_seen = {}
                for _rf in _raw_rf:
                    _rfbase = os.path.splitext(_rf)[0]
                    if _rfbase not in _rf_seen or _rf.endswith(".exr"):
                        _rf_seen[_rfbase] = _rf
                riff_files = sorted(_rf_seen.values(),
                                    key=lambda f: os.path.splitext(f)[0])
                if not riff_files:
                    self.after(0, lambda: self._set_preview_phase("", done=True))
                    return

                # EXR can't be opened by PIL — dimensions come from the
                # Riffled PNG frames which are already loaded below
                step       = total
                _br_v = getattr(self,"rife_blend_radius_var",None)
                _br   = _br_v.get() if _br_v else "Auto"
                if _speedup_bo:
                    # Match _rife_auto_retime's speedup-aware window
                    # exactly: half-width = speedup/2 original-frame
                    # units (halfway to the next kept frame), +1 to
                    # correct for the "_half-1 is the actual reach"
                    # loop convention below.
                    _half = round((_speedup_bo/2.0) * step) + 1 if _br=="Auto" else max(1,int(_br))
                else:
                    _half = step if _br=="Auto" else max(1,int(_br))
                _N         = 2*_half - 1
                src_count  = len(riff_files)
                # Source frames from input folder (for orig side of wipe)
                _exts_src = {".exr",".png",".jpg",".jpeg",".tiff",".tif"}
                src_frames = sorted([f for f in os.listdir(self.rife_folder)
                    if os.path.splitext(f)[1].lower() in _exts_src
                    and not f.startswith("__")])
                # Use center override if set by preview (mini-ADW)
                _co = getattr(self,"_rife_adw_center_override",None)
                center = _co if _co is not None else idx * step
                center = max(0, min(src_count-1, center))

                # Read global norm_scale from PNG cache so all EXR loads match
                _global_scale = [None]
                try:
                    import json as _cjb
                    _ci_path = os.path.join(self._adw_output_root(self.rife_folder),"_png_cache","_cache_info.json")
                    _ci_data = _cjb.loads(open(_ci_path).read())
                    _global_scale[0] = float(_ci_data.get("norm_scale") or 1.0)
                except Exception: pass

                def _exr_to_bgr(arr):
                    """Convert raw EXR float32 RGB array to display-ready uint8 BGR."""
                    arr = np.maximum(arr, 0)
                    sc  = _global_scale[0]
                    if sc is None:          # first-frame fallback
                        lum = arr.max(axis=2)
                        sc  = self._adw_auto_exposure_scale(lum) if lum.any() else 1.0
                        _global_scale[0] = sc
                    gamma = self._adw_gamma_encode(arr, sc)
                    return cv2.cvtColor((gamma*255).astype(np.uint8),
                                       cv2.COLOR_RGB2BGR).astype(np.float32)

                def load(path, adw_pos=None):
                    """Load PNG or EXR as float32 BGR 0-255 (per-frame normalised)."""
                    import subprocess as _sp, json as _json
                    if path.lower().endswith(".exr"):
                        # Try OpenEXR library first
                        try:
                            import OpenEXR as _OE, Imath as _Im
                            _ef = _OE.InputFile(path)
                            _hdr = _ef.header()
                            _dw = _hdr["dataWindow"]; _disp = _hdr["displayWindow"]
                            dw_w = _dw.max.x-_dw.min.x+1; dw_h = _dw.max.y-_dw.min.y+1
                            fw = _disp.max.x-_disp.min.x+1; fh = _disp.max.y-_disp.min.y+1
                            _FP = _Im.PixelType(_Im.PixelType.FLOAT)
                            data = np.stack([
                                np.frombuffer(_ef.channel(c,_FP),np.float32).reshape(dw_h,dw_w)
                                for c in "RGB"],axis=2)
                            if (dw_w,dw_h)==(fw,fh) and _dw.min.x==_disp.min.x and _dw.min.y==_disp.min.y:
                                arr = data
                            else:
                                # dataWindow offset/cropped from displayWindow
                                # (seen from some AI video tools) -- place
                                # at its real position, not the origin
                                arr = np.zeros((fh,fw,3),dtype=np.float32)
                                y0 = _dw.min.y-_disp.min.y; x0 = _dw.min.x-_disp.min.x
                                arr[max(0,y0):max(0,y0)+dw_h, max(0,x0):max(0,x0)+dw_w] = data
                            return _exr_to_bgr(arr)
                        except Exception: pass
                        # ffmpeg float pipe fallback
                        try:
                            pr = _sp.run(
                                ["ffprobe","-v","quiet","-print_format","json",
                                 "-show_streams", path],
                                capture_output=True, text=True, timeout=10)
                            info = _json.loads(pr.stdout)
                            vs = next(s for s in info["streams"]
                                      if s["codec_type"]=="video")
                            fw, fh = int(vs["width"]), int(vs["height"])
                            raw = _sp.run(
                                ["ffmpeg","-y","-i",path,
                                 "-pix_fmt","rgbaf32le","-f","rawvideo","pipe:1"],
                                capture_output=True, timeout=90)
                            if raw.stdout:
                                arr = np.frombuffer(raw.stdout, np.float32
                                    ).reshape(fh, fw, 4)[:,:,:3]
                                return _exr_to_bgr(arr)
                        except Exception: pass
                        # Last resort: ffmpeg tonemap, but log it so a
                        # mismatched-gamma frame is visible rather than
                        # silently swapped in when the wipe re-blends.
                        self.after(0, lambda pth=path: self.log(
                            self.rlog,
                            f"\u26a0 Couldn't read {os.path.basename(pth)} via OpenEXR "
                            f"or ffmpeg's float pipe \u2014 falling back to a plain gamma "
                            f"decode (scale=1.0), not reinhard.", "err"))
                        try:
                            import tempfile as _tf2
                            _tmp = _tf2.NamedTemporaryFile(suffix=".png",delete=False)
                            _tmp.close()
                            _sp.run(["ffmpeg","-y","-i",path,
                                "-pix_fmt","rgb24",_tmp.name],
                                capture_output=True,timeout=60)
                            img = Image.open(_tmp.name).convert("RGB")
                            import os as _os2; _os2.unlink(_tmp.name)
                            _arr8 = np.array(img,dtype=np.float32)/255.0
                            _lin8 = np.power(np.maximum(_arr8,0),2.2)
                            return _exr_to_bgr(_lin8)
                        except Exception: pass
                        return np.zeros((1080,1920,3),dtype=np.float32)
                    else:
                        img = Image.open(path).convert("RGB")
                        return cv2.cvtColor(np.array(img),
                            cv2.COLOR_RGB2BGR).astype(np.float32)

                def get_frame(i):
                    _i = max(0, min(src_count-1, i))
                    return load(os.path.join(riff_dir, riff_files[_i]))

                _oF   = get_frame(center)
                _th, _tw = _oF.shape[:2]  # target size from center frame
                # Patch load to resize all frames to match center frame size
                _load_orig = load
                def load(path, adw_pos=None):
                    _f = _load_orig(path)
                    if _f.shape[:2] != (_th, _tw):
                        import cv2 as _cv2r
                        _f = _cv2r.resize(_f, (_tw, _th),
                            interpolation=_cv2r.INTER_LANCZOS4)
                    return _f
                _acc  = np.zeros_like(_oF, dtype=np.float32)
                _wtot = 0.0
                dis   = cv2.DISOpticalFlow_create(
                    cv2.DISOPTICAL_FLOW_PRESET_FAST if _flowq=="Fast"
                    else cv2.DISOPTICAL_FLOW_PRESET_ULTRAFAST)

                for _off in range(-(_half-1), _half):
                    _pos    = max(0, min(src_count-1, center+_off))
                    _fr     = get_frame(_pos)
                    _n      = _off + (_half-1)
                    _t_norm = _n / max(1, _N-1)
                    if _falloff=="Linear":
                        _wt = 1.0 - abs(_t_norm-0.5)*2
                    elif _falloff=="Gaussian":
                        _wt = max(0.06, np.exp(-0.5*(((_t_norm-0.5)/0.1)**2)))
                    elif _falloff=="Box":
                        _wt = 1.0
                    else:
                        _wt = 0.5*(1-np.cos(2*np.pi*_n/max(1,_N-1)))
                    if _off==0:
                        _acc  += _fr*_wt
                    else:
                        _t   = abs(_off)/_half
                        _wfr = self._flow_warp(_fr,_oF,dis,_t,_flowq,_motion_lo,_motion_on)
                        _acc += _wfr*_wt
                    _wtot += _wt

                blended = np.clip(_acc/_wtot if _wtot > 1e-6 else _oF.astype(np.float32), 0, 255)
                if _blend_str < 1.0:
                    blended = _blend_str*blended + (1-_blend_str)*_oF.astype(np.float32)
                # Histogram Anchor
                _ha_str = float(getattr(
                    self,"rife_hist_anchor_var",
                    type("V",(),{"get":lambda s:0.0})()).get())
                blended = self._reinhard_anchor(blended, _oF, _ha_str)
                blended = np.clip(blended, 0, 255).astype(np.uint8)

                riff_img = Image.fromarray(
                    cv2.cvtColor(blended, cv2.COLOR_BGR2RGB))

                # Load the original INPUT frame for left side
                # Use _oF (ADW center frame) so LEFT and RIGHT share identical
                # load() normalisation — no exposure mismatch possible
                _src_raw = _oF
                _oF_img   = Image.fromarray(
                    cv2.cvtColor(
                        np.clip(_src_raw, 0, 255).astype(np.uint8),
                        cv2.COLOR_BGR2RGB))
                self._rife_wipe_riff_raw    = riff_img.copy()
                self._rife_orig_dims        = _oF_img.size
                self._rife_wipe_riff_base   = riff_img
                self._rife_wipe_orig_base   = _oF_img
                self._rife_wipe_orig_actual = _oF_img.copy()
                try:
                    import numpy as _npdiag2
                    _diag_arr2 = _npdiag2.array(_oF_img.convert("RGB"), dtype=_npdiag2.float32)
                    self.after(0, lambda m=float(_diag_arr2.mean()), s=_global_scale[0]: self.log(
                        self.rlog,
                        f"[diag] orig display REPLACED by ADW-Blur center frame "
                        f"(_exr_to_bgr path, scale={s}) \u2014 mean pixel value: "
                        f"{m:.1f}/255", "dim"))
                except Exception: pass

                self.after(0,   self._rife_display)
                self.after(250, self._rife_display)  # re-draw once canvas settled
                self.after(20, lambda: self._set_preview_phase("", done=True))
                self._set_retime_btn("done")

            except Exception as ex:
                import traceback
                tb = traceback.format_exc()[-300:]
                self.after(0, lambda ex=str(ex), tb=tb: self.log(
                    self.rlog, f"Blend error: {ex}\n{tb}", "err"))
                self.after(0, lambda: self._set_preview_phase(""))
                self._set_retime_btn("stale")
            finally:
                self._blend_running = False
                self.after(0, lambda: self.rife_preview_btn.configure(
                    state="normal"))

        import threading
        threading.Thread(target=go, daemon=True).start()

    def _param_changed_trigger(self):
        """Relay to the local closure stored during _tab_rife setup."""
        fn = getattr(self, "_param_changed_trigger", None)
        if callable(fn): fn()

    def _rife_frame_selected(self, e=None):
        # Clear cached bases so _rife_preview_frame does a full fresh load
        self._rife_wipe_orig_base = None
        self._rife_wipe_riff_base = None
        self._rife_mode = "preview"
        self.rife_wipe_btn.configure(bg="#0D0D0D", fg=W)
        self._rife_preview_frame()

    def _rife_toggle_wipe(self):
        if self._rife_wipe_orig_base is None:
            self.log(self.rlog, "Run Preview first.", "err"); return
        _mpv = getattr(self,"_mt_preview_var",None)
        if _mpv and _mpv.get(): _mpv.set(False)
        if self._rife_mode == "wipe":
            self._rife_mode = "preview"
            self.rife_wipe_btn.configure(bg="#0D0D0D", fg=W)
            self.rife_wipe_canvas.configure(cursor="crosshair")
            self._rife_display()
        else:
            self._rife_mode = "wipe"
            self.rife_wipe_btn.configure(bg="#252525", fg=W)
            self.rife_diff_btn.configure(bg="#0D0D0D", fg=W)
            _cur = {0:"sb_h_double_arrow",90:"sb_v_double_arrow",
                    45:"fleur",135:"fleur"}.get(self._rife_wipe_angle,"crosshair")
            self.rife_wipe_canvas.configure(cursor=_cur)
            self._rife_wipe_draw("ADW-Blur")
        # Always refresh from full ADW so wipe is correctly aligned
        _best_adw = getattr(self,"_rife_full_adw_dir",None) or getattr(self,"_rife_adw_dir",None)
        if _best_adw and os.path.isdir(_best_adw):
            self._rife_adw_dir = _best_adw
            self._rife_adw_center_override = None
            self._rife_retime_blend_only()

    def _rife_run_pair_stepped(self, venv, script, script_dir, f1, f2,
                                exp, extra_flags, tmp_dir, rife_out):
        """Generate the same 2**exp - 1 intermediate frames a single
        '--exp {exp}' call would, but by running RIFE repeatedly at
        the minimal --exp 1 each time (recursive doubling) instead of
        one call asking for the full depth at once.

        Why: at higher Smoothing (exp 2 or 3 -- 4x/8x), RIFE's own
        single-call recursive interpolation appears to hold more
        intermediate state in VRAM at once than a fresh exp=1 call
        does, which can produce the same kind of quality/resolution
        degradation seen from forcing too-large an internal --scale
        at high Model Res -- except here it shows up even at an
        otherwise-safe resolution, scaling instead with how many
        frames are being generated per call. Each invocation here is
        a separate process that fully exits -- and so fully releases
        whatever VRAM it held -- before the next one starts, trading
        invocation count (2**exp - 1 total calls instead of 1, each
        with real process-startup and model-load overhead) for a
        lower peak VRAM footprint per individual call.

        Returns True and leaves rife_out populated with 2**exp + 1
        frames (the two originals plus all genuinely-interpolated
        frames in between, named so sorted(listdir(rife_out)) puts
        them in correct temporal order) -- i.e. left in exactly the
        same shape the caller's existing single-call code already
        expects, so nothing downstream needs to change. Returns False
        on any failure, in which case the caller should fall back to
        a single direct --exp {exp} call."""
        import subprocess, os, shutil
        if exp <= 1:
            return False  # nothing to step -- exp=1 is already minimal
        frames = [f1, f2]
        for round_num in range(exp):
            new_frames = [frames[0]]
            n_pairs = len(frames) - 1
            for pair_i in range(n_pairs):
                if self._rife_cancel:
                    return False
                a, b = frames[pair_i], frames[pair_i+1]
                pair_dir = os.path.join(tmp_dir, f"_step_r{round_num}_p{pair_i}")
                os.makedirs(pair_dir, exist_ok=True)
                pa = os.path.join(pair_dir, "a.png")
                pb = os.path.join(pair_dir, "b.png")
                shutil.copy(a, pa); shutil.copy(b, pb)
                for f in os.listdir(rife_out):
                    try: os.remove(os.path.join(rife_out, f))
                    except Exception: pass
                cmd = (f'cd "{script_dir}" && "{venv}" "{script}" '
                       f'--img "{pa}" "{pb}" --exp 1' + extra_flags)
                self._rife_proc = subprocess.Popen(
                    cmd, shell=True,
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                self._rife_proc.wait()
                _ret = self._rife_proc.returncode
                self._rife_proc = None
                if self._rife_cancel or _ret != 0:
                    return False
                out_files = sorted(f for f in os.listdir(rife_out)
                    if os.path.splitext(f)[1].lower() in {".png",".jpg",".jpeg"})
                if len(out_files) < 3:
                    return False
                mid_src = os.path.join(rife_out, out_files[1])
                mid_dst = os.path.join(pair_dir, "mid.png")
                shutil.copy(mid_src, mid_dst)
                new_frames.append(mid_dst)
                new_frames.append(b)
            frames = new_frames
        # `frames` is now the full ordered list [f1, mid1, ..., midN, f2],
        # length 2**exp + 1. Write into rife_out with simple,
        # guaranteed-sortable names so the caller's existing
        # sorted(listdir(rife_out)) + [1:-1] convention (which strips
        # the original-frame copies at each end) works unchanged.
        for f in os.listdir(rife_out):
            try: os.remove(os.path.join(rife_out, f))
            except Exception: pass
        for idx, fp in enumerate(frames):
            shutil.copy(fp, os.path.join(rife_out, f"step_{idx:05d}.png"))
        return True

    def _rife_inference_script(self):
        """Path to the RIFE inference script to run -- the ADW-owned one
        (written/refreshed next to the cloned repo) when possible, the
        repo's stock inference_img.py only as a fallback.

        The repo clone is still needed (model wrapper code + weights
        live there); only the top-level inference script is replaced,
        because upstream's has proven to be a moving target -- see the
        ADW_RIFE_SCRIPT comment for the 448x256 story.
        """
        import os
        rife_dir = os.path.expanduser("~/RifeApp/practical-RIFE")
        stock = os.path.join(rife_dir, "inference_img.py")
        if not os.path.isdir(rife_dir):
            return stock
        ours = os.path.join(rife_dir, "adw_inference_img.py")
        try:
            cur = ""
            if os.path.exists(ours):
                with open(ours) as fh:
                    cur = fh.read()
            if cur != ADW_RIFE_SCRIPT:
                with open(ours, "w") as fh:
                    fh.write(ADW_RIFE_SCRIPT)
            return ours
        except Exception:
            return stock

    def _rife_settings_fingerprint(self):
        """The settings that change what RIFE frames LOOK like -- stored
        with cached frames so a cache built under different settings is
        detected instead of silently reused. Stale cache reuse after a
        settings change was a prime suspect for 'output looks low-res
        again, but only sometimes'."""
        cs = ""
        for _n in ("rife_src_var", "rife_src_colorspace_var",
                   "rife_colorspace_var"):
            _v = getattr(self, _n, None)
            if _v is not None:
                try:
                    cs = str(_v.get()); break
                except Exception:
                    pass
        def _g(name, default=""):
            _v = getattr(self, name, None)
            try:
                return _v.get() if _v is not None else default
            except Exception:
                return default
        return {"smoothing": str(_g("rmult_var")),
                "model_res": str(_g("rife_scale_var", "full")),
                "tta": bool(_g("rife_tta_var", False)),
                "stepped": bool(_g("rife_stepped_var", True)),
                "colorspace": cs,
                "script": ADW_RIFE_SCRIPT_VERSION}

    def _rife_extra_flags(self):
        """Extra RIFE flags. With the ADW-owned script these are known
        without probing: it always supports --scale and --TTA, and it
        handles VRAM pressure itself (OOM -> retry at a lower internal
        scale, recorded in output/ADW_RUNINFO.json) -- so full scale is
        simply requested and the fallback story is the script's job,
        reported instead of silent. The old policy of withholding
        --scale 1.0 above 720p existed only because a too-tight
        full-scale pass degraded softly with no signal; that hole is
        what the run report closes."""
        import subprocess, os
        script = self._rife_inference_script()
        if script.endswith("adw_inference_img.py"):
            flags = " --scale 1.0"
            if getattr(self, "rife_tta_var", None) and self.rife_tta_var.get():
                flags += " --TTA"
            return flags
        # stock-script fallback: probe --help, same as before
        venv = os.path.expanduser("~/RifeApp/venv/bin/python3")
        flags = ""
        try:
            r = subprocess.run([venv, script, "--help"],
                               capture_output=True, text=True, timeout=5)
            help_txt = (r.stdout + r.stderr).lower()
            if "--scale" in help_txt:
                _res_chk = getattr(self, "rife_scale_var",
                    type("V", (), {"get": lambda s: "full"})()).get()
                _force_full_scale = True
                if _res_chk == "full":
                    _force_full_scale = False
                elif "x" in str(_res_chk):
                    try:
                        _tw_chk, _th_chk = map(int, str(_res_chk).split("x"))
                        if max(_tw_chk, _th_chk) > 1280:
                            _force_full_scale = False
                    except Exception:
                        pass
                if _force_full_scale:
                    flags += " --scale 1.0"
            if "--tta" in help_txt and getattr(self, "rife_tta_var", None) \
                    and self.rife_tta_var.get():
                flags += " --TTA"
        except Exception:
            pass
        return flags

    def _rife_reset_sash(self):
        """Reset RIFE sash then redraw at correct canvas size."""
        try:
            rvpaned = self.rife_wipe_canvas.master.master
            rvpaned.update()
            total = rvpaned.winfo_height()
            if total > 200:
                sash_y = max(200, total - 200)
                rvpaned.sash_place(0, 0, sash_y)
                rvpaned.update()
                # Force canvas to report new size then redraw
                self.rife_wipe_canvas.update_idletasks()
                if self._rife_mode == "diff" and self._rife_wipe_orig_base:
                    self._rife_diff_draw()
                elif self._rife_mode == "wipe" and self._rife_wipe_orig_base:
                    self._rife_wipe_draw()
                elif self._rife_wipe_riff_base:
                    self._rife_display()
        except Exception:
            pass

    def _rife_display(self):
        """Show riffled frame with zoom/pan, wipe, or diff based on current mode."""
        if self._rife_wipe_riff_base is None: return
        if self._rife_mode == "diff" and self._rife_wipe_orig_base is not None:
            self._rife_diff_draw(); return
        if self._rife_mode == "wipe" and self._rife_wipe_orig_base is not None:
            self._rife_wipe_draw(); return
        # Preview mode — full zoom/pan, no wipe handle
        try:
            from PIL import Image, ImageTk
            self.rife_wipe_canvas.update_idletasks()
            cw = self.rife_wipe_canvas.winfo_width()
            ch = self.rife_wipe_canvas.winfo_height()
            if cw < 10 or ch < 10: return
            try:
                _sc = float(self.tk.call("tk","scaling"))
                retina = max(1, round(_sc))
            except Exception:
                retina = 1
            pw, ph = cw*retina, ch*retina
            src = self._rife_wipe_riff_base
            iw, ih = src.size
            base  = max(pw/iw, ph/ih)
            scale = base * self._rife_zoom
            nw = max(1, int(round(iw*scale)))
            nh = max(1, int(round(ih*scale)))
            _f = (Image.NEAREST if self._rife_zoom > 3 else
                  Image.BILINEAR if self._rife_zoom > 1.5 else Image.LANCZOS)
            resized = src.resize((nw, nh), _f)
            bg = Image.new("RGB", (pw, ph), (10,10,10))
            px = int(-(nw-pw)//2 + self._rife_pan_x*retina)
            py = int(-(nh-ph)//2 + self._rife_pan_y*retina)
            bg.paste(resized, (px, py))
            self._rife_preview_tk = ImageTk.PhotoImage(bg)
            self.rife_wipe_canvas.delete("all")
            self.rife_wipe_canvas.create_image(0,0,anchor="nw",
                image=self._rife_preview_tk)
            _usc_on = getattr(self,"rife_prev_upscale_var",None) \
                      and self.rife_prev_upscale_var.get()
            _usc_alg = getattr(self,"rife_upscale_var",None)
            _usc_lbl = (f" [upscaled: {_usc_alg.get()}]" if _usc_on and _usc_alg
                        else " [pre-upscale]" if not _usc_on and
                        getattr(self,"_rife_wipe_riff_raw",None) else "")
            self.rife_wipe_canvas.create_text(6,8,anchor="nw",
                text=f"Riffled{_usc_lbl} — click ⬛ Wipe to compare",
                font=FM, fill=GR)
        except Exception as ex:
            self.log(self.rlog, f"Display error: {ex}", "err")

    def _rife_diff_mult_menu(self, e=None):
        """Right-click popup to choose diff amplification: 1×–16×."""
        m = tk.Menu(self, tearoff=0, bg=S, fg=W, activebackground=BD,
                    activeforeground=W, font=FM, bd=0, relief="flat")
        current = self._rife_diff_mult

        def _set(v):
            self._rife_diff_mult = v
            self.rife_diff_btn._lbl.configure(text=f"△  Diff  {v}×")
            if self._rife_mode == "diff":
                self._rife_diff_draw()

        for v in [1, 2, 4, 6, 8, 10, 12, 16]:
            tick = "✓ " if current == v else "  "
            m.add_command(label=f"{tick}{v}×", command=lambda v=v: _set(v))

        try:
            m.tk_popup(e.x_root, e.y_root)
        finally:
            m.grab_release()

    def _rife_wipe_dir_menu(self, e=None):
        """Right-click: choose wipe split direction."""
        dirs = [
            ("Vertical",    0,   "Split left / right"),
            ("Horizontal",  90,  "Split top / bottom"),
            ("Diagonal /",  45,  "Bottom-left to top-right"),
            ("Diagonal \\", 135, "Top-left to bottom-right"),
        ]
        m = tk.Menu(self, tearoff=0, bg=S, fg=W, activebackground=BD,
                    activeforeground=W, font=FM, bd=0, relief="flat")
        cur = self._rife_wipe_angle
        for label, ang, tip in dirs:
            tick = "✓ " if cur == ang else "  "
            m.add_command(label=f"{tick}{label}",
                command=lambda a=ang: self._rife_wipe_set_dir(a))
        try:
            m.tk_popup(e.x_root, e.y_root)
        finally:
            m.grab_release()

    def _rife_wipe_set_dir(self, ang):
        self._rife_wipe_angle = ang
        _cur = {0:"sb_h_double_arrow",90:"sb_v_double_arrow",
                45:"fleur",135:"fleur"}.get(ang,"crosshair")
        self.rife_wipe_canvas.configure(cursor=_cur)
        if self._rife_mode == "wipe":
            self._rife_wipe_draw()
        else:
            self._rife_mode = "wipe"
            self.rife_wipe_btn.configure(bg="#252525", fg=W)
            self.rife_diff_btn.configure(bg="#0D0D0D", fg=W)
            self._rife_wipe_draw("ADW-Blur")

    def _rife_toggle_diff(self):
        if self._rife_wipe_orig_base is None:
            self.log(self.rlog, "Run Preview first.", "err"); return
        _mpv = getattr(self,"_mt_preview_var",None)
        if _mpv and _mpv.get(): _mpv.set(False)
        if self._rife_mode == "diff":
            self._rife_mode = "preview"
            self.rife_diff_btn.configure(bg="#0D0D0D", fg=W)
            self.rife_wipe_canvas.configure(cursor="crosshair")
            self._rife_display()
        else:
            self._rife_mode = "diff"
            self.rife_diff_btn.configure(bg="#252525", fg="#CC4444")
            self.rife_wipe_btn.configure(bg="#0D0D0D", fg=W)
            self.rife_wipe_canvas.configure(cursor="crosshair")
            self._rife_diff_draw()
        # Always refresh from full ADW so diff is correctly aligned
        _best_adw = getattr(self,"_rife_full_adw_dir",None) or getattr(self,"_rife_adw_dir",None)
        if _best_adw and os.path.isdir(_best_adw):
            self._rife_adw_dir = _best_adw
            self._rife_adw_center_override = None
            self._rife_retime_blend_only()

    def _rife_diff_draw(self):
        """Show amplified absolute difference between orig and riffled frames."""
        if self._rife_wipe_orig_base is None or self._rife_wipe_riff_base is None: return
        try:
            import numpy as np
            from PIL import Image, ImageTk
            rvpaned = self.rife_wipe_canvas.master.master
            cw = self.rife_wipe_canvas.winfo_width()
            ch = self.rife_wipe_canvas.winfo_height()
            try:
                _sc = float(self.tk.call("tk","scaling"))
                retina = max(1, round(_sc))
            except Exception:
                retina = 1
            cw *= retina; ch *= retina
            self.log(self.rlog, f"Wipe: retina={retina} cw={cw} ch={ch} "
                f"orig={self._rife_wipe_orig_base.size if self._rife_wipe_orig_base else None}", "dim")
            if ch < 100 or cw < 100:
                self.after(200, self._rife_diff_draw)
                return

            base   = max(cw / self._rife_wipe_orig_base.width,
                         ch / self._rife_wipe_orig_base.height)
            scale  = base * self._rife_zoom
            nw     = max(1, int(round(self._rife_wipe_orig_base.width  * scale)))
            nh     = max(1, int(round(self._rife_wipe_orig_base.height * scale)))
            orig_r = self._rife_wipe_orig_base.resize((nw, nh), Image.LANCZOS)
            riff_r = self._rife_wipe_riff_base.resize((nw, nh), Image.LANCZOS)

            px = int(-(nw - cw) // 2 + self._rife_pan_x)
            py = int(-(nh - ch) // 2 + self._rife_pan_y)

            canvas_orig = Image.new("RGB", (cw, ch), (0, 0, 0))
            canvas_riff = Image.new("RGB", (cw, ch), (0, 0, 0))
            canvas_orig.paste(orig_r, (px, py))
            canvas_riff.paste(riff_r, (px, py))

            a = np.asarray(canvas_orig, dtype=np.float32)
            b = np.asarray(canvas_riff, dtype=np.float32)
            diff = np.abs(a - b)

            mult   = max(1, self._rife_diff_mult)
            factor = float(mult)
            lbl    = f"Difference matte  ({mult}×)"
            diff = np.clip(diff * factor, 0, 255).astype(np.uint8)

            diff_img = Image.fromarray(diff)
            self._rife_wipe_tk = ImageTk.PhotoImage(diff_img)
            self.rife_wipe_canvas.delete("all")
            self.rife_wipe_canvas.create_image(0, 0, anchor="nw",
                image=self._rife_wipe_tk)
            self.rife_wipe_canvas.create_text(6, 8, anchor="nw",
                text=lbl, font=FM, fill="#CC4444")
        except Exception as ex:
            self.log(self.rlog, "Diff error: " + str(ex), "err")

    # ── RIFE zoom / pan ──────────────────────────────────────────────
    def _rife_zoom_step(self, delta):
        self._rife_zoom = max(0.25, min(8.0, self._rife_zoom + delta))
        self._rife_diff_draw() if self._rife_mode == "diff" else (self._rife_display() if self._rife_mode == "preview" else self._rife_wipe_draw())

    def _make_dis(self, quality="Quality"):
        """Create a DIS optical flow with quality preset."""
        import cv2
        dis = cv2.DISOpticalFlow_create()
        if quality == "Quality":
            dis.setFinestScale(0)                    # finest pyramid level
            dis.setGradientDescentIterations(64)     # much more accurate
            dis.setPatchSize(6)                      # smaller = finer detail
            dis.setPatchStride(1)                    # densest flow
            dis.setVariationalRefinementIterations(100)  # very smooth
        else:  # Fast
            dis.setFinestScale(2)
            dis.setGradientDescentIterations(16)
            dis.setPatchStride(4)
            dis.setVariationalRefinementIterations(5)
        return dis

    def _flow_warp(self, src_bgr, tgt_bgr, dis, t, quality="Quality",
                   motion_lo=2.0, mask_enabled=True):
        """Flow-warp src toward tgt by fraction t with motion-adaptive masking.

        In high-motion regions (large flow vectors) the result falls back to
        tgt_bgr (the original frame) to avoid ghosting. In still regions the
        warped src blends in normally.

        Quality: bidirectional warp + motion mask.
        Fast:    single-direction warp + motion mask.

        mask_enabled=False skips the motion mask entirely -- the warped
        blend applies everywhere, uniformly, with no motion-based
        exception at any magnitude. The threshold slider alone can't
        reach this: even at its maximum, unusually fast motion (above
        the slider's own upper ramp) still falls back to the original
        frame in those regions -- this is a genuine, unconditional off.
        """
        import cv2, numpy as np

        # Advanced Motion Mask settings (from ⚙ popup, with safe defaults)
        _hi_mult  = float(getattr(self, "rife_motion_hi_var",
                          type("V",(),{"get":lambda s:6.0})()).get())
        _dil_px   = int(getattr(self, "rife_mask_dilation_var",
                        type("V",(),{"get":lambda s:9})()).get())
        _feather  = float(getattr(self, "rife_mask_feather_var",
                          type("V",(),{"get":lambda s:5.0})()).get())

        def _warp(img, flow, frac):
            h,w = flow.shape[:2]
            rm = np.stack([
                flow[:,:,0]*frac + np.arange(w, dtype=np.float32),
                flow[:,:,1]*frac + np.arange(h, dtype=np.float32)[:,None]
            ], axis=2)
            return cv2.remap(img, rm, None, cv2.INTER_LINEAR,
                             borderMode=cv2.BORDER_REPLICATE)

        def _motion_mask(flow):
            """Per-pixel mask: 0 = still (blend freely), 1 = motion (use original)."""
            lo = motion_lo; hi = motion_lo * max(1.0, _hi_mult)
            mag = np.sqrt(flow[:,:,0]**2 + flow[:,:,1]**2)
            mask = np.clip((mag - lo)/(hi - lo + 1e-6), 0.0, 1.0).astype(np.float32)
            # Dilate mask to cover edges of moving objects
            _dil = max(1, _dil_px | 1)  # ensure odd
            kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(_dil,_dil))
            mask = cv2.dilate(mask, kernel)
            # Soften the mask boundary
            if _feather > 0:
                mask = cv2.GaussianBlur(mask,(0,0),_feather)
            return mask[:,:,np.newaxis]  # (h,w,1) for broadcasting

        # Pre-blur for flow computation (reduces noise, not applied to output)
        sg = 1.5 if quality=="Quality" else 0.0
        src_b = cv2.GaussianBlur(src_bgr,(0,0),sg) if sg else src_bgr
        tgt_b = cv2.GaussianBlur(tgt_bgr,(0,0),sg) if sg else tgt_bgr
        # dis.calc requires uint8 — tone-map if float linear, else clip
        def _to_gray(img):
            f = img.astype(np.float32)
            mx = float(f.max()) or 1.0
            if mx > 2.0:  # linear HDR — normalise before gamma
                f = f / mx
            g = np.power(np.clip(f,0,1), 1/2.2)
            return cv2.cvtColor((g*255).astype(np.uint8), cv2.COLOR_BGR2GRAY)
        src_g = _to_gray(src_b)
        tgt_g = _to_gray(tgt_b)

        if quality == "Quality":
            f_fwd = dis.calc(src_g, tgt_g, None)
            f_bwd = dis.calc(tgt_g, src_g, None)
            w_fwd = _warp(src_bgr.astype(np.float32), f_fwd,  t)
            w_bwd = _warp(tgt_bgr.astype(np.float32), f_bwd, -(1.0-t))
            warped = (w_fwd + w_bwd) * 0.5
            # Motion mask from forward flow -- skipped entirely when
            # disabled (0.0 broadcasts against the array below, giving
            # full blend everywhere with no motion-based exception)
            mmask = _motion_mask(f_fwd) if mask_enabled else 0.0
        else:
            f = dis.calc(src_g, tgt_g, None)
            warped = _warp(src_bgr.astype(np.float32), f, t)
            mmask  = _motion_mask(f) if mask_enabled else 0.0

        # In moving areas: use original (tgt). In still areas: use warped.
        tgt_f    = tgt_bgr.astype(np.float32)
        warped_f = warped.astype(np.float32)
        result   = warped_f*(1-mmask) + tgt_f*mmask
        # Return same dtype as input — float stays float, uint8 clips
        if src_bgr.dtype == np.uint8:
            return np.clip(result, 0, 255).astype(np.uint8)
        return np.maximum(result, 0).astype(np.float32)

    def _rife_upscale(self, img_bgr, target_w, target_h):
        """Upscale RIFE output to target resolution.
        Uses Real-ESRGAN x2 if model is installed, otherwise cv2 LANCZOS4 + unsharp mask.
        """
        import cv2, numpy as np
        h, w = img_bgr.shape[:2]
        # Note: do NOT bail early if same size — quality algorithms
        # (Lanczos+USM, Real-ESRGAN) still improve detail at same resolution.
        # Only Gaussian gets skipped (pure resize, meaningless at same size).
        _alg = getattr(self,"rife_upscale_var",None)
        _alg_val = _alg.get() if _alg else "Gaussian"
        if w == target_w and h == target_h and _alg_val == "Gaussian":
            return img_bgr

        # Try Real-ESRGAN if model is available
        esrgan_bin = os.path.expanduser(
            "~/RifeApp/realesrgan-ncnn-vulkan/realesrgan-ncnn-vulkan")
        if os.path.exists(esrgan_bin):
            try:
                import tempfile, subprocess as _sp
                with tempfile.NamedTemporaryFile(suffix=".png",delete=False) as _ti:
                    _in = _ti.name
                with tempfile.NamedTemporaryFile(suffix=".png",delete=False) as _to:
                    _out_path = _to.name
                cv2.imwrite(_in, img_bgr)
                # Use x4plus model; -s controls output scale
                _scale = max(2, round(target_w / w))
                _model_dir = os.path.dirname(esrgan_bin)
                r = _sp.run([esrgan_bin,
                    "-i", _in, "-o", _out_path,
                    "-n", "realesrgan-x4plus",
                    "-s", str(_scale),
                    "-f", "png"],
                    capture_output=True, timeout=120)
                os.unlink(_in)
                if r.returncode == 0 and os.path.exists(_out_path):
                    out = cv2.imread(_out_path)
                    os.unlink(_out_path)
                    if out is not None:
                        if out.shape[1] != target_w or out.shape[0] != target_h:
                            out = cv2.resize(out,(target_w,target_h),
                                             interpolation=cv2.INTER_LANCZOS4)
                        return out
                os.unlink(_out_path)
            except Exception as ex:
                pass  # fall through to Lanczos fallback

        # Fallback: cv2 LANCZOS4 + unsharp mask
        out = cv2.resize(img_bgr, (target_w, target_h), interpolation=cv2.INTER_LANCZOS4)
        blur = cv2.GaussianBlur(out, (0, 0), 1.5)
        out  = cv2.addWeighted(out, 1.4, blur, -0.4, 0)
        return out

    def _rife_zoom_1to1(self):
        """Set zoom so 1 source pixel = 1 display pixel."""
        base = self._rife_wipe_orig_base or self._rife_wipe_riff_base
        if base is None: return
        cw = self.rife_wipe_canvas.winfo_width()
        ch = self.rife_wipe_canvas.winfo_height()
        if cw < 2 or ch < 2: return
        iw, ih = base.size
        fit_scale = max(cw / iw, ch / ih)
        self._rife_zoom = 1.0 / fit_scale  # → nw=iw, nh=ih
        self._rife_pan_x = 0
        self._rife_pan_y = 0
        self._rife_display()

    def _rife_zoom_reset(self):
        self._rife_zoom  = 1.0
        self._rife_pan_x = 0
        self._rife_pan_y = 0
        self._rife_wipe_orig_raw = None  # force refit
        if self._rife_mode == "diff":
            self._rife_diff_draw()
        elif self._rife_mode == "wipe":
            self._rife_wipe_draw()
        else:
            self._rife_display()


    def _rife_canvas_scroll(self, e):
        if hasattr(e, "delta") and e.delta != 0:
            factor = 0.15 if e.delta > 0 else -0.15
        else:
            factor = 0.15 if e.num == 4 else -0.15
        old = self._rife_zoom
        self._rife_zoom = max(0.25, min(8.0, old + factor))
        ratio = self._rife_zoom / old
        self._rife_pan_x = int(e.x - ratio * (e.x - self._rife_pan_x))
        self._rife_pan_y = int(e.y - ratio * (e.y - self._rife_pan_y))
        self._rife_diff_draw() if self._rife_mode == "diff" else (self._rife_display() if self._rife_mode == "preview" else self._rife_wipe_draw())

    def _rife_pan_start(self, e):
        self._rife_pan_start_pos = (e.x, e.y, self._rife_pan_x, self._rife_pan_y)

    def _rife_pan_move(self, e):
        if not self._rife_pan_start_pos: return
        sx, sy, ox, oy = self._rife_pan_start_pos
        self._rife_pan_x = ox + (e.x - sx)
        self._rife_pan_y = oy + (e.y - sy)
        self._rife_diff_draw() if self._rife_mode == "diff" else (self._rife_display() if self._rife_mode == "preview" else self._rife_wipe_draw())

    def _rife_canvas_click(self, e):
        if self._rife_mode == "wipe":
            self._rife_dragging_wipe = True
            self._rife_wipe_drag_ev(e)

    def _rife_canvas_b1_motion(self, e):
        if self._rife_mode == "wipe" and self._rife_dragging_wipe:
            self._rife_wipe_drag_ev(e)

    def _rife_canvas_release(self, e):
        self._rife_dragging_wipe = False

    def _rife_wipe_drag_ev(self, e):
        if self._rife_wipe_orig_base is None and \
                not getattr(self,"_rife_playing",False):
            return
        import math
        # Use same size source as _rife_wipe_draw to keep t consistent
        cw = getattr(self,"_rife_canvas_w",0) or self.rife_wipe_canvas.master.winfo_width()
        self.rife_wipe_canvas.update_idletasks()
        ch = self.rife_wipe_canvas.winfo_height()
        if cw < 50 or ch < 50: return
        ang = math.radians(self._rife_wipe_angle)
        nx, ny = math.cos(ang), math.sin(ang)
        proj = (e.x - cw/2) * nx + (e.y - ch/2) * ny
        scale = (cw/2) * abs(nx) + (ch/2) * abs(ny)
        self._rife_wipe_t = max(0.02, min(0.98,
            0.5 + (proj / scale) * 0.5 if scale > 0 else 0.5))
        # While playing, the next tick redraws with the new t —
        # doing a static draw here as well would fight the play loop.
        if not getattr(self,"_rife_playing",False):
            self._rife_wipe_draw()

    # ═══ REAL-TIME PLAYBACK with live wipe ═══════════════════════════════
    def _rife_play_toggle(self):
        if getattr(self,"_rife_play_building",False):
            # Play pressed mid-build = cancel; the build thread checks
            # this flag every frame and aborts.
            self._rife_play_cancel = True
            return
        if getattr(self,"_rife_playing",False):
            self._rife_play_stop()
        else:
            self._rife_play_start()

    def _rife_play_stop(self, quiet=False):
        self._rife_playing = False
        _t = getattr(self,"_rife_play_after_id",None)
        if _t:
            try: self.after_cancel(_t)
            except Exception: pass
            self._rife_play_after_id = None
        if hasattr(self,"_rife_play_btn"):
            self._rife_play_btn.configure(text="▶  Play", fg="#77AA77")
        # Sync the timeline selection to where playback stopped
        cache = getattr(self,"_rife_play_cache",None)
        if cache and not quiet:
            i = cache.get("pos", 0)
            try: self._rife_dual_tl.sync_orig_sel(cache["v0"] + i)
            except Exception: pass

    def _rife_play_start(self):
        if getattr(self,"_rife_playing",False): return
        if not getattr(self,"rife_folder",None) or \
                not getattr(self,"rife_frames",None):
            self.log(self.rlog, "Load a sequence first.", "err"); return
        if getattr(self,"_rife_play_building",False):
            self.log(self.rlog, "Playback cache is still building…", "dim")
            return

        # Read everything Tkinter on the MAIN thread before any thread work
        v0, v1 = self._rife_range_bar.get_range()
        v1 = min(v1, len(self.rife_frames))
        if v1 - v0 < 2:
            self.log(self.rlog, "Range too small to play.", "err"); return
        self.rife_wipe_canvas.update_idletasks()
        cw = max(64, self.rife_wipe_canvas.winfo_width())
        ch = max(64, self.rife_wipe_canvas.winfo_height())
        # Cap the playback buffer — playback is about motion, and
        # PhotoImage conversion cost scales with area. 1280 wide keeps
        # a comfortable 24fps budget on typical hardware.
        if cw > 1280:
            ch = int(ch * 1280 / cw); cw = 1280
        em  = {"2x — Smooth": 2, "4x — Very smooth": 4,
               "6x — Extra smooth": 6, "8x — Maximum": 8}
        total = em.get(self.rmult.get(), 4)

        folder = self.rife_folder
        adw    = self._rife_frames_dir(folder)   # raw RIFE frames
        ret    = self._rife_final_dir(folder)    # retimed deliverable
        out_dir = ret if os.path.isdir(ret) and os.listdir(ret) else \
                  (adw if os.path.isdir(adw) and os.listdir(adw) else None)
        out_mt  = 0
        if out_dir:
            try: out_mt = os.path.getmtime(out_dir)
            except Exception: pass

        key = (folder, v0, v1, out_dir, out_mt, cw, ch)
        cache = getattr(self,"_rife_play_cache",None)
        if cache and cache.get("key") == key:
            self._rife_play_begin_ticking()
            return

        # RAM guard — refuse absurd cache sizes rather than swapping
        est = (v1 - v0) * cw * ch * 3 * 2
        if est > 2_000_000_000:
            self.log(self.rlog,
                f"Playback cache would need ~{est//1_000_000} MB — narrow "
                f"the range slider first.", "err")
            return

        self._rife_play_building = True
        self._rife_play_cancel = False
        self._rife_play_btn.configure(text="…  Caching", progress=0.0)
        frames = list(self.rife_frames)
        self.log(self.rlog,
            f"Building playback cache: frames {v0}–{v1-1} at {cw}×{ch} "
            f"(~{est//1_000_000} MB RAM)…", "hi")

        import threading
        def _bg():
            try:
                self._rife_play_build_cache(key, folder, frames, v0, v1,
                                            out_dir, total, cw, ch)
            finally:
                self._rife_play_building = False
        threading.Thread(target=_bg, daemon=True).start()

    def _rife_play_build_cache(self, key, folder, frames, v0, v1,
                                out_dir, total, cw, ch):
        """Background thread: load input + output frames into RAM at
        playback resolution. No Tkinter calls except via self.after."""
        import numpy as np
        from PIL import Image

        root      = self._adw_output_root(folder)
        png_cache = os.path.join(root, "_png_cache")

        # Global norm scale — same source every EXR display load uses,
        # so playback matches the preview exactly.
        gscale = [None]
        try:
            import json as _j
            ci = _j.loads(open(os.path.join(png_cache,
                "_cache_info.json")).read())
            gscale[0] = float(ci.get("norm_scale") or 1.0)
        except Exception: pass

        def load_exr(path):
            import OpenEXR as _OE, Imath as _Im
            ef  = _OE.InputFile(path)
            hdr = ef.header()
            dw  = hdr["dataWindow"]; disp = hdr["displayWindow"]
            dww = dw.max.x-dw.min.x+1; dwh = dw.max.y-dw.min.y+1
            fw  = disp.max.x-disp.min.x+1; fh = disp.max.y-disp.min.y+1
            FP  = _Im.PixelType(_Im.PixelType.FLOAT)
            data = np.stack([np.frombuffer(ef.channel(c,FP),
                np.float32).reshape(dwh,dww) for c in "RGB"], axis=2)
            if (dww,dwh)==(fw,fh) and dw.min.x==disp.min.x \
                    and dw.min.y==disp.min.y:
                arr = data
            else:
                arr = np.zeros((fh,fw,3), dtype=np.float32)
                y0 = dw.min.y-disp.min.y; x0 = dw.min.x-disp.min.x
                arr[max(0,y0):max(0,y0)+dwh,
                    max(0,x0):max(0,x0)+dww] = data
            arr = np.maximum(arr, 0)
            sc = gscale[0]
            if sc is None:
                lum = arr.max(axis=2)
                sc = self._adw_auto_exposure_scale(lum) if lum.any() else 1.0
                gscale[0] = sc
            g = self._adw_gamma_encode(arr, sc)
            return Image.fromarray((g*255).astype(np.uint8))

        def load_any(path):
            if path.lower().endswith(".exr"):
                img = load_exr(path)
            else:
                img = Image.open(path).convert("RGB")
            # Fit inside cw×ch preserving aspect
            iw, ih = img.size
            s = min(cw/iw, ch/ih)
            return img.resize((max(1,int(iw*s)), max(1,int(ih*s))),
                              Image.LANCZOS)

        def listing(d):
            if not d or not os.path.isdir(d): return []
            fs = sorted(f for f in os.listdir(d)
                if os.path.splitext(f)[1].lower() in (".png",".exr"))
            seen = {}
            for f in fs:
                b = os.path.splitext(f)[0]
                if b not in seen or f.lower().endswith(".exr"):
                    seen[b] = f
            return [os.path.join(d, seen[b]) for b in sorted(seen)]

        out_files = listing(out_dir)
        # The retimed deliverable now lives at ADW/ADW-Blur; older runs
        # used an ADW-Blur_Retimed suffix, so accept both.
        _final = self._rife_final_dir(folder)
        out_is_retimed = bool(out_dir) and (
            os.path.abspath(out_dir) == os.path.abspath(_final)
            or out_dir.endswith("_Retimed"))
        step = total
        n = v1 - v0

        ins, outs = [], []
        err = [None]
        for k, i in enumerate(range(v0, v1)):
            if getattr(self, "_rife_play_cancel", False):
                self.after(0, lambda: (
                    self.log(self.rlog,
                             "Playback cache build cancelled.", "dim"),
                    self._rife_play_btn.configure(
                        text="\u25b6  Play", fg="#77AA77", progress=0.0)))
                return
            try:
                # INPUT — prefer the PNG cache (display-ready, fast)
                base = os.path.splitext(frames[i])[0]
                pc = os.path.join(png_cache, base + ".png")
                src = pc if os.path.isfile(pc) else \
                      os.path.join(folder, frames[i])
                im_in = load_any(src)

                # OUTPUT — retimed maps 1:1; raw ADW maps i → i*step
                im_out = None
                if out_files:
                    oi = i if out_is_retimed else i * step
                    if 0 <= oi < len(out_files):
                        im_out = load_any(out_files[oi])
                outs.append(im_out if im_out is not None else im_in)
                ins.append(im_in)
            except Exception as ex:
                err[0] = f"frame {i}: {str(ex)[:80]}"
                break
            if k % 3 == 0 or k == n-1:
                p = (k+1)/n
                self.after(0, lambda p=p:
                    self._rife_play_btn.configure(progress=p))

        if err[0] or len(ins) < 2:
            self.after(0, lambda e=err[0]: (
                self.log(self.rlog,
                    f"Playback cache failed — {e or 'not enough frames'}",
                    "err"),
                self._rife_play_btn.configure(text="▶  Play",
                    progress=0.0)))
            return

        no_out = not out_files
        self._rife_play_cache = {
            "key": key, "in": ins, "out": outs, "v0": v0, "v1": v1,
            "pos": 0, "cw": cw, "ch": ch, "no_out": no_out,
            "out_label": ("ADW-Blur retimed" if out_is_retimed else
                          "ADW-Blur" if out_files else "no output cached"),
            "mask_key": None, "mask": None,
        }
        if no_out:
            self.after(0, lambda: self.log(self.rlog,
                "No ADW output found — playing input only. Run Cache RIFE "
                "or Run ADW-Blur to compare against the output.", "err"))
        self.after(0, lambda: self.log(self.rlog,
            f"Playback cache ready — {len(ins)} frames.", "ok"))
        self.after(0, self._rife_play_begin_ticking)

    def _rife_play_begin_ticking(self):
        cache = getattr(self,"_rife_play_cache",None)
        if not cache: return
        self._rife_playing = True
        self._rife_mode = "wipe"   # so the wipe drag bindings route here
        self._rife_play_btn.configure(text="⏹  Stop", fg="#AAFFAA",
                                      progress=1.0)
        self._rife_play_last = 0.0
        self._rife_play_tick()

    def _rife_play_tick(self):
        if not getattr(self,"_rife_playing",False): return
        cache = self._rife_play_cache
        if not cache:
            self._rife_play_stop(quiet=True); return
        import time as _t
        t0 = _t.perf_counter()

        i = cache["pos"]
        self._rife_play_draw(i)

        # Sync the timeline playhead every 4th frame (full canvas redraw
        # is too heavy to do at every tick)
        if i % 4 == 0:
            try: self._rife_dual_tl.sync_orig_sel(cache["v0"] + i)
            except Exception: pass

        nxt = i + 1
        if nxt >= len(cache["in"]):
            if self._rife_play_loop:
                nxt = 0
            else:
                self._rife_play_stop(); return
        cache["pos"] = nxt
        # Frame-time compensation: subtract however long the draw took.
        # Speed < 1.0 = slow motion (longer per-frame budget).
        budget = 1000.0 / max(0.5, self._rife_play_fps *
                              self._rife_play_speed)
        spent  = (_t.perf_counter() - t0) * 1000.0
        delay  = max(1, int(budget - spent))
        self._rife_play_after_id = self.after(delay, self._rife_play_tick)

    def _rife_play_set_loop(self, on):
        self._rife_play_loop = on
        self._rife_loop_btn.configure(
            bg="#0F350F" if on else "#0D0D0D",
            fg="#AAFFAA" if on else "#555555")

    def _rife_play_cycle_speed(self):
        order = [1.0, 0.5, 0.25]
        cur = order.index(self._rife_play_speed) \
            if self._rife_play_speed in order else 0
        self._rife_play_speed = order[(cur + 1) % 3]
        lbl = {1.0: "1×", 0.5: "½×", 0.25: "¼×"}[self._rife_play_speed]
        self._rife_speed_btn.configure(
            text=lbl, fg=(G if self._rife_play_speed == 1.0 else "#CCAA44"))

    # ═══ PAINT-MODULE PLAYER (Curve Look / Area Look) ════════════════════
    # Same cache-then-play pattern as ADW-Blur, generalised over the two
    # paint modules ("curve"/"area"). The output side is each module's own
    # corrected image, so the cache builder drives the module's REAL
    # per-frame pipeline (frame load → preview → corrected wipe base)
    # frame by frame -- chunked on the main thread via after(), since the
    # preview computation reads Tkinter state and isn't thread-safe.
    # Playback uses the module's EXISTING viewport wipe (_<mod>_wipe_t):
    # no extra wipe controls, dragging the wipe works while playing.
    def _pp_has_wipe(self, mod):
        """Does this module have a second image to wipe against? The paint
        modules wipe original against corrected; ADW-Interpolate wipes the
        source plate against the spliced result, which is the only way to
        actually SEE a six-frame gap fill."""
        if mod == "ip":
            return bool(self.ip_result_dir
                        and os.path.isdir(self.ip_result_dir))
        return True

    def _pp_wipe_labels(self, mod):
        return {"ip":      ("Source", "Result"),
                "organic": ("Original", "Organic")}.get(
                    mod, ("Original", "Corrected"))

    def _pp_state(self, mod):
        if not hasattr(self, "_pp"): self._pp = {}
        if mod not in self._pp:
            self._pp[mod] = {"playing": False, "cache": None,
                             "building": False, "loop": True,
                             "speed": 1.0, "fps": 24, "after": None,
                             "edit_seq": 0, "build_job": None}
        return self._pp[mod]

    def _pp_invalidate(self, mod, restart_if_playing=True):
        """A parameter changed — the current playback cache no longer
        matches what the user is seeing. Bumping edit_seq alone would
        only take effect the next time the user hits Play manually;
        during an active loop nothing would change. So this also stops
        and transparently restarts playback so the cache rebuilds
        against the new params. If we\'re currently building, cancel
        that build first — no point finishing a cache the user has
        already moved past."""
        st = self._pp_state(mod)
        st["edit_seq"] += 1
        # Wipe the pinned cache so the key comparison in _pp_start
        # can\'t accidentally match a stale entry
        st["cache"] = None
        if st["building"]:
            if st["build_job"]:
                try: self.after_cancel(st["build_job"])
                except Exception: pass
                st["build_job"] = None
            st["building"] = False
            btn = getattr(self, f"_{mod}_play_btn", None)
            if btn: btn.configure(text="\u25b6  Play", fg="#77AA77",
                                   progress=0.0)
        if restart_if_playing and st["playing"]:
            self._pp_stop(mod, quiet=True)
            self._pp_start(mod)

    def _pp_toggle(self, mod):
        st = self._pp_state(mod)
        if st["building"]:
            # Play pressed mid-build = cancel the build. Drop the
            # partial cache -- reusing it would play a truncated range.
            if st["build_job"]:
                try: self.after_cancel(st["build_job"])
                except Exception: pass
                st["build_job"] = None
            st["building"] = False
            st["cache"] = None
            getattr(self, f"_{mod}_play_btn").configure(
                text="\u25b6  Play", fg="#77AA77", progress=0.0)
            self.log(getattr(self, f"{mod}_log_txt"),
                     "Playback cache build cancelled.", "dim")
            return
        if st["playing"]: self._pp_stop(mod)
        else:             self._pp_start(mod)

    def _pp_stop(self, mod, quiet=False):
        st = self._pp_state(mod)
        st["playing"] = False
        if st["after"]:
            try: self.after_cancel(st["after"])
            except Exception: pass
            st["after"] = None
        if st["build_job"]:
            try: self.after_cancel(st["build_job"])
            except Exception: pass
            st["build_job"] = None
            st["building"] = False
        btn = getattr(self, f"_{mod}_play_btn", None)
        if btn: btn.configure(text="▶  Play", fg="#77AA77")
        cache = st["cache"]
        if cache and not quiet:
            # Land the module's UI on the stopped frame
            idx = cache["v0"] + cache.get("pos", 0)
            try:
                getattr(self, f"{mod}_frame_cb").select(idx)
                getattr(self, f"_{mod}_frame_selected")()
            except Exception: pass

    def _pp_start(self, mod):
        st = self._pp_state(mod)
        if st["playing"] or st["building"]: return
        folder = getattr(self, f"{mod}_folder", None)
        frames = getattr(self, f"{mod}_frames", None)
        log    = getattr(self, f"{mod}_log_txt")
        if not folder or not frames:
            self.log(log, "Load a sequence first.", "err"); return
        v0, v1 = getattr(self, f"_{mod}_range_bar").get_range()
        v1 = min(v1, len(frames))
        if v1 - v0 < 2:
            self.log(log, "Range too small to play.", "err"); return
        canvas = getattr(self, f"{mod}_canvas")
        canvas.update_idletasks()
        cw = max(64, canvas.winfo_width())
        ch = max(64, canvas.winfo_height())
        if cw > 1280:
            ch = int(ch * 1280 / cw); cw = 1280

        key = (folder, v0, v1, st["edit_seq"], cw, ch)
        if st["cache"] and st["cache"].get("key") == key:
            self._pp_begin(mod); return

        est = (v1 - v0) * cw * ch * 3 * 2
        if est > 2_000_000_000:
            self.log(log, f"Playback cache would need ~{est//1_000_000} MB "
                     f"— narrow the range slider first.", "err")
            return

        st["building"] = True
        st["cache"] = {"key": key, "in": [], "out": [], "v0": v0,
                       "v1": v1, "pos": 0, "cw": cw, "ch": ch}
        btn = getattr(self, f"_{mod}_play_btn")
        btn.configure(text="…  Caching", progress=0.0)
        self.log(log, f"Building playback cache: frames {v0}–{v1-1} — "
                 f"this runs the {'curve' if mod=='curve' else 'area'} "
                 f"correction on each frame once…", "hi")
        self._pp_build_step(mod, v0)

    def _pp_build_step(self, mod, i):
        """Process ONE frame of the cache build, then yield to the event
        loop. Drives the module's real pipeline so the corrected result
        is exactly what the static preview shows."""
        st = self._pp_state(mod)
        cache = st["cache"]
        if not st["building"] or cache is None: return
        from PIL import Image
        folder = getattr(self, f"{mod}_folder")
        frames = getattr(self, f"{mod}_frames")
        log    = getattr(self, f"{mod}_log_txt")
        v0, v1, cw, ch = cache["v0"], cache["v1"], cache["cw"], cache["ch"]
        try:
            getattr(self, f"{mod}_frame_cb").select(i)
            getattr(self, f"_{mod}_load_frame")(
                os.path.join(folder, frames[i]))
            orig = getattr(self, f"{mod}_img_base")
            corr = getattr(self, f"_{mod}_wipe_corrected_base") or orig
            def fit(img):
                iw, ih = img.size
                s = min(cw/iw, ch/ih)
                return img.resize((max(1,int(iw*s)), max(1,int(ih*s))),
                                  Image.LANCZOS)
            cache["in"].append(fit(orig))
            cache["out"].append(fit(corr))
        except Exception as ex:
            st["building"] = False; st["cache"] = None
            self.log(log, f"Playback cache failed at frame {i} — "
                     f"{str(ex)[:80]}", "err")
            getattr(self, f"_{mod}_play_btn").configure(
                text="▶  Play", progress=0.0)
            return
        done = i - v0 + 1
        getattr(self, f"_{mod}_play_btn").configure(
            progress=done / (v1 - v0))
        if i + 1 < v1:
            st["build_job"] = self.after(1, lambda:
                self._pp_build_step(mod, i + 1))
        else:
            st["building"] = False; st["build_job"] = None
            self.log(log, f"Playback cache ready — {done} frames.", "ok")
            self._pp_begin(mod)

    def _pp_begin(self, mod):
        st = self._pp_state(mod)
        if not st["cache"]: return
        st["playing"] = True
        setattr(self, f"{mod}_mode", "wipe")  # existing wipe drag routes
        getattr(self, f"_{mod}_play_btn").configure(
            text="⏹  Stop", fg="#AAFFAA", progress=1.0)
        self._pp_tick(mod)

    def _pp_tick(self, mod):
        st = self._pp_state(mod)
        if not st["playing"]: return
        cache = st["cache"]
        if not cache:
            self._pp_stop(mod, quiet=True); return
        import time as _t
        t0 = _t.perf_counter()
        i = cache["pos"]
        self._pp_draw(mod, i)
        if i % 4 == 0:
            try: getattr(self, f"{mod}_frame_cb").select(cache["v0"] + i)
            except Exception: pass
        nxt = i + 1
        if nxt >= len(cache["in"]):
            if st["loop"]: nxt = 0
            else: self._pp_stop(mod); return
        cache["pos"] = nxt
        budget = 1000.0 / max(0.5, st["fps"] * st["speed"])
        spent  = (_t.perf_counter() - t0) * 1000.0
        st["after"] = self.after(max(1, int(budget - spent)),
                                 lambda: self._pp_tick(mod))

    def _pp_draw(self, mod, i):
        """One playback frame through the module's EXISTING wipe:
        left = original, right = corrected, split at _<mod>_wipe_t."""
        from PIL import Image, ImageTk
        st = self._pp_state(mod)
        cache = st["cache"]
        im_in, im_out = cache["in"][i], cache["out"][i]
        cw, ch = cache["cw"], cache["ch"]
        canvas = getattr(self, f"{mod}_canvas")
        canvas_w = canvas.winfo_width(); canvas_h = canvas.winfo_height()
        if canvas_w < 10 or canvas_h < 10: return
        bg_in  = Image.new("RGB", (cw, ch), (13,13,13))
        bg_out = Image.new("RGB", (cw, ch), (13,13,13))
        bg_in.paste(im_in,  ((cw-im_in.size[0])//2,  (ch-im_in.size[1])//2))
        bg_out.paste(im_out, ((cw-im_out.size[0])//2, (ch-im_out.size[1])//2))
        t = getattr(self, f"_{mod}_wipe_t")
        cx = int(t * cw)
        comp = bg_in
        if cx < cw:
            comp.paste(bg_out.crop((cx, 0, cw, ch)), (cx, 0))
        if (cw, ch) != (canvas_w, canvas_h):
            s = min(canvas_w/cw, canvas_h/ch)
            comp = comp.resize((max(1,int(cw*s)), max(1,int(ch*s))),
                               Image.BILINEAR)
        tk_img = ImageTk.PhotoImage(comp)
        setattr(self, f"_{mod}_play_tk", tk_img)
        canvas.delete("all")
        ox = (canvas_w - comp.size[0]) // 2
        oy = (canvas_h - comp.size[1]) // 2
        canvas.create_image(ox, oy, anchor="nw", image=tk_img)
        # Same wipe line + handle visuals as the module's static wipe.
        # Modules with no correction pass (ADW-Interpolate just plays the
        # source back) get no wipe furniture — there is nothing to
        # compare against, so a split line and an Original/Corrected
        # label would be a lie.
        if self._pp_has_wipe(mod):
            split_x = ox + int(t * comp.size[0])
            canvas.create_line(split_x, 0, split_x, canvas_h,
                               fill="#DCDCDC", width=2, tags="wipe_line")
            hs = 9; hy = canvas_h // 2
            canvas.create_rectangle(split_x-hs, hy-hs, split_x+hs, hy+hs,
                                    fill="#1A1A1A", outline="#DCDCDC")
            canvas.create_text(split_x-13, hy, text="◀",
                               fill="#DCDCDC", font=("Helvetica", 9))
            canvas.create_text(split_x+13, hy, text="▶",
                               fill="#DCDCDC", font=("Helvetica", 9))
            if split_x > 76:
                _lb_l, _lb_r = self._pp_wipe_labels(mod)
                canvas.create_text(6, 8, anchor="nw", text=_lb_l,
                                   font=FM, fill="#888888")
            if split_x < canvas_w - 86:
                canvas.create_text(split_x+8, 8, anchor="nw",
                                   text=_lb_r, font=FM, fill="#888888")
        canvas.create_text(canvas_w-6, canvas_h-8, anchor="se",
            text=f"▶ {cache['v0']+i}  ({i+1}/{len(cache['in'])})  "
                 f"{st['fps']} fps",
            font=FM, fill="#666666")

    def _pp_set_loop(self, mod, on):
        st = self._pp_state(mod); st["loop"] = on
        btn = getattr(self, f"_{mod}_loop_btn")
        btn.configure(bg="#0F350F" if on else "#0D0D0D",
                      fg="#AAFFAA" if on else "#555555")

    def _pp_cycle_speed(self, mod):
        st = self._pp_state(mod)
        order = [1.0, 0.5, 0.25]
        cur = order.index(st["speed"]) if st["speed"] in order else 0
        st["speed"] = order[(cur + 1) % 3]
        lbl = {1.0: "1×", 0.5: "½×", 0.25: "¼×"}[st["speed"]]
        getattr(self, f"_{mod}_speed_btn").configure(
            text=lbl, fg=(G if st["speed"] == 1.0 else "#CCAA44"))

    def _pp_make_buttons(self, mod, parent):
        """Play / Loop / Speed button strip for a paint module's header
        row. Uses the module's existing viewport wipe — deliberately no
        wipe controls here."""
        btn = self._mk_progress_btn(parent, "▶  Play",
            lambda: self._pp_toggle(mod), bg="#0D0D0D", fg="#77AA77",
            fill_color="#1E6A1E", dim_fill_color="#0F350F")
        btn.configure_native(width=120, height=22)
        btn.pack(side="left", padx=(0,4))
        setattr(self, f"_{mod}_play_btn", btn)
        def _fps_menu(e):
            m = tk.Menu(self, tearoff=0, bg=S, fg=W, activebackground=BD,
                        activeforeground=W, font=FM, bd=0, relief="flat")
            st = self._pp_state(mod)
            for fps in [12, 24, 25, 30, 48, 60]:
                tick = "✓ " if st["fps"] == fps else "  "
                m.add_command(label=f"{tick}{fps} fps",
                    command=lambda f=fps: st.update(fps=f))
            try: m.tk_popup(e.x_root, e.y_root)
            finally: m.grab_release()
        btn.bind("<Button-3>", _fps_menu)
        btn.bind("<Button-2>", _fps_menu)
        lp = self._mkbtn(parent, "⟳ Loop",
            lambda: self._pp_set_loop(mod, not self._pp_state(mod)["loop"]),
            bg="#0F350F", fg="#AAFFAA")
        tk.Label.configure(lp._lbl, width=7, pady=2)
        lp.pack(side="left", padx=(0,4))
        setattr(self, f"_{mod}_loop_btn", lp)
        sp = self._mkbtn(parent, "1×",
            lambda: self._pp_cycle_speed(mod), bg="#0D0D0D", fg=G)
        tk.Label.configure(sp._lbl, width=4, pady=2)
        sp.pack(side="left", padx=(0,10))
        setattr(self, f"_{mod}_speed_btn", sp)

    def _rife_play_draw(self, i):
        """Fast wipe composite for one playback frame. Horizontal wipe is
        a crop+paste; angled wipes use a mask cached per (angle,t,size)."""
        import math
        from PIL import Image, ImageTk
        cache = self._rife_play_cache
        im_in, im_out = cache["in"][i], cache["out"][i]
        cw, ch = cache["cw"], cache["ch"]

        canvas_w = self.rife_wipe_canvas.winfo_width()
        canvas_h = self.rife_wipe_canvas.winfo_height()
        if canvas_w < 10 or canvas_h < 10: return

        # Compose at cache resolution, centred on a letterbox
        bg_in  = Image.new("RGB", (cw, ch), (10,10,10))
        bg_out = Image.new("RGB", (cw, ch), (10,10,10))
        px = (cw - im_in.size[0]) // 2
        py = (ch - im_in.size[1]) // 2
        bg_in.paste(im_in,  (px, py))
        pxo = (cw - im_out.size[0]) // 2
        pyo = (ch - im_out.size[1]) // 2
        bg_out.paste(im_out, (pxo, pyo))

        ang = self._rife_wipe_angle
        t   = self._rife_wipe_t
        rad = math.radians(ang)
        nx_, ny_ = math.cos(rad), math.sin(rad)
        cx = int(cw/2 + (t - 0.5) * cw * nx_)
        cy = int(ch/2 + (t - 0.5) * ch * ny_)

        if ang == 0:
            comp = bg_in
            if cx < cw:
                comp.paste(bg_out.crop((cx, 0, cw, ch)), (cx, 0))
        else:
            mkey = (ang, round(t, 3), cw, ch)
            if cache.get("mask_key") != mkey:
                import numpy as np
                ys, xs = np.mgrid[0:ch, 0:cw]
                dist = (xs - cx)*nx_ + (ys - cy)*ny_
                cache["mask"] = Image.fromarray(
                    (dist >= 0).astype(np.uint8)*255, "L")
                cache["mask_key"] = mkey
            comp = bg_in
            comp.paste(bg_out, (0, 0), cache["mask"])

        # Scale composited frame up/down to the actual canvas size
        if (cw, ch) != (canvas_w, canvas_h):
            s = min(canvas_w/cw, canvas_h/ch)
            comp = comp.resize((max(1,int(cw*s)), max(1,int(ch*s))),
                               Image.BILINEAR)
        self._rife_play_tk = ImageTk.PhotoImage(comp)
        cv = self.rife_wipe_canvas
        cv.delete("all")
        ox = (canvas_w - comp.size[0]) // 2
        oy = (canvas_h - comp.size[1]) // 2
        cv.create_image(ox, oy, anchor="nw", image=self._rife_play_tk)

        # Wipe line + drag handle (canvas coords)
        sx = comp.size[0] / cw
        hx = ox + cx * sx
        hy = oy + cy * sx
        perp = math.radians(ang + 90)
        half = max(canvas_w, canvas_h)
        cv.create_line(int(hx - math.cos(perp)*half),
                       int(hy - math.sin(perp)*half),
                       int(hx + math.cos(perp)*half),
                       int(hy + math.sin(perp)*half),
                       fill="#DCDCDC", width=2, tags="wipe_line")
        hs = 10
        for sign in (1, -1):
            tip_x = int(hx + sign*nx_*hs*2); tip_y = int(hy + sign*ny_*hs*2)
            b1x = int(hx + sign*nx_*hs - ny_*hs)
            b1y = int(hy + sign*ny_*hs + nx_*hs)
            b2x = int(hx + sign*nx_*hs + ny_*hs)
            b2y = int(hy + sign*ny_*hs - nx_*hs)
            cv.create_polygon(tip_x,tip_y,b1x,b1y,b2x,b2y,
                fill="#DCDCDC", outline="", tags="wipe_handle")

        # Labels + frame counter
        if hx > 90:
            cv.create_text(6, 8, anchor="nw", text="Input",
                           font=FM, fill="#888888")
        if hx < canvas_w - 90:
            cv.create_text(int(hx)+20, 8, anchor="nw",
                           text=cache["out_label"], font=FM, fill=GR)
        cv.create_text(canvas_w-6, canvas_h-8, anchor="se",
            text=f"▶ {cache['v0']+i}  ({i+1}/{len(cache['in'])})  "
                 f"{self._rife_play_fps} fps",
            font=FM, fill="#666666")

    def _load_frame_pil(self, path, max_w, max_h):
        """Load any frame (incl EXR) as a PIL Image fitted to max_w x max_h."""
        from PIL import Image
        ext = os.path.splitext(path)[1].lower()
        if ext == ".exr":
            import tempfile
            tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
            tmp.close()
            subprocess.run(["ffmpeg","-y","-i",path,"-vf","tonemap=reinhard",tmp.name],
                           capture_output=True)
            img = Image.open(tmp.name).convert("RGB")
            os.unlink(tmp.name)
        else:
            img = Image.open(path).convert("RGB")
        img.thumbnail((max_w, max_h), Image.LANCZOS)
        return img

    def _load_frame_rgb(self, path):
        """Load any frame (incl EXR) as a PIL RGB Image, full resolution."""
        from PIL import Image
        ext = os.path.splitext(path)[1].lower()
        if ext == ".exr":
            import tempfile
            tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
            tmp.close()
            subprocess.run(["ffmpeg","-y","-i",path,"-vf","tonemap=reinhard",tmp.name],
                           capture_output=True)
            img = Image.open(tmp.name).convert("RGB")
            os.unlink(tmp.name)
        else:
            img = Image.open(path).convert("RGB")
        return img

    def _range_bar(self, parent, get_proxies):
        """
        Range/overview bar. The full animation is mapped across the bar width.
        Left/right handles set view_start and view_end frame indices.
        Both timelines below redraw to show only those frames.
        Handles are draggable; body pans the window.
        """
        HANDLE_PX = 10
        cv = tk.Canvas(parent, bg="#111111", height=20,
                       highlightthickness=1, highlightbackground=BD)
        cv.pack(fill="x", pady=(0,4))

        st = {"n":0, "v0":0, "v1":0,
              "drag":None, "drag_x":0,
              "save_v0":0, "save_v1":0}

        def _w(): return cv.winfo_width() or 400
        def _fx(i): return int(i / st["n"] * _w()) if st["n"] else 0
        def _xi(x): return max(0, min(st["n"], int(x / _w() * st["n"])))

        def _draw():
            cv.delete("all")
            n = st["n"]; w = _w(); h = 20
            cv.create_rectangle(0,3,w,h-3, fill="#1A1A1A", outline="")
            if not n: return
            # Tick marks every ~8% of total
            step = max(1, n//12)
            for i in range(0,n+1,step):
                x=_fx(i)
                cv.create_line(x,h-6,x,h-3,fill="#2A2A2A")
            # Frame number labels at wider intervals
            for i in range(0,n+1,max(1,n//6)):
                x=_fx(i)
                cv.create_text(x,4,text=str(i+1),
                    font=("Helvetica",9),fill="#333333",anchor="n")
            # Greyed-out regions outside window
            x0=_fx(st["v0"]); x1=_fx(st["v1"])
            if x0>0:
                cv.create_rectangle(0,3,x0,h-3,fill="#0A0A0A",outline="")
            if x1<w:
                cv.create_rectangle(x1,3,w,h-3,fill="#0A0A0A",outline="")
            # Viewport body
            cv.create_rectangle(x0+HANDLE_PX,2,x1-HANDLE_PX,h-2,
                fill="#2A0A0A",outline="")
            # Left handle
            cv.create_rectangle(x0,2,x0+HANDLE_PX,h-2,
                fill="#5A1A1A",outline="#CC4444",width=1)
            for dy in [6,10,14]:
                cv.create_line(x0+3,dy,x0+7,dy,fill="#AA3333")
            # Right handle
            cv.create_rectangle(x1-HANDLE_PX,2,x1,h-2,
                fill="#5A1A1A",outline="#CC4444",width=1)
            for dy in [6,10,14]:
                cv.create_line(x1-7,dy,x1-3,dy,fill="#AA3333")
            # Frame range label in body
            mid=(x0+x1)//2
            cv.create_text(mid,h//2,
                text=f"{st['v0']+1}–{st['v1']}",
                font=("Helvetica",10,"bold"),fill="#CC4444",anchor="center")

        def _apply():
            for p in get_proxies():
                if p and hasattr(p,"set_view"):
                    p.set_view(st["v0"], st["v1"])

        def _hit(ex):
            x0=_fx(st["v0"]); x1=_fx(st["v1"])
            if x0<=ex<=x0+HANDLE_PX: return "left"
            if x1-HANDLE_PX<=ex<=x1:  return "right"
            if x0+HANDLE_PX<ex<x1-HANDLE_PX: return "body"
            return "outer"

        def _press(e):
            h=_hit(e.x)
            st["drag"]=h; st["drag_x"]=e.x
            st["save_v0"]=st["v0"]; st["save_v1"]=st["v1"]
            cv.configure(cursor="sb_h_double_arrow" if h in("left","right")
                         else "fleur" if h=="body" else "arrow")
            if h=="outer":
                # Click outside: centre window on click
                span=st["v1"]-st["v0"]
                ci=_xi(e.x)
                v0=max(0,min(st["n"]-span,ci-span//2))
                st["v0"]=v0; st["v1"]=v0+span
                _apply(); _draw()

        def _drag(e):
            if not st["drag"] or st["drag"]=="outer": return
            n=st["n"]; dx_frames=_xi(e.x)-_xi(st["drag_x"])
            sv0=st["save_v0"]; sv1=st["save_v1"]
            span=sv1-sv0
            if st["drag"]=="body":
                v0=max(0,min(n-span,sv0+dx_frames))
                st["v0"]=v0; st["v1"]=v0+span
            elif st["drag"]=="left":
                v0=max(0,min(sv1-1,sv0+dx_frames))
                st["v0"]=v0
            elif st["drag"]=="right":
                v1=max(sv0+1,min(n,sv1+dx_frames))
                st["v1"]=v1
            _apply(); _draw()

        def _cursor(e):
            h=_hit(e.x)
            cv.configure(cursor="sb_h_double_arrow" if h in("left","right")
                         else "fleur" if h=="body" else "arrow")

        cv.bind("<Button-1>",     _press)
        cv.bind("<B1-Motion>",    _drag)
        cv.bind("<ButtonRelease-1>", lambda e: (st.update(drag=None),
                                     cv.configure(cursor="arrow")))
        cv.bind("<Motion>",       _cursor)
        cv.bind("<Configure>",    lambda e: _draw())

        class _RangeProxy:
            def set_n(_self, n):
                st["n"]=n; st["v0"]=0; st["v1"]=n
                _apply(); _draw()
                cv.after(100,_draw)
        return _RangeProxy()


    def _rife_timeline2(self, parent):
        """Riffled-output timeline: original positions in red, interp in green."""
        outer = tk.Frame(parent, bg="#0D0D0D",
                         highlightthickness=1, highlightbackground=BD)
        outer.pack(side="left", fill="x", expand=True)
        cv = tk.Canvas(outer, bg="#0D0D0D", height=20,
                       highlightthickness=0, bd=0)
        cv.pack(fill="both", expand=True)

        # Colour scheme matching main timeline but green for interp frames
        C_ORIG_TICK="#4A0A0A"; C_INTERP_TICK="#1A3A1A"
        C_TICK_MAJ="#3A3A3A"; C_LABEL="#445544"
        C_CURSOR="#CC4444"; C_CUR_TXT="#FF6666"
        C_INTERP_BAND="#0D1A0D"

        state = {"n_orig": 0, "exp": 1, "idx": 0, "dragging": False}

        def total_frames():
            n=state["n_orig"]; e=state["exp"]
            return max(0,n*e-(e-1)) if n>1 else n

        def _draw():
            cv.delete("all")
            n=total_frames()
            w=cv.winfo_width() or 400; h=40
            if not n:
                cv.create_text(w//2,h//2,text="Run ADW-Blur to populate",
                    font=("Helvetica",9),fill="#333333"); return
            e=state["exp"]
            def fx(i): return int(i/(n-1)*(w-1)) if n>1 else w//2
            # Shade interp bands (between orig frames)
            for oi in range(state["n_orig"]-1):
                x1=fx(oi*e); x2=fx((oi+1)*e)
                if x2>x1+1:
                    cv.create_rectangle(x1+1,0,x2-1,h,
                        fill=C_INTERP_BAND,outline="")
            # Tick marks — orig frames in dark red, interp in dark green
            for i in range(n):
                x=fx(i)
                is_o=(i%e==0)
                col=C_ORIG_TICK if is_o else C_INTERP_TICK
                hh=12 if is_o else 6
                cv.create_line(x,h-hh,x,h-1,fill=col)
            # Label orig frames at sensible intervals
            no=state["n_orig"]
            for maj,_ in [(200,1),(100,1),(50,1),(25,1),(10,1),(5,1),(1,1)]:
                if no>=maj*2:
                    for oi in range(0,no,maj):
                        x=fx(oi*e)
                        cv.create_text(x,h-15,text=str(oi+1),
                            font=("Helvetica",10),fill=C_LABEL,anchor="s")
                    break
            # Cursor
            ci=state["idx"]; cx_=fx(ci)
            cv.create_line(cx_,0,cx_,h,fill=C_CURSOR,width=2)
            lbl_x=max(20,min(w-20,cx_))
            cv.create_text(lbl_x,3,text=str(ci+1),
                font=("Helvetica",9,"bold"),fill=C_CUR_TXT,anchor="n")
            cv.create_polygon(cx_-5,h,cx_+5,h,cx_,h-8,
                fill=C_CURSOR,outline="")

        def _x_to_idx(x):
            n=total_frames()
            if not n: return 0
            w=cv.winfo_width() or 400
            return max(0,min(n-1,int(round(x/max(1,w-1)*(n-1)))))

        def _click(e):
            if not total_frames(): return
            state["dragging"]=True
            state["idx"]=_x_to_idx(e.x)
            self._rife_rife_tl_idx=state["idx"]
            self._rife_tl_mode="rife"
            _draw(); self._rife_frame_selected()

        def _drag(e):
            if not state["dragging"] or not total_frames(): return
            ni=_x_to_idx(e.x)
            if ni!=state["idx"]:
                state["idx"]=ni
                self._rife_rife_tl_idx=ni
                self._rife_tl_mode="rife"
                _draw(); self._rife_frame_selected()

        cv.bind("<Button-1>",_click)
        cv.bind("<B1-Motion>",_drag)
        cv.bind("<ButtonRelease-1>",lambda e: state.update(dragging=False))
        cv.bind("<Configure>",lambda e: _draw())

        class _Proxy:
            def set_data(_self, n_orig, exp):
                state["n_orig"] = n_orig
                state["exp"]    = exp
                state["idx"]    = min(state["idx"], max(0,total_frames()-1))
                lbl = f"RIFE frames  ({exp}×  —  {total_frames()} total)"
                try: self._rife_rife_tl_lbl.configure(text=lbl)
                except Exception: pass
                _draw()
            def sync_to_orig(_self, orig_idx):
                """Highlight the orig-position in the rife timeline."""
                state["idx"] = orig_idx * state["exp"]
                _draw()
        return _Proxy()

    def _sync_range_to_other(self, source_key, v0, v1):
        """Mirror a range-bar drag from one of AreaLock/CurveLock to
        the other -- they're so often used together on the same (or
        chained, via the cross-module output handoff) footage that
        having to re-drag the same range twice is pure friction.
        Clamped to the target's own frame count by set_view itself,
        so a mismatched sequence length just clips rather than breaking."""
        target = getattr(self, "_area_range_bar" if source_key == "curve"
                          else "_curve_range_bar", None)
        if target is None:
            return
        target.set_view(v0, v1)

    def _sync_frame_to_other(self, source_key, idx):
        """Mirror the current frame selection from one of AreaLock/
        CurveLock to the other, same reasoning as the range sync above.
        No-ops if the other module has no sequence loaded at all."""
        if source_key == "curve":
            frames  = getattr(self, "area_frames", None)
            folder  = getattr(self, "area_folder", None)
            cb      = getattr(self, "area_frame_cb", None)
            load_fn = getattr(self, "_area_load_frame", None)
        else:
            frames  = getattr(self, "curve_frames", None)
            folder  = getattr(self, "curve_folder", None)
            cb      = getattr(self, "curve_frame_cb", None)
            load_fn = getattr(self, "_curve_load_frame", None)
        if not frames or not folder or cb is None or load_fn is None:
            return
        clamped = max(0, min(len(frames)-1, idx))
        if cb.current() == clamped:
            return
        cb.select(clamped)
        load_fn(os.path.join(folder, frames[clamped]))

    def _maya_range_bar(self, parent, get_proxies, on_change=None):
        """Maya-style range slider with big draggable handles.
        on_change(v0, v1), if given, fires whenever the user actually
        drags a handle -- not when set_view() is called programmatically
        (e.g. to mirror another module's range), which avoids feedback
        loops between two range bars kept in sync with each other."""
        H = 32        # total canvas height including handle tabs
        RAIL_Y1 = 10  # rail top
        RAIL_Y2 = 22  # rail bottom
        HDL_W   = 14  # handle width px

        cv = tk.Canvas(parent, bg="#0D0D0D", height=H,
                       highlightthickness=1, highlightbackground=BD)
        cv.pack(fill="x", pady=(0, 4))

        st = {"n":0, "v0":0, "v1":0,
              "drag":None, "press_x":0, "save0":0, "save1":0}

        def _w():
            wv = cv.winfo_width()
            return wv if wv > 1 else 400
        def _f2x(f): return int(f / st["n"] * _w()) if st["n"] else 0
        def _x2f(x): return max(0, min(st["n"], round(x / _w() * st["n"])))

        def _draw():
            cv.delete("all")
            n = st["n"]; w = _w()
            # Rail background
            cv.create_rectangle(0, RAIL_Y1, w, RAIL_Y2,
                fill="#1A1A1A", outline="#2A2A2A")
            if not n: return
            x0 = _f2x(st["v0"]); x1 = _f2x(st["v1"])
            # Dim outside regions
            cv.create_rectangle(0,      RAIL_Y1, x0, RAIL_Y2, fill="#111111", outline="")
            cv.create_rectangle(x1, RAIL_Y1, w,      RAIL_Y2, fill="#111111", outline="")
            # Active range
            cv.create_rectangle(x0, RAIL_Y1, x1, RAIL_Y2, fill="#2A0A0A", outline="")
            # Tick marks
            step = max(1, n//(w//8))
            for i in range(0, n+1, step):
                x = _f2x(i); th = 5 if (i%(step*5)==0) else 3
                cv.create_line(x, RAIL_Y2-th, x, RAIL_Y2, fill="#333333")
            # Frame labels at wider intervals
            lstep = max(1, n//(w//50))
            for i in range(0, n+1, lstep):
                x = _f2x(i)
                cv.create_text(x, RAIL_Y1+1, text=str(i+1),
                    font=("Helvetica",9), fill="#444444", anchor="n")

            # ── Left handle (start) ──
            # Vertical bar full height
            cv.create_rectangle(x0-2, 0, x0+HDL_W, H,
                fill="#4A1010", outline="#CC4444", width=1)
            # Grip lines
            for gx in [x0+3, x0+6, x0+9]:
                cv.create_line(gx, 4, gx, H-4, fill="#883333", width=1)
            # Frame label tab
            cv.create_text(x0 + HDL_W//2, H//2,
                text=str(st["v0"]+1),
                font=("Helvetica", 8, "bold"), fill="#FF6666", anchor="center")

            # ── Right handle (end) ──
            cv.create_rectangle(x1-HDL_W, 0, x1+2, H,
                fill="#4A1010", outline="#CC4444", width=1)
            for gx in [x1-9, x1-6, x1-3]:
                cv.create_line(gx, 4, gx, H-4, fill="#883333", width=1)
            cv.create_text(x1 - HDL_W//2, H//2,
                text=str(st["v1"]),
                font=("Helvetica", 8, "bold"), fill="#FF6666", anchor="center")

        def _hit(x):
            if not st["n"]: return None
            x0 = _f2x(st["v0"]); x1 = _f2x(st["v1"])
            if x0-2 <= x <= x0+HDL_W:          return "start"
            if x1-HDL_W <= x <= x1+2:           return "end"
            if x0+HDL_W < x < x1-HDL_W:         return "body"
            return "outer"

        def _set_cursor(h):
            cv.configure(cursor="sb_h_double_arrow" if h in("start","end")
                         else "fleur" if h=="body" else "arrow")

        def _press(e):
            h = _hit(e.x)
            st.update(drag=h, press_x=e.x,
                      save0=st["v0"], save1=st["v1"])
            _set_cursor(h)
            if h == "outer":
                f = _x2f(e.x)
                if abs(f-st["v0"]) <= abs(f-st["v1"]):
                    st["v0"] = max(0, min(st["v1"]-1, f))
                else:
                    st["v1"] = max(st["v0"]+1, min(st["n"], f))
                _apply(); _draw()

        def _drag(e):
            if not st["drag"] or st["drag"]=="outer": return
            df = _x2f(e.x) - _x2f(st["press_x"])
            s0,s1,n = st["save0"],st["save1"],st["n"]
            if st["drag"]=="start":
                st["v0"] = max(0, min(s1-1, s0+df))
            elif st["drag"]=="end":
                st["v1"] = max(s0+1, min(n, s1+df))
            elif st["drag"]=="body":
                span = s1-s0
                v0 = max(0, min(n-span, s0+df))
                st["v0"]=v0; st["v1"]=v0+span
            _apply(); _draw()

        def _apply():
            for p in get_proxies():
                if p and hasattr(p,"set_view"):
                    p.set_view(st["v0"], st["v1"])
            if on_change:
                on_change(st["v0"], st["v1"])

        cv.bind("<Button-1>",        _press)
        cv.bind("<B1-Motion>",       _drag)
        cv.bind("<ButtonRelease-1>", lambda e:(st.update(drag=None),
                                    cv.configure(cursor="arrow")))
        cv.bind("<Motion>",          lambda e: _set_cursor(_hit(e.x)))
        cv.bind("<Configure>",       lambda e: _draw())

        class _RangeProxy:
            def set_n(_self, n):
                st.update(n=n, v0=0, v1=min(n, 22))
                _apply(); _draw(); cv.after(120, _draw)
            def set_view(_self, v0, v1):
                """Programmatic range set (e.g. mirroring another
                module) -- updates the proxied timelines and redraws,
                but deliberately doesn't call on_change, since this
                IS the response to a change, not a new one to repeat."""
                n = st["n"]
                if not n: return
                v0c = max(0, min(n-1, int(v0)))
                v1c = max(v0c+1, min(n, int(v1)))
                st["v0"] = v0c; st["v1"] = v1c
                for p in get_proxies():
                    if p and hasattr(p,"set_view"):
                        p.set_view(st["v0"], st["v1"])
                _draw()
            def get_range(_self): return st["v0"], st["v1"]
        return _RangeProxy()

    def _dual_timeline(self, parent, on_orig, on_rife):
        """
        Two-row timeline. Top row = original frames (T-cap).
        Bottom row = riffled interp (green) + T-stem (red).
        Each source frame is a T-shape: wide cap above, narrow stem below.
        """
        ROW_H    = 18
        COL_SRC        = "#3A0808"    # unselected source frame — very dark
        COL_SRC_CACHED = "#6A1414"    # PNG-cached source frame — slightly brighter
        COL_R_ORIG     = "#3A0808"    # unselected stem — matches cap
        COL_INTERP     = "#082308"    # uncalculated interp — darker green, not yet cached
        COL_INTERP_HOT = "#1E6A1E"    # calculated interp — visible green
        COL_SEL_RED    = "#FF4444"    # selected source frame
        COL_SEL_GREEN  = "#55FF55"    # selected interp frame
        HOV_ORIG       = "#662222"
        HOV_RIFE       = "#2A7A2A"
        GROUP_GAP      = 5

        cv = tk.Canvas(parent, bg="#0D0D0D", height=ROW_H*2+4,
                       highlightthickness=1, highlightbackground=BD)
        cv.pack(fill="x", expand=True)

        st = {"n_orig":0, "exp":2, "v0":0, "v1":0,
              "sel_type":"orig", "sel_i":0, "o_hover":-1, "r_hover":-1,
              "cached_pairs":set(), "os_pairs":set(),
              "sample_half":0, "sample_falloff":"Hann", "sample_strength":1.0,
              "cached_pngs":set(), "speedup":0}

        def _bw():
            cnt = max(1, st["v1"]-st["v0"])
            W   = cv.winfo_width() or 400
            return max(1, (W - max(0,cnt-1)*GROUP_GAP) // cnt)

        def _draw():
            cv.delete("all")
            n    = st["n_orig"]; ns = st["exp"]
            v0   = st["v0"];     v1 = st["v1"]
            if not n: return
            cnt  = max(1, v1-v0)
            W    = cv.winfo_width() or 400
            H    = ROW_H*2+4
            bw   = _bw()
            slot = bw + GROUP_GAP
            cpairs= st["cached_pairs"]
            sel_t = st["sel_type"]; sel_i = st["sel_i"]

            if st.get("retime", True):
                # ── Symmetric T-shape: greens drawn as unified inter-stem blocks ──
                # n_interp = 2*ns-1  →  the actual RIFE frames between each pair
                #   2× (ns=1) → 1 green between stems
                #   4× (ns=2) → 3 greens between stems
                #   8× (ns=4) → 7 greens between stems
                #
                # Each group is (2*ns+1) sub-boxes wide for cap/stem placement.
                # Greens are drawn as a SINGLE block between adjacent stems,
                # subdivided into n_interp equal slices.
                subs   = 2*ns + 1
                n_itp  = max(1, 2*ns - 1)   # actual interp frames per pair
                T_GAP  = 3                   # black gap between T-caps
                sw     = max(1.0, (W - T_GAP*max(0,cnt-1)) / max(1, cnt * subs))
                grp_w  = subs * sw
                stem_w = max(2, min(int(sw)-1, 5))
                CAP_Y1=1;     CAP_Y2=ROW_H
                BOT_Y1=ROW_H+2; BOT_Y2=H-2

                def _stem_cx(j):
                    return int(j * (grp_w + T_GAP) + ns*sw + sw/2)

                # 1. Unified green blocks between each pair of adjacent stems
                for j in range(cnt-1):
                    i   = v0+j
                    x0  = _stem_cx(j)   + stem_w//2 + 1
                    x1  = _stem_cx(j+1) - stem_w//2 - 1
                    blk = max(1, x1-x0)
                    pair_cached = i in cpairs
                    for k in range(n_itp):
                        ri      = i*n_itp + k
                        gx0     = x0 + int(k * blk / n_itp)
                        gx1     = x0 + int((k+1) * blk / n_itp) - 1
                        is_sel  = (sel_t=="rife" and ri==sel_i)
                        is_hov  = ri==st["r_hover"]
                        col = (COL_SEL_GREEN if is_sel
                               else HOV_RIFE  if is_hov
                               else COL_INTERP_HOT if pair_cached
                               else "#2A6A2A" if i in st.get("os_pairs",set())
                               else COL_INTERP)
                        cv.create_rectangle(gx0, BOT_Y1, gx1, BOT_Y2,
                                            fill=col, outline="")

                # 2. T-caps and stems on top
                _speedup = st.get("speedup", 0)
                for j in range(cnt):
                    i  = v0+j
                    gx = j * (grp_w + T_GAP)
                    is_o_sel = (sel_t=="orig" and i==sel_i)
                    is_dropped = _speedup > 0 and (i % _speedup) != 0
                    cap_col  = (COL_SEL_RED if is_o_sel
                                else HOV_ORIG if i==st["o_hover"]
                                else "#000000" if is_dropped
                                else COL_SRC_CACHED if i in st.get("cached_pngs",set())
                                else COL_SRC)
                    stem_col = (COL_SEL_RED if is_o_sel else COL_R_ORIG)

                    # Wide T-CAP (top zone), 1px right margin
                    cv.create_rectangle(int(gx), CAP_Y1,
                                        int(gx+grp_w)-1, CAP_Y2,
                                        fill=cap_col, outline="")

                    # Thin top line = PNG cache indicator
                    if i in st.get("cached_pngs", set()) and not is_dropped:
                        cv.create_line(int(gx), CAP_Y1,
                                       int(gx+grp_w)-1, CAP_Y1,
                                       fill="#FF6666", width=2)

                    # Narrow stem (bottom zone)
                    cx_  = _stem_cx(j)
                    sx0  = cx_ - stem_w//2
                    sx1  = cx_ + stem_w//2 + stem_w%2
                    cv.create_rectangle(sx0, CAP_Y2, sx1, BOT_Y2,
                                        fill=stem_col, outline="")

                    # Frame number centred on cap -- dark gray instead
                    # of white/light gray for a frame Speedup drops
                    # (folded into a kept neighbor's blend, never
                    # written as its own output)
                    if grp_w >= 14:
                        cv.create_text(int(gx + grp_w//2), (CAP_Y1+CAP_Y2)//2,
                            text=str(i+1),
                            font=("Helvetica", max(9, min(13, int(grp_w)//5)), "bold"),
                            fill="#444444" if (is_dropped and not is_o_sel) else "#CCCCCC",
                            anchor="center")

            else:
                # ── Flat mode (Auto Retime OFF) — no gaps ──
                # Each group: [RED src] [GREEN interp × (2^ns - 1)]
                step  = max(1, 2**ns)
                # Fill full canvas width with no gap
                sf    = W / max(1, cnt * step)
                FY1=2; FY2=H-2

                for j in range(cnt):
                    i   = v0+j
                    gx  = j * step * sf   # group starts here (no gap)
                    for k in range(step):
                        bx0 = int(gx + k*sf)
                        bx1 = int(gx + (k+1)*sf) - 1
                        ri  = i*step + k
                        if k == 0:  # source frame box
                            col = (COL_SEL_RED if (sel_t=="orig" and i==sel_i)
                                   else HOV_ORIG if i==st["o_hover"]
                                   else COL_SRC)
                        else:       # interp box
                            pair_idx = i
                            is_cached= pair_idx in cpairs
                            col = (COL_SEL_GREEN if (sel_t=="rife" and ri==sel_i)
                                   else HOV_RIFE  if ri==st["r_hover"]
                                   else COL_INTERP_HOT if is_cached
                                   else "#2A6A2A" if pair_idx in st.get("os_pairs",set())
                                   else COL_INTERP)
                        cv.create_rectangle(bx0+1, FY1, bx1, FY2, fill=col, outline="")
                    if sf >= 8:
                        cv.create_text(int(gx+sf/2), H//2,
                            text=str(i+1),
                            font=("Helvetica", max(9,min(13,int(sf)//3)), "bold"),
                            fill="#CCCCCC", anchor="center")

            # ── Auto-retime indicator — tapered bar over green boxes ─────
            import math as _mg
            _speedup_viz = st.get("speedup", 0)
            if _speedup_viz > 0:
                # Speedup mode: same symmetric falloff shape as normal
                # Smoothing, just based on HALF the gap to the next
                # kept frame (speedup/2 original-frame-units) --
                # centered on the selected/kept frame, matching
                # _rife_auto_retime's actual blend exactly. stp2 uses
                # the actual current Smoothing density (independent of
                # Speedup now -- a higher Smoothing density gives the
                # window more in-between frames to draw from); the
                # speedup scale itself lives in sample_half (see
                # _push_speedup_tl).
                _kept_i = (st["sel_i"] // _speedup_viz) * _speedup_viz
                _stp2   = max(1, 2*st["exp"])
                _cxg    = int(max(0,_kept_i-st["v0"])*(grp_w+T_GAP)+grp_w/2)
            else:
                _stp2 = max(1, 2*st["exp"])
                _cxg  = int(max(0,st["sel_i"]-st["v0"])*(grp_w+T_GAP)+grp_w/2)
            _sh   = st.get("sample_half", 0) or _stp2
            _fo   = st.get("sample_falloff", "Hann")
            _ss   = st.get("sample_strength", 1.0)
            _hpg  = max(4, int((_sh/_stp2)*(grp_w+T_GAP))-T_GAP)
            _GBY0 = ROW_H+2; _GBY1 = ROW_H*2+2
            _BASE = _GBY1 - 1          # baseline at bottom of zone
            _FULL = _GBY1 - _GBY0 - 2  # drawable height above baseline
            # Profile curve — smooth polygon growing upward from baseline
            _x0 = max(0, _cxg-_hpg); _x1 = min(W, _cxg+_hpg)
            cv.create_line(_x0, _BASE, _x1, _BASE, fill="#882222", width=1)
            _pts = []
            for _px in range(_x0, _x1+1):
                _t  = min(1.0, abs((_px-_cxg)/max(1,_hpg)))
                if   _fo=="Hann":     _fw=0.5*(1+_mg.cos(_mg.pi*_t))
                elif _fo=="Gaussian": _fw=_mg.exp(-6.0*_t*_t)
                elif _fo=="Box":      _fw=1.0
                else:                 _fw=max(0.0, 1.0-_t)
                _pts.append((_px, _BASE - _FULL * _fw * _ss if _ss > 0.01 else _BASE))
            if _pts:
                _poly = _pts + [(_pts[-1][0], _BASE), (_pts[0][0], _BASE)]
                # Box's shape is a flat top with two sharp 90° corners
                # down to the baseline -- Tk's spline smoothing pulls
                # those corners inward and rounds the flat top into
                # something that reads as a dome (the opposite of what
                # "no falloff" should look like), so Box draws with
                # sharp corners instead. Every other mode's shape is
                # genuinely curved and still benefits from smoothing.
                cv.create_polygon(
                    [c for pt in _poly for c in pt],
                    fill="#FF4444", outline="", smooth=(_fo != "Box"))

        def _hit_row(ey, ex=None):
            if not st.get("retime",True): return "orig" if ey < ROW_H else "rife"
            return "row"  # T-shape uses x position only

        def _click_orig(ex):
            # (Recovered: this body had been stranded as unreachable
            # code after _hit_row's return, so top-row clicks with
            # Auto Retime OFF raised NameError instead of selecting.)
            cnt=max(1,st["v1"]-st["v0"]); bw=_bw()
            slot=bw+GROUP_GAP
            j=max(0,min(cnt-1,int(ex//max(1,slot))))
            i=st["v0"]+j
            st["sel_type"]="orig"; st["sel_i"]=i
            _draw(); on_orig(i)

        def _click_rife(ex):
            ns=st["exp"]; subs=2*ns+1
            cnt=max(1,st["v1"]-st["v0"])
            bw=_bw(); slot=bw+GROUP_GAP; sf=bw/subs
            grp=max(0,min(cnt-1,int(ex//max(1,slot))))
            lx=ex-grp*slot
            k=max(0,min(subs-1,int(lx//max(1,sf))))
            i=st["v0"]+grp
            if k==ns:                        # stem = source frame
                st["sel_type"]="orig"; st["sel_i"]=i
                _draw(); on_orig(i); return
            ri=i*subs+k
            st["sel_type"]="rife"; st["sel_i"]=ri
            _draw(); on_rife(ri)

        def _hover_orig(ex):
            cnt=max(1,st["v1"]-st["v0"]); bw=_bw()
            slot=bw+GROUP_GAP
            j=max(0,min(cnt-1,int(ex//max(1,slot))))
            i=st["v0"]+j
            if i!=st["o_hover"]: st["o_hover"]=i; _draw()

        def _hover_rife(ex):
            ns=st["exp"]; subs=2*ns+1
            cnt=max(1,st["v1"]-st["v0"])
            bw=_bw(); slot=bw+GROUP_GAP; sf=bw/subs
            grp=max(0,min(cnt-1,int(ex//max(1,slot))))
            lx=ex-grp*slot
            k=max(0,min(subs-1,int(lx//max(1,sf))))
            ri=(st["v0"]+grp)*subs+k
            if ri!=st["r_hover"]: st["r_hover"]=ri; _draw()

        def _tshape_hit(ex):
            """In T-shape mode: return ("orig",i,i) or ("rife",ri,i) --
            the third element is always the containing original-frame
            GROUP index, whether the precise hit was on the stem or a
            neighboring green sub-frame. Needed so Speedup mode can
            resolve any click within a group to that group's original
            frame, regardless of exactly where within it was clicked."""
            ns2  = st["exp"]; subs2 = 2*ns2+1
            cnt2 = max(1, st["v1"]-st["v0"])
            W2   = cv.winfo_width() or 400
            sw2  = max(1.0, W2 / max(1, cnt2*subs2))
            grp_w2 = subs2 * sw2
            n_itp2 = max(1, 2*ns2-1)
            j    = max(0, min(cnt2-1, int(ex // grp_w2)))
            i    = st["v0"] + j
            # Stem position in this group
            stem_cx = j*grp_w2 + ns2*sw2 + sw2/2
            # Top zone → always orig
            if ex < 0: return ("orig", i, i)
            # Stem zone (±4px around stem centre) → orig
            if abs(ex - stem_cx) <= 6: return ("orig", i, i)
            # Green zone between this stem and adjacent stem
            # Left of stem → greens from pair (i-1, i), if i>0
            if ex < stem_cx and j > 0:
                prev_cx = (j-1)*grp_w2 + ns2*sw2 + sw2/2
                blk = stem_cx - prev_cx
                k   = max(0, min(n_itp2-1, int((ex-prev_cx)/blk*n_itp2)))
                return ("rife", (i-1)*n_itp2 + k, i)
            # Right of stem → greens from pair (i, i+1)
            if ex > stem_cx and j < cnt2-1:
                next_cx = (j+1)*grp_w2 + ns2*sw2 + sw2/2
                blk = next_cx - stem_cx
                k   = max(0, min(n_itp2-1, int((ex-stem_cx)/blk*n_itp2)))
                return ("rife", i*n_itp2 + k, i)
            return ("orig", i, i)

        def _on_click(e):
            if not st.get("retime",True):
                if _hit_row(e.y)=="orig": _click_orig(e.x)
                else: _click_rife(e.x)
            else:
                typ, idx, grp_i = _tshape_hit(e.x)
                _sp = st.get("speedup", 0)
                if _sp > 0:
                    # Speedup mode: nothing within a dropped frame's
                    # group -- its stem, or either neighboring green
                    # zone -- is independently selectable, since none
                    # of it is written as its own output. Every click
                    # anywhere in the group resolves to that group's
                    # nearest KEPT frame (floor to the kept frame that
                    # owns this span), always as an "orig" selection.
                    kept_i = (grp_i // _sp) * _sp
                    st["sel_type"]="orig"; st["sel_i"]=kept_i; _draw(); on_orig(kept_i)
                elif typ=="orig":
                    st["sel_type"]="orig"; st["sel_i"]=idx; _draw(); on_orig(idx)
                else:
                    st["sel_type"]="rife"; st["sel_i"]=idx; _draw(); on_rife(idx)
        def _on_motion(e):
            if not st.get("retime",True):
                if _hit_row(e.y)=="orig": _hover_orig(e.x)
                else: _hover_rife(e.x)
            else:
                typ, idx, grp_i = _tshape_hit(e.x)
                _sp = st.get("speedup", 0)
                if _sp > 0:
                    kept_i = (grp_i // _sp) * _sp
                    if kept_i!=st["o_hover"]: st["o_hover"]=kept_i; st["r_hover"]=-1; _draw()
                elif typ=="orig":
                    if idx!=st["o_hover"]: st["o_hover"]=idx; st["r_hover"]=-1; _draw()
                else:
                    if idx!=st["r_hover"]: st["r_hover"]=idx; st["o_hover"]=-1; _draw()
        cv.bind("<Button-1>", _on_click)
        cv.bind("<Motion>",   _on_motion)
        cv.bind("<Leave>",
            lambda e: (st.update(o_hover=-1,r_hover=-1),_draw()))
        cv.bind("<Configure>", lambda e: _draw())

        class _DualProxy:
            def _st_exp(_self): return st["exp"]
            def set_data(_self, n_orig, exp):
                st.update(n_orig=n_orig, exp=exp,
                          v0=0, v1=min(n_orig,22),
                          o_idx=0, r_idx=0)
                _draw(); cv.after(80,_draw); cv.after(300,_draw)
            def set_view(_self, v0, v1):
                st["v0"]=max(0,v0); st["v1"]=min(st["n_orig"],max(v0+1,v1))
                _draw()
            def orig_current(_self): return st["sel_i"] if st["sel_type"]=="orig" else 0
            def rife_current(_self): return st["sel_i"] if st["sel_type"]=="rife" else -1
            def sync_orig_sel(_self, i):
                _sp = st.get("speedup", 0)
                st["sel_type"]="orig"
                st["sel_i"]=(i // _sp) * _sp if _sp > 0 else i
                _draw()
            def sel_orig(_self, i):
                _sp = st.get("speedup", 0)
                st["sel_type"]="orig"
                st["sel_i"]=(i // _sp) * _sp if _sp > 0 else i
                _draw()
            def sel_rife(_self, ri):
                st["sel_type"]="rife"; st["sel_i"]=ri; _draw()
            def frame_count(_self): return st["n_orig"]
            def set_retime(_self, on):
                st["retime"]=bool(on); st.setdefault("cached_pairs",set()); _draw()
            def set_cached(_self, v):
                """Set ALL pairs cached/uncached (e.g. on folder load)."""
                n = st["n_orig"]
                st["cached_pairs"] = set(range(n)) if v else set()
                _draw()
            def add_cached_pair(_self, pair_idx):
                """Mark a single pair as calculated (called after preview/run)."""
                st["cached_pairs"].add(pair_idx); _draw()
            def set_cached_pairs(_self, pairs):
                st["cached_pairs"] = set(pairs); _draw()
            def add_os_pair(_self, i):
                st.setdefault("os_pairs", set()).add(i); _draw()
            def set_os_cached_pairs(_self, p):
                st["os_pairs"] = set(p); _draw()
            def set_cached_pngs(_self, pngs):
                st["cached_pngs"] = set(pngs); _draw()
            def set_sample_range_and_falloff(_self, half, fo, strength=1.0):
                st["sample_half"]    = half
                st["sample_falloff"] = fo
                st["sample_strength"]= strength
                _draw()
            def set_speedup(_self, factor):
                """factor=0 means off. factor=N means only every Nth
                original frame (0, N, 2N, ...) is kept as its own
                output frame -- the rest get folded into a kept
                frame's widened motion-blur blend instead, shown here
                as their T-cap going black and frame number going
                dark gray rather than removed from the timeline."""
                st["speedup"] = max(0, int(factor or 0))
                _draw()
        return _DualProxy()



    def _rife_upscale_pil(self, img_pil, target_w=None, target_h=None):
        """Apply upscale algorithm to PIL Image → PIL Image at target dims.
        Mirrors the main run's _save_frame branching exactly, so the
        preview actually reflects the chosen algorithm: ESRGAN delegates
        to _rife_upscale (which itself falls back to Lanczos+unsharp if
        the model isn't installed); Unsharp and Gaussian are applied
        directly here, since _rife_upscale doesn't distinguish between
        them on its own."""
        try:
            import numpy as _np, cv2 as _cv2
            from PIL import Image as _PI
            _bgr = _cv2.cvtColor(_np.array(img_pil), _cv2.COLOR_RGB2BGR)
            tw = target_w or img_pil.width
            th = target_h or img_pil.height
            _alg = getattr(self,"rife_upscale_var",None)
            _alg_val = _alg.get() if _alg else "Unsharp"
            if _alg_val == "ESRGAN":
                _bgr2 = self._rife_upscale(_bgr, tw, th)
            elif _alg_val == "Unsharp":
                _bgr2 = _cv2.resize(_bgr,(tw,th),interpolation=_cv2.INTER_LANCZOS4)
                _blur = _cv2.GaussianBlur(_bgr2,(0,0),1.5)
                _bgr2 = _cv2.addWeighted(_bgr2,1.4,_blur,-0.4,0)
            else:  # Gaussian — smooth, no ringing
                _bgr2 = _cv2.resize(_bgr,(tw,th),interpolation=_cv2.INTER_CUBIC)
                _bgr2 = _cv2.GaussianBlur(_bgr2,(0,0),0.6)
            return _PI.fromarray(_cv2.cvtColor(_bgr2, _cv2.COLOR_BGR2RGB))
        except Exception as e:
            self.log(self.rlog, f"Upscale preview error: {e}", "err")
            return img_pil

    def _rife_refresh_view(self):
        """Refresh current display mode."""
        if self._rife_mode == "wipe":
            cmp = getattr(self,"_rife_upscale_compare_mode",False)
            lbl = "RIFE upscaled" if cmp else "ADW-Blur"
            self._rife_wipe_draw(label_r=lbl)
        elif self._rife_mode == "diff":
            self._rife_diff_draw()
        else:
            self._rife_display()

    def _rife_apply_upscale_preview(self):
        """Toggle upscale on the stored raw riff — no RIFE re-run needed."""
        raw = getattr(self, "_rife_wipe_riff_raw", None)
        if not raw: return
        on = getattr(self,"rife_prev_upscale_var",None) and              self.rife_prev_upscale_var.get()
        if on:
            # Upscale to the TRUE original resolution (what the actual
            # full run would produce), not raw's own Model Res size --
            # without an explicit target, _rife_upscale_pil defaults to
            # the input's own dimensions, making this a same-size,
            # algorithm-irrelevant no-op regardless of which upscale
            # method is selected.
            _ow, _oh = getattr(self, "_rife_orig_dims", (0, 0))
            if _ow and _oh:
                self._rife_wipe_riff_base = self._rife_upscale_pil(raw, _ow, _oh)
            else:
                self._rife_wipe_riff_base = self._rife_upscale_pil(raw)
        else:
            self._rife_wipe_riff_base = raw.copy()
        self._rife_display()

    def _rife_tl_orig_click(self, i):
        self._rife_tl_mode = "orig"
        if hasattr(self,"_rife_dual_tl"):
            self._rife_dual_tl.sel_orig(i)  # clears rife sel, highlights cap
        self._rife_frame_selected()

    def _rife_rife_tl_clicked(self, i):
        self._rife_rife_tl_idx = i
        self._rife_tl_mode = "rife"
        self._rife_frame_selected()

    def _rife_preview_cancel(self):
        self._rife_preview_cancel_flag = True
        proc = getattr(self, "_rife_preview_proc", None)
        if proc and proc.poll() is None:
            try: proc.terminate(); proc.wait(timeout=3)
            except Exception:
                try: proc.kill()
                except Exception: pass
        self._rife_preview_proc = None
        self.after(0, lambda: self.log(self.rlog, "Preview cancelled.", "err"))
        self.after(0, lambda: self.progress(-1))
        self._set_preview_phase("", done=True)
        self.after(0, lambda: self.rife_preview_btn.configure(
            text="Preview", state="normal",
            bg="#2A0A0A", fg="#CC4444",
            command=self._rife_preview_frame))

    def _rife_preview_frame(self):
        if not self.rife_folder or not self.rife_frames: return
        self._rife_preview_cancel_flag = False
        self._rife_preview_proc = None
        self.rife_preview_btn.configure(
            text="CANCEL PREVIEW", state="normal",
            bg="#2A0A0A", fg="#FF4444",
            command=self._rife_preview_cancel)
        _mode    = getattr(self,"_rife_tl_mode","orig")
        _rife_raw_idx = getattr(self,"_rife_rife_tl_idx",0)
        # Use T-cap selected index if available; combobox can return -1 (no selection)
        _src_idx = getattr(self,"_rife_adw_src_idx",None)
        _cb_idx  = self.rife_frame_cb.current()
        if _cb_idx < 0:                     # combobox has no selection
            _cb_idx = _src_idx if _src_idx is not None else 0
        idx   = max(0, _cb_idx)
        fname = self.rife_frames[idx]
        inp_path = os.path.join(self.rife_folder, fname)
        # For rife-timeline mode: derive which pair and sub-frame
        _em4 = {"2x — Smooth":2,"4x — Very smooth":4,
                "6x — Extra smooth":6,"8x — Maximum":8}
        _step4 = _em4.get(self.rmult.get(),4)
        _pair4 = _rife_raw_idx // _step4 if _mode=="rife" else idx
        _sub4  = _rife_raw_idx %  _step4 if _mode=="rife" else 0
        # Clamp pair to valid range
        _pair4 = max(0, min(len(self.rife_frames)-2, _pair4))
        if _mode == "rife":
            idx = _pair4
            fname = self.rife_frames[idx]
            inp_path = os.path.join(self.rife_folder, fname)

        # Always run RIFE fresh — never reuse cached frames (may be wrong scale/quality)
        riff_path = None
        orig_w = orig_h = 0

        venv      = os.path.expanduser("~/RifeApp/venv/bin/python3")
        script    = self._rife_inference_script()
        em        = {"2x — Smooth": 2, "4x — Very smooth": 4,
                     "6x — Extra smooth": 6, "8x — Maximum": 8}
        total     = em.get(self.rmult.get(), 4)
        _prev_ret = bool(getattr(self,"rife_retime_var",None) and
                         self.rife_retime_var.get())

        def go():
            orig_w = orig_h = 0  # ensure always bound
            # Clear stale cached images immediately so old data is never reused
            self._rife_wipe_orig_base = None
            self._rife_wipe_riff_base = None
            if self._rife_preview_cancel_flag: return
            import tempfile, shutil
            nonlocal riff_path
            riff_path = None  # reset inside thread — guard against stale nonlocal
            tmp_in = tmp_out = None
            f1 = None
            try:
                # ── Step 0: reuse the full ADW-Blur cache if it already
                # covers this pair (built via Cache RIFE or Run
                # ADW-Blur) -- no point paying for a fresh RIFE
                # invocation just to preview/select a frame that's
                # already been interpolated. This is specifically what
                # makes it possible to adjust Auto Retime settings and
                # re-preview without RIFE itself ever running again,
                # since the retime blend works on these same frames
                # either way.
                try:
                    _adw_dir_chk = self._rife_frames_dir(self.rife_folder)
                    if os.path.isdir(_adw_dir_chk):
                        _rfiles_chk = sorted(f for f in os.listdir(_adw_dir_chk)
                            if os.path.splitext(f)[1].lower() in (".png",".exr"))
                        # De-dupe same-basename PNG+EXR pairs the same
                        # way the load-time cache-detection scan does.
                        _seen_chk = {}
                        for _rf in _rfiles_chk:
                            _b = os.path.splitext(_rf)[0]
                            if _b not in _seen_chk or _rf.lower().endswith(".exr"):
                                _seen_chk[_b] = _rf
                        _rfiles_chk = sorted(_seen_chk.values(),
                            key=lambda f: os.path.splitext(f)[0])
                        _ri_start = _pair4 * _step4
                        _ri_end   = (_pair4+1) * _step4
                        if _ri_end <= len(_rfiles_chk):
                            # Pair's full slice already exists. Pick
                            # the specific sub-frame in "rife" mode
                            # (matching the exact RIFE-timeline
                            # position selected), otherwise the
                            # midpoint of the slice -- the same
                            # logical position a fresh run's own
                            # out_frames[len//2] pick would land on
                            # for this same pair.
                            _pick = _sub4 if _mode == "rife" else _step4 // 2
                            _pick = max(0, min(_step4 - 1, _pick))
                            _cached_fname = _rfiles_chk[_ri_start + _pick]
                            _cand = os.path.join(_adw_dir_chk, _cached_fname)
                            # Only reuse the cache if it was built under
                            # the CURRENT settings. A cache from an older
                            # run at a lower Model Res (or different TTA/
                            # Smoothing, or an older inference script)
                            # looks softer than a fresh frame would --
                            # reused silently, that reads as "output is
                            # low resolution again, but only sometimes".
                            _fp_ok, _fp_msg = True, ""
                            try:
                                import json as _json_ck
                                _fp_file = os.path.join(_adw_dir_chk,
                                    "_ADW_CACHE_INFO.json")
                                if os.path.exists(_fp_file):
                                    with open(_fp_file) as _ckh:
                                        _rec = _json_ck.load(_ckh)
                                    _now = self._rife_settings_fingerprint()
                                    _diff = [k for k in _now
                                             if _rec.get(k) != _now[k]]
                                    if _diff:
                                        _fp_ok = False
                                        _fp_msg = ("cached RIFE frames were "
                                            "built with different settings ("
                                            + ", ".join(_diff) + ") — "
                                            "recomputing this preview. Clear "
                                            "RIFE cache and re-run Cache RIFE "
                                            "to rebuild with the current "
                                            "settings.")
                                else:
                                    _fp_msg = ("cache has no settings record "
                                        "(built by an older version) — if "
                                        "output looks soft, Clear RIFE cache "
                                        "and re-run Cache RIFE.")
                            except Exception:
                                pass
                            if _fp_ok:
                                riff_path = _cand
                                self.after(0, lambda m=_fp_msg: self.log(
                                    self.rlog,
                                    "Using cached RIFE frame — no "
                                    "recalculation needed (Cache RIFE "
                                    "already covers this pair)."
                                    + ((" Note: " + m) if m else ""),
                                    "dim"))
                            else:
                                riff_path = None
                                self.after(0, lambda m=_fp_msg: self.log(
                                    self.rlog, "Cache skipped: " + m, "err"))
                except Exception:
                    riff_path = None  # any failure here just falls through below

                # ── Step 1: run RIFE (folder mode, same as full run) on 2 frames ─
                if not riff_path or not os.path.exists(riff_path):
                    if not os.path.exists(venv) or not os.path.exists(script):
                        self.after(0, lambda: self.log(self.rlog,
                            "RIFE not installed — run Setup first.", "err"))
                        return

                    self.after(0, lambda: self.log(self.rlog,
                        "Running RIFE preview on " + fname + "…", "hi"))
                    self.after(0, lambda: (self.progress(0.1, "EXR → PNG…"), self._set_preview_phase("EXR → PNG")))

                    tmp_in     = tempfile.mkdtemp(prefix="rife_prev_in_")
                    script_dir = os.path.dirname(script)
                    # Use fresh temp dir — never reuse persistent output/ folder
                    tmp_out    = tempfile.mkdtemp(prefix="rife_prev_out_")
                    # Also clean the script-dir output/ in case RIFE writes there
                    _scr_out = os.path.join(script_dir, "output")
                    os.makedirs(_scr_out, exist_ok=True)
                    for _f in os.listdir(_scr_out):
                        try: os.remove(os.path.join(_scr_out, _f))
                        except: pass

                    idx2 = min(idx + 1, len(self.rife_frames) - 1)
                    if idx2 == idx: idx2 = max(0, idx - 1)
                    inp2 = os.path.join(self.rife_folder, self.rife_frames[idx2])
                    def _exr_read_float(path):
                        """Read EXR as float32 RGB array, correctly
                        placed within the full displayWindow-sized
                        canvas. Tries OpenEXR directly first -- this
                        handles dataWindow != displayWindow (a cropped
                        or offset render region, common from some AI
                        video tools) correctly by placing the actual
                        data at its real offset with black filling the
                        rest. ffmpeg's raw pixel pipe can fail outright
                        on EXRs with this mismatch (confirmed: returns
                        zero bytes on a real file with an offset
                        dataWindow), which silently forces every frame
                        through a lower-quality tonemap fallback with
                        no indication anything went wrong."""
                        import json, numpy as _np
                        try:
                            import OpenEXR as _OEp, Imath as _Imp
                            ef = _OEp.InputFile(path)
                            hdr = ef.header()
                            dw = hdr["dataWindow"]; disp = hdr["displayWindow"]
                            dw_w = dw.max.x-dw.min.x+1; dw_h = dw.max.y-dw.min.y+1
                            fw = disp.max.x-disp.min.x+1; fh = disp.max.y-disp.min.y+1
                            _ptype = hdr["channels"]["R"].type
                            _np_dtype = _np.float16 if str(_ptype)=="HALF" else _np.float32
                            FPp = _Imp.PixelType(_Imp.PixelType.HALF if _np_dtype==_np.float16
                                                  else _Imp.PixelType.FLOAT)
                            data = _np.stack([_np.frombuffer(
                                ef.channel(c,FPp),_np_dtype).reshape(dw_h,dw_w).astype(_np.float32)
                                for c in "RGB"], axis=2)
                            if (dw_w,dw_h) == (fw,fh) and dw.min.x==disp.min.x and dw.min.y==disp.min.y:
                                arr = data
                            else:
                                arr = _np.zeros((fh,fw,3),dtype=_np.float32)
                                y0 = dw.min.y-disp.min.y; x0 = dw.min.x-disp.min.x
                                arr[max(0,y0):max(0,y0)+dw_h, max(0,x0):max(0,x0)+dw_w] = data
                            return _np.maximum(arr,0), fw, fh
                        except Exception:
                            pass
                        # Fallback: ffmpeg raw pipe (no dataWindow handling)
                        pr = subprocess.run(
                            ["ffprobe","-v","quiet","-print_format","json",
                             "-show_streams", path],
                            capture_output=True, text=True, timeout=10)
                        info = json.loads(pr.stdout)
                        vs = next(s for s in info["streams"] if s["codec_type"]=="video")
                        fw, fh = int(vs["width"]), int(vs["height"])
                        raw = subprocess.run(
                            ["ffmpeg","-y","-i",path,
                             "-pix_fmt","rgbaf32le","-f","rawvideo","pipe:1"],
                            capture_output=True, timeout=90)
                        arr = _np.frombuffer(raw.stdout, _np.float32
                            ).reshape(fh, fw, 4)[:,:,:3]
                        return _np.maximum(arr, 0), fw, fh

                    _exr_norm_scale = [None]  # shared across pair for consistency

                    def exr_to_png_robust(path, dst, norm_scale=None):
                        """Convert EXR→PNG with percentile auto-exposure.
                        norm_scale: if provided reuse from first frame (consistency).
                        Returns (True, scale) or (False, None).
                        """
                        import numpy as _np
                        from PIL import Image as _PI
                        if os.path.splitext(path)[1].lower() != ".exr":
                            shutil.copy(path, dst)
                            return True, norm_scale
                        # S1: float pipe + percentile normalisation
                        try:
                            arr, fw, fh = _exr_read_float(path)
                            if arr.size > 0:
                                if norm_scale is None:
                                    # 95th-percentile of max-channel luminance
                                    lum = arr.max(axis=2)
                                    norm_scale = self._adw_auto_exposure_scale(lum)
                                gamma = self._adw_gamma_encode(arr, norm_scale)
                                _PI.fromarray((gamma*255).astype(_np.uint8)).save(dst)
                                if os.path.exists(dst) and os.path.getsize(dst)>100:
                                    return True, norm_scale
                        except Exception as _e:
                            self.after(0, lambda e=str(_e)[:80]: self.log(
                                self.rlog, f"EXR float pipe: {e}", "dim"))
                        # S2: ffmpeg tonemap fallback
                        for _args in [
                            ["ffmpeg","-y","-i",path,
                             "-vf","tonemap=reinhard:desat=0,format=rgb24",dst],
                            ["ffmpeg","-y","-i",path,"-pix_fmt","rgb24",dst],
                        ]:
                            r = subprocess.run(_args,capture_output=True,timeout=90)
                            if r.returncode==0 and os.path.exists(dst):
                                return True, norm_scale
                        return False, norm_scale

                    def to_png_rife(path, dst):
                        """EXR→PNG for RIFE: robust conversion + pad to multiple of 32."""
                        ok, scale = exr_to_png_robust(path, dst, _exr_norm_scale[0])
                        if scale is not None: _exr_norm_scale[0] = scale
                        if not ok:
                            return None, None, None
                        from PIL import Image
                        img = Image.open(dst).convert("RGB")
                        ow, oh = img.size
                        pw = ((ow + 31) // 32) * 32
                        ph = ((oh + 31) // 32) * 32
                        if pw != ow or ph != oh:
                            padded = Image.new("RGB", (pw, ph), (0, 0, 0))
                            padded.paste(img, (0, 0))
                            padded.save(dst)
                        return ow, oh, (pw, ph)

                    f1 = os.path.join(tmp_in, "frame1.png")
                    f2 = os.path.join(tmp_in, "frame2.png")
                    # Check for an already-persisted scale FIRST --
                    # without this, every preview of a different frame
                    # computes its own fresh scale from that frame's
                    # own local statistics, while Wipe's background
                    # re-blend (_rife_retime_blend_only) keeps reading
                    # whichever scale was first ever persisted to this
                    # folder's cache. That mismatch is exactly what
                    # shows up as a slight pop in brightness/contrast
                    # the moment Wipe's redraw lands, even though
                    # neither value is "wrong" on its own.
                    _exr_norm_scale = [None]
                    try:
                        import json as _cjp0
                        _ci_path_p0 = os.path.join(
                            self._adw_output_root(self.rife_folder),
                            "_png_cache", "_cache_info.json")
                        _ci0 = _cjp0.loads(open(_ci_path_p0).read())
                        _exr_norm_scale[0] = float(_ci0.get("norm_scale")) \
                            if _ci0.get("norm_scale") is not None else None
                    except Exception:
                        _exr_norm_scale[0] = None
                    orig_w, orig_h, padded_size = to_png_rife(inp_path, f1)
                    if _exr_norm_scale[0] is not None:
                        # Persist immediately so anything reading
                        # _cache_info.json afterward (e.g. the wipe's
                        # automatic background re-blend) uses this SAME
                        # scale rather than independently computing a
                        # different one from different frame statistics
                        # -- that mismatch is what causes a correct
                        # preview to visibly pop to a different
                        # brightness/contrast moments after toggling
                        # Wipe, with no error and no obvious cause.
                        try:
                            import json as _cjp
                            _cache_dir_p = os.path.join(
                                self._adw_output_root(self.rife_folder), "_png_cache")
                            os.makedirs(_cache_dir_p, exist_ok=True)
                            _ci_path_p = os.path.join(_cache_dir_p, "_cache_info.json")
                            _ci_existing = {}
                            if os.path.exists(_ci_path_p):
                                try: _ci_existing = _cjp.loads(open(_ci_path_p).read())
                                except Exception: _ci_existing = {}
                            if "norm_scale" not in _ci_existing:
                                _ci_existing["norm_scale"] = _exr_norm_scale[0]
                                _ci_existing["cache_version"] = self._ADW_PNG_CACHE_VERSION
                                with open(_ci_path_p, "w") as _f_ci:
                                    _cjp.dump(_ci_existing, _f_ci)
                        except Exception: pass
                    to_png_rife(inp2, f2)

                    if not orig_w or not os.path.exists(f1):
                        self.after(0, lambda: self.log(self.rlog,
                            "EXR→PNG conversion failed — all strategies failed.", "err"))
                        return

                    # Validate: check converted PNG has reasonable pixel variance (not noise/blank)
                    try:
                        from PIL import Image as _pil, ImageStat as _stat
                        _img = _pil.open(f1).convert("RGB")
                        _s   = _stat.Stat(_img)
                        _means = _s.mean  # [R, G, B] average values
                        self.after(0, lambda m=_means, sz=(orig_w,orig_h): self.log(
                            self.rlog,
                            f"Converted PNG: {sz[0]}×{sz[1]}  RGB means: {[round(x,1) for x in m]}", "dim"))
                    except Exception:
                        pass

                    if self._rife_preview_cancel_flag: return
                    self.after(0, lambda: (self.progress(0.25, "Running RIFE…"), self._set_preview_phase("RIFE interpolation")))
                    self.after(0, lambda s=padded_size, o=(orig_w,orig_h): self.log(
                        self.rlog,
                        f"Input {o} padded to {s} (must be divisible by 32)", "dim"))

                    # Resize to model target resolution
                    _res_v = getattr(self,"rife_scale_var",
                        type("V",(),{"get":lambda s:"full"})()).get()
                    if _res_v != "full" and "x" in _res_v:
                        _tw, _th = map(int, _res_v.split("x"))
                        from PIL import Image as _PIL_sc
                        _sc_img = _PIL_sc.open(f1).convert("RGB")
                        _sf = min(_tw/orig_w, _th/orig_h) if orig_w and orig_h else min(_tw/_sc_img.width, _th/_sc_img.height)
                        # Model Res is a downscale cap, never a forced
                        # upscale -- processing above native resolution
                        # adds no real detail, just blur from the
                        # resize round trip that the chosen upscale
                        # algorithm can't recover afterward.
                        _sf = min(1.0, _sf)
                        _sw = max(32, int(_sc_img.width  * _sf))
                        _sh = max(32, int(_sc_img.height * _sf))
                        _sc_img.resize((_sw,_sh), _PIL_sc.LANCZOS).save(f1)
                        _PIL_sc.open(f2).convert("RGB").resize(
                            (_sw,_sh), _PIL_sc.LANCZOS).save(f2)
                        self.after(0, lambda w=_sw, h=_sh:
                            self.log(self.rlog, f"Model input: {w}×{h}", "dim"))
                    cmd = (f'cd "{script_dir}" && '
                           f'"{venv}" "{script}" --img "{f1}" "{f2}" --n-total {total}'
                       + self._rife_extra_flags()
                       )
                    if self._rife_preview_cancel_flag: return
                    import subprocess as _rsp, time as _ptime
                    # Clear output dir so we can count new files as they appear
                    for _pf in os.listdir(tmp_out):
                        try: os.remove(os.path.join(tmp_out, _pf))
                        except: pass
                    _expected_frames = total + 1
                    _proc = _rsp.Popen(
                        cmd, shell=True,
                        stdout=_rsp.DEVNULL, stderr=_rsp.DEVNULL)
                    self._rife_preview_proc = _proc
                    # Poll output folder — bar advances as frames appear
                    while _proc.poll() is None:
                        if self._rife_preview_cancel_flag:
                            _proc.terminate(); break
                        try:
                            _nf = len([_pf for _pf in os.listdir(tmp_out)
                                if _pf.endswith((".png",".jpg"))])
                            _frac = min(_nf / max(1, _expected_frames), 0.95)
                            _pct = 0.25 + _frac * 0.55
                            _p2, _n2, _e2 = _pct, _nf, _expected_frames
                            self.after(1, lambda p=_p2, n=_n2, e=_e2:
                                self.progress(p, f"RIFE  {n}/{e}"))
                        except Exception: pass
                        _ptime.sleep(0.15)
                    _proc.wait()
                    ret = _proc.returncode
                    self._rife_preview_proc = None
                    if self._rife_preview_cancel_flag: return

                    # RIFE may write to tmp_out or to script_dir/output/
                    _scr_out2 = os.path.join(script_dir, "output")
                    all_files = os.listdir(tmp_out) if os.path.exists(tmp_out) else []
                    if not all_files and os.path.exists(_scr_out2):
                        all_files = os.listdir(_scr_out2)
                        if all_files: tmp_out = _scr_out2  # redirect to actual output
                    self.after(0, lambda fs=all_files: self.log(self.rlog,
                        f"RIFE output files: {fs}", "dim"))

                    if ret == 0 and all_files:
                        out_frames = sorted([
                            f for f in all_files
                            if os.path.splitext(f)[1].lower() in
                               {".png",".jpg",".jpeg",".exr"}
                        ])
                        if out_frames:
                            # Rife mode: pick specific sub-frame
                            if _mode == "rife" and _sub4 > 0:
                                # Skip img0/imgN (input copies), pick interp frame
                                _interps = out_frames[1:-1]
                                _fi = min(max(0, _sub4-1), len(_interps)-1)
                                raw_out = os.path.join(tmp_out,
                                    _interps[_fi] if _interps else out_frames[0])
                            else:
                                raw_out = os.path.join(tmp_out, out_frames[len(out_frames)//2])
                            if orig_w and orig_h:
                                import time as _time
                                from PIL import Image
                                # Wait up to 2s for RIFE to finish writing the file
                                for _attempt in range(8):
                                    if (os.path.exists(raw_out) and
                                            os.path.getsize(raw_out) > 100):
                                        break
                                    _time.sleep(0.25)
                                from PIL import ImageFile as _PIF2
                                _PIF2.LOAD_TRUNCATED_IMAGES = True
                                try:
                                    img_raw_modelres = Image.open(raw_out).convert("RGB")
                                except Exception:
                                    _time.sleep(0.3)
                                    try:
                                        img_raw_modelres = Image.open(raw_out).convert("RGB")
                                    except Exception as _pe:
                                        # Fallback: use ffmpeg to decode the frame
                                        import subprocess as _sp, tempfile as _tf
                                        _t = _tf.NamedTemporaryFile(
                                            suffix=".png", delete=False); _t.close()
                                        _sp.run(["ffmpeg","-y","-i",raw_out,_t.name],
                                            capture_output=True)
                                        img_raw_modelres = Image.open(_t.name).convert("RGB")
                                        os.unlink(_t.name)
                                # Store model-res output — upscale toggle works on this
                                self._rife_wipe_riff_raw = img_raw_modelres.copy()
                                self._rife_orig_dims     = (orig_w, orig_h)
                                # Upscale for retime blend (riff_path) using the
                                # chosen algorithm -- a plain Lanczos resize here
                                # would silently ignore Unsharp/ESRGAN selection
                                # for the default (pre-toggle) wipe comparison.
                                rw2, rh2 = img_raw_modelres.size
                                if rw2 >= orig_w and rh2 >= orig_h:
                                    img_out = img_raw_modelres.crop((0,0,orig_w,orig_h))
                                else:
                                    img_out = self._rife_upscale_pil(img_raw_modelres, orig_w, orig_h)
                                riff_path = os.path.join(tmp_out,"rife_cropped.png")
                                img_out.save(riff_path)
                            else:
                                riff_path = raw_out
                                self._rife_wipe_riff_raw = None
                                self._rife_orig_dims     = (0,0)

                            # ── Auto Retime blend in preview ─────────────────
                            # Skip retime when a rife interp frame was clicked directly
                            _show_raw = (getattr(self,"_rife_tl_mode","orig") == "rife")
                            if _prev_ret and not _show_raw and riff_path and os.path.exists(riff_path):
                                self.after(0, lambda: self.log(self.rlog,
                                    "Retime: running preceding pair for blend…", "dim"))
                                # Save ALL following interp frames before clearing
                                _after_frames = []
                                for _af in sorted([f for f in os.listdir(tmp_out)
                                    if f.endswith(".png")])[1:-1]:  # skip img0/imgN
                                    _dst = os.path.join(tmp_in, f"after_{_af}")
                                    shutil.copy(os.path.join(tmp_out, _af), _dst)
                                    _after_frames.append(_dst)
                                riff_path = _after_frames[len(_after_frames)//2] \
                                    if _after_frames else riff_path
                                idx_prev = max(0, idx - 1)
                                inp_prev = os.path.join(
                                    self.rife_folder, self.rife_frames[idx_prev])
                                fp1 = os.path.join(tmp_in, "prev1.png")
                                fp2 = os.path.join(tmp_in, "prev2.png")
                                to_png_rife(inp_prev, fp1)
                                to_png_rife(inp_path, fp2)
                                # Clear RIFE output, run preceding pair
                                for _f in os.listdir(tmp_out):
                                    try: os.remove(os.path.join(tmp_out, _f))
                                    except: pass
                                _cmd2 = (f'cd "{script_dir}" && '
                                    f'"{venv}" "{script}" --img "{fp1}" "{fp2}" '
                                    f'--n-total {total}' + self._rife_extra_flags())
                                if self._rife_preview_cancel_flag: return
                                _p2 = _rsp.Popen(_cmd2, shell=True,
                                    stdout=_rsp.DEVNULL, stderr=_rsp.DEVNULL)
                                self._rife_preview_proc = _p2
                                _p2.wait()
                                self._rife_preview_proc = None
                                if self._rife_preview_cancel_flag: return
                                _out2 = [f for f in os.listdir(tmp_out)
                                    if os.path.splitext(f)[1].lower()==".png"]
                                if _out2:
                                    _before_frames = [os.path.join(tmp_out, f)
                                        for f in sorted(_out2)[1:-1]]  # skip img0/imgN
                                    try:
                                        import numpy as _np, cv2 as _cv
                                        from PIL import Image as _PI

                                        def _load_bgr(path):
                                            i = _PI.open(path).convert("RGB")
                                            if i.size != (orig_w, orig_h):
                                                i = i.crop((0,0,orig_w,orig_h)) if i.width>=orig_w \
                                                    else i.resize((orig_w,orig_h),_PI.LANCZOS)
                                            return _cv.cvtColor(_np.array(i), _cv.COLOR_RGB2BGR)

                                        _dis = self._make_dis(
                                            getattr(self,"rife_flow_var",
                                            type("V",(),{"get":lambda s:"Quality"})()).get())
                                        _motion_lo = getattr(self,"rife_motion_thresh_var",None)
                                        _motion_lo = float(_motion_lo.get()) if _motion_lo else 2.0
                                        _motion_on = getattr(self,"rife_motion_mask_var",None)
                                        _motion_on = _motion_on.get() if _motion_on else True

                                        _o   = _load_bgr(f1)
                                        self.after(0, lambda b=len(_before_frames),a=len(_after_frames):
                                            self.log(self.rlog,
                                                f"Retime blend: {b} before + source + {a} after frames","dim"))
                                        _n   = min(len(_before_frames), len(_after_frames))
                                        _N2  = 2*_n + 1
                                        _fq2 = getattr(self,"rife_flow_var",
                                            type("V",(),{"get":lambda s:"Quality"})()).get()

                                        # Build symmetric ordered list (_n frames each side)
                                        _all = []
                                        _bfs = _before_frames[-_n:] if _n else []
                                        _afs = _after_frames[:_n]   if _n else []
                                        for _k, _bf in enumerate(_bfs):
                                            _off = -(_n - _k)
                                            _all.append((_off, _load_bgr(_bf)))
                                        _all.append((0, _o))
                                        for _k, _af in enumerate(_afs):
                                            _all.append((_k+1, _load_bgr(_af)))

                                        # Hann window + bidirectional flow warp
                                        _acc  = _np.zeros_like(_o, dtype=_np.float32)
                                        _wtot = 0.0
                                        for _idx2, (_off, _fr) in enumerate(_all):
                                            _w = 0.5*(1-_np.cos(2*_np.pi*_idx2/max(1,_N2-1)))
                                            if _off == 0:
                                                _warped = _fr
                                            else:
                                                _t = abs(_off)/(_n+1)
                                                _warped = self._flow_warp(
                                                    _fr, _o, _dis, _t, _fq2,
                                                    _motion_lo, _motion_on)
                                            _acc  += _warped.astype(_np.float32) * _w
                                            _wtot += _w
                                        _blend = _np.clip(_acc/_wtot,0,255).astype(_np.uint8)
                                        _blend_path = os.path.join(tmp_in,"retime_blend.png")
                                        _PI.fromarray(_cv.cvtColor(_blend,_cv.COLOR_BGR2RGB)
                                            ).save(_blend_path)
                                        riff_path = _blend_path
                                        self.after(0, lambda n=len(_all): self.log(self.rlog,
                                            f"Retime: Gaussian blend over {n} frames", "dim"))
                                        # Save preview frames to ADW-Blur folder for Recalc
                                        try:
                                            _adw_dir = self._adw_module_output_dir(
                                                self.rife_folder, "ADW-Blur_Rife")
                                            # Write: src_before, before_interps, src_curr, after_interps, src_next
                                            _aidx = 1
                                            # src at idx-1
                                            _src_prev = os.path.join(
                                                self.rife_folder,
                                                self.rife_frames[max(0,idx-1)])
                                            _PI.open(fp1).save(os.path.join(
                                                _adw_dir, f"{_aidx:05d}.png")); _aidx+=1
                                            for _bf in _bfs:
                                                _PI.open(_bf).save(os.path.join(
                                                    _adw_dir, f"{_aidx:05d}.png")); _aidx+=1
                                            # src at idx (center)
                                            _PI.open(fp2).save(os.path.join(
                                                _adw_dir, f"{_aidx:05d}.png")); _aidx+=1
                                            for _af in _afs:
                                                _PI.open(_af).save(os.path.join(
                                                    _adw_dir, f"{_aidx:05d}.png")); _aidx+=1
                                            # src at idx+1
                                            _f2_src = os.path.join(
                                                self.rife_folder,
                                                self.rife_frames[min(len(self.rife_frames)-1,idx+1)])
                                            _PI.open(fp2).save(os.path.join(
                                                _adw_dir, f"{_aidx:05d}.png"))
                                            self._rife_adw_dir = _adw_dir
                                            self._rife_adw_center_override = len(_bfs)  # 0-indexed
                                            self._rife_adw_src_idx = idx
                                            self.after(0, lambda: self.log(self.rlog,
                                                "ADW preview folder saved — Recalc ready","dim"))
                                            _bv=int(getattr(self,"rife_blend_oversample_var",
                                                type("V",(),{"get":lambda s:0})()).get())
                                            if _bv>0:
                                                self.after(50,lambda b=_bv:
                                                    self._adw_generate_extra_pairs(b))
                                        except Exception as _se:
                                            self.after(0, lambda e=str(_se): self.log(
                                                self.rlog, f"ADW save error: {e}", "dim"))
                                    except Exception as _be:
                                        self.after(0, lambda e=str(_be): self.log(
                                            self.rlog, f"Retime blend error: {e}", "err"))

                        else:
                            self.after(0, lambda: self.log(self.rlog,
                                "No image files in RIFE output.", "err"))
                            return
                    else:
                        self.after(0, lambda r=ret: self.log(self.rlog,
                            f"RIFE failed (exit {r}) or produced no files.", "err"))
                        return

                # ── Step 2: load both into wipe at identical size ────────────────
                cw = max(1, getattr(self,"_rife_canvas_w",0) or self.rife_wipe_canvas.winfo_width() or 600)
                ch = max(1, self.rife_wipe_canvas.winfo_height() or 400)

                from PIL import Image

                def load_full(path, is_reconstructed=False):
                    """is_reconstructed=True for our own ADW-Blur output
                    (built from an 8-bit gamma-encoded PNG via a specific
                    norm_scale -- see _png_to_exr): decode with the SAME
                    inverse transform it was encoded with, rather than a
                    generic HDR tonemap operator. A mismatched second
                    nonlinear curve on top of already-quantized 8-bit
                    data is exactly what reveals/amplifies that
                    quantization as visible banding, and can shift
                    colors too since reinhard's curve shape differs from
                    a plain gamma curve -- typically toward a brighter,
                    flatter/lower-contrast look, since reinhard's HDR
                    compression curve is applied to data that's already
                    been compressed into a normal display-ish range
                    once. Genuine, never-reprocessed source footage
                    (is_reconstructed=False) keeps using the generic
                    tonemap, since there's no known encoding to match
                    in the first place."""
                    ext = os.path.splitext(path)[1].lower()
                    if ext == ".exr":
                        if is_reconstructed:
                            import time as _timeL
                            _last_err = None
                            for _attempt in range(3):
                                try:
                                    import numpy as _npL, json as _jsL
                                    import OpenEXR as _OEL, Imath as _ImL
                                    ef = _OEL.InputFile(path)
                                    dw = ef.header()["dataWindow"]
                                    fw = dw.max.x-dw.min.x+1; fh = dw.max.y-dw.min.y+1
                                    FPL = _ImL.PixelType(_ImL.PixelType.FLOAT)
                                    arrL = _npL.stack([_npL.frombuffer(
                                        ef.channel(c,FPL),_npL.float32).reshape(fh,fw)
                                        for c in "RGB"], axis=2)
                                    arrL = _npL.maximum(arrL, 0)
                                    _scaleL = 1.0
                                    try:
                                        _ciL = _jsL.loads(open(os.path.join(
                                            self._adw_output_root(self.rife_folder), "_png_cache",
                                            "_cache_info.json")).read())
                                        _scaleL = float(_ciL.get("norm_scale") or 1.0)
                                    except Exception: pass
                                    _gmL = self._adw_gamma_encode(arrL, _scaleL)
                                    return Image.fromarray((_gmL*255).astype(_npL.uint8))
                                except Exception as _eL:
                                    _last_err = _eL
                                    _timeL.sleep(0.15)  # transient file-write race, retry
                            # All retries failed -- this should be rare.
                            # Surface it (no more silent wrong-colorspace
                            # frames) and fall back to a gamma-only
                            # decode (scale=1.0): still the SAME family
                            # of transform we encoded with, just without
                            # the persisted scale -- far closer to
                            # correct than reinhard's incompatible curve.
                            self.after(0, lambda e=str(_last_err), pth=path: self.log(
                                self.rlog,
                                f"\u26a0 Couldn't read {os.path.basename(pth)} with the "
                                f"matching decode after 3 tries ({e}) \u2014 falling back "
                                f"to a plain gamma decode, not reinhard.", "err"))
                            try:
                                import numpy as _npL2
                                import OpenEXR as _OEL2, Imath as _ImL2
                                ef2 = _OEL2.InputFile(path)
                                dw2 = ef2.header()["dataWindow"]
                                fw2 = dw2.max.x-dw2.min.x+1; fh2 = dw2.max.y-dw2.min.y+1
                                FPL2 = _ImL2.PixelType(_ImL2.PixelType.FLOAT)
                                arrL2 = _npL2.maximum(_npL2.stack([_npL2.frombuffer(
                                    ef2.channel(c,FPL2),_npL2.float32).reshape(fh2,fw2)
                                    for c in "RGB"], axis=2), 0)
                                _gmL2 = self._adw_gamma_encode(arrL2, 1.0)
                                return Image.fromarray((_gmL2*255).astype(_npL2.uint8))
                            except Exception: pass
                        import tempfile as _tf
                        _t = _tf.NamedTemporaryFile(suffix=".png", delete=False)
                        _t.close()
                        subprocess.run(["ffmpeg","-y","-i",path,
                            "-vf","tonemap=reinhard:desat=0,format=rgb24",_t.name],
                            capture_output=True, timeout=60)
                        img = Image.open(_t.name).convert("RGB")
                        os.unlink(_t.name)
                    else:
                        img = Image.open(path).convert("RGB")
                    return img

                # Always load orig from the original source (not scaled temp f1).
                # Use the matching gamma+scale decode (is_reconstructed=True),
                # not reinhard -- the source EXR and ADW-Blur's own output
                # represent the same underlying linear values, so displaying
                # them via two genuinely different curves (reinhard vs
                # gamma+scale) made them look mismatched by construction,
                # independent of whether the scale value itself was
                # consistent between the two paths.
                orig_full = load_full(inp_path, is_reconstructed=True)
                # Verify riff_path exists before loading
                if not riff_path or not os.path.exists(riff_path):
                    # Try to find any output from RIFE in tmp locations
                    _fallback = None
                    for _d in [tmp_out, os.path.join(script_dir,"output")]:
                        if os.path.isdir(_d):
                            _imgs = sorted(f for f in os.listdir(_d)
                                if os.path.splitext(f)[1].lower() in {".png",".jpg"})
                            if _imgs:
                                _fallback = os.path.join(_d, _imgs[len(_imgs)//2])
                                break
                    if _fallback:
                        self.after(0, lambda p=riff_path: self.log(self.rlog,
                            f"riff_path missing ({p}), using fallback", "dim"))
                        riff_path = _fallback
                    else:
                        raise FileNotFoundError(
                            f"RIFE produced no output.\n"
                            f"Expected: {riff_path}\n"
                            f"tmp_out contents: {os.listdir(tmp_out) if os.path.isdir(tmp_out) else []}"
                        )
                riff_full = load_full(riff_path, is_reconstructed=True)
                self.after(0, lambda o=orig_full.size, r=riff_full.size:
                    self.log(self.rlog,
                        f"Loaded orig={o} riff={r}", "dim"))
                # orig_w/orig_h may be unset when using a cached riff_path —
                # fall back to the loaded original's actual dimensions
                _ow = orig_w or orig_full.width
                _oh = orig_h or orig_full.height
                # Fix riff size: crop if padded larger, resize if model output smaller
                self.after(0, lambda s=riff_full.size, ow=_ow, oh=_oh:
                    self.log(self.rlog,
                        f"RIFE output: {s[0]}×{s[1]} expected: {ow}×{oh}", "dim"))
                if riff_full.size != (_ow, _oh):
                    rw, rh = riff_full.size
                    if rw >= _ow and rh >= _oh:
                        # Larger (padded) — crop back
                        riff_full = riff_full.crop((0, 0, _ow, _oh))
                    else:
                        # Smaller than expected — resize to match original
                        riff_full = riff_full.resize((_ow, _oh), Image.LANCZOS)
                # Ensure both are same size (should be after crop/resize above)
                if riff_full.size != orig_full.size:
                    target = orig_full.size if orig_full.size[0] >= riff_full.size[0] else riff_full.size
                    orig_full = orig_full.resize(target, Image.LANCZOS)
                    riff_full = riff_full.resize(target, Image.LANCZOS)

                self._rife_wipe_orig_base  = orig_full
                self._rife_wipe_orig_actual = orig_full.copy()  # keep for toggle
                self._rife_upscale_compare_mode = False
                try:
                    import numpy as _npdiag
                    _diag_arr = _npdiag.array(orig_full.convert("RGB"), dtype=_npdiag.float32)
                    self.after(0, lambda m=float(_diag_arr.mean()): self.log(
                        self.rlog,
                        f"[diag] initial orig display set (reinhard/source path) "
                        f"\u2014 mean pixel value: {m:.1f}/255", "dim"))
                except Exception: pass
                # Apply upscale to display base if Preview upscale is on
                _raw = getattr(self,"_rife_wipe_riff_raw",None)
                _odims = getattr(self,"_rife_orig_dims",(0,0))
                if _raw and getattr(self,"rife_prev_upscale_var",None) \
                        and self.rife_prev_upscale_var.get():
                    self._rife_wipe_riff_base = self._rife_upscale_pil(
                        _raw, _odims[0] or riff_full.width,
                             _odims[1] or riff_full.height)
                else:
                    self._rife_wipe_riff_base = riff_full
                # Mark computed pairs as cached in timeline
                if hasattr(self,"_rife_dual_tl"):
                    # After pair: always (frame idx → idx+1)
                    if 0 <= _pair4 < len(self.rife_frames)-1:
                        self.after(0, lambda p=_pair4:
                            self._rife_dual_tl.add_cached_pair(p))
                    # Before pair: also marked when retime ran preceding pair
                    if _prev_ret and _pair4 > 0:
                        self.after(0, lambda p=_pair4-1:
                            self._rife_dual_tl.add_cached_pair(p))
                # Preserve mode and wipe position across previews
                if self._rife_wipe_orig_base is None:
                    self._rife_mode   = "preview"
                    self._rife_wipe_t = 0.5
                # Pre-render thumbnail at canvas size for instant display
                def _show_preview():
                    try:
                        from PIL import Image, ImageTk
                        self.rife_wipe_canvas.update_idletasks()
                        cw = self.rife_wipe_canvas.winfo_width()
                        ch = self.rife_wipe_canvas.winfo_height()
                        if cw < 10 or ch < 10:
                            self.after(100, _show_preview); return
                        self.log(self.rlog, f"Canvas: {cw}×{ch} Image: {riff_full.size}", "dim")
                        # Fit image to canvas (FIT mode — shows whole image)
                        fit = riff_full.copy()
                        try:
                            _sc2 = float(self.tk.call("tk","scaling"))
                            _rf = max(1, round(_sc2))
                        except Exception:
                            _rf = 1
                        self.log(self.rlog, f"retina={_rf} tk_scaling={_sc2:.2f}", "dim")
                        fit.thumbnail((cw*_rf, ch*_rf), Image.LANCZOS)
                        # Centre on dark background
                        bg = Image.new("RGB", (cw*_rf, ch*_rf), (10,10,10))
                        ox = (cw*_rf - fit.width)  // 2
                        oy = (ch*_rf - fit.height) // 2
                        bg.paste(fit, (ox, oy))
                        self._rife_preview_tk = ImageTk.PhotoImage(bg)
                        self.rife_wipe_canvas.delete("all")
                        self.rife_wipe_canvas.create_image(0,0,anchor="nw",
                            image=self._rife_preview_tk)
                        self.rife_wipe_canvas.create_text(6,8,anchor="nw",
                            text="Riffled — click ⬛ Wipe to compare",
                            font=FM, fill=GR)
                    except Exception as ex:
                        self.log(self.rlog, f"Preview show error: {ex}", "err")
                self.after(50, _show_preview)
                self.after(0, lambda: self.rife_wipe_canvas.configure(
                    highlightbackground=GR, highlightthickness=2))
                self.after(1500, lambda: self.rife_wipe_canvas.configure(
                    highlightbackground=BD, highlightthickness=1))
                self.after(0, lambda: self.log(self.rlog,
                    "Preview ready — click ⬛ Wipe to compare.", "ok"))
                self.after(50, lambda: self._set_preview_phase("", done=True))

            except Exception as ex:
                import traceback
                err = traceback.format_exc()   # capture NOW, not in lambda
                self.after(0, lambda e=err: self.log(self.rlog,
                    "Preview error: " + e[:500], "err"))
            finally:
                if tmp_in:  shutil.rmtree(tmp_in,  ignore_errors=True)
                self.after(0, lambda: self.progress(-1))
                self.after(0, lambda: self.rife_preview_btn.configure(
                    text="Preview", state="normal",
                    bg="#2A0A0A", fg="#CC4444",
                    command=self._rife_preview_frame))

        threading.Thread(target=go, daemon=True).start()

    def _rife_wipe_draw(self, label_r="ADW-Blur"):
        if self._rife_wipe_orig_base is None: return
        try:
            import math, numpy as np
            from PIL import Image, ImageTk
            rvpaned = self.rife_wipe_canvas.master.master
            cw = self.rife_wipe_canvas.winfo_width()
            ch = self.rife_wipe_canvas.winfo_height()
            try:
                _sc = float(self.tk.call("tk","scaling"))
                retina = max(1, round(_sc))
            except Exception:
                retina = 1
            cw *= retina; ch *= retina
            if ch < 100 or cw < 100:
                self.after(200, self._rife_wipe_draw)
                return

            src_orig = self._rife_wipe_orig_base
            iw, ih   = src_orig.size
            base  = max(cw / iw, ch / ih)
            scale = base * self._rife_zoom
            nw    = max(1, int(round(iw * scale)))
            nh    = max(1, int(round(ih * scale)))
            px    = int(-(nw - cw)//2 + self._rife_pan_x)
            py    = int(-(nh - ch)//2 + self._rife_pan_y)
            orig_r = src_orig.resize((nw, nh), Image.LANCZOS)
            riff_r = self._rife_wipe_riff_base.resize((nw, nh), Image.LANCZOS)

            ang = self._rife_wipe_angle
            t   = self._rife_wipe_t
            rad = math.radians(ang)
            nx_, ny_ = math.cos(rad), math.sin(rad)

            # Build canvas-sized composite with pan applied
            base_img = Image.new("RGB", (cw, ch), (10, 10, 10))
            base_img.paste(orig_r, (px, py))
            riff_canvas = Image.new("RGB", (cw, ch), (10, 10, 10))
            riff_canvas.paste(riff_r, (px, py))

            # Split centre in canvas coords
            cx_c = int(cw/2 + (t - 0.5) * cw * nx_)
            cy_c = int(ch/2 + (t - 0.5) * ch * ny_)

            if ang == 0:
                composite = base_img.copy()
                if cx_c < cw:
                    composite.paste(riff_canvas.crop((cx_c,0,cw,ch)), (cx_c,0))
            else:
                ys, xs = np.mgrid[0:ch, 0:cw]
                dist = (xs - cx_c)*nx_ + (ys - cy_c)*ny_
                mask_img = Image.fromarray((dist>=0).astype(np.uint8)*255,"L")
                composite = base_img.copy()
                composite.paste(riff_canvas, (0,0), mask_img)

            self._rife_wipe_tk = ImageTk.PhotoImage(composite)
            self.rife_wipe_canvas.delete("all")
            self.rife_wipe_canvas.create_image(0, 0, anchor="nw", image=self._rife_wipe_tk)

            perp = math.radians(ang + 90)
            half = max(cw, ch)
            hx = cx_c
            hy = cy_c
            lx1 = int(hx - math.cos(perp) * half)
            ly1 = int(hy - math.sin(perp) * half)
            lx2 = int(hx + math.cos(perp) * half)
            ly2 = int(hy + math.sin(perp) * half)
            self.rife_wipe_canvas.create_line(lx1, ly1, lx2, ly2,
                fill="#DCDCDC", width=2, tags="wipe_line")

            # Double-headed drag arrow along the normal direction
            hs = 10
            nx2, ny2 = math.cos(rad), math.sin(rad)
            for sign in (1, -1):
                tip_x = int(hx + sign * nx2 * hs * 2)
                tip_y = int(hy + sign * ny2 * hs * 2)
                base1_x = int(hx + sign * nx2 * hs - ny2 * hs)
                base1_y = int(hy + sign * ny2 * hs + nx2 * hs)
                base2_x = int(hx + sign * nx2 * hs + ny2 * hs)
                base2_y = int(hy + sign * ny2 * hs - nx2 * hs)
                self.rife_wipe_canvas.create_polygon(
                    tip_x, tip_y, base1_x, base1_y, base2_x, base2_y,
                    fill="#DCDCDC", outline="", tags="wipe_handle")

            # Labels
            _cmp = getattr(self,"_rife_upscale_compare_mode",False)
            _lbl_l = "RIFE pre-upscale" if _cmp else "Input"
            _lbl_r = label_r
            if hx > 80:
                self.rife_wipe_canvas.create_text(6, 8, anchor="nw",
                    text=_lbl_l, font=FM, fill="#888888")
            if hx < cw//retina - 80:
                self.rife_wipe_canvas.create_text(hx + 20, 8, anchor="nw",
                    text=_lbl_r, font=FM, fill=GR)
        except Exception as ex:
            self.log(self.rlog, "Wipe draw error: " + str(ex), "err")

    def _combo(self, parent, label, options, default=None, tip=None,
               wide=False):
        """`default` picks a starting option other than the first --
        needed wherever the sensible default is not the top of the list.
        `tip` adds the same hover icon the sliders use.
        `wide` puts the dropdown on its own line under the label, the
        full width of the card, for option names longer than the
        standard 20 characters -- a name cut off in the box is a choice
        that cannot be read back once it is made."""
        row = tk.Frame(parent, bg=S)
        row.pack(fill="x", pady=2)
        tk.Label(row, text=label, font=FSM, bg=S, fg=G,
                 width=12, anchor="w").pack(side="left")
        v = tk.StringVar(value=default if default in options else options[0])
        if wide:
            row2 = tk.Frame(parent, bg=S)
            row2.pack(fill="x", pady=(0, 3))
            cb = ttk.Combobox(row2, textvariable=v, values=options,
                              state="readonly", font=FSM, width=20)
            cb.pack(fill="x", expand=True)
        else:
            cb = ttk.Combobox(row, textvariable=v, values=options,
                              state="readonly", font=FSM, width=20)
            cb.pack(side="left", padx=4)
        if tip:
            i = tk.Label(row, text="\u24d8", font=FSM, bg=S, fg="#555555",
                         cursor="hand2")
            i.pack(side="left", padx=(4, 0))
            self._tooltip(tip)(i)
        return v

    def _rpick(self, e=None):
        p = filedialog.askdirectory(title="Select image sequence folder")
        if not p: return
        try:
            self._rpick_load(p)
        except Exception as _ex:
            import traceback
            messagebox.showerror("Load error",
                f"{_ex}\n\n{traceback.format_exc()[-300:]}")

    def _rpick_load(self, p):
        # Stop playback and drop its RAM cache — it belongs to the old folder
        if hasattr(self,"_rife_play_stop"):
            self._rife_play_stop(quiet=True)
            self._rife_play_cache = None
        exts = {".exr", ".png", ".tif", ".tiff", ".jpg", ".jpeg"}
        all_files = os.listdir(p)
        frames = sorted([f for f in all_files
                         if os.path.splitext(f)[1].lower() in exts])
        if not frames:
            # Show what IS in the folder to help diagnose
            sample = ", ".join(all_files[:8]) or "(empty)"
            messagebox.showerror("No frames",
                f"No image files found in:\n{p}\n\nContents: {sample}")
            return
        self.rife_folder = p
        self.rife_frames = frames
        self.rife_frame_cb["values"] = frames
        # Populate Riffled timeline
        _em_r  = {"2x":2,"4x":4,"6x":6,"8x":8}
        _exp_r = _em_r.get(self.rmult_var.get(), 4)
        self.rife_rife_tl.set_data(len(frames), _exp_r)
        if hasattr(self,"_rife_range_bar"):
            self._rife_range_bar.set_n(len(frames))
        # Auto-detect existing RIFE frames so Wipe/Diff/slider work without a fresh run
        _adw_candidate = self._rife_frames_dir(p)
        if os.path.isdir(_adw_candidate):
            self._rife_full_adw_dir = _adw_candidate
            self._rife_adw_dir      = _adw_candidate
        # Show Recalc state based on whether the RIFE frames exist
        _riffled = self._rife_frames_dir(p)
        if not os.path.isdir(_riffled):  # legacy fallback
            _riffled = os.path.join(p, "Riffled")
        _rb = getattr(self,"_retime_recalc_btn",None)
        if _rb:
            if os.path.isdir(_riffled):
                _rb.configure(text="\u27f3  Recalc", fg="#FF4444",
                              bg="#2A0808", cursor="hand2")
            else:
                _rb.configure(text="Run Preview first", fg="#444444",
                              bg="#0A0A0A", cursor="arrow")
        # Scan the RIFE frames folder for which pairs are calculated
        _riffled = self._rife_frames_dir(p)
        if hasattr(self,"_rife_dual_tl") and os.path.isdir(_riffled):
            _em_r2={"2x":2,"4x":4,"6x":6,"8x":8}
            _exp_r2=_em_r2.get(self.rmult_var.get(),4)
            _step2 = _exp_r2   # frames per pair in riffled
            _rfiles_raw = sorted(f for f in os.listdir(_riffled)
                             if f.lower().endswith((".png",".exr")))
            _rf_seen2 = {}
            for _rf2 in _rfiles_raw:
                _b2 = os.path.splitext(_rf2)[0]
                if _b2 not in _rf_seen2 or _rf2.lower().endswith(".exr"):
                    _rf_seen2[_b2] = _rf2
            _rfiles = sorted(_rf_seen2.values(),
                             key=lambda f: os.path.splitext(f)[0])
            _n_riffled = len(_rfiles)
            _n_orig    = len(frames)
            # A pair i is cached if its riffled frames exist
            # Riffled index for pair i = i*_step2 to (i+1)*_step2
            _cached = set()
            for _pi in range(max(0,_n_orig-1)):
                _ri_start = _pi * _step2
                _ri_end   = (_pi+1) * _step2
                if _ri_end <= _n_riffled:
                    _cached.add(_pi)
            self._rife_dual_tl.set_cached_pairs(_cached)
        elif hasattr(self,"_rife_dual_tl"):
            self._rife_dual_tl.set_cached(False)
        self.rife_path_lbl.configure(text=p, fg=G)
        name = os.path.basename(p)
        ext  = os.path.splitext(frames[0])[1].upper()
        self.rl.configure(
            text="OK  " + name + "  (" + str(len(frames)) + " " + ext + " frames)",
            fg=GR)
        self.ri.configure(text="First: " + frames[0] + "   Last: " + frames[-1])
        out = self._rife_final_dir(p)
        self.rb2.configure(state="normal")
        self.log(self.rlog, "Loaded: " + str(len(frames)) + " frames from " + name, "ok")
        self.log(self.rlog, "Output -> " + out + "/", "hi")
        # Show first frame immediately as a raw preview
        def _load_raw():
            try:
                from PIL import Image
                first = os.path.join(p, frames[0])
                ext = os.path.splitext(frames[0])[1].lower()
                if ext == ".exr":
                    import tempfile
                    tmp = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
                    tmp.close()
                    subprocess.run(["ffmpeg","-y","-i",first,
                        "-vf","tonemap=reinhard",tmp.name], capture_output=True)
                    img = Image.open(tmp.name).convert("RGB")
                    os.unlink(tmp.name)
                else:
                    img = Image.open(first).convert("RGB")
                # Use same image for both sides — wipe will replace riff side later
                self._rife_wipe_orig_base = img
                self._rife_wipe_riff_base = img
                self._rife_mode = "preview"
                self.after(0, self._rife_display)
            except Exception:
                pass
        threading.Thread(target=_load_raw, daemon=True).start()
        if hasattr(self,"_cache_btns_refresh"):
            self._cache_btns_refresh()
        # Kick off PNG cache build in background if EXR sequence
        if frames and os.path.splitext(frames[0])[1].lower() == ".exr":
            _png_cache_target = os.path.join(self._adw_output_root(p), "_png_cache")
            self.log(self.rlog, "Building PNG cache -> " + _png_cache_target + "/", "dim")
            self._png_cache_building = True
            if hasattr(self,"_cache_btns_refresh"):
                self._cache_btns_refresh()
            def _bg_build_then_refresh(folder=p, fr=frames):
                try:
                    self._build_png_cache(folder, fr)
                finally:
                    self._png_cache_building = False
                    if hasattr(self,"_cache_btns_refresh"):
                        self.after(0, self._cache_btns_refresh)
            threading.Thread(target=_bg_build_then_refresh, daemon=True).start()
        else:
            self.log(self.rlog,
                f"No PNG cache — input frames are {ext}, not EXR "
                f"(only EXR sequences need the gamma/exposure round-trip cache).", "dim")

    def _build_png_cache(self, folder, frames):
        """Thin wrapper: the inner implementation can fail for all
        sorts of reasons (disk space, a malformed EXR, OpenEXR/ffmpeg
        not behaving) and since this runs in a daemon background
        thread, an uncaught exception there would just silently kill
        the thread with zero visible indication of what happened or
        even that anything happened at all. Surface it instead."""
        try:
            self._build_png_cache_inner(folder, frames)
        except Exception as ex:
            import traceback
            tb = traceback.format_exc()
            self.after(0, lambda e=str(ex), t=tb: self.log(
                self.rlog, f"PNG cache build failed: {e}", "err"))
            self.after(0, lambda t=tb: self.log(
                self.rlog, t[-600:], "dim"))

    def _build_png_cache_inner(self, folder, frames):
        """Convert EXR sequence to cached 8-bit PNGs on load. Used by _rrun."""
        import json, numpy as _np
        from PIL import Image as _PI
        cache_dir = os.path.join(self._adw_output_root(folder), "_png_cache")
        self._adw_invalidate_stale_png_cache(cache_dir)
        info_path = os.path.join(cache_dir, "_cache_info.json")
        # Check if all frames already cached
        if os.path.isdir(cache_dir):
            cached = [f for f in os.listdir(cache_dir) if f.endswith(".png")]
            if len(cached) >= len(frames):
                try:
                    info = json.loads(open(info_path).read())
                    self.after(0, lambda n=len(frames): (
                        self._png_cache_lbl.configure(
                            text=f"PNG cache: {n} frames ✓", fg="#44AA44")))
                    return
                except Exception: pass
        os.makedirs(cache_dir, exist_ok=True)
        self.after(0, lambda: self._png_cache_lbl.configure(
            text="PNG cache: building…", fg="#CC8844"))
        if hasattr(self,"_cache_png_btn"):
            self.after(0, lambda: self._cache_png_btn.configure(progress=0.01))
        norm_scale = [None]
        done = 0
        for fn in frames:
            src = os.path.join(folder, fn)
            dst = os.path.join(cache_dir, os.path.splitext(fn)[0]+".png")
            if os.path.exists(dst) and os.path.getsize(dst) > 100:
                done += 1; continue
            ok = False
            try:
                import OpenEXR as _OE, Imath as _Im
                ef = _OE.InputFile(src)
                hdrc = ef.header()
                dw = hdrc["dataWindow"]; dispc = hdrc["displayWindow"]
                dw_wc = dw.max.x-dw.min.x+1; dw_hc = dw.max.y-dw.min.y+1
                fw = dispc.max.x-dispc.min.x+1; fh = dispc.max.y-dispc.min.y+1
                FP = _Im.PixelType(_Im.PixelType.FLOAT)
                data_c = _np.stack([
                    _np.frombuffer(ef.channel(c,FP),_np.float32).reshape(dw_hc,dw_wc)
                    for c in "RGB"],axis=2)
                if (dw_wc,dw_hc)==(fw,fh) and dw.min.x==dispc.min.x and dw.min.y==dispc.min.y:
                    arr = data_c
                else:
                    # dataWindow offset/cropped from displayWindow (seen
                    # from some AI video tools) -- this builds the cache
                    # both preview and the main run rely on, so a
                    # mismatch here propagates everywhere downstream.
                    arr = _np.zeros((fh,fw,3),dtype=_np.float32)
                    y0c = dw.min.y-dispc.min.y; x0c = dw.min.x-dispc.min.x
                    arr[max(0,y0c):max(0,y0c)+dw_hc, max(0,x0c):max(0,x0c)+dw_wc] = data_c
                arr = _np.maximum(arr,0)
                if norm_scale[0] is None:
                    lum = arr.max(axis=2)
                    norm_scale[0] = self._adw_auto_exposure_scale(lum) if lum.max()>0 else 1.0
                gm = self._adw_gamma_encode(arr, norm_scale[0])
                _PI.fromarray((gm*255).astype(_np.uint8)).save(dst)
                ok = True
            except ImportError: pass
            except Exception: pass
            if not ok:
                try:
                    import json as _js, subprocess as _sp
                    pr = _sp.run(["ffprobe","-v","quiet","-print_format","json",
                        "-show_streams",src],capture_output=True,text=True,timeout=10)
                    vs = next(s for s in _js.loads(pr.stdout)["streams"]
                              if s["codec_type"]=="video")
                    fw,fh = int(vs["width"]),int(vs["height"])
                    raw = _sp.run(["ffmpeg","-y","-i",src,"-pix_fmt","rgbaf32le",
                        "-f","rawvideo","pipe:1"],capture_output=True,timeout=90)
                    arr = _np.frombuffer(raw.stdout,_np.float32).reshape(fh,fw,4)[:,:,:3]
                    arr = _np.maximum(arr,0)
                    if norm_scale[0] is None:
                        lum = arr.max(axis=2)
                        norm_scale[0] = self._adw_auto_exposure_scale(lum) if lum.max()>0 else 1.0
                    gm = self._adw_gamma_encode(arr, norm_scale[0])
                    _PI.fromarray((gm*255).astype(_np.uint8)).save(dst)
                    ok = True
                except Exception: pass
            if not ok:
                import subprocess as _sp2
                _sp2.run(["ffmpeg","-y","-i",src,
                    "-vf","tonemap=reinhard:desat=0,format=rgb24",dst],
                    capture_output=True,timeout=90)
                if norm_scale[0] is None: norm_scale[0] = 1.0
            done += 1
            if hasattr(self,"_cache_png_btn"):
                n = len(frames)
                self.after(0, lambda d=done,n=n: self._cache_png_btn.configure(
                    progress=d/max(1,n)))
            if done % 10 == 0:
                n = len(frames)
                self.after(0, lambda d=done,n=n: self._png_cache_lbl.configure(
                    text=f"PNG cache: {d}/{n}…", fg="#CC8844"))
        # Save info
        try:
            with open(info_path,"w") as f:
                json.dump({"n_frames":len(frames),"norm_scale":norm_scale[0],
                    "cache_version":self._ADW_PNG_CACHE_VERSION},f)
        except Exception: pass
        n = len(frames)
        self.after(0, lambda n=n: self._png_cache_lbl.configure(
            text=f"PNG cache: {n} frames ✓", fg="#44AA44"))
        self.after(0, lambda n=n, c=cache_dir: self.log(
            self.rlog, f"PNG cache ready: {n} frames -> {c}/", "dim"))
        # Mark cached frames in timeline
        if hasattr(self,"_rife_dual_tl") and \
                hasattr(self._rife_dual_tl,"set_cached_pngs"):
            self.after(0, lambda n=n:
                self._rife_dual_tl.set_cached_pngs(set(range(n))))

    def _rife_auto_retime(self, riffled_dir, original_count, speedup=0,
                          then_mov=False, out_dir=None, log_widget=None,
                          on_done=None, params=None):
        """Retime RIFE/ back to original frame count using DIS optical
        flow blend. speedup<=1 is the normal behavior (one output
        frame per input frame -- 1x is the default, meaning "every
        frame kept", mathematically identical to off). speedup=N>1
        instead keeps only every Nth input frame, blending each kept
        frame's motion blur across the full span to the next kept
        frame -- so the dropped frames' motion gets absorbed rather
        than lost, instead of just being decimated. See the loop below
        for exactly how the window is computed in that case."""
        import threading
        # `params` lets a caller (ADW-Interpolate) drive the retime with a
        # chosen ADW-Blur preset WITHOUT reaching over and mutating
        # ADW-Blur's UI vars behind the user's back. With no params we
        # read the live vars exactly as before.
        _P = params or {}
        def _pv(key, attr, default, cast=None):
            if key in _P:
                v = _P[key]
            else:
                var = getattr(self, attr, None)
                v = var.get() if var is not None else default
            if cast:
                try: return cast(v)
                except Exception: return cast(default)
            return v
        _flowq     = _pv("flow", "rife_flow_var", "Quality")
        _blend_str = _pv("blend_str", "rife_blend_str_var", 100.0, float) / 100.0
        _falloff   = _pv("falloff", "rife_blend_falloff_var", "Hann")
        _motion_on = _pv("motion_mask_on", "rife_motion_mask_var", True)
        # NOTE: the motion threshold is used by the motion-MASK preview
        # (_rife_show_motion_mask), not by the retime blend. The old code
        # read it here and never used it; the self-referential assignment
        # (x = getattr(...); x = float(x.get()) if x else ...) hid that
        # from pyflakes. Dropped rather than carried.
        speedup = max(0, int(speedup or 0))
        if speedup <= 1:
            speedup = 0   # 1x (or unset) is a no-op, same as off
        # ADW-Interpolate reuses this to compress a slow-motion generated
        # span back to speed, so the log target and destination are
        # parameters rather than hardwired to ADW-Blur.
        _rlog = log_widget if log_widget is not None else self.rlog
        _forced_out = out_dir
        _done = {"dir": None}
        def _run():
            import cv2, numpy as np, os, glob, shutil
            from PIL import Image
            self._adw_run_active = True   # block _adw_generate_extra_pairs during retime
            try:
                self.log(_rlog,
                    f"Auto Retime: {riffled_dir} → {original_count} frames…", "hi")
                # Disk space pre-check: estimate output size and warn if tight
                try:
                    _disk = shutil.disk_usage(riffled_dir)
                    _free_gb = _disk.free / 1024**3
                    # Rough estimate: frames × ~25 MB per EXR frame
                    _est_gb = original_count * 25 / 1024
                    if _free_gb < _est_gb * 1.5:
                        self.after(0, lambda f=_free_gb, e=_est_gb: self.log(
                            _rlog,
                            f"⚠ Low disk space: {f:.1f} GB free, ~{e:.1f} GB needed — "
                            f"free up space before running retime", "err"))
                    if _free_gb < _est_gb:
                        self.after(0, lambda: self.log(_rlog,
                            "✖ Aborting retime — not enough disk space", "err"))
                        return
                except Exception:
                    pass
                # Deduplicate: if both .exr and .png exist for same base, prefer .exr
                _all = sorted([
                    f for f in os.listdir(riffled_dir)
                    if os.path.splitext(f)[1].lower() in ('.png','.jpg','.exr')
                    and not f.startswith("__")
                ])
                _seen = {}
                for _f in _all:
                    _base = os.path.splitext(_f)[0]
                    _ext  = os.path.splitext(_f)[1].lower()
                    if _base not in _seen or _ext == '.exr':
                        _seen[_base] = _f
                frames = sorted(_seen.values(), key=lambda f: os.path.splitext(f)[0])
                src_count = len(frames)
                if src_count < 2:
                    self.log(_rlog, "Auto Retime: not enough frames.", "err"); return

                # Full paths for cv2 access
                work_dir   = riffled_dir
                work_files = [os.path.join(riffled_dir, f) for f in frames]

                # The retimed sequence is ADW-Blur's deliverable, so it
                # gets the clean ADW/ADW-Blur name; the raw RIFE frames
                # we are reading from live in ADW/ADW-Blur_Rife.
                _rt_src = getattr(self, "rife_folder", None)
                if _forced_out:
                    out_dir = _forced_out          # caller picked the target
                    _rt_src = None
                elif _rt_src:
                    out_dir = self._rife_final_dir(_rt_src)
                else:   # derive from the RIFE frames dir as a fallback
                    out_dir = os.path.join(
                        os.path.dirname(riffled_dir.rstrip('/\\')),
                        "ADW-Blur")
                import shutil as _sh2
                # Never clear a folder we are reading from: not the RIFE
                # frames we retime out of, and not the source sequence
                # (which ADW/ADW-Blur could be if a prior ADW-Blur output
                # was propagated back in as the input).
                _guard = {os.path.abspath(riffled_dir)}
                if _rt_src:
                    _guard.add(os.path.abspath(_rt_src))
                _suffix = 2
                while os.path.abspath(out_dir) in _guard:
                    out_dir = os.path.join(
                        os.path.dirname(riffled_dir.rstrip('/\\')),
                        f"ADW-Blur_{_suffix}")
                    _suffix += 1
                if os.path.isdir(out_dir): _sh2.rmtree(out_dir, ignore_errors=True)
                os.makedirs(out_dir, exist_ok=True)
                _done["dir"] = out_dir

                dis = cv2.DISOpticalFlow_create(cv2.DISOPTICAL_FLOW_PRESET_MEDIUM)

                # Detect output format from ADW frames — majority vote so a
                # handful of leftover PNGs don't flip the whole output to PNG
                _exr_count = sum(1 for f in frames
                                 if os.path.splitext(f)[1].lower() == ".exr")
                _out_is_exr = _exr_count >= len(frames) // 2

                def _load_linear(path):
                    """Load as linear float32 BGR [0,∞). EXR=native, PNG=gamma decode."""
                    ext = os.path.splitext(path)[1].lower()
                    if ext == ".exr":
                        try:
                            import OpenEXR as _OE, Imath as _Im
                            ef = _OE.InputFile(path)
                            hdr = ef.header()
                            dw = hdr["dataWindow"]; disp = hdr["displayWindow"]
                            dw_w = dw.max.x-dw.min.x+1; dw_h = dw.max.y-dw.min.y+1
                            fw = disp.max.x-disp.min.x+1; fh = disp.max.y-disp.min.y+1
                            FP = _Im.PixelType(_Im.PixelType.FLOAT)
                            data = np.stack([
                                np.frombuffer(ef.channel(c,FP),np.float32
                                    ).reshape(dw_h,dw_w) for c in "RGB"],axis=2)
                            if (dw_w,dw_h)==(fw,fh) and dw.min.x==disp.min.x and dw.min.y==disp.min.y:
                                arr = data
                            else:
                                # dataWindow offset/cropped from displayWindow
                                # (seen from some AI video tools) -- this sets
                                # the reference size for the WHOLE output
                                # sequence below, so getting it wrong here
                                # silently stretches every frame, not just
                                # this one.
                                arr = np.zeros((fh,fw,3),dtype=np.float32)
                                y0 = dw.min.y-disp.min.y; x0 = dw.min.x-disp.min.x
                                arr[max(0,y0):max(0,y0)+dw_h, max(0,x0):max(0,x0)+dw_w] = data
                            return np.maximum(arr,0)[:,:,::-1]  # RGB→BGR linear
                        except Exception as _e1: pass
                        try:
                            import subprocess as _sp, tempfile as _tf
                            tmp = _tf.NamedTemporaryFile(suffix=".png",delete=False)
                            tmp.close()
                            _sp.run(["ffmpeg","-y","-i",path,
                                "-vf","tonemap=reinhard:desat=0,format=rgb24",tmp.name],
                                capture_output=True,timeout=30)
                            img = cv2.imread(tmp.name)
                            os.unlink(tmp.name)
                            if img is not None:
                                return np.power(img.astype(np.float32)/255,2.2)
                        except Exception as _e2: pass
                        self.after(0, lambda p=os.path.basename(path): self.log(
                            _rlog, f"Retime: failed to load {p}", "err"))
                        return None
                    # PNG: gamma → linear
                    img = cv2.imread(path)
                    if img is None: return None
                    return np.power(img.astype(np.float32)/255, 2.2)

                _ref0 = _load_linear(work_files[0])
                if _ref0 is not None:
                    _ref_h, _ref_w = _ref0.shape[:2]
                else:
                    # Fallback: read dimensions from source input folder
                    try:
                        import OpenEXR as _OEr, Imath as _Imr
                        _src_list = sorted([f for f in os.listdir(self.rife_folder)
                            if f.lower().endswith(".exr") and not f.startswith("__")])
                        if _src_list:
                            _ef0 = _OEr.InputFile(os.path.join(self.rife_folder, _src_list[0]))
                            _hdr0 = _ef0.header()
                            _disp0 = _hdr0.get("displayWindow", _hdr0["dataWindow"])
                            _ref_w = _disp0.max.x - _disp0.min.x + 1
                            _ref_h = _disp0.max.y - _disp0.min.y + 1
                        else:
                            _ref_h, _ref_w = 1080, 1920
                    except Exception:
                        _ref_h, _ref_w = 1080, 1920

                # Read the consistent norm_scale used when building the PNG cache.
                # ALL frames (source and interp) will be normalised to [0,1] with
                # this same scale before blending, so they share the same encoding.
                _ns = 1.0
                try:
                    import json as _cjr
                    _ci = _cjr.loads(open(os.path.join(
                        self._adw_output_root(self.rife_folder),"_png_cache","_cache_info.json")).read())
                    _ns = float(_ci.get("norm_scale") or 1.0) or 1.0
                except Exception: pass

                def load(path, scale=None):
                    """Load frame as float32 BGR, normalised to [0,255] by given scale."""
                    img = _load_linear(path)
                    if img is None or img.size == 0:
                        _sc = scale if scale is not None else 1.0
                        return np.zeros((_ref_h,_ref_w,3),dtype=np.float32), _sc
                    img = img.astype(np.float32)
                    if img.shape[:2] != (_ref_h,_ref_w):
                        img = cv2.resize(img,(_ref_w,_ref_h),cv2.INTER_LINEAR)
                    if scale is None:
                        lum = img.max(axis=2)
                        scale = self._adw_auto_exposure_scale(lum) if lum.any() else 1.0
                    img = np.power(np.clip(img/scale,0,1), 1/2.2) * 255
                    return img.astype(np.float32), scale

                def load_norm(path, scale=None):
                    """Return (img_0_255, scale) normalised consistently."""
                    result = load(path, scale)
                    if isinstance(result, tuple): return result
                    lum = result.max(axis=2)
                    return result, (self._adw_auto_exposure_scale(lum) if lum.any() else 1.0)

                def _to_u8gray(img):
                    """Tone-map to uint8 greyscale for DIS optical flow."""
                    p = float(np.percentile(img, 99)) + 1e-6
                    g = np.power(np.clip(img/p, 0, 1), 1/2.2)
                    return cv2.cvtColor((g*255).astype(np.uint8),
                                       cv2.COLOR_BGR2GRAY)

                def warp(img, flow):
                    h, w = flow.shape[:2]
                    map_x = (np.arange(w,dtype=np.float32)[None,:]+flow[:,:,0])
                    map_y = (np.arange(h,dtype=np.float32)[:,None]+flow[:,:,1])
                    map_x = np.clip(map_x,0,w-1).astype(np.float32)
                    map_y = np.clip(map_y,0,h-1).astype(np.float32)
                    return cv2.remap(img.astype(np.float32),map_x,map_y,
                                     cv2.INTER_LINEAR)

                def _write_frame(path_no_ext, arr_0_255, scale):
                    """Convert gamma 0-255 → linear using scale, write as EXR."""
                    arr_gamma = np.clip(arr_0_255/255, 0, 1)
                    arr_linear = np.power(arr_gamma, 2.2) * scale
                    if _out_is_exr:
                        try:
                            import OpenEXR as _OE, Imath as _Im
                            h,w = arr_linear.shape[:2]
                            hdr = _OE.Header(w,h)
                            FP  = _Im.PixelType(_Im.PixelType.FLOAT)
                            hdr['channels'] = {c: _Im.Channel(FP) for c in "RGB"}
                            of  = _OE.OutputFile(path_no_ext+".exr", hdr)
                            of.writePixels({
                                "R": np.ascontiguousarray(arr_linear[:,:,2],np.float32).tobytes(),
                                "G": np.ascontiguousarray(arr_linear[:,:,1],np.float32).tobytes(),
                                "B": np.ascontiguousarray(arr_linear[:,:,0],np.float32).tobytes()})
                            of.close(); return
                        except Exception as _we:
                            self.after(0,lambda e=str(_we): self.log(
                                _rlog,f"EXR write error: {e}","err"))
                    # PNG fallback
                    cv2.imwrite(path_no_ext+".png",(arr_gamma*255).astype(np.uint8))

                interp_step = (src_count-1)/max(1,original_count-1)

                # Sanity check: does the actual RIFE frame density on
                # disk match what the current Smoothing setting would
                # produce? A real mismatch here (not just rounding)
                # means the RIFE generation step didn't fully
                # complete -- cancelled, crashed, or ran out of disk
                # partway through a denser-than-usual run -- and this
                # retime would otherwise silently blend from whatever
                # partial, early-sequence frames happen to exist rather
                # than the frame positions it's actually asking for.
                # This sanity check only makes sense for ADW-Blur's own
                # RIFE output, where the frame density on disk should match
                # the Smoothing setting. ADW-Interpolate drives the retime
                # over VACE frames -- there is no RIFE step and no rmult --
                # so the check would fire a confusing false alarm. `params`
                # being supplied is exactly the signal that a caller is
                # driving with its own plan.
                _em_chk = {"2x":2,"4x":4,"6x":6,"8x":8}
                _expected_step = _em_chk.get(
                    getattr(self,"rmult_var",type("V",(),{"get":lambda s:"4x"})()).get(), 4)
                if params is None and interp_step < _expected_step * 0.6:
                    self.after(0, lambda e=_expected_step, a=interp_step: self.log(
                        _rlog,
                        f"\u26a0 RIFE frame density on disk ({a:.1f}\u00d7) is much lower "
                        f"than the current Smoothing setting ({e}\u00d7) would produce "
                        f"\u2014 the RIFE generation step may not have finished "
                        f"(cancelled, crashed, or ran out of disk space). This retime "
                        f"will only have early-sequence frames to draw from. Re-run "
                        f"ADW-Blur fully before retiming.", "err"))

                def get_frame(pos, scale=None):
                    pos = max(0,min(pos,src_count-1))
                    lo = int(pos); t = pos-lo
                    if t < 0.001 or lo >= src_count-1:
                        img,sc = load(work_files[lo], scale)
                        return img,sc
                    A,sc = load(work_files[lo], scale)
                    B,_  = load(work_files[lo+1], sc)
                    if A.shape[:2] != B.shape[:2]:
                        B = cv2.resize(B,(A.shape[1],A.shape[0]),cv2.INTER_LINEAR)
                    Ag = _to_u8gray(A); Bg = _to_u8gray(B)
                    fAB = dis.calc(Ag,Bg,None)
                    fBA = dis.calc(Bg,Ag,None)
                    blended = np.maximum(0,(1-t)*warp(A,fAB*t)+t*warp(B,fBA*(1-t)))
                    return blended, sc

                n_out = -(-original_count // speedup) if speedup else original_count  # ceil division
                if speedup:
                    self.log(_rlog,
                        f"Speedup {speedup}\u00d7: {original_count} \u2192 {n_out} frames "
                        f"(every {speedup}th kept, blend window widened to absorb the rest)", "hi")

                for i in range(n_out):
                    if speedup:
                        # Peak sits AT the kept frame itself. Base
                        # half-width is HALFWAY to the next kept frame
                        # (speedup/2 original-frame-units), so adjacent
                        # kept frames' windows meet exactly at the
                        # midpoint between them -- full coverage, no
                        # gaps, no overlap -- same curve shape as
                        # normal Smoothing, just scaled wider.
                        _orig_k = i * speedup
                        center  = _orig_k * interp_step
                        _gap    = speedup / 2.0
                    else:
                        center = i * interp_step
                        _gap   = 1

                    # Get center frame + its per-frame scale (mirrors preview exactly)
                    _oF, _frame_scale = get_frame(center)
                    _og2 = _to_u8gray(_oF)

                    _br   = _pv("blend_radius", "rife_blend_radius_var", "Auto")
                    _bias = _pv("bias", "rife_blend_oversample_var", 0, int)
                    # Base window = _gap full RIFE steps each side (one
                    # gap-to-neighbor for normal frames, half the
                    # gap-to-next-kept-frame for Speedup). Bias
                    # adds/removes N RIFE frames each side on top of
                    # that, identically in both modes: +1 → ±1, -1 → ∓1.
                    # Speedup's +1 corrects for the loop's "_half-1 is
                    # the actual reach" convention, so the window lands
                    # on exact original-frame boundaries (e.g. Speedup
                    # 4x at frame 5, bias 0 → exactly frames 3 to 7).
                    if speedup:
                        _half = round(_gap * interp_step) + 1 if _br=="Auto" else max(1,int(_br))
                    else:
                        _half = int(_gap * interp_step) if _br=="Auto" else max(1,int(_br))
                    _half = max(1, _half + _bias)
                    _N    = 2*_half - 1
                    _acc  = np.zeros((_ref_h,_ref_w,3),dtype=np.float32)
                    _wtot = 0.0
                    for _off in range(-(_half-1), _half):
                        _pos    = max(0,min(src_count-1,center+_off))
                        # Use same scale as center frame so blend is in consistent space
                        _fr,_   = get_frame(_pos, _frame_scale)
                        _n      = _off+(_half-1)
                        _t_norm = _n/max(1,_N-1)
                        if _falloff=="Linear":
                            _wt = 1.0-abs(_t_norm-0.5)*2
                        elif _falloff=="Gaussian":
                            _wt = max(0.06,np.exp(-0.5*(((_t_norm-0.5)/0.1)**2)))
                        elif _falloff=="Box":
                            _wt = 1.0
                        else:
                            _wt = 0.5*(1-np.cos(2*np.pi*_n/max(1,_N-1)))
                        if _off == 0:
                            _acc  += _fr * _wt
                        else:
                            _t    = abs(_off)/_half
                            _wfr  = self._flow_warp(_fr,_oF,dis,_t,_flowq,mask_enabled=_motion_on)
                            _acc  += _wfr * _wt
                        _wtot += _wt

                    blended = np.maximum(0,
                        _acc/_wtot if _wtot>1e-6 else _oF
                    ).astype(np.float32)
                    # Blend strength
                    if _blend_str < 1.0:
                        blended = _blend_str*blended + (1-_blend_str)*_oF
                    # Histogram anchor (in 0-255 space, same as preview)
                    _ha_str = _pv("hist_anchor", "rife_hist_anchor_var",
                                  0.5, float)
                    if _ha_str > 0:
                        for _c in range(3):
                            _ms=_oF[:,:,_c].mean(); _ss=_oF[:,:,_c].std()+1e-8
                            _mb=blended[:,:,_c].mean(); _sb=blended[:,:,_c].std()+1e-8
                            _anc=(blended[:,:,_c]-_mb)*(_ss/_sb)+_ms
                            blended[:,:,_c]=blended[:,:,_c]*(1-_ha_str)+_anc*_ha_str
                    blended = np.clip(blended, 0, 255)
                    # Convert 0-255 back to linear EXR using same scale
                    _base = os.path.join(out_dir, f"{i+1:05d}")
                    _write_frame(_base, blended, _frame_scale)

                    self.after(0, lambda p=(i+1)/n_out, n=i+1, tot=n_out:
                        self.progress(p, f"Retime  {n} / {tot}"))

                self.after(0, lambda: self.progress(-1))
                self.log(_rlog,
                    f"Auto Retime done → {os.path.basename(out_dir)}/", "ok")
                # The MOV should be of the DELIVERABLE, so it is encoded
                # from the retimed output here rather than from the raw
                # RIFE frames (which would give a slow-motion clip at the
                # interpolated frame count).
                if then_mov:
                    self.after(0, lambda d=out_dir: self._rife_encode_mov(d))
            except Exception as ex:
                import traceback
                self.log(_rlog, f"Auto Retime error: {ex}", "err")
                self.log(_rlog, traceback.format_exc()[-300:], "err")
            finally:
                self._adw_run_active = False
                # Let a caller chain off the retime instead of polling the
                # output directory — ADW-Interpolate needs to know exactly
                # when the compressed span has landed.
                if on_done is not None:
                    _d = _done.get("dir")
                    try:
                        self.after(0, lambda d=_d: on_done(d))
                    except Exception:
                        pass

        threading.Thread(target=_run, daemon=True).start()

    def _rife_show_motion_mask(self):
        """Compute and display the motion blend mask in the viewer."""
        import threading
        def go():
            try:
                import cv2, numpy as np
                from PIL import Image
                # Need two adjacent frames to compute flow
                adw = getattr(self,"_rife_adw_dir",None)
                if not adw or not os.path.isdir(adw):
                    self.after(0,lambda: self.log(self.rlog,
                        "Run Preview first to generate ADW frames","dim"))
                    return
                files = sorted([f for f in os.listdir(adw)
                    if os.path.splitext(f)[1].lower() in ('.png','.exr')
                    and not f.startswith("__")])
                if len(files) < 2:
                    self.after(0,lambda: self.log(self.rlog,
                        "Not enough ADW frames for mask preview","dim"))
                    return
                ctr = getattr(self,"_rife_adw_center_override",None)
                if ctr is None: ctr = max(0,len(files)//2)
                lo_i = max(0, ctr-1); hi_i = min(len(files)-1, ctr+1)
                def load_bgr(fname):
                    p = os.path.join(adw, fname)
                    ext = os.path.splitext(fname)[1].lower()
                    if ext == ".exr":
                        try:
                            import OpenEXR as _OE, Imath as _Im
                            ef = _OE.InputFile(p)
                            hdrm = ef.header()
                            dw = hdrm["dataWindow"]; dispm = hdrm["displayWindow"]
                            dw_wm = dw.max.x-dw.min.x+1; dw_hm = dw.max.y-dw.min.y+1
                            fw = dispm.max.x-dispm.min.x+1; fh = dispm.max.y-dispm.min.y+1
                            FP=_Im.PixelType(_Im.PixelType.FLOAT)
                            data_m=np.stack([np.frombuffer(ef.channel(c,FP),
                                np.float32).reshape(dw_hm,dw_wm) for c in "RGB"],axis=2)
                            if (dw_wm,dw_hm)==(fw,fh) and dw.min.x==dispm.min.x and dw.min.y==dispm.min.y:
                                arr = data_m
                            else:
                                arr = np.zeros((fh,fw,3),dtype=np.float32)
                                y0m = dw.min.y-dispm.min.y; x0m = dw.min.x-dispm.min.x
                                arr[max(0,y0m):max(0,y0m)+dw_hm, max(0,x0m):max(0,x0m)+dw_wm] = data_m
                            arr=np.maximum(arr,0)
                            lum = arr.max(axis=2)
                            sc = self._adw_auto_exposure_scale(lum) if lum.max()>0 else 1.0
                            g = self._adw_gamma_encode(arr, sc)
                            return (g[:,:,::-1]*255).astype(np.uint8)
                        except Exception: pass
                    img = cv2.imread(p)
                    return img
                A = load_bgr(files[lo_i]); B = load_bgr(files[hi_i])
                if A is None or B is None:
                    self.after(0,lambda: self.log(self.rlog,"Mask: could not load frames","err"))
                    return
                if A.shape[:2] != B.shape[:2]:
                    B = cv2.resize(B,(A.shape[1],A.shape[0]),cv2.INTER_LINEAR)
                # Compute DIS flow
                dis = cv2.DISOpticalFlow_create(cv2.DISOPTICAL_FLOW_PRESET_MEDIUM)
                Ag = cv2.cvtColor(A,cv2.COLOR_BGR2GRAY)
                Bg = cv2.cvtColor(B,cv2.COLOR_BGR2GRAY)
                flow = dis.calc(Ag,Bg,None)
                # Reproduce _motion_mask exactly: same dilation + blur
                motion_lo = float(getattr(self,"rife_motion_thresh_var",
                    type("V",(),{"get":lambda s:8.0})()).get())
                _hi_mult  = float(getattr(self,"rife_motion_hi_var",
                    type("V",(),{"get":lambda s:6.0})()).get())
                _dil_px   = int(getattr(self,"rife_mask_dilation_var",
                    type("V",(),{"get":lambda s:9})()).get())
                _feather  = float(getattr(self,"rife_mask_feather_var",
                    type("V",(),{"get":lambda s:5.0})()).get())
                lo_t = motion_lo; hi_t = max(lo_t * max(1.0,_hi_mult), lo_t+0.1)
                mag  = np.sqrt(flow[...,0]**2 + flow[...,1]**2)
                raw_mask = np.clip((mag - lo_t)/(hi_t - lo_t + 1e-6), 0, 1).astype(np.float32)
                _dil = max(1, _dil_px | 1)
                kernel = cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(_dil,_dil))
                mask_d = cv2.dilate(raw_mask, kernel)
                mask   = cv2.GaussianBlur(mask_d,(0,0),_feather) if _feather > 0 else mask_d
                # Visualise in BGR: green=blended(mask≈0), red=original kept(mask≈1)
                h,w = mask.shape
                vis = np.zeros((h,w,3),dtype=np.uint8)
                vis[...,1] = ((1-mask)*200).astype(np.uint8)  # green = blended (low mask)
                vis[...,2] = (mask*200).astype(np.uint8)       # red   = original kept (high mask)
                # Blend with source for context
                overlay = cv2.addWeighted(A,0.45,vis,0.55,0)
                img_pil = Image.fromarray(cv2.cvtColor(overlay,cv2.COLOR_BGR2RGB))
                self._rife_wipe_orig_base = img_pil
                self._rife_wipe_riff_base = img_pil
                self._rife_mode = "preview"
                self.after(0,self._rife_display)
                self.after(0,lambda: self.log(self.rlog,
                    f"Motion mask: {motion_lo}px threshold — "
                    "green=blended, red=original","dim"))
            except Exception as ex:
                self.after(0,lambda e=str(ex): self.log(
                    self.rlog,f"Mask preview error: {e}","err"))
        threading.Thread(target=go,daemon=True).start()

    def _rife_encode_mov(self, riffled_dir):
        """Encode Riffled EXR sequence to ProRes MOV."""
        import glob, re as _re, subprocess as _sp, threading as _th
        exrs = sorted(glob.glob(os.path.join(riffled_dir, "*.exr")))
        if not exrs: return
        first = os.path.basename(exrs[0])
        m = _re.match(r'^(.*?)(\d+)(\.exr)$', first, _re.I)
        if not m: return
        prefix, num, ext = m.groups()
        pattern = os.path.join(riffled_dir,
            prefix + "%0" + str(len(num)) + "d" + ext)
        out_mov = os.path.join(os.path.dirname(riffled_dir),
            os.path.basename(riffled_dir) + ".mov")
        fps = getattr(self, "rife_fps_var", None)
        fps_val = fps.get() if fps else "24"
        cmd = ["ffmpeg", "-y", "-framerate", str(fps_val),
              "-start_number", str(int(num)), "-i", pattern,
              "-vf", "format=gbrpf32le", "-c:v", "prores_ks",
              "-profile:v", "4", out_mov]
        self.log(self.rlog, "Encoding Riffled to MOV…", "hi")
        def _enc():
            r = self.runcmd(cmd, self.rlog)
            if r == 0:
                self.log(self.rlog, f"MOV ready: {os.path.basename(out_mov)}", "ok")
            else:
                self.log(self.rlog, "ffmpeg encode failed.", "err")
        _th.Thread(target=_enc, daemon=True).start()

    def _rife_cancel_run(self):
        """Cancel the running RIFE sequence render."""
        from tkinter import messagebox as _mb
        if not _mb.askyesno("Cancel Render",
                "Cancel the RIFE render?\n\n"
                "Frames rendered so far will be kept in RIFE/.",
                icon="warning"):
            return
        self._rife_cancel = True
        proc = getattr(self, "_rife_proc", None)
        if proc and proc.poll() is None:
            try: proc.terminate(); proc.wait(timeout=3)
            except Exception:
                try: proc.kill()
                except Exception: pass
        self._rife_proc = None
        self.log(self.rlog, "Render cancelled by user.", "err")
        self.after(0, lambda: self.progress(-1))
        self.after(0, lambda: self.setstatus("Cancelled", RB))
        self.after(0, lambda: self.rb2.configure(
            text="RUN ADW-BLUR", bg="#2A0A0A", fg="#CC4444",
            command=self._rrun, state="normal"))

    def _rrun(self, cache_only=False):
        """cache_only=True (used by the Cache RIFE button): just
        generates the interpolated frames -- skips Auto Retime, MOV
        encoding, opening the output folder, and chaining to the next
        module. Those are 'finished, deliverable output' steps; this
        mode is specifically for pre-computing the RIFE cache on its
        own, separate from actually finishing a run."""
        if not self.rife_folder: return
        # A run clears/rewrites the output folder — stop playback and
        # invalidate its RAM cache so the next play rebuilds from the
        # fresh output rather than showing stale frames.
        if hasattr(self,"_rife_play_stop"):
            self._rife_play_stop(quiet=True)
            self._rife_play_cache = None
        # ── Read ALL Tkinter values on main thread before spawning ──
        em = {"2x — Smooth": 1, "4x — Very smooth": 2, "8x — Maximum": 3}
        _speedup_str = getattr(self,"rife_speedup_var",
            type("V",(),{"get":lambda s:"1x"})()).get()
        _speedup = {"1x":1,"2x":2,"3x":3,"4x":4}.get(_speedup_str, 1)  # 1 = off (every frame kept)
        # Smoothing always controls RIFE density now, independent of
        # Speedup -- combining a higher Smoothing density with a
        # higher Speedup factor gives the wider blend window more
        # in-between frames to draw from, reducing ghosting versus
        # forcing minimal density regardless of the chosen factor.
        _exp     = em.get(self.rmult.get(), 1)
        _scale   = getattr(self,"rife_scale_var",
            type("V",(),{"get":lambda s:"full"})()).get()
        _do_mov  = bool(getattr(self,"rife_out_mov_var",None) and
                        self.rife_out_mov_var.get())
        _do_ret  = (_speedup > 1) or bool(getattr(self,"rife_retime_var",None) and
                        self.rife_retime_var.get())
        _folder  = self.rife_folder
        _venv    = os.path.expanduser("~/RifeApp/venv/bin/python3")
        _script  = self._rife_inference_script()
        _extra   = self._rife_extra_flags()  # probes script — do on main thread
        _upalg   = getattr(self,"rife_upscale_var",
            type("V",(),{"get":lambda s:"Unsharp"})()).get()
        _flowq   = getattr(self,"rife_flow_var",
            type("V",(),{"get":lambda s:"Quality"})()).get()
        _upalg   = getattr(self,"rife_upscale_var",
            type("V",(),{"get":lambda s:"Unsharp"})()).get()
        _flowq   = getattr(self,"rife_flow_var",
            type("V",(),{"get":lambda s:"Quality"})()).get()

        self._rife_cancel = False
        self._rife_proc   = None
        self._rife_vram_warned = False
        self._adw_run_active = True   # set BEFORE thread starts
        if not cache_only:
            self.rb2.configure(
                text="CANCEL RENDER", state="normal",
                bg="#2A0A0A", fg="#FF4444",
                command=self._rife_cancel_run)
        self.setstatus("Processing…", R)

        def go():
            # Use pre-read values — no Tkinter calls from this thread
            p          = _folder
            exp        = _exp
            venv       = _venv
            script     = _script
            script_dir = os.path.dirname(script)
            out = self._adw_module_output_dir(p, "ADW-Blur_Rife")
            if not self._adw_safe_clear_output_dir(out, p, self.rlog):
                self.after(0, lambda: self.setstatus("Error", RB))
                if not cache_only:
                    self.after(0, lambda: self.rb2.configure(
                        text="RUN ADW-BLUR",bg="#2A0A0A",fg="#CC4444",
                        command=self._rrun,state="normal"))
                return
            self.after(0, lambda: self.log(self.rlog, "Created: " + out, "ok"))
            if not os.path.exists(venv):
                self.after(0, lambda: self.log(self.rlog, "venv not found — run RIFE Install in Setup tab.", "err"))
                self.after(0, lambda: self.setstatus("Error", RB))
                if not cache_only:
                    self.after(0, lambda: self.rb2.configure(
                        text="RUN ADW-BLUR",bg="#2A0A0A",fg="#CC4444",
                        command=self._rrun,state="normal"))
                return

            exts   = {".exr",".png",".tif",".tiff",".jpg",".jpeg"}
            frames = sorted([f for f in os.listdir(p)
                             if os.path.splitext(f)[1].lower() in exts
                             and not f.startswith("__")])
            total  = len(frames)
            if total < 2:
                self.after(0, lambda: self.log(self.rlog, "Need at least 2 frames.", "err"))
                if not cache_only:
                    self.after(0, lambda: self.rb2.configure(
                        text="RUN ADW-BLUR",bg="#2A0A0A",fg="#CC4444",
                        command=self._rrun,state="normal"))
                return
            _input_is_exr = os.path.splitext(frames[0])[1].lower() == ".exr"
            _full_count = len(frames)  # total before any range slice
            _range_only = bool(getattr(self,"rife_range_only_var",None) and
                               self.rife_range_only_var.get())
            if _range_only and hasattr(self,"_rife_range_bar"):
                _rv0,_rv1 = self._rife_range_bar.get_range()
                _rv0=max(0,_rv0); _rv1=min(len(frames),_rv1)
                if _rv1>_rv0+1:
                    frames=frames[_rv0:_rv1]; total=len(frames)
                    self.after(0,lambda a=_rv0+1,b=_rv1: self.log(self.rlog,
                        f"⚠ Range-slider only: rendering frames {a}–{b} of {_full_count}","err"))

            self.after(0, lambda n=total: self.log(self.rlog,
                f"Processing {n} frames ({n-1} pairs)…", "hi"))
            self.after(0, lambda: self.progress(0.0, "RIFE  0 / " + str(total-1) + " pairs"))
            if cache_only and hasattr(self,"_cache_rife_btn"):
                self.after(0, lambda: self._cache_rife_btn.configure(progress=0.01))

            # Write each pair of consecutive frames to RIFE/
            # Script API: --img file1 file2 --exp N  → outputs to {script_dir}/output/
            tmp_in = os.path.expanduser("~/RifeApp/_rife_pair_tmp")
            rife_out = os.path.join(script_dir, "output")
            os.makedirs(tmp_in, exist_ok=True)
            os.makedirs(rife_out, exist_ok=True)

            out_idx = 1
            errors  = 0
            # Derive output file base name from input sequence
            import re as _re
            _base = _re.sub(r"[._]?\d+$", "",
                os.path.splitext(frames[0])[0]) if frames else "frame"
            _base = _base.rstrip("._- ") or "frame"
            _out_prefix = _base + "_RIFE"

            # Convert EXR → PNG for RIFE (it can't read EXR in two-file mode)
            _norm_scale_run = [None]  # set from first frame, reused for whole sequence

            def _png_to_exr(png_path, exr_path):
                """Reconstruct linear float EXR from gamma-encoded PNG."""
                import numpy as _np2; from PIL import Image as _PI2
                _scale = _norm_scale_run[0]
                try:
                    _img = _PI2.open(png_path).convert("RGB")
                    _w, _h = _img.size
                    _g = _np2.array(_img, dtype=_np2.float32) / 255.0
                    if _scale is None:
                        # Derive scale from the image itself (per-frame
                        # fallback) -- decode at scale=1.0 first just to
                        # get a luminance estimate to feed the auto-
                        # exposure heuristic, then decode for real below
                        # with whatever scale that heuristic picks.
                        _lin_chk = self._adw_gamma_decode(_g, 1.0)
                        _lum_chk = _lin_chk.max(axis=2)
                        _scale = self._adw_auto_exposure_scale(_lum_chk) if _lum_chk.any() else 1.0
                        _norm_scale_run[0] = _scale  # remember for subsequent frames
                    _lin = self._adw_gamma_decode(_g, _scale)
                    # ffmpeg's EXR encoder rejects packed rgbf32le for this
                    # filter graph ("Impossible to convert between the
                    # formats supported by the filter") -- confirmed this
                    # silently fails every time, with the existing
                    # except-and-fall-back-to-PNG below masking it
                    # completely. gbrpf32le (planar, EXR-native channel
                    # order) is what actually works.
                    _planar = _np2.stack(
                        [_lin[:,:,1], _lin[:,:,2], _lin[:,:,0]], axis=0)
                    _raw = _np2.ascontiguousarray(_planar,
                        dtype=_np2.float32).tobytes()
                    _r = subprocess.run(
                        ["ffmpeg","-y","-f","rawvideo","-pix_fmt","gbrpf32le",
                         "-s",f"{_w}x{_h}","-i","pipe:0",
                         "-frames:v","1",exr_path],
                        input=_raw, capture_output=True, timeout=30)
                    return _r.returncode == 0 and os.path.exists(exr_path)
                except Exception as _ex:
                    self.after(0, lambda e=str(_ex)[:60]: self.log(
                        self.rlog, f"EXR save: {e}", "dim"))
                    return False

            # ── PNG cache: mtime-based, write-through ─────────────
            _png_cache_dir = os.path.join(self._adw_output_root(p), "_png_cache")
            self._adw_invalidate_stale_png_cache(_png_cache_dir)
            os.makedirs(_png_cache_dir, exist_ok=True)
            _cache_info_path = os.path.join(_png_cache_dir, "_cache_info.json")
            _cache_norm = [None]
            try:
                import json as _cj
                _ci = _cj.loads(open(_cache_info_path).read())
                _cache_norm[0] = _ci.get("norm_scale")
            except Exception: pass

            def _cache_png_path(src_path):
                return os.path.join(_png_cache_dir,
                    os.path.splitext(os.path.basename(src_path))[0]+".png")

            _cache_hits = [0]

            def _cache_valid(src_path):
                """True if a valid cached PNG exists for this source file."""
                cp = _cache_png_path(src_path)
                return os.path.exists(cp) and os.path.getsize(cp) > 100

            def _cache_hit_log():
                if _cache_hits[0] == 0:
                    self.after(0, lambda: self.log(self.rlog,
                        "PNG cache hit — skipping EXR conversion", "dim"))
                _cache_hits[0] += 1

            def _save_to_cache(converted_png, src_path):
                """Copy a freshly converted PNG into the cache folder."""
                try:
                    cp = _cache_png_path(src_path)
                    if os.path.abspath(converted_png) != os.path.abspath(cp):
                        shutil.copy2(converted_png, cp)
                    # Persist norm_scale so future runs skip conversion
                    if _norm_scale_run[0] is not None:
                        import json as _cj2
                        with open(_cache_info_path, "w") as _cf:
                            _cj2.dump({"norm_scale": _norm_scale_run[0],
                                "cache_version": self._ADW_PNG_CACHE_VERSION}, _cf)
                except Exception: pass

            def to_png_full(path, dst):
                """EXR→PNG: use mtime cache if fresh, else convert and cache."""
                import numpy as _np
                from PIL import Image as _PIf
                # ── Cache hit ──────────────────────────────────────
                if _cache_valid(path):
                    cp = _cache_png_path(path)
                    if os.path.abspath(cp) != os.path.abspath(dst):
                        shutil.copy2(cp, dst)
                    if _norm_scale_run[0] is None and _cache_norm[0] is not None:
                        _norm_scale_run[0] = _cache_norm[0]
                    _cache_hit_log()
                    return True
                # ── Not EXR → plain copy ───────────────────────────
                if os.path.splitext(path)[1].lower() != ".exr":
                    if os.path.abspath(path) != os.path.abspath(dst):
                        shutil.copy(path, dst)
                    return True
                # ── Primary: OpenEXR direct (most reliable -- doesn't
                # depend on ffmpeg's EXR decoder/pixel-format support,
                # which varies by build and can silently fail) ───────
                try:
                    import OpenEXR as _OEp, Imath as _Imp
                    ef = _OEp.InputFile(path)
                    hdrp = ef.header()
                    dw = hdrp["dataWindow"]; dispp = hdrp["displayWindow"]
                    dw_wp = dw.max.x-dw.min.x+1; dw_hp = dw.max.y-dw.min.y+1
                    _fw = dispp.max.x-dispp.min.x+1; _fh = dispp.max.y-dispp.min.y+1
                    FPp = _Imp.PixelType(_Imp.PixelType.FLOAT)
                    data_p = _np.stack([_np.frombuffer(
                        ef.channel(c,FPp),_np.float32).reshape(dw_hp,dw_wp)
                        for c in "RGB"], axis=2)
                    if (dw_wp,dw_hp)==(_fw,_fh) and dw.min.x==dispp.min.x and dw.min.y==dispp.min.y:
                        _arr = data_p
                    else:
                        # dataWindow offset/cropped from displayWindow (seen
                        # from some AI video tools) -- this is the primary
                        # converter for every frame of every full run, so a
                        # silent mismatch here corrupts the whole sequence,
                        # not just one frame.
                        _arr = _np.zeros((_fh,_fw,3),dtype=_np.float32)
                        y0p = dw.min.y-dispp.min.y; x0p = dw.min.x-dispp.min.x
                        _arr[max(0,y0p):max(0,y0p)+dw_hp, max(0,x0p):max(0,x0p)+dw_wp] = data_p
                    _arr = _np.maximum(_arr,0)
                    if _norm_scale_run[0] is None:
                        _norm_scale_run[0] = _cache_norm[0] if _cache_norm[0] is not None else None
                    if _norm_scale_run[0] is None:
                        _lum = _arr.max(axis=2)
                        _norm_scale_run[0] = self._adw_auto_exposure_scale(_lum)
                        self.after(0, lambda s=_norm_scale_run[0]: self.log(
                            self.rlog, f"Auto-exposure scale: {s:.4f}", "dim"))
                    _gamma  = self._adw_gamma_encode(_arr, _norm_scale_run[0])
                    _PIf.fromarray((_gamma*255).astype(_np.uint8)).save(dst)
                    if os.path.exists(dst) and os.path.getsize(dst)>100:
                        _save_to_cache(dst, path)
                        return True
                except ImportError: pass
                except Exception: pass
                # ── Secondary: ffmpeg rawvideo float pipe ─────────────
                try:
                    import json as _js
                    pr = subprocess.run(
                        ["ffprobe","-v","quiet","-print_format","json",
                         "-show_streams",path],
                        capture_output=True, text=True, timeout=10)
                    _vs = next(s for s in _js.loads(pr.stdout)["streams"]
                               if s["codec_type"]=="video")
                    _fw,_fh = int(_vs["width"]),int(_vs["height"])
                    _raw = subprocess.run(
                        ["ffmpeg","-y","-i",path,
                         "-pix_fmt","rgbaf32le","-f","rawvideo","pipe:1"],
                        capture_output=True, timeout=90)
                    _arr = _np.frombuffer(_raw.stdout,_np.float32
                        ).reshape(_fh,_fw,4)[:,:,:3]
                    _arr = _np.maximum(_arr,0)
                    if _norm_scale_run[0] is None:
                        _norm_scale_run[0] = _cache_norm[0] if _cache_norm[0] is not None else None
                    if _norm_scale_run[0] is None:
                        _lum = _arr.max(axis=2)
                        _norm_scale_run[0] = self._adw_auto_exposure_scale(_lum)
                        self.after(0, lambda s=_norm_scale_run[0]: self.log(
                            self.rlog, f"Auto-exposure scale: {s:.4f}", "dim"))
                    _gamma  = self._adw_gamma_encode(_arr, _norm_scale_run[0])
                    _PIf.fromarray((_gamma*255).astype(_np.uint8)).save(dst)
                    if os.path.exists(dst) and os.path.getsize(dst)>100:
                        _save_to_cache(dst, path)
                        return True
                except Exception: pass
                # Last resort: ffmpeg's own reinhard tonemap. NOTE this
                # produces a PNG via a completely different tonemapping
                # curve than our gamma+scale method, so the scale
                # recorded here is just a marker, not a reconstruction
                # value that matches it -- _png_to_exr reconstructing a
                # frame that hit this path won't exactly match the
                # original. This only triggers if EVERY other read
                # method (the OpenEXR library AND two separate ffmpeg
                # approaches) has already failed on this specific file.
                for _args in [
                    ["ffmpeg","-y","-i",path,
                     "-vf","tonemap=reinhard:desat=0,format=rgb24",dst],
                    ["ffmpeg","-y","-i",path,"-pix_fmt","rgb24",dst],
                ]:
                    try:
                        r = subprocess.run(_args,capture_output=True,timeout=90)
                        if r.returncode==0 and os.path.exists(dst) \
                                and os.path.getsize(dst)>100:
                            if _norm_scale_run[0] is None: _norm_scale_run[0] = 1.0
                            _save_to_cache(dst, path)
                            return True
                    except Exception: pass
                return False

            # Pre-convert the WHOLE sequence to the PNG cache BEFORE any
            # RIFE processing starts. This is the same fix that worked
            # before: make sure RIFE's actual input is always a cached
            # PNG, never an EXR converted in the moment, interleaved
            # with the interpolation itself. Without this, the per-pair
            # loop below only guarantees the scale is consistent "as
            # far as the write-through cache happens to have propagated
            # by the time each pair is reached" -- this locks it in
            # from frame 0 of the FULL sequence first, with nothing
            # left to vary frame-to-frame once interpolation begins.
            if _input_is_exr:
                self.after(0, lambda n=total: self.log(self.rlog,
                    f"Pre-converting {n} frames to the PNG cache "
                    f"before interpolation…", "hi"))
                for _pf_idx, _pf in enumerate(frames):
                    if self._rife_cancel: break
                    _pf_src = os.path.join(p, _pf)
                    to_png_full(_pf_src, _cache_png_path(_pf_src))
                    self.after(0, lambda i=_pf_idx, n=total: self.progress(
                        (i+1)/n*0.15, f"Pre-converting  {i+1} / {n}"))
                self.after(0, lambda s=_norm_scale_run[0]: self.log(
                    self.rlog,
                    f"PNG cache ready, exposure scale {s:.4f} locked in "
                    f"— running interpolation entirely on PNGs.", "ok"))

            # Expected total RIFE output frame count, for the progress
            # label below -- 1 (the first original frame) plus each
            # of the (total-1) pairs contributing 2**exp new frames.
            # Speedup can drop some pairs' frames entirely, so this is
            # the baseline expectation, not a guarantee in every case.
            _expected_rife_frames = 1 + (total - 1) * (2 ** exp)

            for i in range(total - 1):
                if self._rife_cancel: break
                f1_src = os.path.join(p, frames[i])
                f2_src = os.path.join(p, frames[i+1])
                _pct_base = i / (total - 1)
                _pct_step = 1.0 / (total - 1)
                self.after(0, lambda i=i,t=total,f=frames[i],p=_pct_base,
                        oi=out_idx,n=_expected_rife_frames: (
                    self.log(self.rlog, f"Pair {i+1}/{t-1}: {f}", "dim"),
                    self.progress(p, f"Generating RIFE  {oi} / {n}")))

                f1 = os.path.join(tmp_in, "a.png")
                f2 = os.path.join(tmp_in, "b.png")
                # Clear stale files before conversion
                for _stale in [f1, f2]:
                    try: os.remove(_stale)
                    except: pass
                self.after(0,lambda p=(i+0.3)/(total-1):
                    getattr(self,"_push_step",lambda*a:None)(0,p))
                if not to_png_full(f1_src, f1) or not to_png_full(f2_src, f2):
                    self.after(0, lambda i=i: self.log(self.rlog,
                        f"EXR→PNG failed for pair {i+1}", "err"))
                    errors += 1; continue
                # Verify files are valid before proceeding
                if i == total-2:
                    self.after(0,lambda:getattr(self,"_push_step",lambda*a:None)(0,1.0,True))
                if not os.path.exists(f1) or os.path.getsize(f1) < 100 \
                        or not os.path.exists(f2) or os.path.getsize(f2) < 100:
                    self.after(0, lambda i=i: self.log(self.rlog,
                        f"EXR→PNG produced empty file for pair {i+1}", "err"))
                    errors += 1; continue

                # Apply scale + pad to multiple of 32
                from PIL import Image
                img1 = Image.open(f1).convert("RGB")

                # If both dimensions are exact multiples of 32 the cache entry
                # is almost certainly a previously-padded frame.  Wipe it and
                # re-convert from the source EXR so we get the true resolution.
                if img1.width % 32 == 0 and img1.height % 32 == 0:
                    _cp = os.path.join(self._adw_output_root(p), "_png_cache",
                                       os.path.splitext(os.path.basename(f1_src))[0] + ".png")
                    for _bad in [f1, _cp]:
                        try: os.remove(_bad)
                        except OSError: pass
                    to_png_full(f1_src, f1)      # fresh conversion
                    img1 = Image.open(f1).convert("RGB")

                _orig_img1 = img1.copy()
                ow, oh = img1.size               # true pre-padding dimensions
                if i == 0:
                    self.after(0, lambda w=ow, h=oh: self.log(
                        self.rlog, f"RIFE crop target: {w}×{h}", "dim"))
                # Resize to model target resolution
                if _scale == "full" or "x" not in str(_scale):
                    sw, sh = ow, oh
                else:
                    _tw2, _th2 = map(int, str(_scale).split("x"))
                    _sf2 = min(_tw2/ow, _th2/oh)
                    # Model Res is a downscale cap, never a forced
                    # upscale -- see matching note in the preview path.
                    _sf2 = min(1.0, _sf2)
                    sw = max(32, int(ow * _sf2))
                    sh = max(32, int(oh * _sf2))
                if sw != ow or sh != oh:  # resize if model res differs from original
                    img1 = img1.resize((sw, sh), Image.LANCZOS)
                    img1.save(f1)
                    img2s = Image.open(f2).convert("RGB").resize((sw,sh),Image.LANCZOS)
                    img2s.save(f2)

                pw2 = ((sw+31)//32)*32; ph2 = ((sh+31)//32)*32
                if pw2 != sw or ph2 != sh:
                    import numpy as _np2
                    # Edge-pad (repeat border pixels) so RIFE sees no hard black edge.
                    # Zero-padding causes the neural network to bleed dark values
                    # back into the content area near the boundary.
                    _a1 = _np2.array(img1)
                    _a1p = _np2.pad(_a1, ((0,ph2-sh),(0,pw2-sw),(0,0)), mode='edge')
                    Image.fromarray(_a1p).save(f1)
                    _a2 = _np2.array(Image.open(f2).convert("RGB"))
                    _a2p = _np2.pad(_a2, ((0,ph2-sh),(0,pw2-sw),(0,0)), mode='edge')
                    Image.fromarray(_a2p).save(f2)

                # Clear previous output
                for f in os.listdir(rife_out):
                    try: os.remove(os.path.join(rife_out, f))
                    except: pass

                _stepped_ok = False
                if exp > 1 and getattr(self,"rife_stepped_var",None) \
                        and self.rife_stepped_var.get():
                    if i == 0:
                        self.after(0, lambda e=exp: self.log(self.rlog,
                            f"Stepped generation: running RIFE at exp=1 "
                            f"repeatedly instead of exp={e} directly, to "
                            f"keep peak VRAM per call minimal", "dim"))
                    _stepped_ok = self._rife_run_pair_stepped(
                        venv, script, script_dir, f1, f2, exp, _extra,
                        tmp_in, rife_out)
                    if not _stepped_ok and i == 0:
                        self.after(0, lambda: self.log(self.rlog,
                            "Stepped generation failed — falling back "
                            "to a single direct call for this pair", "dim"))

                if _stepped_ok:
                    r_code = 0
                else:
                    cmd = (f'cd "{script_dir}" && '
                           f'"{venv}" "{script}" --img "{f1}" "{f2}" --exp {exp}'
                           + _extra
                           )
                    if self._rife_cancel: break
                    # stderr goes to a file, not DEVNULL: a PyTorch
                    # out-of-memory (or any crash) used to vanish
                    # entirely, leaving "Pair failed (rc=1)" with no
                    # explanation. A file sidesteps pipe deadlock while
                    # keeping the message.
                    _errf = os.path.join(tmp_in, "rife_stderr.log")
                    with open(_errf, "w") as _efh:
                        self._rife_proc = subprocess.Popen(
                            cmd, shell=True,
                            stdout=subprocess.DEVNULL,
                            stderr=_efh)
                        self._rife_proc.wait()
                    r_code = self._rife_proc.returncode
                    self._rife_proc = None
                    if r_code != 0:
                        try:
                            with open(_errf) as _efh:
                                _etail = _efh.read()[-400:].strip()
                            if _etail:
                                self.after(0, lambda t=_etail: self.log(
                                    self.rlog, "RIFE stderr: " + t, "err"))
                        except Exception:
                            pass
                self.after(0,lambda p=(i+0.7)/(total-1),d=(i==total-2):
                    getattr(self,"_push_step",lambda*a:None)(1,p,d))
                if self._rife_cancel: break

                if r_code == 0:
                    self.after(0, lambda i=i,t=total,p=_pct_base,s=_pct_step: (
                        self.progress(p+s*0.8,f"Saving  {i+1} / {t-1}"),
                        getattr(self,"_push_step",lambda*a:None)(2,(i+0.9)/(t-1),(i==t-2))))
                    # Write: original frame + interpolated frame(s)
                    if i == 0:  # write first original only at start
                        dst = os.path.join(out, f"{_out_prefix}.{out_idx:05d}.png")
                        _img1 = _orig_img1  # already at (ow, oh)
                        _img1.save(dst)
                        if _input_is_exr:
                            if _png_to_exr(dst, dst.replace(".png",".exr")):
                                try: os.remove(dst)
                                except OSError: pass
                            # if _png_to_exr failed, PNG stays — better than no frame
                        out_idx += 1

                    def _save_frame(img, dst, target_w, target_h):
                        """Crop if padded, upscale using selected algorithm."""
                        import cv2 as _cv, numpy as _np
                        if img.width > target_w or img.height > target_h:
                            img = img.crop((0, 0, target_w, target_h))
                        if img.size != (target_w, target_h):
                            _bgr = _cv.cvtColor(_np.array(img), _cv.COLOR_RGB2BGR)
                            if _upalg == "ESRGAN":
                                _bgr = self._rife_upscale(_bgr, target_w, target_h)
                            elif _upalg == "Unsharp":
                                _bgr = _cv.resize(_bgr,(target_w,target_h),
                                    interpolation=_cv.INTER_LANCZOS4)
                                _blur = _cv.GaussianBlur(_bgr,(0,0),1.5)
                                _bgr = _cv.addWeighted(_bgr,1.4,_blur,-0.4,0)
                            else:  # Gaussian — smooth, no ringing
                                _bgr = _cv.resize(_bgr,(target_w,target_h),
                                    interpolation=_cv.INTER_CUBIC)
                                _bgr = _cv.GaussianBlur(_bgr,(0,0),0.6)
                            img = Image.fromarray(_cv.cvtColor(_bgr,_cv.COLOR_BGR2RGB))
                        img.save(dst)

                    # The ADW script writes a run report; if it had to
                    # drop internal scale to survive memory pressure,
                    # SAY so -- softer frames with a stated cause beat
                    # softer frames as a mystery.
                    try:
                        import json as _json_ri
                        with open(os.path.join(rife_out,
                                "ADW_RUNINFO.json")) as _rif:
                            _ri = _json_ri.load(_rif)
                        if (_ri.get("oom_retries", 0)
                                or _ri.get("scale_used", 1.0)
                                   < _ri.get("scale_requested", 1.0)) \
                                and not getattr(self,
                                    "_rife_vram_warned", False):
                            self._rife_vram_warned = True
                            self.after(0, lambda s=_ri.get("scale_used"),
                                       i=i: self.log(self.rlog,
                                f"VRAM pressure: pair {i+1} fell back to "
                                f"internal scale {s} after out-of-memory. "
                                f"Frames from here may look softer. Lower "
                                f"Model Res or Smoothing, or close other "
                                f"GPU-heavy apps.", "err"))
                    except Exception:
                        pass

                    from PIL import ImageFile as _PIF
                    _PIF.LOAD_TRUNCATED_IMAGES = True
                    interp = sorted([f for f in os.listdir(rife_out)
                                     if os.path.splitext(f)[1].lower() in {".png",".jpg"}])
                    interp = interp[1:-1] if len(interp) > 2 else interp
                    for fname in interp:
                        dst = os.path.join(out, f"{_out_prefix}.{out_idx:05d}.png")
                        _fpath = os.path.join(rife_out, fname)
                        try:
                            _img = Image.open(_fpath).convert("RGB")
                        except Exception:
                            import time as _t2; _t2.sleep(0.2)
                            try:
                                _img = Image.open(_fpath).convert("RGB")
                            except Exception:
                                self.after(0, lambda fn=fname: self.log(
                                    self.rlog, f"Skipped truncated frame: {fn}", "dim"))
                                out_idx += 1; continue
                        # Remove RIFE padding proportionally — handles cases where
                        # RIFE outputs at a different scale than sw×sh.
                        _rw, _rh = _img.size
                        if i == 0 and fname == interp[0] \
                                and (_rw, _rh) not in ((pw2, ph2), (sw, sh)):
                            self.after(0, lambda rw=_rw, rh=_rh: self.log(
                                self.rlog,
                                f"WARNING: RIFE returned {rw}\u00d7{rh} for a "
                                f"{pw2}\u00d7{ph2} input \u2014 the inference "
                                f"script downscaled internally. Output will "
                                f"look soft. This should not happen with the "
                                f"ADW script; re-run Setup if it persists.",
                                "err"))
                        _crop_w = min(_rw, round(_rw * sw / pw2))
                        _crop_h = min(_rh, round(_rh * sh / ph2))
                        if _rw != _crop_w or _rh != _crop_h:
                            _img = _img.crop((0, 0, _crop_w, _crop_h))
                        _save_frame(_img, dst, ow, oh)
                        if _input_is_exr:
                            if _png_to_exr(dst, dst.replace(".png", ".exr")):
                                try: os.remove(dst)
                                except OSError: pass
                        out_idx += 1

                    # Write second original — use source file, not scaled temp
                    dst = os.path.join(out, f"{_out_prefix}.{out_idx:05d}.png")
                    _save_frame(Image.open(f2).convert("RGB"), dst, ow, oh)
                    if _input_is_exr:
                        if _png_to_exr(dst, dst.replace(".png", ".exr")):
                            os.remove(dst)
                    out_idx += 1
                else:
                    errors += 1
                    self.after(0, lambda i=i,rc=r_code,t=total: self.log(self.rlog,
                        f"Pair {i+1}/{t-1} failed (rc={rc})", "err"))

                self.after(0, lambda p=(i+1)/(total-1), i=i, t=total:
                    self.progress(p, f"Done  {i+1} / {t-1} pairs"))
                if cache_only and hasattr(self,"_cache_rife_btn"):
                    self.after(0, lambda p=(i+1)/(total-1):
                        self._cache_rife_btn.configure(progress=p))

            shutil.rmtree(tmp_in, ignore_errors=True)
            self._adw_run_active = False
            # Point wipe comparison at full ADW; clear mini-preview override
            self._rife_adw_dir = out
            self._rife_full_adw_dir = out        # never overwritten by T-cap clicks
            self._rife_adw_center_override = None
            # Refresh wipe/diff images from full ADW
            self.after(200, self._rife_retime_blend_only)
            n = len([f for f in os.listdir(out)
                     if os.path.splitext(f)[1].lower() in ('.exr','.png')])
            # Record what settings produced these frames -- the check on
            # the cache-reuse side turns "stale cache silently reused
            # after a settings change" from a documented trap into a
            # detected condition.
            try:
                import json as _json_fp
                with open(os.path.join(out, "_ADW_CACHE_INFO.json"),
                          "w") as _fph:
                    _json_fp.dump(self._rife_settings_fingerprint(), _fph)
            except Exception:
                pass
            self.after(0, lambda n=n: self.log(self.rlog,
                f"ADW folder: {n} frames written", "ok" if n > 1 else "err"))
            if errors == 0 and n > 1:
                self.after(0, lambda n=n: self.log(self.rlog, f"Done — {n} frames in RIFE/", "ok"))
                self._set_preview_phase("", done=True)
                self._set_retime_btn("stale")
            if hasattr(self,"_rife_dual_tl"):
                n_p = max(0,len(getattr(self,"rife_frames",[]))-1)
                self.after(0, lambda n=n_p: self._rife_dual_tl.set_cached_pairs(set(range(n))))
                if cache_only:
                    self.after(0, lambda n=n: self.log(self.rlog,
                        f"Cache RIFE done — {n} interpolated frames cached. "
                        f"Auto Retime, MOV encoding, and folder-opening are "
                        f"skipped in this mode — use Run ADW-Blur for a full, "
                        f"finished run.", "ok"))
                else:
                    if _do_ret and n > 1:
                        # MOV (if requested) is encoded from the retimed
                        # deliverable once the retime finishes.
                        self.after(0, lambda o=out, fc=_full_count, sp=_speedup,
                                   mv=(_do_mov and n > 1):
                            self._rife_auto_retime(o, fc, speedup=sp,
                                                   then_mov=mv))
                    else:
                        if _do_mov and n > 1:
                            self.after(0, lambda: self._rife_encode_mov(out))
                        # No retime: the interpolated frames ARE the
                        # output, and they live in ADW-Blur_Rife. Say so,
                        # or the user hunts for an ADW-Blur folder that
                        # was never written.
                        self.after(0, lambda o=out: self.log(self.rlog,
                            f"Auto Retime is off — the interpolated "
                            f"sequence in {os.path.basename(o)}/ is your "
                            f"output (no ADW-Blur/ folder is written).",
                            "hi"))
                    if _do_ret and n <= 1:
                        self.after(0, lambda: self.log(self.rlog,
                            "Auto Retime skipped — ADW has no frames", "err"))
                self.after(0, lambda: self.progress(1.0, f"RIFE done — {n} frames"))
                self.after(3000, lambda: self.progress(-1))
                self.after(0, lambda: self.progress(1.0, f"RIFE done — {n} frames"))
                self.after(3000, lambda: self.progress(-1))
                self.setstatus("Complete", GR)
                if hasattr(self,"_cache_btns_refresh"):
                    self.after(0, self._cache_btns_refresh)
                if not cache_only:
                    self._reveal(out)
                self.after(600, self._rife_preview_frame)
                if not cache_only:
                    self.after(0, lambda o=out: self._rife_after_run_sendto(o))
            else:
                self.after(0, lambda e=errors: self.log(self.rlog, f"{e} pairs failed — check log.", "err"))
                self.after(0, lambda: self.progress(-1))
                self.setstatus("Error", RB)
            if not cache_only:
                self.after(0, lambda: self.rb2.configure(
                    text="RUN ADW-BLUR", bg="#2A0A0A", fg="#CC4444",
                    command=self._rrun, state="normal"))

        def go_safe():
            self._rrun_active = True
            try:
                go()
            except Exception as _ex:
                import traceback
                _tb = traceback.format_exc()
                self.after(0, lambda e=str(_ex), tb=_tb: (
                    self.log(self.rlog, f"RIFE error: {e}", "err"),
                    self.log(self.rlog, tb[-400:], "err"),
                    self.progress(-1),
                    self.setstatus("Error", RB)))
                if not cache_only:
                    self.after(0, lambda: self.rb2.configure(
                        text="RUN ADW-BLUR", bg="#2A0A0A",
                        fg="#CC4444", command=self._rrun, state="normal"))
            finally:
                self._rrun_active = False
                if hasattr(self,"_cache_btns_refresh"):
                    self.after(0, self._cache_btns_refresh)
        threading.Thread(target=go_safe, daemon=True).start()

    # Bump this any time the EXR<->PNG exposure/conversion logic
    # changes in a way that affects pixel values. A stale cache built
    # under older logic looking byte-identical to a fresh one (right
    # file, right size) is exactly how a fixed bug can keep reappearing
    # indefinitely: the fix only ever applies to conversions that
    # haven't already happened, and once a folder has a cache, nothing
    # before this existed to ever tell it that cache no longer matches
    # what the current code would produce.
    _ADW_PNG_CACHE_VERSION = 2

    def _adw_invalidate_stale_png_cache(self, cache_dir):
        """If cache_dir's _cache_info.json doesn't carry the current
        _ADW_PNG_CACHE_VERSION (including if the file or key is simply
        missing, e.g. from before versioning existed at all), wipe the
        whole cache directory so everything in it gets rebuilt fresh
        under current logic. Call this before trusting anything in the
        cache, on both the load-time build and the run-time pre-pass."""
        import json, shutil
        info_path = os.path.join(cache_dir, "_cache_info.json")
        try:
            with open(info_path) as f:
                info = json.load(f)
            if info.get("cache_version") == self._ADW_PNG_CACHE_VERSION:
                return  # current, nothing to do
        except Exception:
            pass  # missing/unreadable info -- treat as stale below
        if os.path.isdir(cache_dir):
            shutil.rmtree(cache_dir, ignore_errors=True)

    def _adw_auto_exposure_scale(self, lum_values):
        """Scale for converting linear EXR values into the [0,1] range
        before gamma-encoding to 8-bit PNG (and the matching inverse
        to reconstruct EXR from that PNG later).

        Never compresses below scale=1.0 -- i.e. never divides values
        down before they're gamma-encoded. AI-generated footage
        (Kling, etc.) converted to EXR is typically already sitting in
        a sane, roughly display-referred range rather than true
        unbounded HDR, so gamma encoding alone already produces a
        correctly-exposed result; any additional downward rescaling
        doesn't brighten anything that needed it; it just pushes
        legitimate upper-range content past 1.0, where it hard-clips
        and is permanently lost.

        Only scales UP -- and only just enough to bring the 99th
        percentile to 1.0 -- when content genuinely exceeds the
        display range (true HDR highlights: practical lights, bright
        skies that actually go above white). This is deliberately
        conservative versus an earlier version that also tried to
        rescale DOWN to protect a dim subject behind a bright region
        (a real failure mode, but evidently a rarer one in practice
        than the regression it caused): verified directly on a real,
        reported-as-too-dark file -- the old formula computed scale
        0.141 from this single frame and hard-clipped 17.7% of all
        its pixels to an identical ceiling value; this one computes
        1.0, with zero clipping, and renders identically well."""
        import numpy as np
        lum = np.asarray(lum_values)
        lum_pos = lum[lum > 0]
        if lum_pos.size == 0:
            return 1.0
        p99 = float(np.percentile(lum_pos, 99))
        return max(1.0, p99)

    def _adw_source_is_encoded(self):
        """True if the active source should be treated as already
        display-encoded rather than scene-linear -- the default for
        EXR sequences exported from AI video-generation tools (Kling,
        Seedance, etc).

        Confirmed by direct A/B test against two real files from two
        different AI tools: rendering the raw stored values with NO
        gamma curve at all produced a correctly contrasted, normal-
        looking image; applying the standard linear-to-display gamma
        curve (which every part of this pipeline previously did
        unconditionally) produced exactly a washed-out, low-contrast,
        too-bright result. These tools appear to write display-ready
        float values into the EXR container without a genuine
        linearisation step, despite using a container format
        conventionally reserved for scene-linear data.

        False for genuine scene-linear sources (traditional VFX
        renders from Nuke, Maya, Houdini etc), where the standard
        gamma encode is correct and necessary."""
        v = getattr(self, "adw_source_encoded_var", None)
        return bool(v.get()) if v is not None else True

    def _adw_gamma_encode(self, arr, scale=1.0, is_encoded=None):
        """The single, shared first conversion of a raw source EXR's
        float values toward a display-ready [0,1] array, ready to be
        written as an 8-bit PNG. EVERY site in this codebase that
        reads a source EXR file and prepares it for PNG (preview,
        cache builder, main run, motion mask, etc) must route through
        this function rather than reimplementing the curve locally --
        that duplication, with each copy drifting independently
        whenever one got fixed and the others didn't, is what made
        this specific bug so persistent across this session.

        For an 'already encoded' source (see _adw_source_is_encoded),
        no gamma CURVE is applied -- the values are already correct
        tonally, so reshaping them would be wrong. The scale is still
        applied, though: without it, any single frame with even a
        brief excursion above 1.0 (a specular highlight, a lens
        flare, a momentary bright reflection) would hard-clip with no
        compensation while an otherwise-identical neighbouring frame
        that stayed under 1.0 wouldn't, producing a visible frame-to-
        frame brightness/contrast inconsistency rather than a real
        difference in the footage. This is a no-op for any frame that
        doesn't need it, since _adw_auto_exposure_scale never goes
        below 1.0.

        For a genuine scene-linear source, applies the standard
        linear->display gamma curve with the given exposure scale,
        exactly as this pipeline always has.

        is_encoded, if given, overrides the live Source toggle for
        this one call -- needed by anything that must reconstruct
        (decode) a value it encoded earlier using the SAME branch,
        regardless of whether the shared, global toggle has since
        changed (it's an ordinary UI checkbox, not something tied to
        a specific loaded sequence, so nothing stops it changing
        between when a frame was first read and when it's later
        saved). Defaults to the live toggle for every existing caller
        that doesn't pass it, so this is purely additive."""
        import numpy as np
        enc = is_encoded if is_encoded is not None \
            else self._adw_source_is_encoded()
        if enc:
            return np.clip(arr/max(scale, 1e-6), 0, 1)
        return np.power(np.clip(arr/max(scale, 1e-6), 0, 1), 1/2.2)

    def _adw_gamma_decode(self, arr_0to1, scale=1.0, is_encoded=None):
        """The exact inverse of _adw_gamma_encode -- reconstructs the
        original linear-scale numbers from an already-encoded [0,1]
        array (typically an 8-bit PNG's values, divided by 255).

        This needs the SAME Source-toggle branching as the encode
        side, for the same reason a one-way door doesn't work: every
        site that writes this pipeline's own output back out as EXR,
        or otherwise needs to undo the encode step, must use this
        rather than unconditionally applying pow(x, 2.2) -- doing so
        for an 'AI-Generated' source (which the encode side never
        gamma-curved in the first place) reintroduces exactly the
        same double-curve mismatch this session spent considerable
        effort eliminating from the encode side alone, just on the
        decode side instead, and is calibrated against the encode's
        OWN choice of branch, not a separate guess.

        is_encoded works the same way as on the encode side above --
        pass the SAME value used at encode time to guarantee this
        stays a true inverse, since the live toggle it defaults to
        reading could have changed in between otherwise."""
        import numpy as np
        enc = is_encoded if is_encoded is not None \
            else self._adw_source_is_encoded()
        if enc:
            return np.maximum(arr_0to1, 0) * max(scale, 1e-6)
        return np.power(np.maximum(arr_0to1, 0), 2.2) * max(scale, 1e-6)

    def _adw_output_root(self, input_folder):
        """The shared 'ADW' folder every module's named output
        subdirectory lives inside, created next to the input files --
        a sibling of the input folder, not nested inside it. Without
        this, propagating one module's output as another's input (see
        _adw_propagate_output below) chains output folders deeper with
        every hop: CurveLock's output becomes ADW-Blur's input, so
        ADW-Blur's own output lands inside CurveLock's folder, then
        THAT becomes AreaLock's input, so AreaLock's output lands
        inside ADW-Blur's folder which is inside CurveLock's folder --
        a different, deeper nesting path depending purely on which
        order modules happened to run in, rather than one predictable
        location.

        If the input folder is already itself somewhere inside an ADW
        folder -- normally true after the first hop, since every
        module's output is ADW/<ModuleName>, whose parent IS literally
        named ADW -- reuse that exact ADW folder rather than creating
        a nested ADW-inside-ADW. Only a fresh, never-before-processed
        input folder creates a new ADW sibling."""
        input_folder = os.path.abspath(input_folder)
        parts = input_folder.split(os.sep)
        if "ADW" in parts:
            idx = parts.index("ADW")
            return os.sep.join(parts[:idx+1]) or os.sep
        parent = os.path.dirname(input_folder)
        return os.path.join(parent, "ADW")

    def _adw_module_output_dir(self, input_folder, module_name):
        """The actual output directory a module should render into:
        ADW/<module_name>, with ADW placed next to the input files
        (see _adw_output_root) rather than inside them. Creates it if
        needed and returns the path.

        Guards against a specific, severe collision: if a module is
        re-run using its OWN prior output as input -- e.g. running
        ADW-Blur again on an already-interpolated sequence for even
        more frames, a perfectly normal thing to want to do -- the
        naive ADW/<module_name> path is identical to the input folder
        itself. Callers universally treat "the output directory" as
        safe to clear and recreate before rendering; if that directory
        IS the input, clearing it destroys the frames before they're
        even read. Auto-disambiguates with a numeric suffix instead of
        ever returning a path equal to the input."""
        root = self._adw_output_root(input_folder)
        out_dir = os.path.join(root, module_name)
        input_abs = os.path.abspath(input_folder)
        if os.path.abspath(out_dir) == input_abs:
            suffix = 2
            while os.path.abspath(os.path.join(root, f"{module_name}_{suffix}")) == input_abs:
                suffix += 1
            out_dir = os.path.join(root, f"{module_name}_{suffix}")
        os.makedirs(out_dir, exist_ok=True)
        return out_dir

    # ── ADW-Blur presets, readable from other modules ─────────────────
    ADW_PRESET_VARS = {
        "rmult":        "rmult_var",
        "scale":        "rife_scale_var",
        "flow":         "rife_flow_var",
        "upscale":      "rife_upscale_var",
        "tta":          "rife_tta_var",
        "prev_upscale": "rife_prev_upscale_var",
        "retime":       "rife_retime_var",
        "range_only":   "rife_range_only_var",
        "blend_str":    "rife_blend_str_var",
        "falloff":      "rife_blend_falloff_var",
        "bias":         "rife_blend_oversample_var",
        "motion_thr":   "rife_motion_thresh_var",
        "motion_mask_on": "rife_motion_mask_var",
        "hist_anchor":  "rife_hist_anchor_var",
        "motion_hi":    "rife_motion_hi_var",
        "dilation":     "rife_mask_dilation_var",
        "feather":      "rife_mask_feather_var",
        "out_mov":      "rife_out_mov_var",
    }

    def _adw_preset_file(self):
        import pathlib
        return pathlib.Path.home() / ".ai_toolbox" / "presets_adw.json"

    def _adw_presets(self):
        """The saved ADW-Blur presets: [{"name":…, "settings":{…}}]."""
        import json
        try:
            p = self._adw_preset_file()
            if p.exists():
                return json.loads(p.read_text()) or []
        except Exception:
            pass
        return []

    def _adw_preset_names(self):
        return [p.get("name", "?") for p in self._adw_presets()
                if isinstance(p, dict)]

    def _adw_preset_settings(self, name):
        """A preset's settings by name, or None. Falls back to whatever
        ADW-Blur's live vars hold when the name isn't found — which is
        also what 'no preset' means: use ADW-Blur's defaults."""
        for p in self._adw_presets():
            if isinstance(p, dict) and p.get("name") == name:
                return dict(p.get("settings") or {})
        return None

    def _adw_live_blur_settings(self):
        """ADW-Blur's current (default) values, for when no preset is
        chosen."""
        d = {}
        for k, attr in self.ADW_PRESET_VARS.items():
            v = getattr(self, attr, None)
            if v is None:
                continue
            try:
                d[k] = v.get()
            except Exception:
                pass
        return d

    def _rife_frames_dir(self, input_folder):
        """Where ADW-Blur's RIFE interpolated frames live (and are
        cached): ADW/ADW-Blur_Rife. These are the intermediate,
        many-times-more-numerous interp frames — not the deliverable."""
        return os.path.join(self._adw_output_root(input_folder),
                            "ADW-Blur_Rife")

    def _rife_final_dir(self, input_folder):
        """ADW-Blur's FINAL output: the retimed sequence, at the original
        frame count. This is the deliverable, so it gets the clean
        ADW/ADW-Blur name (the raw RIFE frames go to ADW-Blur_Rife)."""
        return os.path.join(self._adw_output_root(input_folder),
                            "ADW-Blur")

    def _adw_versioned_output_dir(self, input_folder, module_name,
                                  reuse_latest=False):
        """Like _adw_module_output_dir but never overwrites a previous
        render: it returns ADW/<module_name>_vNN, picking the next free
        version number. ADW-Paint is not procedural — each render is a
        hand-made result you don't want silently clobbered — so its
        Run always writes a fresh version (v01, then v02, v03 ...).

        With reuse_latest=True it returns the HIGHEST existing version
        instead of a new one (creating v01 only if none exist). Save
        Frame uses this so repeatedly saving single frames in one
        session groups them into the same version folder rather than
        spawning a new one per frame.
        """
        import re
        root = self._adw_output_root(input_folder)
        os.makedirs(root, exist_ok=True)
        pat = re.compile(r"^" + re.escape(module_name) + r"_v(\d+)$")
        existing = []
        try:
            for name in os.listdir(root):
                m = pat.match(name)
                if m and os.path.isdir(os.path.join(root, name)):
                    existing.append(int(m.group(1)))
        except FileNotFoundError:
            pass
        if reuse_latest and existing:
            ver = max(existing)
        else:
            ver = (max(existing) + 1) if existing else 1
        out_dir = os.path.join(root, f"{module_name}_v{ver:02d}")
        # guard against the ADW-Paint_vNN path equalling the input
        input_abs = os.path.abspath(input_folder)
        while os.path.abspath(out_dir) == input_abs:
            ver += 1
            out_dir = os.path.join(root, f"{module_name}_v{ver:02d}")
        os.makedirs(out_dir, exist_ok=True)
        return out_dir

    def _adw_peek_next_version_dir(self, input_folder, module_name):
        """What _adw_versioned_output_dir would return NEXT, without
        calling it.

        The real function creates the directory it returns -- fine for
        a render, wrong for a label that redraws on every folder pick
        or keystroke. Calling the real one there would silently mint a
        new empty version folder every time the UI repainted, so this
        mirrors its numbering with no filesystem write."""
        import re
        root = self._adw_output_root(input_folder)
        pat = re.compile(r"^" + re.escape(module_name) + r"_v(\d+)$")
        existing = []
        try:
            for name in os.listdir(root):
                m = pat.match(name)
                if m and os.path.isdir(os.path.join(root, name)):
                    existing.append(int(m.group(1)))
        except FileNotFoundError:
            pass
        ver = (max(existing) + 1) if existing else 1
        out_dir = os.path.join(root, f"{module_name}_v{ver:02d}")
        input_abs = os.path.abspath(input_folder)
        while os.path.abspath(out_dir) == input_abs:
            ver += 1
            out_dir = os.path.join(root, f"{module_name}_v{ver:02d}")
        return out_dir

    def _adw_safe_clear_output_dir(self, out_dir, input_folder, log_widget=None):
        """Defense in depth alongside _adw_module_output_dir's own
        collision-avoidance above: refuse to rmtree+recreate an output
        directory that's the same as, or an ancestor of, the input
        folder we're about to read frames from. Returns True if it's
        safe to proceed (and has cleared+recreated out_dir), False if
        it refused. A silent data-loss bug is categorically worse than
        an aborted render, so this errs hard toward refusing."""
        out_abs = os.path.abspath(out_dir)
        input_abs = os.path.abspath(input_folder)
        if out_abs == input_abs or (input_abs + os.sep).startswith(out_abs + os.sep):
            if log_widget is not None:
                self.after(0, lambda: self.log(log_widget,
                    f"\u2716 Refusing to clear {out_dir} — it's the same as, "
                    f"or contains, the input folder. Aborting to protect "
                    f"your source frames; this shouldn't normally happen, "
                    f"please report it.", "err"))
            return False
        if os.path.exists(out_dir):
            shutil.rmtree(out_dir)
        os.makedirs(out_dir, exist_ok=True)
        return True

    def _adw_propagate_output(self, out_dir, source_key, log_widget):
        """After ANY module finishes a render, load its output as the
        input for every OTHER applicable module that can receive a
        sequence folder -- so jumping between modules always means
        you're picking up wherever the latest result actually is.
        source_key excludes that module from the target list (no
        point loading a module's own output back into itself).
        Each target is wrapped individually so one module's load
        issue can't block the others from receiving the handoff."""
        targets = []
        attempts = [
            ("curve",   "_curve_load_folder", "ADW-CurveLock"),
            ("area",    "_area_load_folder",  "ADW-AreaLock"),
            ("organic", "_organic_load_folder", "Lens Studio"),
            ("rife",    "_rpick_load",        "ADW-Blur"),
            ("sam",     "_sam_load_folder",   "SAM 3"),
            ("upstudio", "_ups_load_folder",  "Upscale Studio"),
            ("upscale", "_usc_load_folder",   "Expansion Studio"),
            ("smudge",  "_smudge_load_folder", "Paint Studio"),
        ]
        for key, fn_name, label in attempts:
            if key == source_key:
                continue
            if key == "upstudio" and source_key == "upscale":
                # Expanded output is never upscaled afterwards -- that
                # order interpolates PQ code values. Upscale first.
                continue
            fn = getattr(self, fn_name, None)
            if not fn:
                continue
            try:
                fn(out_dir)
                targets.append(label)
            except Exception:
                pass
        if targets:
            self.log(log_widget,
                f"Output also loaded as input in {', '.join(targets)} — "
                f"switch tabs anytime to continue there.", "hi")

    def _rife_after_run_sendto(self, out_dir):
        self._adw_propagate_output(out_dir, "rife", self.rlog)

    # ── TAB: SAM 3 ──────────────────────────────────────────────────
    # ════════════════════════════════════════════════════════════════
    #  ADW-PAINT — per-frame paint / smudge / stamp fixes
    # ════════════════════════════════════════════════════════════════
    # ══ ADW-Interpolate ══════════════════════════════════════════════
    # Regenerate a short run of temporally-broken frames (the 5-10 frame
    # blowouts AI video loves to produce) by throwing them away and
    # letting RIFE interpolate a fresh set between the last good frame
    # before the span and the first good frame after it.
    def _tab_interp(self):
        f = self._frame("interp")

        def _ip_info_popup(widget, tip):
            """Hover tooltip — no focus stealing, always works. Same
            pattern as ADW-Blur's, so the .MOV checkbox reads the same way
            in both places."""
            _pop = [None]
            def _show(e):
                if _pop[0]:
                    try: _pop[0].destroy()
                    except Exception: pass
                pop = tk.Toplevel(self)
                pop.overrideredirect(True)
                pop.configure(bg=BD)
                pop.attributes("-topmost", True)
                tk.Label(pop, text=tip, font=FM, bg=BD, fg=W,
                         justify="left", padx=12, pady=10,
                         wraplength=300).pack()
                pop.update_idletasks()
                sw = self.winfo_screenwidth()
                x = min(e.x_root + 4, sw - pop.winfo_width() - 8)
                pop.geometry(f"+{x}+{e.y_root+16}")
                _pop[0] = pop
            def _hide(e=None):
                if _pop[0]:
                    try: _pop[0].destroy()
                    except Exception: pass
                    _pop[0] = None
            widget.bind("<Enter>", _show)
            widget.bind("<Leave>", _hide)
            widget.bind("<Button-1>", _hide)

        pan = self._make_paned(f, "horizontal")
        pan.pack(fill="both", expand=True)
        lf = tk.Frame(pan, bg=BG); pan.add(lf, minsize=300)
        rf = tk.Frame(pan, bg=BG); pan.add(rf, minsize=400)

        # scrollable left panel (same pattern as Paint / Area)
        _ip_cv  = tk.Canvas(lf, bg=BG, highlightthickness=0)
        _ip_vsb = self._mk_scrollbar(lf, _ip_cv, width=10)
        _ip_vsb.pack(side="right", fill="y")
        _ip_cv.pack(side="left", fill="both", expand=True)
        _ip_inner = tk.Frame(_ip_cv, bg=BG)
        _ip_win = _ip_cv.create_window((0, 0), window=_ip_inner, anchor="nw")
        _ip_cv.bind("<Configure>",
                    lambda e: _ip_cv.itemconfig(_ip_win, width=e.width))
        _ip_inner.bind("<Configure>",
                       lambda e: _ip_cv.configure(scrollregion=_ip_cv.bbox("all")))
        def _ip_panel_scroll(e):
            wx = _ip_cv.winfo_rootx(); wy = _ip_cv.winfo_rooty()
            ww = _ip_cv.winfo_width(); wh = _ip_cv.winfo_height()
            if wx <= e.x_root <= wx+ww and wy <= e.y_root <= wy+wh:
                _ip_cv.yview_scroll(int(-1*(e.delta/120)), "units")
        _ip_cv.bind_all("<MouseWheel>", _ip_panel_scroll, add="+")
        lf = _ip_inner

        tk.Label(lf, text="ADW-Interpolate", font=("Futura", 14), bg=BG,
                 fg=R).pack(anchor="w", padx=16, pady=(14, 0))
        tk.Label(lf, text="Scrap a run of temporally-broken frames and "
                 "rebuild them: RIFE interpolates a fresh span between "
                 "the good frame before and the good frame after.",
                 font=FSM, bg=BG, fg=G, wraplength=280, justify="left",
                 anchor="w").pack(anchor="w", padx=16, pady=(2, 8))

        # ── state ────────────────────────────────────────────────────
        self.ip_folder = None
        self.ip_frames = []
        self.ip_idx = 0
        self.ip_motion = {}         # idx -> 0..1 motion score
        self._ip_analysing = False
        self._ip_analyse_cancel = False
        # Cache to RAM (same feature as Paint/AreaLock/CurveLock, opt-in
        # alongside Analyse Motion): guaranteed-resident frames for the
        # current range, immune to eviction from other tabs' decode
        # activity on the shared _pv_frame LRU.
        self.ip_ram_cache = {}
        self._ip_ram_building = False
        self._ip_ram_cancel = False
        self.ip_cache_to_ram_var = tk.BooleanVar(value=False)
        self.ip_segments = []       # [{name,color,in,out}] — ranges to regenerate
        self.ip_active = 0          # which segment Set In / Set Out apply to
        self._ip_drag = None        # live timeline drag
        self._ip_exporting = False
        self._ip_vace_busy = False
        self._ip_vace_cancel = False
        self._ip_vace_result = {}          # segment name -> retimed frames dir
        self._ip_applying = False
        self.ip_src_folder = None          # the plate, before any splice
        self.ip_src_frames = []
        self._ip_src_by_base = {}
        self._ip_result_files = []
        self._ip_result_dir_cached = None
        self.ip_result_dir = None          # the spliced output, once applied
        self._ip_view = "Source"
        self.ip_view_var = tk.StringVar(value="Source")
        self._ip_vace_t0 = None            # start time, for the elapsed clock
        self._ip_vace_phase = None
        self._ip_vace_detail = ""
        self._ip_vace_ticker = None
        # inpainting (mask + coverage/taper, partial regen) or depth
        # (whole-frame regen guided by a depth video, no mask at all)
        self.ip_vace_method_var = tk.StringVar(value="inpainting")
        # depth-estimation model size (Depth method only)
        self.ip_depth_model_var = tk.StringVar(value="VDA-Large")
        self.ip_vace_res_var = tk.StringVar(value="720p")
        # Raised again, from 40 to 60: more diffusion steps can mean
        # tighter adherence to the anchor conditioning (first/last
        # frame, mask), worth trying before anything more structural
        # for a boundary mismatch. fal's own endpoint default is 30 --
        # this app's default has always run higher than that.
        # 50, not 60: wan-22-vace-fun-a14b rejects anything above 50
        # ("Input should be less than or equal to 50") -- 60 was set for
        # the older wan-vace-14b endpoint and failed every call on this
        # one. _vace_steps() clamps whatever is typed here anyway.
        self.ip_vace_steps_var = tk.StringVar(value="50")
        self.ip_vace_prompt_var = tk.StringVar(value="")
        self.ip_vace_neg_var = tk.StringVar(
            value="blurry, distorted, morphing, flicker")
        self.ip_vace_seed_var = tk.StringVar(value="-1")
        self.ip_vace_frames_var = tk.IntVar(value=81)    # generation length
        # No UI slider any more -- Paint is the precise way to say WHERE
        # to regenerate. Without a painted mask, the whole frame is
        # regenerated (100%); this stays internal-only, used by
        # _vace_mask_for_frame as the no-mask-painted fallback.
        self.ip_vace_coverage_var = tk.IntVar(value=100)
        # VACE caps at 720p; ESRGAN reconstructs detail on the way back up
        # to the plate instead of just interpolating soft pixels
        self.ip_vace_upscale_var = tk.BooleanVar(value=True)
        # deliverable: EXR by default (the pipeline format), MOV optional
        self.ip_out_fmt_var = tk.StringVar(value="EXR")
        # on by default: each segment gets its own motion words + a fresh
        # caption of its own middle frame, rather than one shared prompt
        # for every range in the batch
        self.ip_autoprompt_var = tk.BooleanVar(value=True)
        # Tether: how many extra REAL, unmasked frames to include on
        # each side of the selected range when building what's sent to
        # VACE -- context for it to anchor motion from, not a blend.
        # Those extra frames are discarded from VACE's output before
        # the splice; only the selection itself is ever replaced. The
        # splice is always a sharp cut -- no crossfade at the join
        # (that never reliably worked: it can only ever hide a SMALL
        # mismatch, and a real content difference just shows through as
        # a ghost/double-exposure during the fade instead of a clean
        # cut). Applied at Generate time (changes what gets sent to
        # VACE), unlike a blend which would be a Run-time-only fix.
        self.ip_vace_tether_var = tk.IntVar(value=4)
        # freehand brush mask (same mechanics as ADW-Area's Look brush):
        # paints WHERE to regenerate, replacing the auto-centred box for
        # the active segment
        self.ip_paint_mode = False
        self.ip_paint_pts = None
        self.ip_brush_size_var = tk.IntVar(value=28)
        self.ip_img_base = None            # for the shared _pp_* player
        self._ip_wipe_corrected_base = None
        self._ip_wipe_t = 0.5              # wipe line starts centred
        self._ip_cmp_mode = "off"          # "off", "wipe", or "diff"
        self.ip_fps_var = tk.StringVar(value="24")
        self.ip_motion_tint_var = tk.BooleanVar(value=True)

        # ── Sequence ─────────────────────────────────────────────────
        c1 = self._card(lf, "Input Sequence Folder")
        rowf = tk.Frame(c1, bg=S); rowf.pack(fill="x", pady=2)
        self.ip_folder_btn = self._mkbtn(rowf, "Choose folder\u2026",
            self._interp_pick_folder, bg="#0D0D0D", fg=W)
        tk.Label.configure(self.ip_folder_btn._lbl, width=0, pady=6)
        self.ip_folder_btn.pack(side="left", fill="x", expand=True)
        self.ip_lbl = tk.Label(c1, text="no folder", font=FSM, bg=S, fg=G,
                               anchor="w"); self.ip_lbl.pack(fill="x", pady=(4,0))
        nav = tk.Frame(c1, bg=S); nav.pack(fill="x", pady=(4, 0))
        for txt, d in (("\u25c0", -1), ("\u25b6", +1)):
            b = self._mkbtn(nav, txt, lambda dd=d: self._interp_step(dd),
                            bg="#0D0D0D", fg=W)
            tk.Label.configure(b._lbl, width=3, pady=4)
            b.pack(side="left" if d < 0 else "right", padx=2)
        self.ip_frame_lbl = tk.Label(nav, text="no folder", font=FM,
                                     bg=S, fg=G)
        self.ip_frame_lbl.pack(side="left", fill="x", expand=True)

        # Same control Fix Missing Frames has, for the same reason: an
        # EXR cannot tell you which of the two it is holding, and
        # getting it wrong looks exactly like a bad grade -- here,
        # like an "extremely dark" plate that is actually a correctly
        # exposed one nobody gamma-encoded for preview yet.
        _rowcs = tk.Frame(c1, bg=S); _rowcs.pack(fill="x", pady=(6, 0))
        tk.Label(_rowcs, text="EXR is", font=FSM, bg=S, fg=G).pack(side="left")
        self.ip_cs_var = tk.StringVar(
            value="Display-encoded" if self._adw_source_is_encoded()
            else "Scene-linear")
        ttk.Combobox(_rowcs, textvariable=self.ip_cs_var, font=FSM,
            state="readonly", width=17,
            values=["Display-encoded", "Scene-linear"]).pack(
                side="left", padx=(6, 0))
        self.ip_cs_var.trace_add("write", lambda *_: self._ip_cs_changed())

        # ── Motion analysis, with an opt-in RAM cache alongside ──────
        ccache = self._card(lf, "Analyse Motion")
        _cache_info = tk.Label(ccache, text="\u24d8  Scores motion between "
                              "frames; tints the timeline", font=FSM,
                              bg=S, fg="#555555", cursor="hand2",
                              anchor="w")
        _cache_info.pack(fill="x", pady=(0, 4))
        _ip_info_popup(_cache_info,
            "Scores how much each frame moves against the one before it. "
            "The timeline goes red (calm) \u2192 orange \u2192 yellow "
            "(unstable), so a temporally-broken run stands out.\n\n"
            "Frames are streamed and released by default \u2014 nothing "
            "held in RAM. Check Cache to RAM below to also pre-decode "
            "the current range slider selection into memory once the "
            "scan finishes, for instant scrubbing.")
        self.ip_cache_btn = self._mkbtn(ccache, "\u2295  Analyse Motion",
            self._interp_analyse_toggle, bg="#0D0D0D", fg=W)
        tk.Label.configure(self.ip_cache_btn._lbl, width=0, pady=8)
        self.ip_cache_btn.pack(fill="x")
        tk.Checkbutton(ccache, text="Cache to RAM (also pre-decode "
            "the current range for instant scrubbing)",
            variable=self.ip_cache_to_ram_var, bg=S, fg=W,
            activebackground=S, activeforeground=W, selectcolor=R,
            font=FSM, highlightthickness=0, bd=0).pack(anchor="w",
                pady=(4, 0))
        _icrow = tk.Frame(ccache, bg=S); _icrow.pack(fill="x", pady=(4, 0))
        # Clear is packed FIRST so its space is always reserved on the
        # right, regardless of panel width -- previously the status
        # label (packed first, with no width limit) could grow long
        # enough after an analysis run to push Clear off the edge of a
        # narrow settings panel entirely.
        self.ip_cache_clear_btn = self._mkbtn(_icrow, "Clear",
            self._interp_analyse_clear, bg="#0D0D0D", fg=W)
        tk.Label.configure(self.ip_cache_clear_btn._lbl, width=0, pady=4, padx=10)
        self.ip_cache_clear_btn.pack(side="right")
        self.ip_cache_info = tk.Label(_icrow, text="Not analysed", font=FSM,
            bg=S, fg=G, anchor="w")
        self.ip_cache_info.pack(side="left", fill="x", expand=True)
        tk.Checkbutton(ccache, text="Tint timeline by motion",
            variable=self.ip_motion_tint_var, bg=S, fg=W, activebackground=S,
            activeforeground=W, selectcolor=R, font=FSM,
            highlightthickness=0, bd=0,
            command=lambda: (hasattr(self, "ip_frame_cb")
                and self.ip_frame_cb.refresh())).pack(anchor="w", pady=(4, 0))

        # ── Timing ───────────────────────────────────────────────────
        ctime = self._card(lf, "Timing")
        rowfps = tk.Frame(ctime, bg=S); rowfps.pack(fill="x", pady=2)
        tk.Label(rowfps, text="Frames / sec", font=FSM, bg=S, fg=G,
                 width=12, anchor="w").pack(side="left")
        tk.Entry(rowfps, textvariable=self.ip_fps_var, width=7, bg="#0D0D0D",
                 fg=W, insertbackground=W, font=FM, bd=0,
                 highlightthickness=1, highlightbackground=BD
                 ).pack(side="left")
        self.ip_fps_lbl = tk.Label(rowfps, text="", font=FSM, bg=S, fg=G,
                                   anchor="w")
        self.ip_fps_lbl.pack(side="left", padx=(10, 0))
        _time_info = tk.Label(ctime, text="\u24d8  Frame rate for exports "
                              "and segment lengths", font=FSM, bg=S,
                              fg="#555555", cursor="hand2", anchor="w")
        _time_info.pack(fill="x", pady=(2, 0))
        _ip_info_popup(_time_info,
            "Sets the frame rate of the exported videos and what the "
            "2-second Seedance minimum works out to in frames. Segment "
            "lengths are shown in both units.")

        # ── Segments: the ranges to regenerate ───────────────────────
        cspan = self._card(lf, "Segments \u2014 ranges to regenerate")
        _span_info = tk.Label(cspan, text="\u24d8  Add a range for each "
                              "broken run", font=FSM, bg=S, fg="#555555",
                              cursor="hand2", anchor="w")
        _span_info.pack(fill="x", pady=(0, 4))
        _ip_info_popup(_span_info,
            "Add a segment for each broken run. Each gets its own colour "
            "on the timeline. Drag the middle of a box to push it "
            "around, drag an end to resize \u2014 it will not go under 2 "
            "seconds.\n\n"
            "VACE keeps the segment's first and last frame and "
            "regenerates everything between them. Mark the run that fell "
            "apart; keep it short.")

        _ip_outer = tk.Frame(cspan, bg=S,
            highlightthickness=1, highlightbackground=BD)
        _ip_outer.pack(fill="x", pady=(2, 4))
        _iptab_bar = tk.Frame(_ip_outer, bg=BG)
        _iptab_bar.pack(fill="x")

        def _ip_switch(i):
            self.ip_active = i
            self._interp_segments_changed()
            s_ = self._interp_active_seg()
            if s_:
                self._interp_show_frame(s_["in"])

        def _ip_rename(i):
            import tkinter.simpledialog as _sd
            nm = _sd.askstring("Rename segment", "Name:",
                initialvalue=self.ip_segments[i]["name"], parent=self)
            if nm and nm != self.ip_segments[i]["name"]:
                old_nm = self.ip_segments[i]["name"]
                # the result is keyed by name — carry it across, or the
                # rename would silently orphan a perfectly good rebuild
                if old_nm in self._ip_vace_result:
                    self._ip_vace_result[nm] = \
                        self._ip_vace_result.pop(old_nm)
                self.ip_segments[i]["name"] = nm
                self._interp_segments_changed()

        def _ip_menu(ev, i):
            m = tk.Menu(self, tearoff=0, bg="#1A1A1A", fg=W,
                        activebackground=R, activeforeground=W)
            m.add_command(label="Rename\u2026", command=lambda: _ip_rename(i))
            m.add_command(label="Go to start",
                command=lambda: self._interp_show_frame(
                    self.ip_segments[i]["in"]))
            if len(self.ip_segments) > 0:
                m.add_separator()
                m.add_command(label="Delete",
                    command=lambda: self._interp_del_segment(i))
            m.tk_popup(ev.x_root, ev.y_root)

        def _ip_rebuild_tabs():
            for w in list(_iptab_bar.winfo_children()):
                w.destroy()
            for si, s_ in enumerate(self.ip_segments):
                is_active = (si == self.ip_active)
                item_bg = S if is_active else BG
                col = s_["color"]
                st_ = self._interp_seg_state(s_)
                _item = tk.Frame(_iptab_bar, bg=item_bg)
                _item.pack(side="left")
                # the state glyph: hollow = nothing yet, filled = rebuilt,
                # tick = spliced into the shot
                tk.Label(_item, text=self.IP_STATE_GLYPH[st_], font=FSM,
                         bg=item_bg,
                         fg=("#66CC66" if st_ != "new" else col),
                         pady=4).pack(side="left", padx=(8, 2))
                # frames AND seconds, so both units are always visible
                lbl = (f"{s_['name']}  {s_['in']+1}\u2013{s_['out']+1}"
                       f"  ({self._interp_seg_secs(s_):.1f}s)")
                _tb = tk.Label(_item, text=lbl, font=FSM, bg=item_bg,
                    fg=(col if is_active else "#888888"),
                    pady=4, cursor="hand2")
                _tb.pack(side="left", padx=(2, 10))
                _tb.bind("<Button-1>", lambda e, i=si: _ip_switch(i))
                _tb.bind("<Double-Button-1>", lambda e, i=si: _ip_rename(i))
                _tb.bind("<Button-3>", lambda e, i=si: _ip_menu(e, i))
                _tb.bind("<Button-2>", lambda e, i=si: _ip_menu(e, i))
            _add = tk.Label(_iptab_bar, text=" + ",
                font=("Futura", 16, "bold"), bg=BG, fg="#CC4444",
                padx=8, pady=3, cursor="hand2")
            _add.pack(side="left")
            _add.bind("<Button-1>", lambda e: self._interp_add_segment())
            _add.bind("<Enter>", lambda e: _add.configure(fg="#FF4444"))
            _add.bind("<Leave>", lambda e: _add.configure(fg="#CC4444"))
        self._ip_rebuild_tabs_fn = _ip_rebuild_tabs
        _ip_rebuild_tabs()

        rowio = tk.Frame(cspan, bg=S); rowio.pack(fill="x", pady=2)
        for i in range(3):
            rowio.columnconfigure(i, weight=1)
        self.ip_in_btn = self._mkbtn(rowio, "[  Set In (I)",
            self._interp_set_in, bg="#0D0D0D", fg=W)
        tk.Label.configure(self.ip_in_btn._lbl, width=0, pady=7)
        self.ip_in_btn.grid(row=0, column=0, sticky="ew", padx=1)
        self.ip_out_btn = self._mkbtn(rowio, "]  Set Out (O)",
            self._interp_set_out, bg="#0D0D0D", fg=W)
        tk.Label.configure(self.ip_out_btn._lbl, width=0, pady=7)
        self.ip_out_btn.grid(row=0, column=1, sticky="ew", padx=1)
        self.ip_clear_btn = self._mkbtn(rowio, "\u2715  Delete",
            lambda: self._interp_del_segment(self.ip_active),
            bg="#0D0D0D", fg=W)
        tk.Label.configure(self.ip_clear_btn._lbl, width=0, pady=7)
        self.ip_clear_btn.grid(row=0, column=2, sticky="ew", padx=1)

        self.ip_span_lbl = tk.Label(cspan, text="No segments", font=FM,
            bg=S, fg=G, anchor="w")
        self.ip_span_lbl.pack(fill="x", pady=(4, 0))

        # ── Wan VACE ─────────────────────────────────────────────────
        cvace = self._card(lf, "Wan VACE \u2014 regenerate the range")
        _vace_info = tk.Label(cvace, text="\u24d8  Regenerates the "
                              "selected range using VACE", font=FSM,
                              bg=S, fg="#555555", cursor="hand2",
                              anchor="w")
        _vace_info.pack(fill="x", pady=(0, 4))
        _ip_info_popup(_vace_info,
            "Sends the selected range to VACE as a control clip and "
            "regenerates it. The output matches the range length "
            "automatically. Use the Regenerate slider to trade off how "
            "much is re-synthesised against how closely it tracks your "
            "footage.")

        # Three genuinely different pipelines, not a quality knob:
        # - Inpainting: real footage + a mask. Supports partial-frame
        #   coverage.
        # - Depth: the real footage run through a separate depth-
        #   estimation pass first, then VACE regenerates the WHOLE frame
        #   guided by that depth video. No mask -- and it costs a second
        #   fal call on top.
        # - Full image: the same whole-frame, no-mask regeneration as
        #   Depth, but skipping the depth-estimation pass entirely --
        #   the real plate footage itself is sent as VACE's conditioning
        #   video, same request shape as Depth (video/first/last, no
        #   mask), just with the plain clip in place of a depth map.
        #   Cheaper than Depth (no $0.04/s depth-anything charge) and
        #   worth trying when the shot's own colour/lighting/detail
        #   matters more to the regeneration than an explicit depth
        #   cue would add.
        _rmeth = tk.Frame(cvace, bg=S); _rmeth.pack(fill="x", pady=(0, 4))
        tk.Label(_rmeth, text="Method", font=FSM, bg=S, fg=G, width=11,
                 anchor="w").pack(side="left")
        _meth_info = tk.Label(_rmeth, text="\u24d8", font=FSM, bg=S,
                              fg="#555555", cursor="hand2")
        _meth_info.pack(side="left", padx=(0, 6))
        _ip_info_popup(_meth_info,
            "Mask: real footage + a mask defining WHERE to regenerate.\n"
            "Paint it freehand, or leave unpainted for the whole frame.\n"
            "The only method with partial-frame coverage.\n\n"
            "Depth map: the range is run through a separate depth-\n"
            "estimation pass first (fal-ai/depth-anything-video), then\n"
            "VACE regenerates the WHOLE frame guided by that depth\n"
            "video's structure/layout instead of a masked patch. No\n"
            "mask at all -- Paint does not apply. Costs an\n"
            "extra $0.04/s on top of the generation itself for the\n"
            "depth pass.\n\n"
            "Full image: same whole-frame regeneration as Depth map,\n"
            "same no-mask conditioning -- but the real plate footage\n"
            "is sent to VACE directly instead of first being run\n"
            "through the depth-estimation pass. No mask, no depth\n"
            "pass, no extra $0.04/s charge.\n\n"
            "Worth trying if Mask keeps drifting even with a tight\n"
            "painted area -- depth/full-image constrain the whole\n"
            "layout, not just a masked region.")
        for _mv, _ml in (("inpainting", "Mask"),
                         ("depth", "Depth map"),
                         ("full", "Full image")):
            tk.Radiobutton(_rmeth, text=_ml, variable=self.ip_vace_method_var,
                value=_mv, bg=S, fg=W, activebackground=S,
                activeforeground=W, selectcolor=R, font=FSM,
                highlightthickness=0, bd=0).pack(side="left", padx=(0, 10))
        self.ip_method_note = tk.Label(cvace, text="", font=FSM, bg=S,
                                       fg="#CCAA44", anchor="w",
                                       wraplength=460, justify="left")
        self.ip_method_note.pack(fill="x", pady=(0, 4))
        # _method_changed itself is defined further down, once the rows
        # it shows/hides (Paint, Depth quality) all exist -- wired up
        # right after the last of those is built.

        _rslow = tk.Frame(cvace, bg=S); _rslow.pack(fill="x", pady=2)
        self.ip_slow_lbl = tk.Label(_rslow, text="", font=FSM, bg=S, fg=G,
                                    anchor="w", wraplength=460,
                                    justify="left")
        self.ip_slow_lbl.pack(side="left", fill="x", expand=True)

        # Freehand brush mask -- same mechanics as ADW-Area's Look brush:
        # toggle Paint, drag a stroke on the viewer, release to set where
        # VACE regenerates for the active segment (replaces the whole-
        # frame default entirely, same as it replaced the auto box).
        cpaint = tk.Frame(cvace, bg=S); cpaint.pack(fill="x", pady=(2, 2))
        self.ip_paint_btn = self._mkbtn(cpaint, "\u270e  Paint",
            lambda: self._interp_set_paint_mode(not self.ip_paint_mode),
            bg="#1A3A1A", fg="#66CC66")
        tk.Label.configure(self.ip_paint_btn._lbl, width=0, pady=2, padx=8)
        self.ip_paint_btn.pack(side="left")
        self.ip_clearmask_btn = self._mkbtn(cpaint, "Clear mask",
            self._interp_clear_brush_mask, bg="#0D0D0D", fg=G)
        tk.Label.configure(self.ip_clearmask_btn._lbl, width=0, pady=2,
                          padx=8)
        self.ip_clearmask_btn.pack(side="left", padx=(6, 0))

        tk.Label(cpaint, text="Brush", font=FSM, bg=S, fg=G,
                 width=6, anchor="w").pack(side="left", padx=(14, 0))
        _BRUSH_SNAP = list(range(6, 121, 2))
        self.ip_brush_lbl = tk.Label(cpaint, text=" 28px ", font=FSM,
                                     bg=S, fg="#CC4444", width=6,
                                     anchor="e")
        self.ip_brush_lbl.pack(side="right")
        _brush_cv = tk.Canvas(cpaint, height=30, bg=S,
            highlightthickness=1, highlightbackground=BD, cursor="hand2")
        _brush_cv.pack(side="left", fill="x", expand=True, padx=(6, 4))

        def _brush_draw(*_):
            _brush_cv.delete("all")
            W7 = _brush_cv.winfo_width() or 200
            cur = int(self.ip_brush_size_var.get())
            n = len(_BRUSH_SNAP)
            TY = 10
            def sx(i): return int(i / (n - 1) * (W7 - 8)) + 4
            _brush_cv.create_line(4, TY, W7 - 4, TY, fill="#333333",
                width=2)
            ci = min(range(n), key=lambda i: abs(_BRUSH_SNAP[i] - cur))
            cx = sx(ci)
            _brush_cv.create_line(sx(0), TY, cx, TY, fill="#CC4444",
                width=3)
            _brush_cv.create_oval(cx - 5, TY - 5, cx + 5, TY + 5,
                fill="#CC4444", outline="#888888", width=1)

        def _brush_snap(ex):
            W7 = _brush_cv.winfo_width() or 200
            t = max(0.0, min(1.0, (ex - 4) / max(1, W7 - 8)))
            fi = int(round(t * (len(_BRUSH_SNAP) - 1)))
            self.ip_brush_size_var.set(
                _BRUSH_SNAP[max(0, min(len(_BRUSH_SNAP) - 1, fi))])

        def _brush_changed(*_):
            self.ip_brush_lbl.configure(
                text=f" {int(self.ip_brush_size_var.get())}px ")
            _brush_draw()

        _brush_cv.bind("<Button-1>", lambda e: _brush_snap(e.x))
        _brush_cv.bind("<B1-Motion>", lambda e: _brush_snap(e.x))
        _brush_cv.bind("<Configure>", _brush_draw)
        self.ip_brush_size_var.trace_add("write", _brush_changed)
        _brush_changed()

        # Depth-only: the depth-estimation pass's model size. Small is
        # fastest/cheapest, Large is the best quality -- a real trade-off
        # worth exposing, unlike Mask's coverage percentage which Paint
        # has made unnecessary.
        _rdepthq = tk.Frame(cvace, bg=S); _rdepthq.pack(fill="x", pady=(2, 2))
        tk.Label(_rdepthq, text="Depth quality", font=FSM, bg=S, fg=G,
                 width=11, anchor="w").pack(side="left")
        _dq_info = tk.Label(_rdepthq, text="\u24d8", font=FSM, bg=S,
                            fg="#555555", cursor="hand2")
        _dq_info.pack(side="left", padx=(0, 6))
        _ip_info_popup(_dq_info,
            "The depth-estimation pass's model size (Video Depth "
            "Anything). Small is fastest and cheapest to run; Large "
            "gives the most accurate depth map. This only affects the "
            "depth pass, not the VACE generation cost.")
        for _dv, _dl in (("VDA-Small", "Small"), ("VDA-Base", "Base"),
                         ("VDA-Large", "Large")):
            tk.Radiobutton(_rdepthq, text=_dl,
                variable=self.ip_depth_model_var, value=_dv, bg=S, fg=W,
                activebackground=S, activeforeground=W, selectcolor=R,
                font=FSM, highlightthickness=0, bd=0).pack(side="left",
                                                           padx=(0, 10))

        # VACE caps at 720p. On a 2K plate a plain resize just enlarges soft
        # pixels; ESRGAN reconstructs detail, which is the difference
        # between a usable rebuild and an obvious soft patch.
        _rup = tk.Frame(cvace, bg=S); _rup.pack(fill="x", pady=2)
        tk.Label(_rup, text="Upscale", font=FSM, bg=S, fg=G, width=12,
                 anchor="w").pack(side="left")
        tk.Checkbutton(_rup,
            text="Real-ESRGAN back to the plate resolution",
            variable=self.ip_vace_upscale_var, bg=S, fg=W,
            activebackground=S, activeforeground=W, selectcolor=R,
            font=FSM, highlightthickness=0, bd=0,
            anchor="w").pack(side="left")

        # EXR is the pipeline format and the default (unchecked); Out .MOV
        # writes a single ProRes 4444 review copy instead — same control,
        # same wording, as ADW-Blur's "Out .MOV".
        self.ip_out_mov_var = tk.BooleanVar(
            value=(self.ip_out_fmt_var.get() == "MOV"))
        def _ip_out_mov_changed():
            self.ip_out_fmt_var.set(
                "MOV" if self.ip_out_mov_var.get() else "EXR")
        _rfmt = tk.Frame(cvace, bg=S); _rfmt.pack(fill="x", pady=2)
        tk.Label(_rfmt, text="Output", font=FSM, bg=S, fg=G, width=12,
                 anchor="w").pack(side="left")
        tk.Checkbutton(_rfmt, text="Out .MOV",
            variable=self.ip_out_mov_var, command=_ip_out_mov_changed,
            bg=S, fg=W, selectcolor=R, activebackground=S,
            activeforeground=W, font=FSM, bd=0,
            highlightthickness=0).pack(side="left")
        _mov_info = tk.Label(_rfmt, text=" \u24d8", font=FSM, bg=S,
                             fg="#555555", cursor="hand2")
        _mov_info.pack(side="left", padx=(2, 0))
        _ip_info_popup(_mov_info,
            "Unchecked (default): a 32-bit linear EXR sequence, which is "
            "what the rest of the pipeline reads and the only format the "
            "wipe/diff compare can play back.\n\n"
            "Checked: a single ProRes 4444 .mov instead, for review. Much "
            "smaller than an uncompressed EXR sequence, but being a flat "
            "movie there are no frames left for the viewer to compare.")

        # A straight cut from the untouched plate into VACE's result can
        # show as a visible jump in look at the edges of a replaced
        # range. A crossfade blend used to be the fix here (the old
        # Feather); it's gone -- it can only ever hide a SMALL mismatch,
        # and a real content difference just shows through as a ghost/
        # double-exposure during the fade rather than a clean cut, so it
        # never reliably worked. The splice is now always a sharp cut.
        #
        # Tether fixes the actual cause instead of the symptom: it sends
        # this many extra REAL, untouched frames on each side of the
        # selection to VACE, so it has genuine moving footage to anchor
        # motion from -- not just a single static first/last still. Those
        # extra frames are discarded from the result before splicing;
        # only the selection itself is ever replaced. This is a
        # Generate-time setting (it changes what gets sent to VACE), not
        # a Run-time one -- change it and Generate again to take effect.
        #
        # Drawn as a snap-slider (tick marks + a draggable dot), the same
        # widget ADW-Blur's Blend Bias uses -- a plain tk.Scale on this
        # dark background was easy to miss.
        _rfth = tk.Frame(cvace, bg=S); _rfth.pack(fill="x", pady=(6, 2))
        tk.Label(_rfth, text="Tether", font=FSM, bg=S, fg=G,
                 width=11, anchor="w").pack(side="left")
        _fth_info = tk.Label(_rfth, text="\u24d8", font=FSM, bg=S,
                             fg="#555555", cursor="hand2")
        _fth_info.pack(side="left", padx=(0, 6))
        _ip_info_popup(_fth_info,
            "Sends this many extra REAL frames on each side of the\n"
            "selection to VACE, alongside it -- genuine moving footage\n"
            "for it to anchor motion from, instead of just a single\n"
            "static first/last still. Those extra frames are always\n"
            "discarded before the splice; only the selection itself is\n"
            "ever replaced, and the join is always a sharp cut.\n\n"
            "0 sends no extra context (just the selection, anchored by\n"
            "stills only, as before). Costs a little more, since fal\n"
            "bills for every second it actually processes -- the\n"
            "estimate above already includes it. A Generate-time\n"
            "setting: change it and Generate again to take effect.")
        _TETH_SNAP = list(range(0, 11))
        self.ip_tether_lbl = tk.Label(_rfth, text=" 4 ", font=FSM, bg=S,
                                      fg="#CC4444", width=4, anchor="e")
        self.ip_tether_lbl.pack(side="right")
        _teth_cv = tk.Canvas(_rfth, height=38, bg=S,
            highlightthickness=1, highlightbackground=BD, cursor="hand2")
        _teth_cv.pack(side="left", fill="x", expand=True, padx=(0, 4))

        def _teth_draw(*_):
            _teth_cv.delete("all")
            W3 = _teth_cv.winfo_width() or 200
            cur = self.ip_vace_tether_var.get()
            n = len(_TETH_SNAP)
            TY = 13
            def sx(i): return int(i / (n - 1) * (W3 - 8)) + 4
            _teth_cv.create_line(4, TY, W3 - 4, TY, fill="#333333", width=2)
            zx = sx(0)
            ci = _TETH_SNAP.index(cur) if cur in _TETH_SNAP else 0
            cx = sx(ci)
            if cx != zx:
                _teth_cv.create_line(zx, TY, cx, TY, fill="#CC4444", width=3)
            for ii, sv in enumerate(_TETH_SNAP):
                tx = sx(ii)
                if sv == 0:
                    _teth_cv.create_line(tx, TY - 8, tx, TY + 8,
                        fill="#888888", width=2)
                    _teth_cv.create_text(tx, TY + 11, text="0",
                        font=("Helvetica", 9, "bold"), fill="#888888",
                        anchor="n")
                else:
                    _teth_cv.create_line(tx, TY - 5, tx, TY + 5,
                        fill="#555555", width=1)
                    _teth_cv.create_text(tx, TY + 8, text=str(sv),
                        font=("Helvetica", 9), fill="#555555", anchor="n")
            _teth_cv.create_oval(cx - 6, TY - 7, cx + 6, TY + 7,
                fill=("#CC4444" if cur > 0 else "#888888"),
                outline="#888888", width=1)

        def _teth_snap(ex):
            W3 = _teth_cv.winfo_width() or 200
            t = max(0.0, min(1.0, (ex - 4) / max(1, W3 - 8)))
            fi = int(round(t * (len(_TETH_SNAP) - 1)))
            v = _TETH_SNAP[max(0, min(len(_TETH_SNAP) - 1, fi))]
            self.ip_vace_tether_var.set(v)

        def _teth_label_and_draw(*_):
            v = int(float(self.ip_vace_tether_var.get()))
            self.ip_tether_lbl.configure(text=f" {v} ",
                fg="#CC4444" if v > 0 else "#888888")
            _teth_draw()

        _teth_cv.bind("<Button-1>", lambda e: _teth_snap(e.x))
        _teth_cv.bind("<B1-Motion>", lambda e: _teth_snap(e.x))
        _teth_cv.bind("<Configure>", _teth_draw)
        self.ip_vace_tether_var.trace_add("write", _teth_label_and_draw)
        _teth_label_and_draw()

        def _vrow(label, var, width=None, show=None, trail=None):
            r = tk.Frame(cvace, bg=S); r.pack(fill="x", pady=1)
            tk.Label(r, text=label, font=FSM, bg=S, fg=G, width=12,
                     anchor="w").pack(side="left")
            # a trailing widget claims its space first; the entry then
            # fills what is left, rather than squeezing it to nothing
            if trail is not None:
                trail(r)
            e_ = tk.Entry(r, textvariable=var, bg="#0D0D0D", fg=W,
                          insertbackground=W, font=FM, bd=0,
                          highlightthickness=1, highlightbackground=BD,
                          show=show)
            if width:
                e_.configure(width=width); e_.pack(side="left")
            else:
                e_.pack(side="left", fill="x", expand=True)
            return r

        # Fill the prompt from the shot itself: motion words come free from
        # Analyse Motion, the description from one small vision-model call.
        def _add_prompt_btn(row):
            self.ip_prompt_btn = self._mkbtn(row, "\u2728  Describe shot",
                self._interp_autoprompt, bg="#0D0D0D", fg=W)
            tk.Label.configure(self.ip_prompt_btn._lbl, width=0, pady=3,
                               padx=8)
            self.ip_prompt_btn.pack(side="right", padx=(4, 0))
        _vrow("Prompt", self.ip_vace_prompt_var, trail=_add_prompt_btn)
        _rap = tk.Frame(cvace, bg=S); _rap.pack(fill="x", pady=(0, 1))
        tk.Label(_rap, text="", font=FSM, bg=S, fg=G, width=12,
                 anchor="w").pack(side="left")
        tk.Checkbutton(_rap,
            text="Auto-generate prompt per segment (motion words free, "
                 "one small captioning call per range)",
            variable=self.ip_autoprompt_var, bg=S, fg=W,
            activebackground=S, activeforeground=W, selectcolor=R,
            font=FSM, highlightthickness=0, bd=0,
            anchor="w").pack(side="left")
        _vrow("Negative", self.ip_vace_neg_var)
        _vrow("Seed", self.ip_vace_seed_var, width=10)

        # A live box-meter next to Steps: one half-height box per 5
        # steps, so the artist SEES the quality/speed trade-off change
        # shape as they type, instead of reading a bare number. Capped
        # at 30 boxes (150 steps) -- fal's own docs describe 30 as
        # already the endpoint's own default and higher values as
        # "better quality but take longer", so 150 is comfortably past
        # any value worth actually using.
        def _add_step_meter(row):
            self.ip_steps_meter = tk.Canvas(row, width=186, height=14,
                bg=S, highlightthickness=0, bd=0)
            self.ip_steps_meter.pack(side="left", padx=(6, 8))
        _vrow("Steps", self.ip_vace_steps_var, width=10,
              trail=_add_step_meter)
        self.ip_vace_steps_var.trace_add("write",
            lambda *_: self._interp_draw_step_meter())
        self._interp_draw_step_meter()
        _rsz = tk.Frame(cvace, bg=S); _rsz.pack(fill="x", pady=1)
        tk.Label(_rsz, text="Resolution", font=FSM, bg=S, fg=G, width=12,
                 anchor="w").pack(side="left")
        _sz = tk.OptionMenu(_rsz, self.ip_vace_res_var, "480p", "580p", "720p",
                            command=lambda _v: self._interp_update_span_label())
        _sz.configure(bg="#0D0D0D", fg=W, activebackground="#252525",
                      activeforeground=W, highlightthickness=1,
                      highlightbackground=BD, bd=0, font=FSM, anchor="w")
        _sz["menu"].configure(bg="#0D0D0D", fg=W, font=FSM)
        _sz.pack(side="left")
        self.ip_cost_lbl = tk.Label(_rsz, text="", font=FSM, bg=S, fg=G,
                                    anchor="w")
        self.ip_cost_lbl.pack(side="left", padx=(10, 0))

        self.ip_vace_btn = self._mkbtn(cvace, "\u26a1  Generate Interpolation",
            self._vace_generate, bg="#0A2A0A", fg="#66CC66")
        tk.Label.configure(self.ip_vace_btn._lbl, width=0, pady=8)
        self.ip_vace_btn.pack(fill="x", pady=(4, 0))

        # Now that every conditional row exists (Paint, Depth
        # quality) and _rup (the anchor to re-pack in front of) exist,
        # wire up the Method-driven show/hide: Mask shows Paint, Depth
        # shows Depth quality. Steps and Resolution apply to both
        # remaining methods, so they're just packed normally below and
        # aren't part of this toggle at all -- they only needed hiding
        # while Enhance existed (it had neither). before=_rup keeps a
        # re-shown row in its original position instead of jumping to
        # the end of the card, which plain pack_forget()+pack() would do.
        _mask_rows = (cpaint,)
        _depth_rows = (_rdepthq,)
        _all_conditional = _mask_rows + _depth_rows
        _notes = {
            "depth": "Depth mode: the whole frame is regenerated, "
                     "guided by depth \u2014 there is no mask, so Paint "
                     "does not apply.",
            "full": "Full image mode: the whole frame is regenerated, "
                    "guided directly by the real plate footage \u2014 no "
                    "mask (Paint does not apply) and no depth pass "
                    "(Depth quality does not apply either).",
        }
        def _method_changed(*_):
            m = self.ip_vace_method_var.get()
            self.ip_method_note.configure(text=_notes.get(m, ""))
            # Mask shows Paint; Depth shows Depth quality (it's the one
            # that actually runs the depth-estimation model); Full
            # image shows neither -- same whole-frame/no-mask shape as
            # Depth, but with no depth pass to size a quality dropdown
            # for.
            shown = (_depth_rows if m == "depth"
                     else _mask_rows if m == "inpainting" else ())
            for _row in _all_conditional:
                if _row in shown:
                    _row.pack(fill="x", pady=(1, 1), before=_rup)
                else:
                    _row.pack_forget()
            try:
                self._interp_render()
            except Exception:
                pass
            try:
                self._interp_update_span_label()
            except Exception:
                pass
        self.ip_vace_method_var.trace_add("write", _method_changed)
        _method_changed()
        self.ip_vace_stat = tk.Label(cvace, text="", font=FSM, bg=S,
            fg="#66CC66", anchor="w", wraplength=460, justify="left")
        self.ip_vace_stat.pack(fill="x", pady=(3, 0))
        self.ip_vace_apply_btn = self._mkbtn(cvace,
            "RUN ADW-INTERPOLATE \u2014 NOTHING REBUILT YET",
            self._vace_apply, bg="#2A0A0A", fg="#CC4444")
        tk.Label.configure(self.ip_vace_apply_btn._lbl, width=0, pady=8)
        self.ip_vace_apply_btn.pack(fill="x", pady=(3, 0))
        self.after(0, self._interp_refresh_vace_btn)

        # ── viewer + console live in the RIGHT column, in a vertical
        #    paned window: image on top, Activity Log below — same layout
        #    as ADW-Area / ADW-Curve.
        vpaned = self._make_paned(rf, "vertical")
        vpaned.pack(fill="both", expand=True)
        top_frame = tk.Frame(vpaned, bg=BG)
        vpaned.add(top_frame, minsize=140, height=360, stretch="always")
        vpaned._bind_pane_configure(top_frame)

        # ── viewer ───────────────────────────────────────────────────
        # Canvas toolbar, matching the other ADW modules: Wipe and Diff are
        # toggle buttons (lit when active), with the same hint line.
        ctbar = tk.Frame(top_frame, bg=BG)
        ctbar.pack(fill="x", padx=16, pady=(12, 3))
        tk.Label(ctbar, text="Source vs Result \u2014 drag to wipe  |  "
                 "click a frame's blue top for Result, red base for Source",
                 font=FSM, bg=BG, fg=G).pack(side="left")
        self.ip_wipe_btn = self._mkbtn(ctbar, "Wipe",
            self._interp_toggle_wipe, bg="#0D0D0D", fg=G)
        tk.Label.configure(self.ip_wipe_btn._lbl, width=6, pady=2)
        self.ip_wipe_btn.pack(side="right", padx=(2, 10))
        self.ip_diff_btn = self._mkbtn(ctbar, "\u25b3  Diff",
            self._interp_toggle_diff, bg="#0D0D0D", fg=G)
        tk.Label.configure(self.ip_diff_btn._lbl, width=0, pady=2, padx=8)
        self.ip_diff_btn.pack(side="right", padx=(2, 4))

        self.ip_canvas = tk.Canvas(top_frame, bg="#0A0A0A",
                                   highlightthickness=1, highlightbackground=BD)
        self.ip_canvas.pack(fill="both", expand=True, padx=16, pady=(0, 14))
        self.ip_canvas.bind("<Configure>", lambda e: self._interp_render())
        # drag the wipe line across the viewer
        self.ip_canvas.bind("<B1-Motion>", self._interp_canvas_drag)
        self.ip_canvas.bind("<Button-1>", self._interp_canvas_press)
        self.ip_canvas.bind("<ButtonRelease-1>", self._interp_canvas_release)

        # ── console: its own panel under the image, like other modules ──
        _iplogbot = tk.Frame(vpaned, bg=BG)
        vpaned.add(_iplogbot, minsize=80, height=150, stretch="never")
        vpaned._bind_pane_configure(_iplogbot)
        _iplogh = tk.Frame(_iplogbot, bg=BG)
        _iplogh.pack(fill="x", padx=16, pady=(4, 2))
        tk.Label(_iplogh, text="Activity Log", font=FSM, bg=BG,
                 fg=G).pack(side="left")
        _iplf = tk.Frame(_iplogbot, bg=S2, highlightthickness=1,
                         highlightbackground=BD)
        _iplf.pack(fill="both", expand=True, padx=16, pady=(0, 8))
        self.ip_log_txt = tk.Text(_iplf, bg=S2, fg=G, font=FM, bd=0,
            highlightthickness=0, wrap="word", state="disabled", padx=8, pady=6)
        self.ip_log_txt.pack(fill="both", expand=True, side="left")
        self._mk_scrollbar(_iplf, self.ip_log_txt).pack(side="right", fill="y")
        for tag, col in (("ok", "#7CBF7C"), ("err", "#CC4444"),
                         ("hi", "#CCAA44"), ("dim", "#555555")):
            self.ip_log_txt.tag_configure(tag, foreground=col)


        # ── timeline + range bar ─────────────────────────────────────
        _iptb = self._tl_frames["interp"]
        self._ip_range_bar = self._maya_range_bar(_iptb,
            lambda: [getattr(self, "ip_frame_cb", None)])
        _ip_hdr = tk.Frame(_iptb, bg=BG); _ip_hdr.pack(fill="x")
        # Cached playback: same engine as ADW-Curve / ADW-Area Look.
        # Right-click the Play button for the playback frame rate.
        self._pp_make_buttons("ip", _ip_hdr)

        # the result-name label sits by the timeline; the compare controls
        # live in the canvas toolbar above the viewer, like other modules
        _ip_vw = tk.Frame(_ip_hdr, bg=BG); _ip_vw.pack(side="right")
        self.ip_view_lbl = tk.Label(_ip_vw, text="No result yet", font=FSM,
                                    bg=BG, fg=G, anchor="e")
        self.ip_view_lbl.pack(side="right", padx=(8, 0))

        tk.Label(_ip_hdr, text="Frames  \u2014  drag a segment to move it, "
                 "drag its ends to resize",
                 font=FM, bg=BG, fg=G, anchor="w").pack(side="left")
        _ip_row = tk.Frame(_iptb, bg=BG); _ip_row.pack(fill="x")

        def _shade(hexcol, f):
            """Darken a segment colour by factor f, for its interior."""
            r_ = int(hexcol[1:3], 16); g_ = int(hexcol[3:5], 16)
            b_ = int(hexcol[5:7], 16)
            return "#%02X%02X%02X" % (int(r_ * f), int(g_ * f), int(b_ * f))

        def _ip_frame_color(i):
            # A segment always wins over the motion tint: the artist needs
            # to see exactly which frames are going to be extracted. The
            # active segment is full strength, the others dimmed; the two
            # end frames of each are brightest because they become the
            # conditioning stills AND they are the resize grips.
            def _under(idx):
                """The bottom half of a rebuilt frame: the original plate,
                shown as its motion tint (yellow=fast, red=slow) so the
                lower strip literally is the source you are comparing to."""
                if idx in self.ip_motion:
                    return self._motion_tint_color(self.ip_motion[idx])
                return "#CC7722"

            si = self._interp_seg_at(i)
            if si is not None:
                s_ = self.ip_segments[si]
                col = s_["color"]
                active = (si == self.ip_active)
                # every frame of the range is regenerated; the splice is
                # always a sharp cut now, so no fade toward the plate's
                # colour at the edges -- solid colour throughout the range
                top = col if active else _shade(col, 0.7)
                if s_.get("applied"):
                    # Rebuilt and spliced in: the generated (blue) frame
                    # takes the TOP half of the box, the original plate
                    # shows through the BOTTOM half — so you can read the
                    # before/after per frame straight off the timeline, and
                    # click either half to view it.
                    return (_under(i), top, 0.5)
                return top
            teth_si = self._interp_tether_at(i)
            if teth_si is not None:
                # Tether context: real footage, never regenerated, just
                # sent alongside the selection so VACE has motion to
                # anchor from. Half/half like "applied", but noticeably
                # MUTED rather than full-strength -- these frames were
                # never touched, so the block should read as "related to
                # this segment" without looking like already-generated
                # content the way the applied split does.
                s_ = self.ip_segments[teth_si]
                dim = _shade(s_["color"], 0.35 if teth_si == self.ip_active
                             else 0.2)
                return (_under(i), dim, 0.5)
            if self.ip_motion_tint_var.get() and i in self.ip_motion:
                return self._motion_tint_color(self.ip_motion[i])
            return None

        self._ip_frame_color = _ip_frame_color   # exposed so it is testable
        self.ip_frame_cb = self._timeline(_ip_row,
            lambda i: self._interp_timeline_frame(i), fill=True,
            get_frame_color=_ip_frame_color,
            get_frame_marker=lambda i: False,
            taller=True, show_numbers=True,
            drag_hooks={"press":   self._interp_drag_press,
                        "drag":    self._interp_drag_move,
                        "release": self._interp_drag_release,
                        "hover":   self._interp_drag_hover})

        # hotkeys, guarded to this tab
        def _ip_key(fn):
            def _h(e):
                if not self.tabs["interp"].winfo_ismapped():
                    return
                w = self.focus_get()
                if self._typing_in_field(w):
                    return
                fn()
                return "break"
            return _h
        # fill the preset dropdown from ADW-Blur's saved presets

        for _k, _fn in (("i", self._interp_set_in),
                        ("o", self._interp_set_out),
                        ("z", lambda: self._interp_step(-1)),
                        ("x", lambda: self._interp_step(+1))):
            self.bind_all(f"<KeyPress-{_k}>", _ip_key(_fn), add="+")
            self.bind_all(f"<KeyPress-{_k.upper()}>", _ip_key(_fn), add="+")

    # ── ADW-Interpolate: sequence, nav, render ───────────────────────
    # Seedance will not generate a clip shorter than this.
    IP_MIN_SECONDS = 2.0

    # One distinct colour per segment, cycled.
    # Kept clear of red/orange/yellow on purpose: Analyse Motion tints the
    # timeline red->orange->yellow, and a segment in that same band all
    # but disappears against a busy-motion background.
    IP_COLORS = ["#4499EE", "#44CC88", "#44CCCC", "#8888EE",
                 "#CC44CC", "#9955EE", "#22AA99", "#EE55AA"]

    # ── segments: the ranges to regenerate ────────────────────────────
    def _interp_seg_color(self, i):
        return self.IP_COLORS[i % len(self.IP_COLORS)]

    def _interp_active_seg(self):
        if not self.ip_segments:
            return None
        i = max(0, min(len(self.ip_segments) - 1, self.ip_active))
        return self.ip_segments[i]

    def _interp_seg_at(self, frame):
        """Which segment covers this frame. The active one wins a tie, so
        overlapping segments stay grabbable rather than the topmost
        always stealing the click."""
        act = self._interp_active_seg()
        if act and act["in"] <= frame <= act["out"]:
            # _interp_active_seg() already clamps ip_active into range;
            # returning the raw pointer here instead could hand back an
            # out-of-bounds index (e.g. after segments are deleted) and
            # crash the very next self.ip_segments[si] lookup.
            return self.ip_segments.index(act)
        for i, s in enumerate(self.ip_segments):
            if s["in"] <= frame <= s["out"]:
                return i
        return None

    def _interp_tether_at(self, frame):
        """Which segment's TETHER zone (extra real context frames sent to
        VACE alongside its selection, Mask method only) covers this
        frame -- None if the frame is inside a segment's own core range
        (that always takes precedence; check _interp_seg_at first), in
        no segment's padding at all, or Tether doesn't apply right now.

        Mirrors _vace_plan's own clamping exactly (same tether amount,
        same sequence-bounds clamp) so the preview always matches what
        Generate will actually send -- deliberately NOT calling
        _vace_plan itself, since that builds a whole dict per call and
        this runs on every timeline repaint, once per visible frame.
        """
        if getattr(self, "ip_vace_method_var", None) is not None \
                and self.ip_vace_method_var.get() in ("depth", "full"):
            return None
        tv = getattr(self, "ip_vace_tether_var", None)
        tether = max(0, min(10, int(tv.get()))) if tv is not None else 0
        if tether <= 0 or not self.ip_segments:
            return None
        n_total = len(self.ip_frames)
        for i, s in enumerate(self.ip_segments):
            a, b = s["in"], s["out"]
            if a <= frame <= b:
                continue   # core range -- not this function's concern
            send0 = max(0, a - tether)
            send1 = min(n_total - 1, b + tether)
            if send0 <= frame < a or b < frame <= send1:
                return i
        return None

    def _interp_mask_box_at(self, frame, real_size):
        """The regenerate box for THIS frame, in real image pixels, or
        None if the frame isn't inside any segment -- or if the Depth
        or Full image method is selected, neither of which has a mask
        at all to preview.

        Mirrors exactly what _vace_build_source_clip/_vace_build_mask_clip
        will actually send to VACE -- same coverage -- so this can be
        drawn as a live preview of the mask rather than the person
        having to imagine it from a percentage label. The box is the
        same on every frame of the range (no more per-frame tapering).
        """
        if getattr(self, "ip_vace_method_var", None) is not None \
                and self.ip_vace_method_var.get() in ("depth", "full"):
            return None
        si = self._interp_seg_at(frame)
        if si is None:
            return None
        coverage = max(5, min(100, int(self.ip_vace_coverage_var.get()))) / 100.0
        return self._vace_mask_box(real_size, coverage)

    def _interp_clamp_seg(self, s, n=None):
        """Force a segment legal: at least the 2s minimum, and inside the
        sequence. Returns True if it had to change anything."""
        if n is None:
            n = len(self.ip_frames)
        if n <= 0:
            return False
        need = min(self._interp_min_frames(), n)
        before = (s["in"], s["out"])
        s["in"] = max(0, min(n - 1, int(s["in"])))
        s["out"] = max(0, min(n - 1, int(s["out"])))
        if s["out"] < s["in"]:
            s["in"], s["out"] = s["out"], s["in"]
        if s["out"] - s["in"] + 1 < need:
            s["out"] = s["in"] + need - 1
            if s["out"] > n - 1:              # ran off the end: push back
                s["out"] = n - 1
                s["in"] = max(0, s["out"] - need + 1)
        return (s["in"], s["out"]) != before

    def _interp_seg_frames(self, s):
        return s["out"] - s["in"] + 1

    def _interp_seg_secs(self, s):
        return self._interp_seg_frames(s) / self._interp_fps()

    def _interp_add_segment(self, at=None):
        """A new segment starts at the current frame and runs for the 2s
        minimum, so it is immediately valid and can just be dragged."""
        if not self.ip_frames:
            self.log(self.ip_log_txt, "Load a sequence first.", "err")
            return None
        n = len(self.ip_frames)
        need = min(self._interp_min_frames(), n)
        start = self.ip_idx if at is None else at
        start = max(0, min(n - need, start)) if n >= need else 0
        s = {"name": f"R{len(self.ip_segments) + 1}",
             "color": self._interp_seg_color(len(self.ip_segments)),
             "in": start, "out": min(n - 1, start + need - 1),
             }
        self._interp_clamp_seg(s, n)
        self.ip_segments.append(s)
        self.ip_active = len(self.ip_segments) - 1
        self._interp_segments_changed()
        self.log(self.ip_log_txt,
            f"Added {s['name']}: frames {s['in']+1}\u2013{s['out']+1} "
            f"({self._interp_seg_secs(s):.2f}s).", "ok")
        return s

    def _interp_del_segment(self, i):
        if not (0 <= i < len(self.ip_segments)):
            return
        name = self.ip_segments[i]["name"]
        self.ip_segments.pop(i)
        # keep the colours matching their position in the list
        for k, s in enumerate(self.ip_segments):
            s["color"] = self._interp_seg_color(k)
        self.ip_active = max(0, min(self.ip_active, len(self.ip_segments) - 1))
        self._interp_segments_changed()
        self.log(self.ip_log_txt, f"Removed {name}.", "dim")

    # ── dragging segments on the timeline ─────────────────────────────
    def _interp_edge_zone(self, s):
        """How many frames at each end count as a resize grip. Scaled to
        the segment so a long one doesn't get a hair-thin grip, capped so
        a short one still has a middle you can grab to move it."""
        n = self._interp_seg_frames(s)
        return max(1, min(3, n // 10))

    def _interp_drag_press(self, frame, ev):
        """Grab a segment. Near an end = resize that end; in the middle =
        move the whole thing. Returns True when we take the event, so the
        playhead does not scrub out from under the drag."""
        if not self.ip_frames or not self.ip_segments:
            return False
        si = self._interp_seg_at(frame)
        if si is None:
            return False
        s = self.ip_segments[si]
        self.ip_active = si
        z = self._interp_edge_zone(s)
        if frame <= s["in"] + z - 1:
            mode = "left"
        elif frame >= s["out"] - z + 1:
            mode = "right"
        else:
            mode = "move"
        self._ip_drag = {"seg": si, "mode": mode, "grab": frame,
                         "in0": s["in"], "out0": s["out"], "moved": False}
        self._ip_rebuild_tabs_fn()
        return True

    def _interp_drag_move(self, frame, ev):
        d = getattr(self, "_ip_drag", None)
        if not d:
            return False
        n = len(self.ip_frames)
        s = self.ip_segments[d["seg"]]
        need = min(self._interp_min_frames(), n)
        shift = frame - d["grab"]
        if d["mode"] == "move":
            # length is preserved; slide, then clamp against both ends
            ln = d["out0"] - d["in0"] + 1
            new_in = max(0, min(n - ln, d["in0"] + shift))
            s["in"] = new_in
            s["out"] = new_in + ln - 1
        elif d["mode"] == "left":
            # the 2s minimum is a hard floor: the In can never come
            # closer to the Out than that
            s["in"] = max(0, min(d["out0"] - need + 1, d["in0"] + shift))
            s["out"] = d["out0"]
        else:
            s["out"] = min(n - 1, max(d["in0"] + need - 1, d["out0"] + shift))
            s["in"] = d["in0"]
        self._interp_clamp_seg(s, n)
        # Only count it as a drag if the segment ACTUALLY moved. Otherwise
        # a plain click (press + release on the same frame) would be
        # treated as a drag and swallow the scrub.
        if shift != 0:
            d["moved"] = True
        self._interp_update_span_label()
        self._ip_rebuild_tabs_fn()
        self._interp_render()
        return True

    def _interp_drag_release(self, frame, ev):
        d = getattr(self, "_ip_drag", None)
        if not d:
            return False
        self._ip_drag = None
        if d["moved"]:
            s = self.ip_segments[d["seg"]]
            # it covers different frames now, so anything generated or
            # spliced for it no longer corresponds to it
            self._interp_drop_result(s, "moved")
            secs = self._interp_seg_secs(s)
            msg = (f"{s['name']}: frames {s['in']+1}\u2013{s['out']+1} "
                   f"({self._interp_seg_frames(s)} f, {secs:.2f}s)")
            if d["mode"] != "move" and self._interp_seg_frames(s) <= 2:
                msg += "  \u2014 at the 2-frame minimum"
            self.log(self.ip_log_txt, msg, "dim")
        else:
            # It was a CLICK, not a drag. The press hook consumed the event
            # to stop the playhead scrubbing out from under a drag — so if
            # no drag happened, we owe the user the scrub. Without this you
            # cannot click any frame inside a segment, which is precisely
            # the frames you want to look at.
            self._interp_show_frame(frame)
            # On an applied segment the box is split: the segment colour on
            # top, the original frame showing through below. Clicking a half
            # switches to what that half depicts.
            s0 = self.ip_segments[d["seg"]]
            if s0.get("applied") and ev is not None:
                try:
                    zone = self.ip_frame_cb.y_zone(ev.y)
                except Exception:
                    zone = None
                # The box is split: blue (generated) on top, red/yellow
                # (original) below. Click a half to VIEW that half, plainly
                # and without a wipe. Turning off any active compare mode is
                # the point — you asked to see one or the other.
                if self.ip_result_dir and self._interp_frame_rebuilt(frame):
                    if zone == "top":
                        self._ip_cmp_mode = "off"
                        self._interp_refresh_cmp_btns()
                        self.ip_view_var.set("Result")
                        self._interp_set_view("Result", jump=False)
                    elif zone == "bottom":
                        self._ip_cmp_mode = "off"
                        self._interp_refresh_cmp_btns()
                        self.ip_view_var.set("Source")
                        self._interp_set_view("Source", jump=False)
                    else:
                        self._interp_render()
                elif zone == "bottom" and self._ip_view != "Source":
                    self.ip_view_var.set("Source")
                    self._interp_set_view("Source", jump=False)
                elif zone == "top" and self._ip_view != "Result":
                    self.ip_view_var.set("Result")
                    self._interp_set_view("Result", jump=False)
        self._interp_segments_changed()
        return True

    def _interp_drag_hover(self, frame, ev):
        """Cursor tells you what a drag would do before you commit to it."""
        if getattr(self, "_ip_drag", None):
            return False
        cur = ""
        si = self._interp_seg_at(frame) if self.ip_segments else None
        if si is not None:
            s = self.ip_segments[si]
            z = self._interp_edge_zone(s)
            if frame <= s["in"] + z - 1 or frame >= s["out"] - z + 1:
                cur = "sb_h_double_arrow"
            else:
                cur = "fleur"
        try:
            self.ip_frame_cb.set_cursor(cur)
        except Exception:
            pass
        return False




    def _interp_seg_state(self, s):
        """Where this segment is in the pipeline. Drives the Generate
        button, the segment tab and the timeline, so all three agree."""
        if s.get("applied"):
            return "applied"
        if self._ip_vace_result.get(s["name"]):
            d = self._ip_vace_result[s["name"]]
            if d and os.path.isdir(d) and os.listdir(d):
                return "generated"
        return "new"

    IP_STATE_GLYPH = {"new": "\u25cb",        # hollow: nothing yet
                      "generated": "\u25c9",  # filled ring: rebuilt, not in
                      "applied": "\u2713"}    # tick: spliced into the shot

    def _interp_drop_result(self, s, why):
        """The segment changed, so anything generated for it no longer
        corresponds to it. Say so rather than leaving a stale result
        quietly attached to the wrong frames."""
        name = s["name"]
        had = bool(self._ip_vace_result.pop(name, None))
        was_applied = s.pop("applied", None)
        if had or was_applied:
            self.log(self.ip_log_txt,
                f"{name}: {why} \u2014 the previous VACE result no longer "
                "matches, so it has been cleared. Generate again.", "hi")
        return had

    def _interp_refresh_vace_btn(self):
        """The Generate button reports the ACTIVE segment's state."""
        if not hasattr(self, "ip_vace_btn") or self._ip_vace_busy:
            return
        s = self._interp_active_seg()
        if s is None:
            self.ip_vace_btn.configure(text="\u26a1  Generate Interpolation",
                                       bg="#0A2A0A", fg="#66CC66")
            self.ip_vace_apply_btn.configure(
                state="disabled",
                text="RUN ADW-INTERPOLATE \u2014 NOTHING REBUILT YET")
            return
        st = self._interp_seg_state(s)
        if st == "applied":
            self.ip_vace_btn.configure(
                text=f"\u2713  {s['name']} is in the shot  \u2014  "
                     "Re-generate Interpolation",
                bg="#0A3A0A", fg="#88EE88")
        elif st == "generated":
            self.ip_vace_btn.configure(
                text=f"\u25c9  {s['name']} rebuilt  \u2014  "
                     "Re-generate Interpolation",
                bg="#0A3A0A", fg="#88EE88")
        else:
            self.ip_vace_btn.configure(text="\u26a1  Generate Interpolation",
                                       bg="#0A2A0A", fg="#66CC66")
        # Apply is only meaningful once SOMETHING is rebuilt
        ready = [x for x in self.ip_segments
                 if self._interp_seg_state(x) == "generated"]
        n_app = [x for x in self.ip_segments
                 if self._interp_seg_state(x) == "applied"]
        if ready:
            self.ip_vace_apply_btn.configure(
                state="normal",
                text=f"RUN ADW-INTERPOLATE ON SEQUENCE \u2014 "
                     f"{len(ready)} REBUILT SEGMENT(S)")
        elif n_app:
            self.ip_vace_apply_btn.configure(
                state="normal",
                text=f"RUN ADW-INTERPOLATE ON SEQUENCE \u2014 "
                     f"{len(n_app)} ALREADY IN THE SEQUENCE")
        else:
            self.ip_vace_apply_btn.configure(
                state="disabled",
                text="RUN ADW-INTERPOLATE \u2014 NOTHING REBUILT YET")

    def _interp_segments_changed(self):
        if hasattr(self, "_ip_rebuild_tabs_fn"):
            self._ip_rebuild_tabs_fn()
        self._interp_update_span_label()
        self._interp_refresh_vace_btn()
        if hasattr(self, "ip_frame_cb"):
            self.ip_frame_cb.refresh()
        self._interp_render()


    def _interp_fps(self):
        """The MOV fps, falling back to 24 if the field is nonsense —
        used for the minimum-duration maths as well as the encodes."""
        try:
            f = float(self.ip_fps_var.get())
            return f if f > 0 else 24.0
        except Exception:
            return 24.0

    def _interp_min_frames(self):
        """VACE needs a first and a last frame to generate between, so the
        floor is 2. No Seedance 2-second minimum any more."""
        return 2

    def _interp_src_frame_no(self, idx):
        """The frame number the artist knows this frame by: the trailing
        digits of the source filename (f_0120.png -> 120), so the export
        traces straight back to the plate. Falls back to the sequence
        index when the name carries no number."""
        import re
        if not (0 <= idx < len(self.ip_frames)):
            return idx
        m = re.findall(r"(\d+)", os.path.splitext(self.ip_frames[idx])[0])
        return int(m[-1]) if m else idx

    def _interp_still_name(self, prefix, idx, fps):
        """e.g. range1First_3.5s_f0120.png — the timecode is the frame's
        position in the sequence, the frame number is the source one."""
        t = idx / float(fps if fps else 24.0)
        return f"{prefix}_{t:.1f}s_f{self._interp_src_frame_no(idx):04d}.png"

    def _interp_pick_folder(self):
        d = filedialog.askdirectory(title="Sequence folder")
        if d:
            self._interp_load_folder(d)

    def _interp_load_folder(self, folder):
        frames = sorted(f for f in os.listdir(folder)
            if os.path.splitext(f)[1].lower() in
            {".png", ".exr", ".tif", ".tiff", ".jpg", ".jpeg"})
        if not frames:
            messagebox.showwarning("No frames found",
                "No image sequence found in that folder.")
            return
        self.ip_folder = folder
        self.ip_frames = frames
        self.ip_idx = 0
        self.ip_motion = {}
        self.ip_ram_cache = {}
        self.ip_segments = []
        self.ip_active = 0
        self._ip_drag = None
        # remember the plate: the Result view swaps ip_frames out, and we
        # need to be able to swap back
        self.ip_src_folder = folder
        self.ip_src_frames = list(frames)
        # basename -> source path, so the wipe can pair a result PNG back
        # to its plate frame whatever the plate's extension was
        self._ip_src_by_base = {
            os.path.splitext(f)[0]: os.path.join(folder, f) for f in frames}
        self.ip_result_dir = None
        self._ip_view = "Source"
        self._ip_vace_result = {}
        try:
            self.ip_view_var.set("Source")
        except Exception:
            pass
        self._interp_refresh_view_btn()
        # a new sequence invalidates any cached playback frames
        self._pp_stop("ip", quiet=True)
        self._pp_state("ip")["cache"] = None
        self.ip_lbl.configure(
            text=f"OK  {os.path.basename(folder)}  ({len(frames)} frames)",
            fg=GR)
        self._interp_cache_info_update()
        self._interp_update_span_label()
        if hasattr(self, "_ip_range_bar"):
            self._ip_range_bar.set_n(len(frames))
        if hasattr(self, "ip_frame_cb"):
            self.ip_frame_cb.set_frames(frames)
            self.ip_frame_cb.refresh()
        self.log(self.ip_log_txt,
            f"Loaded {len(frames)} frames from {os.path.basename(folder)}.",
            "ok")
        self._interp_show_frame(0)

    def _interp_pv(self, idx):
        """Decoded source frame. Goes straight to the shared LRU — this
        module deliberately holds no cache of its own, since all it
        needs from a scan is the motion score, not the pixels."""
        return self._ip_pv_frame(os.path.join(self.ip_folder,
                                           self.ip_frames[idx]))

    def _interp_display_pil(self, idx):
        return self._interp_pv(idx)

    def _interp_show_frame(self, i):
        if not self.ip_frames:
            return
        self.ip_idx = max(0, min(len(self.ip_frames) - 1, int(i)))
        self.ip_frame_lbl.configure(
            text=f"{self.ip_idx + 1} / {len(self.ip_frames)}   "
                 f"{self.ip_frames[self.ip_idx]}")
        if hasattr(self, "ip_frame_cb"):
            self.ip_frame_cb.select(self.ip_idx)
        self._interp_render()

    def _interp_step(self, d):
        if self.ip_frames:
            self._interp_show_frame(self.ip_idx + d)

    def _interp_timeline_frame(self, i):
        self._interp_show_frame(i)

    # ── hooks the shared playback engine (_pp_*) expects ─────────────
    # ADW-Interpolate has no correction pass, so "corrected" is just the
    # source and the wipe furniture is suppressed via _pp_has_wipe.
    def _ip_cs_changed(self):
        """The "EXR is" dropdown just changed -- every cached preview
        was built under the OLD assumption and is now wrong, not just
        stale. Cleared rather than left to expire naturally, since the
        whole point is seeing the correction immediately, on the
        frame already on screen.

        An OrderedDict, not a plain {} -- _ip_pv_frame calls
        .move_to_end() on a cache hit, which only exists on
        OrderedDict. A plain dict here works right up until the first
        repeat lookup, then crashes with "'dict' object has no
        attribute 'move_to_end'"."""
        import collections
        self._ip_pv_lru = collections.OrderedDict()
        self._interp_show_frame(self.ip_idx)

    def _ip_source_is_encoded(self):
        """ADW-Interpolate's own colour-space setting, falling back to
        the app-wide default -- same pattern as Fix Missing Frames'
        _ff_source_encoded, which this tab never had until now."""
        v = getattr(self, "ip_cs_var", None)
        if v is not None:
            return v.get() == "Display-encoded"
        return self._adw_source_is_encoded()

    def _ip_pv_frame(self, path):
        """The colour-space-aware equivalent of _pv_frame, used ONLY
        within this tab. Anything but an EXR delegates straight to
        _pv_frame, unchanged.

        An EXR instead goes through this app's own proven reader
        (_ff_read_frame) and the SAME evidence/setting-based
        linear-or-not decision Fix Missing Frames already uses
        (_ff_is_linear + _organic_linear_to_display) -- rather than
        _pv_frame's ffmpeg-based path, which decodes EXR with
        tonemap=reinhard. That filter is an HDR-to-SDR COMPRESSOR, not
        an OETF: it does nothing to gamma-encode ordinary linear data
        for display, so a genuinely scene-linear EXR (as this app's
        own MOV -> EXR conversion can produce) comes back looking
        "extremely dark" -- the raw linear numbers, numerically much
        smaller than their correctly display-encoded counterparts for
        the same apparent brightness, shown with no correction at all.

        Cached the same way _pv_frame caches (path, mtime), in a
        separate dict, so repeated scrubbing over the same frames
        during playback stays free after the first read."""
        from PIL import Image
        import numpy as np, collections
        if os.path.splitext(path)[1].lower() != ".exr":
            return self._pv_frame(path)
        if not hasattr(self, "_ip_pv_lru"):
            self._ip_pv_lru = collections.OrderedDict()
        try:
            mt = os.path.getmtime(path)
        except OSError:
            mt = 0
        key = (path, mt)
        lru = self._ip_pv_lru
        if key in lru:
            lru.move_to_end(key)
            return lru[key]
        arr = self._ff_read_frame(path)
        if arr is None:
            return self._pv_frame(path)   # fall back rather than crash
        # A sidecar (written by this app's own MOV -> EXR, ADW-Organic,
        # or Upscale & Expand) is real evidence and takes priority over
        # the manual dropdown -- the dropdown exists for exactly the
        # cases with no such evidence, like a sequence converted
        # before this fix existed, or one from outside this app.
        cs_tag = self._adw_read_colorspace(os.path.dirname(path))
        is_linear = (cs_tag == "scene-linear" if cs_tag is not None
                    else self._ff_is_linear(path, self._ip_source_is_encoded()))
        if is_linear:
            disp = self._organic_linear_to_display(arr)
        else:
            disp = (np.clip(arr, 0.0, 1.0) * 255.0 + 0.5).astype(np.uint8)
        img = Image.fromarray(disp, "RGB")
        lru[key] = img
        while len(lru) > 64:
            lru.popitem(last=False)
        return img

    def _ip_load_frame(self, path):
        """Feeds the playback engine AND the wipe.

        The wipe always compares the SOURCE plate against the spliced
        RESULT, whichever view the still happens to be on — so dragging
        the handle across a filled gap shows you exactly what changed.
        Both sides are resolved by frame BASENAME, because Apply writes
        PNGs whatever the plate's extension was.
        """
        base = os.path.splitext(os.path.basename(path))[0]

        src = None
        if self.ip_src_folder:
            src = self._ip_src_by_base.get(base)
        self.ip_img_base = self._ip_pv_frame(src or path)

        self._ip_wipe_corrected_base = None
        # map by index: results are an ordered sequence, names differ
        try:
            _ridx = self.ip_frames.index(os.path.basename(path))
        except (ValueError, AttributeError):
            _ridx = self.ip_idx
        cand = self._interp_result_frame(_ridx)
        if cand:
            self._ip_wipe_corrected_base = self._ip_pv_frame(cand)
        return self.ip_img_base

    def _ip_frame_selected(self):
        """Called when playback stops, to land the UI on that frame."""
        try:
            self.ip_idx = self.ip_frame_cb.current()
        except Exception:
            pass
        self._interp_show_frame(self.ip_idx)

    def _interp_draw_step_meter(self):
        """Redraw the Steps box-meter to match the current value: one
        half-height box per 5 steps (rounded down), capped at 30 boxes
        (150 steps). Runs on every keystroke via the StringVar trace,
        same live-update pattern as the exposure/gamma toolbar
        elsewhere in this app -- the visual updates as you type, not
        only after you tab away or hit a button."""
        cv = getattr(self, "ip_steps_meter", None)
        if cv is None:
            return
        try:
            steps = int(self.ip_vace_steps_var.get())
        except (ValueError, TypeError):
            steps = 0
        n_boxes = max(0, min(30, steps // 5))
        cv.delete("all")
        bw, gap, h = 4, 2, 14
        for i in range(n_boxes):
            x0 = i * (bw + gap)
            cv.create_rectangle(x0, h - 8, x0 + bw, h,
                fill="#66CC66", outline="")
        if n_boxes == 0 and steps > 0:
            # under 5 -- still show something rather than an empty
            # canvas implying the field didn't register at all
            cv.create_rectangle(0, h - 4, bw, h, fill="#448844",
                outline="")

    def _interp_render(self, live_paint=False):
        cv = getattr(self, "ip_canvas", None)
        if cv is None or not self.ip_frames:
            return
        from PIL import ImageTk
        try:
            src_pil, res_pil = self._interp_wipe_pair(self.ip_idx)
        except Exception as ex:
            self.log(self.ip_log_txt, f"Decode failed: {ex}", "err")
            return
        cw = max(1, cv.winfo_width()); ch = max(1, cv.winfo_height())
        iw, ih = src_pil.size
        s = min(cw / iw, ch / ih)
        dw, dh = max(1, int(iw * s)), max(1, int(ih * s))
        ox, oy = (cw - dw) // 2, (ch - dh) // 2
        self._ip_disp_rect = (ox, oy, dw, dh)
        self._ip_disp_real_size = (iw, ih)

        compare = (res_pil is not None and self._interp_wipe_on()
                   and self._ip_cmp_mode in ("wipe", "diff"))
        if compare and self._ip_cmp_mode == "diff":
            # Amplified per-pixel difference, like ADW-Blur's diff: black
            # where source and result agree, bright where they differ.
            from PIL import ImageChops, ImageOps
            left = src_pil.resize((dw, dh)).convert("RGB")
            right = res_pil.resize((dw, dh)).convert("RGB")
            d = ImageChops.difference(left, right)
            d = ImageOps.autocontrast(d, cutoff=0)
            self._ip_tk = ImageTk.PhotoImage(d)
            cv.delete("all")
            cv.create_image(ox, oy, anchor="nw", image=self._ip_tk)
            cv.create_text(ox + 6, oy + 8, anchor="nw",
                           text="Difference (Source \u2194 Result)",
                           fill="#66CC66", font=FM)
        elif compare:
            # Source on the LEFT of the line, Result on the RIGHT — one
            # composited image with a single hard seam, like ADW-Blur.
            wl = max(0.0, min(1.0, self._ip_wipe_t))
            cut = int(dw * wl)
            left = src_pil.resize((dw, dh))
            right = res_pil.resize((dw, dh))
            comp = right.copy()
            if cut > 0:
                comp.paste(left.crop((0, 0, cut, dh)), (0, 0))
            self._ip_tk = ImageTk.PhotoImage(comp)
            cv.delete("all")
            cv.create_image(ox, oy, anchor="nw", image=self._ip_tk)
            lx = ox + cut
            cv.create_line(lx, oy, lx, oy + dh, fill="#FFCC00", width=2)
            cv.create_rectangle(lx - 5, oy + dh // 2 - 12, lx + 5,
                                oy + dh // 2 + 12, fill="#FFCC00",
                                outline="")
            cv.create_text(ox + 6, oy + 8, anchor="nw", text="Source",
                           fill="#FFCC00", font=FM)
            cv.create_text(ox + dw - 6, oy + 8, anchor="ne", text="Result",
                           fill="#66CC66", font=FM)
        else:
            # no compare mode: show ONE image, and show the GENERATED
            # one automatically whenever there is one for this frame --
            # pre-Export (a segment's own raw VACE result) or post-
            # Export (the spliced output on disk), _interp_wipe_pair/
            # _interp_result_frame don't distinguish and neither does
            # this. There is no separate "switch to Result" step any
            # more: the whole point is seeing the new generation the
            # moment it exists, just by scrubbing. Wipe/Diff (above)
            # remains how to deliberately compare against the original
            # plate.
            one = res_pil if res_pil is not None else src_pil
            disp = one.resize((dw, dh))
            self._ip_tk = ImageTk.PhotoImage(disp)
            cv.delete("all")
            cv.create_image(ox, oy, anchor="nw", image=self._ip_tk)
            if res_pil is not None:
                cv.create_text(ox + 6, oy + 8, anchor="nw", text="Generated",
                               fill="#66CC66", font=FM)

        si = self._interp_seg_at(self.ip_idx) if self.ip_segments else None
        if si is not None:
            s_ = self.ip_segments[si]
            rebuilt = res_pil is not None
            if rebuilt and not compare:
                cv.create_text(12, ch - 16, anchor="nw",
                    text=f"{s_['name']} \u2014 rebuilt. Timeline: blue top = "
                         "result, red base = source. Wipe/Diff to compare.",
                    fill="#66CC66", font=FM)
            elif not rebuilt:
                cv.create_text(12, ch - 16, anchor="nw",
                    text=f"{s_['name']} \u2014 outside the selected range "
                         "(unchanged)", fill="#888888", font=FM)

            # The mask itself. If a brush mask has been painted for this
            # segment, that shape IS the regenerate area -- draw its real
            # outline. Otherwise fall back to the auto-centred box (same
            # coverage/taper maths that will actually be sent to VACE).
            # Only meaningful on the untouched plate.
            if not compare and self._ip_view != "Result":
                brush_mask = s_.get("brush_mask")
                if brush_mask is not None:
                    self._interp_draw_brush_outline(cv, brush_mask,
                        (ox, oy, dw, dh), (iw, ih))
                else:
                    box = self._interp_mask_box_at(self.ip_idx, (iw, ih))
                    if box is not None:
                        x0, y0, x1, y1 = box
                        bx0, by0 = ox + x0 * s, oy + y0 * s
                        bx1, by1 = ox + x1 * s, oy + y1 * s
                        full = (x1 - x0) >= iw - 1 and (y1 - y0) >= ih - 1
                        if not full:
                            cv.create_rectangle(bx0, by0, bx1, by1,
                                outline="#FFCC00", width=2, dash=(6, 4))
                            cv.create_text(bx0 + 6, by0 + 6, anchor="nw",
                                text="regenerate", fill="#FFCC00", font=FM)
                        else:
                            cv.create_rectangle(ox + 2, oy + 2, ox + dw - 2,
                                oy + dh - 2, outline="#FFCC00", width=2,
                                dash=(6, 4))
                            cv.create_text(ox + 6, oy + dh - 20, anchor="nw",
                                text="regenerate: whole frame",
                                fill="#FFCC00", font=FM)

        # the in-progress brush stroke, drawn live while dragging -- same
        # stippled-line technique as ADW-Area's Look brush
        if live_paint and self.ip_paint_pts and len(self.ip_paint_pts) >= 1:
            r2 = getattr(self, "_ip_disp_rect", None)
            if r2:
                ox2, oy2, dw2, dh2 = r2
                sz2 = getattr(self, "_ip_disp_real_size", None) or (iw, ih)
                sc = dw2 / max(1, sz2[0])
                pts_c = []
                for (x, y) in self.ip_paint_pts:
                    pts_c.extend([ox2 + x * sc, oy2 + y * sc])
                brush_px = max(1, int(self.ip_brush_size_var.get()))
                canvas_w = max(2, int(round(brush_px * sc)))
                if len(pts_c) >= 4:
                    cv.create_line(*pts_c, fill="#FFCC00", width=canvas_w,
                        smooth=True, capstyle="round", joinstyle="round",
                        stipple="gray25")
                else:
                    cv.create_oval(pts_c[0] - canvas_w / 2,
                        pts_c[1] - canvas_w / 2, pts_c[0] + canvas_w / 2,
                        pts_c[1] + canvas_w / 2, outline="#FFCC00",
                        stipple="gray25", fill="#FFCC00")

    def _interp_draw_brush_outline(self, cv, mask, disp_rect, real_size):
        """Draw the real outline of a painted brush mask on the canvas,
        in image coordinates mapped through the current display rect."""
        import cv2, numpy as np
        ox, oy, dw, dh = disp_rect
        iw, ih = real_size
        mh, mw = mask.shape
        sx, sy = dw / max(1, mw), dh / max(1, mh)
        u8 = (mask.astype(np.uint8)) * 255
        contours, _ = cv2.findContours(u8, cv2.RETR_EXTERNAL,
                                       cv2.CHAIN_APPROX_SIMPLE)
        for c in contours:
            pts = c.reshape(-1, 2)
            if len(pts) < 2:
                continue
            flat = []
            for (x, y) in pts:
                flat.extend([ox + x * sx, oy + y * sy])
            cv.create_line(*flat, ox + pts[0][0] * sx, oy + pts[0][1] * sy,
                fill="#FFCC00", width=2, dash=(6, 4))
        if contours:
            x, y, w, h = cv2.boundingRect(contours[0])
            cv.create_text(ox + x * sx + 6, oy + y * sy + 6, anchor="nw",
                text="regenerate (painted)", fill="#FFCC00", font=FM)

    def _interp_wipe_on(self):
        """Show the wipe only where there is something to compare: a
        result exists for this exact frame -- either already spliced
        to disk (Export/Apply) or still just a per-segment VACE result
        that hasn't been exported yet -- and the user has not
        collapsed the wipe fully to one side."""
        return self._interp_result_frame(self.ip_idx) is not None

    def _interp_result_frame(self, idx):
        """The generated frame for this index, if any -- checked two
        ways, in priority order:

        1) Exported: the spliced Insert output on disk (an index-
           ordered EXR/PNG sequence, ADW-Interpolate.00000.exr ...),
           mapped by position, not basename. This is the real, final,
           versioned output, so it wins whenever it exists.

        2) Not yet exported: a segment's own raw VACE result folder
           (self._ip_vace_result), consulted as a fallback whenever
           (1) has nothing for this index. _vace_apply itself later
           splices this the exact same positional way -- generated
           frame j becomes the segment's (in + j)-th replaced frame --
           so checking it here too means scrubbing shows the new
           result the moment Generate finishes, with no separate
           Apply/Export step first.
        """
        if self.ip_result_dir and os.path.isdir(self.ip_result_dir):
            if not hasattr(self, "_ip_result_files") or \
                    self._ip_result_dir_cached != self.ip_result_dir:
                self._ip_result_files = sorted(
                    f for f in os.listdir(self.ip_result_dir)
                    if os.path.splitext(f)[1].lower()
                    in (".exr", ".png", ".tif", ".tiff", ".jpg", ".jpeg"))
                self._ip_result_dir_cached = self.ip_result_dir
            if 0 <= idx < len(self._ip_result_files):
                return os.path.join(self.ip_result_dir,
                                    self._ip_result_files[idx])
        si = self._interp_seg_at(idx) if self.ip_segments else None
        if si is None:
            return None
        seg = self.ip_segments[si]
        d = self._ip_vace_result.get(seg["name"])
        if not d or not os.path.isdir(d):
            return None
        cache_key = (seg["name"], d)
        if getattr(self, "_ip_seg_result_cache_key", None) != cache_key:
            self._ip_seg_result_files = sorted(
                f for f in os.listdir(d)
                if os.path.splitext(f)[1].lower() in (".png", ".exr", ".jpg"))
            self._ip_seg_result_cache_key = cache_key
        pos = idx - seg["in"]
        if 0 <= pos < len(self._ip_seg_result_files):
            return os.path.join(d, self._ip_seg_result_files[pos])
        return None

    def _interp_wipe_pair(self, idx):
        """(source_pil, result_pil) for this frame. result is None when
        nothing was generated for it, in which case the viewer shows the
        plate whole."""
        name = self.ip_src_frames[idx] if idx < len(self.ip_src_frames) \
               else self.ip_frames[idx]
        base = os.path.splitext(os.path.basename(name))[0]
        src_path = self._ip_src_by_base.get(base) if self._ip_src_by_base \
                   else os.path.join(self.ip_folder, self.ip_frames[idx])
        # The dedicated RAM cache (Cache to RAM checkbox) is checked
        # first: guaranteed resident for the current range, unlike the
        # shared _pv_frame LRU which other tabs' decoding can evict from.
        src = self.ip_ram_cache.get(idx) or self._ip_pv_frame(src_path)
        res = None
        cand = self._interp_result_frame(idx)
        if cand:
            res = self._ip_pv_frame(cand)
            if res.size != src.size:
                from PIL import Image as _I
                res = res.resize(src.size, _I.LANCZOS)
        return src, res

    def _interp_canvas_to_img(self, cx, cy):
        """Canvas pixel -> real image pixel, using the current display
        rect (fit-to-canvas, no zoom/pan -- Interpolate doesn't have
        Area's zoom, so this is simpler than _area_canvas_to_img but the
        same idea)."""
        r = getattr(self, "_ip_disp_rect", None)
        sz = getattr(self, "_ip_disp_real_size", None)
        if not r or not sz:
            return (cx, cy)
        ox, oy, dw, dh = r
        iw, ih = sz
        ix = (cx - ox) * iw / max(1, dw)
        iy = (cy - oy) * ih / max(1, dh)
        return ix, iy

    def _interp_set_paint_mode(self, on):
        """Toggle freehand brush painting -- same mechanics as ADW-Area's
        Look brush: drag a stroke, release to rasterize it into a mask.
        Here the mask defines WHERE VACE regenerates, replacing the
        auto-centred box for the active segment."""
        if on and self._interp_wipe_on():
            self._interp_toggle_wipe()
        self.ip_paint_mode = on
        self.ip_paint_pts = None
        self.ip_canvas.configure(cursor="pencil" if on else "arrow")
        if hasattr(self, "ip_paint_btn"):
            self.ip_paint_btn.configure(
                bg="#3A1A1A" if on else "#1A3A1A",
                fg="#FF6666" if on else "#66CC66")
        if on:
            if self._interp_active_seg() is None:
                self.log(self.ip_log_txt,
                    "Add a range first (+) -- the painted mask applies "
                    "to the active one.", "err")
                return
            self.log(self.ip_log_txt,
                "Drag over the area to regenerate, release to finish. "
                "Replaces the auto-centred box for this range.", "hi")
        self._interp_render()

    def _interp_canvas_press(self, ev):
        if getattr(self, "ip_paint_mode", False):
            if self._interp_active_seg() is None:
                return
            self.ip_paint_pts = [self._interp_canvas_to_img(ev.x, ev.y)]
            return
        self._interp_canvas_drag(ev)

    def _interp_canvas_drag(self, ev):
        """Wipe-line drag, or continuing a paint stroke -- whichever
        mode is active."""
        if getattr(self, "ip_paint_mode", False):
            if self.ip_paint_pts is None:
                return
            ix, iy = self._interp_canvas_to_img(ev.x, ev.y)
            lx, ly = self.ip_paint_pts[-1]
            if (ix - lx) ** 2 + (iy - ly) ** 2 >= 9:   # >=3px in image space
                self.ip_paint_pts.append((ix, iy))
            self._interp_render(live_paint=True)
            return
        r = getattr(self, "_ip_disp_rect", None)
        if not r or not self._interp_wipe_on():
            return
        ox, oy, dw, dh = r
        self._ip_wipe_t = max(0.0, min(1.0, (ev.x - ox) / float(max(1, dw))))
        self._interp_render()

    def _interp_canvas_release(self, ev):
        if not getattr(self, "ip_paint_mode", False) or self.ip_paint_pts is None:
            return
        pts = self.ip_paint_pts
        self.ip_paint_pts = None
        seg = self._interp_active_seg()
        sz = getattr(self, "_ip_disp_real_size", None)
        if seg is None or sz is None or len(pts) < 1:
            self._interp_set_paint_mode(False)
            return
        iw, ih = sz
        brush_r = max(1, int(self.ip_brush_size_var.get())) / 2.0
        mask = self._curve_rasterize_mask(pts, brush_r, (ih, iw))
        if not mask.any():
            self.log(self.ip_log_txt,
                "That stroke didn't cover any area \u2014 try again.", "err")
            self._interp_set_paint_mode(False)
            return
        seg["brush_mask"] = mask
        seg["brush_mask_size"] = (iw, ih)
        self.log(self.ip_log_txt,
            f"{seg['name']}: painted mask set ({int(mask.sum())} px). "
            "Clear mask to go back to the auto-centred box.", "ok")
        # One stroke, then Paint turns itself off -- same as ADW-Area's
        # Look brush. That's the visible "committed" signal: the button
        # flips back to inactive, so a second drag can't silently
        # overwrite this stroke without you noticing Paint had to be
        # switched back on first.
        self._interp_set_paint_mode(False)

    def _interp_clear_brush_mask(self):
        """Drop the active segment's painted mask, reverting to the
        auto-centred box (Regenerate coverage)."""
        seg = self._interp_active_seg()
        if seg is None:
            self.log(self.ip_log_txt, "No active range.", "err")
            return
        if "brush_mask" not in seg:
            self.log(self.ip_log_txt,
                f"{seg['name']} has no painted mask.", "dim")
            return
        del seg["brush_mask"]
        seg.pop("brush_mask_size", None)
        self.log(self.ip_log_txt,
            f"{seg['name']}: painted mask cleared, back to the "
            "auto-centred box.", "ok")
        self._interp_render()

    # ── span selection ───────────────────────────────────────────────
    def _interp_set_in(self):
        """Set the active segment's In at the current frame. With no
        segments yet this creates one. The 2s minimum is upheld by
        _interp_clamp_seg, so the Out is pushed out if it has to be."""
        if not self.ip_frames:
            self.log(self.ip_log_txt, "Load a sequence first.", "err"); return
        if not self.ip_segments:
            self._interp_add_segment(at=self.ip_idx)
            return
        s_ = self._interp_active_seg()
        n = len(self.ip_frames)
        need = min(self._interp_min_frames(), n)
        if s_["in"] != self.ip_idx:
            self._interp_drop_result(s_, "In moved")
        s_["in"] = self.ip_idx
        if s_["out"] < s_["in"] + need - 1:
            s_["out"] = s_["in"] + need - 1     # clamp_seg pulls it back in
        if self._interp_clamp_seg(s_, n):
            self.log(self.ip_log_txt,
                f"{s_['name']} held at the {self.IP_MIN_SECONDS:g}s minimum "
                f"({need} frames at {self._interp_fps():g} fps).", "dim")
        self._interp_segments_changed()

    def _interp_set_out(self):
        """Set the active segment's Out. An Out that would take the
        segment under 2 seconds is refused and held at the minimum,
        rather than silently ignoring the click."""
        if not self.ip_frames:
            self.log(self.ip_log_txt, "Load a sequence first.", "err"); return
        if not self.ip_segments:
            self._interp_add_segment(at=self.ip_idx)
            return
        s_ = self._interp_active_seg()
        n = len(self.ip_frames)
        need = min(self._interp_min_frames(), n)
        want = self.ip_idx
        if want < s_["in"]:
            self.log(self.ip_log_txt,
                "Out is before In — set In first, or step forward.", "err")
            return
        got = want - s_["in"] + 1
        if got < need:
            s_["out"] = min(n - 1, s_["in"] + need - 1)
            self.log(self.ip_log_txt,
                f"{self.IP_MIN_SECONDS:g} seconds is the Seedance minimum "
                f"\u2014 that would be {got} frame(s) "
                f"({got / self._interp_fps():.2f}s). {s_['name']} held at "
                f"{need} frames.", "err")
        else:
            s_["out"] = want
        self._interp_clamp_seg(s_, n)
        self._interp_segments_changed()

    def _interp_span_ok(self):
        """The segments that will be exported, or None with a reason."""
        if not self.ip_frames:
            self.log(self.ip_log_txt, "Load a sequence first.", "err")
            return None
        if not self.ip_segments:
            self.log(self.ip_log_txt,
                "Add at least one segment to extract (+).", "err")
            return None
        n = len(self.ip_frames)
        need = self._interp_min_frames()
        if n < need:
            self.log(self.ip_log_txt,
                f"The sequence is {n} frames "
                f"({n / self._interp_fps():.2f}s) \u2014 shorter than the "
                f"{self.IP_MIN_SECONDS:g}s Seedance minimum "
                f"({need} frames at {self._interp_fps():g} fps).", "err")
            return None
        bad = [s_ for s_ in self.ip_segments
               if self._interp_seg_frames(s_) < need]
        if bad:
            self.log(self.ip_log_txt,
                f"{', '.join(b['name'] for b in bad)} under the "
                f"{self.IP_MIN_SECONDS:g}s minimum ({need} frames).", "err")
            return None
        return list(self.ip_segments)

    def _interp_update_span_label(self):
        if not hasattr(self, "ip_span_lbl"):
            return
        if hasattr(self, "ip_fps_lbl"):
            self.ip_fps_lbl.configure(
                text=f"min {self._interp_min_frames()} frames")
        if hasattr(self, "ip_key_lbl"):
            if self._fal_get_key():
                self.ip_key_lbl.configure(text="fal.ai key saved", fg=GR)
            else:
                self.ip_key_lbl.configure(
                    text="\u2716 No fal.ai key \u2014 add one on Setup",
                    fg="#CC4444")
        # VACE plan readout for the active segment
        if hasattr(self, "ip_slow_lbl"):
            seg = self._interp_active_seg()
            if seg:
                p = self._vace_plan(seg, self.ip_vace_frames_var.get())
                if p["ok"]:
                    _cov = int(self.ip_vace_coverage_var.get())
                    self.ip_slow_lbl.configure(
                        text=f"Regenerate {p['gap']} frames "
                             f"({p['r0']+1}\u2013{p['r1']+1}) at {_cov}% "
                             f"of frame; ends {p['a']+1} & {p['b']+1} "
                             f"anchor it.",
                        fg=G)
                else:
                    self.ip_slow_lbl.configure(
                        text="\u2716 " + p["reason"][:70], fg="#CC4444")
                if hasattr(self, "ip_cost_lbl"):
                    self.ip_cost_lbl.configure(
                        text=f"~${self._vace_cost(p, self.ip_vace_res_var.get()):.2f}"
                             f"   \u2022  {p['gap']} frames")
            else:
                self.ip_slow_lbl.configure(text="", fg=G)
                if hasattr(self, "ip_cost_lbl"):
                    self.ip_cost_lbl.configure(text="")
        if not self.ip_segments:
            self.ip_span_lbl.configure(text="No segments", fg=G)
            return
        need = self._interp_min_frames()
        tot_f = sum(self._interp_seg_frames(s_) for s_ in self.ip_segments)
        under = [s_["name"] for s_ in self.ip_segments
                 if self._interp_seg_frames(s_) < need]
        txt = (f"{len(self.ip_segments)} segment(s), {tot_f} frames "
               f"= {tot_f / self._interp_fps():.2f}s total")
        if under:
            txt += f"   \u2716 {', '.join(under)} under {self.IP_MIN_SECONDS:g}s"
        self.ip_span_lbl.configure(text=txt,
                                   fg=("#CC4444" if under else W))

    # ── motion analysis (threaded, streaming — nothing held in RAM) ───
    def _interp_luma_small(self, path):
        """A small luma plane for one frame, as cheaply as possible.

        The obvious route — full decode, tonemap, float32 numpy, then
        slice — is brutally wasteful: a 4K RGB frame becomes ~106 MB of
        float32 before we throw away fifteen sixteenths of it. Instead
        convert to 8-bit greyscale and box-reduce inside PIL's C code,
        so only a tiny array ever reaches numpy.
        """
        import numpy as np
        from PIL import Image
        ext = os.path.splitext(path)[1].lower()
        if ext == ".exr":
            im = self._ip_pv_frame(path).convert("L")   # EXR needs the reader
        else:
            im = Image.open(path)
            try:
                # JPEG can decode straight to a reduced size
                im.draft("L", (max(1, im.width // 4), max(1, im.height // 4)))
            except Exception:
                pass
            im = im.convert("L")
        if im.width >= 8 and im.height >= 8:
            im = im.reduce(4)
        return np.asarray(im, dtype=np.float32)

    def _interp_analyse_toggle(self):
        """Score per-frame motion across the range.

        Runs on a background thread with a bounded prefetch pool: the
        decode is the bottleneck and it parallelises, and keeping it off
        the main thread is what lets the progress bar actually animate
        (chaining after() calls on the main thread meant every decode
        froze the UI mid-repaint). Frames are released as they are
        scored — only the numbers are kept. Click again to cancel.
        """
        import threading
        if not self.ip_frames:
            self.log(self.ip_log_txt, "Load a sequence first.", "err"); return
        if self._ip_analysing:
            self._ip_analyse_cancel = True
            self.log(self.ip_log_txt, "Cancelling…", "dim")
            return
        if self._ip_ram_building:
            self._ip_ram_cancel = True
            return
        # Scan the WHOLE sequence, not the range bar's view. The range
        # bar is a timeline zoom; a broken run can be anywhere in the
        # shot, and silently scoring only the visible slice (22 frames
        # by default) is exactly how you miss it.
        v0, v1 = 0, len(self.ip_frames)
        self.ip_motion = {}
        self._ip_analysing = True
        self._ip_analyse_cancel = False
        self.ip_cache_btn.configure(
            text="\u2026  Analysing  (click to cancel)", progress=0.0)
        self.log(self.ip_log_txt,
            f"Analysing motion, frames {v0+1}\u2013{v1}\u2026", "hi")
        threading.Thread(target=self._interp_analyse_worker,
                         args=(v0, v1), daemon=True).start()

    def _interp_analyse_worker(self, v0, v1):
        import numpy as np, collections, time
        from concurrent.futures import ThreadPoolExecutor

        def _ui(fn):
            try: self.after(0, fn)
            except Exception: pass

        raw = {}
        total = max(1, v1 - v0)
        folder = self.ip_folder
        names = list(self.ip_frames)
        try:
            workers = min(8, max(2, (os.cpu_count() or 4)))
            # Prefetch a bounded window so decodes overlap without ever
            # holding the whole sequence: only ~prefetch small planes are
            # alive at once, and each is already tiny.
            prefetch = workers * 2
            with ThreadPoolExecutor(max_workers=workers) as ex:
                pending = collections.deque()
                nxt = [v0]

                def fill():
                    while nxt[0] < v1 and len(pending) < prefetch:
                        i = nxt[0]
                        pending.append((i, ex.submit(
                            self._interp_luma_small,
                            os.path.join(folder, names[i]))))
                        nxt[0] += 1

                fill()
                prev = None; prev_i = None
                done = 0
                last_ui = 0.0
                while pending:
                    if self._ip_analyse_cancel:
                        for _i, f in pending:
                            f.cancel()
                        _ui(lambda: self._interp_analyse_finish({}, v0, v1, True))
                        return
                    i, fut = pending.popleft()
                    small = fut.result()
                    if prev is not None and prev.shape == small.shape \
                            and prev_i == i - 1:
                        raw[i] = float(np.mean(np.abs(small - prev)))
                    prev = small; prev_i = i
                    done += 1
                    fill()
                    # throttle UI posts: 30/s is plenty and keeps the
                    # event loop free to actually paint them
                    now = time.time()
                    if now - last_ui > 0.033 or done == total:
                        last_ui = now
                        frac = done / total
                        _ui(lambda p=frac, d=done: (
                            self.ip_cache_btn.configure(progress=p),
                            self.progress(p, f"Analyse motion  {d}/{total}")))
            _ui(lambda r=raw: self._interp_analyse_finish(r, v0, v1, False))
        except Exception as ex_:
            _ui(lambda e=ex_: self.log(self.ip_log_txt,
                f"Analyse failed: {type(e).__name__}: {e}", "err"))
            _ui(lambda: self._interp_analyse_finish({}, v0, v1, True))

    def _interp_analyse_finish(self, raw, v0, v1, cancelled):
        self._ip_analysing = False
        self._ip_analyse_cancel = False
        self.ip_cache_btn.configure(text="\u2295  Analyse Motion",
                                    progress=0.0)
        self.progress(-1)
        if not cancelled:
            # the first scanned frame has no predecessor — inherit its
            # neighbour so it isn't misleadingly flagged calm
            for i in range(v0, v1):
                if i not in raw and (i + 1) in raw:
                    raw[i] = raw[i + 1]
            self._motion_normalise(raw, self.ip_motion)
        self._interp_cache_info_update()
        if hasattr(self, "ip_frame_cb"):
            self.ip_frame_cb.refresh()
        if cancelled:
            self.log(self.ip_log_txt, "Analysis cancelled.", "hi")
        else:
            self.log(self.ip_log_txt,
                f"Analysed {len(self.ip_motion)} frames. The yellow run is "
                "where the plate is least stable — likely your broken span.",
                "ok")
            if self.ip_cache_to_ram_var.get():
                self._interp_start_ram_cache_build()

    def _interp_start_ram_cache_build(self):
        """Pre-decode the current range slider selection into RAM, for
        instant scrubbing. Runs automatically after Analyse Motion when
        Cache to RAM is checked (same mechanism as Paint/AreaLock/
        CurveLock's own Cache to RAM)."""
        if not self.ip_frames:
            return
        rb = getattr(self, "_ip_range_bar", None)
        if rb is not None and hasattr(rb, "get_range"):
            v0, v1 = rb.get_range()
        else:
            v0, v1 = 0, len(self.ip_frames)
        v0 = max(0, v0); v1 = min(len(self.ip_frames), v1)
        if v1 <= v0:
            v0, v1 = 0, len(self.ip_frames)
        # keep the cache to exactly the range: evict anything outside.
        # Motion scores are NOT dropped here -- Analyse Motion covers
        # the whole sequence independently of what's RAM-cached.
        stale = [i for i in self.ip_ram_cache if i < v0 or i >= v1]
        for i in stale:
            self.ip_ram_cache.pop(i, None)
        self._ip_ram_building = True
        self._ip_ram_cancel = False
        self.ip_cache_btn.configure(text="…  Caching  (click to cancel)",
                                    progress=0.0)
        self.log(self.ip_log_txt,
            f"Caching frames {v0+1}–{v1} to RAM…", "hi")
        self._interp_cache_ram_step(v0, v1, v0)

    def _interp_cache_ram_step(self, v0, v1, i):
        if self._ip_ram_cancel:
            self._interp_cache_ram_finish(v0, v1, cancelled=True); return
        if i >= v1:
            self._interp_cache_ram_finish(v0, v1, cancelled=False); return
        if i not in self.ip_ram_cache:
            try:
                path = os.path.join(self.ip_folder, self.ip_frames[i])
                self.ip_ram_cache[i] = self._ip_pv_frame(path)
            except Exception as ex:
                self.log(self.ip_log_txt,
                    f"Cache failed at frame {i+1}: {str(ex)[:80]}", "err")
                self._interp_cache_ram_finish(v0, v1, cancelled=True)
                return
        done = i - v0 + 1; total = v1 - v0
        self.ip_cache_btn.configure(progress=done / total)
        if i % 8 == 0 and hasattr(self, "ip_frame_cb"):
            self.ip_frame_cb.refresh()
        self.after(1, lambda: self._interp_cache_ram_step(v0, v1, i + 1))

    def _interp_cache_ram_finish(self, v0, v1, cancelled):
        self._ip_ram_building = False
        self._ip_ram_cancel = False
        self.ip_cache_btn.configure(text="\u2295  Analyse Motion",
                                    progress=0.0)
        if not cancelled:
            # Refine motion for this range from the full-resolution
            # decode now in RAM -- more accurate than the cheap
            # whole-sequence scan for exactly these frames, same
            # refinement Paint/AreaLock/CurveLock's own cache builds do.
            self._analyse_motion_cache(self.ip_ram_cache,
                                       self.ip_motion, v0, v1)
        self._interp_cache_info_update()
        if hasattr(self, "ip_frame_cb"):
            self.ip_frame_cb.refresh()
        try:
            self._interp_render()
        except Exception:
            pass
        if cancelled:
            self.log(self.ip_log_txt,
                f"Cache cancelled — {len(self.ip_ram_cache)} frames held.",
                "hi")
        else:
            n = sum(1 for i in range(v0, v1) if i in self.ip_ram_cache)
            self.log(self.ip_log_txt,
                f"RAM cache ready — {n} frames instant. Motion scores "
                "for this range refined from the full decode.", "ok")

    def _interp_analyse_clear(self):
        n = len(self.ip_motion)
        c = len(self.ip_ram_cache)
        self.ip_motion = {}
        self.ip_ram_cache = {}
        self._interp_cache_info_update()
        if hasattr(self, "ip_frame_cb"):
            self.ip_frame_cb.refresh()
        try:
            self._interp_render()
        except Exception:
            pass
        self.log(self.ip_log_txt,
            f"Cleared {n} motion score(s) and {c} cached frame(s).", "ok")

    def _interp_cache_info_update(self):
        if not hasattr(self, "ip_cache_info"):
            return
        n_motion = len(self.ip_motion)
        n_cache = len(self.ip_ram_cache)
        if n_motion == 0 and n_cache == 0:
            self.ip_cache_info.configure(text="Not analysed")
            return
        parts = []
        if n_motion:
            parts.append(f"{n_motion} frame(s) analysed")
        if n_cache:
            parts.append(f"{n_cache} cached")
        self.ip_cache_info.configure(text="  \u2022  ".join(parts))

    # ── export the range for an external generative model ─────────────
    # Container/codec choices. H.264 in MP4 is what every AI platform
    # (Weavy, Fal, Seedance, Kling, Runway…) will actually accept —
    # ProRes is a mastering codec and gets rejected by most of them.

    # VACE video-to-video. Two methods, chosen by the Method radio:
    #
    # - INPAINTING (Mask): the range's real footage as a control clip
    #   plus a mask (grey/white box, tapered near the edges, or a
    #   painted shape). VACE keeps whatever is outside the mask and only
    #   regenerates inside it -- the only method with partial-frame
    #   coverage.
    # - DEPTH: the range's real footage run through a depth-estimation
    #   pass first (fal-ai/depth-anything-video), then that depth video
    #   is what VACE conditions on -- no mask, the whole frame is
    #   regenerated, guided by the real shot's structure/layout rather
    #   than a masked patch.
    #
    # Wan 2.2 VACE Fun A14B, not the older Wan 2.1-based wan-vace-14b --
    # a newer base model behind the exact same request shape (video_url,
    # mask_video_url, first_frame_url, last_frame_url, prompt, ...).
    VACE_ENDPOINT_INPAINTING = \
        "https://queue.fal.run/fal-ai/wan-22-vace-fun-a14b/inpainting"
    VACE_ENDPOINT_DEPTH = \
        "https://queue.fal.run/fal-ai/wan-22-vace-fun-a14b/depth"
    DEPTH_ANYTHING_ENDPOINT = "fal-ai/depth-anything-video"
    DEPTH_ANYTHING_RATE = 0.04   # per second of video, flat
    VACE_MIN_GEN = 81           # the model will not generate fewer
    # num_inference_steps the endpoint accepts. 50 is fal's own limit
    # for wan-22-vace-fun-a14b, learned from its validation error.
    VACE_MAX_STEPS = 50
    VACE_DEFAULT_STEPS = 30
    VACE_MAX_GEN = 241

    def _vace_steps(self):
        """Steps to send, from the Steps field (ADW-Interpolate; Expansion
        Studio's Wan inpaint shares it), kept within what the endpoint
        accepts -- an out-of-range value is not a quality choice, it is a
        request fal refuses outright after the clips have been uploaded."""
        try:
            n = int(float(str(self.ip_vace_steps_var.get()).strip()))
        except Exception:
            return self.VACE_DEFAULT_STEPS
        if n <= 0:
            return self.VACE_DEFAULT_STEPS
        return min(n, self.VACE_MAX_STEPS)

    def _vace_active_endpoint(self):
        """Which VACE endpoint the current Method selects.

        Full image shares Depth's endpoint -- both are whole-frame,
        no-mask conditioning on a video_url, same request shape. The
        only difference is WHICH video gets built and sent (a depth
        map vs. the real plate footage untouched), decided where that
        video is actually assembled, not here."""
        m = (getattr(self, "ip_vace_method_var", None).get()
             if getattr(self, "ip_vace_method_var", None) is not None
             else "inpainting")
        if m in ("depth", "full"):
            return self.VACE_ENDPOINT_DEPTH
        return self.VACE_ENDPOINT_INPAINTING

    def _vace_gap(self, s):
        """The whole selected range is regenerated.

        The range's first and last frame are sent to VACE as the two
        anchor stills (FLF2V needs a start and end image), but EVERY frame
        in the range is replaced in the output — including the ends. The
        user selected those frames because they are broken; keeping them
        would defeat the point.

        Returns (r0, r1, a, b, n) where r0..r1 is the replaced range
        (== the whole segment), a/b are the frames sent as anchors, and n
        is how many frames get replaced. None if the range is too short.
        """
        a, b = s["in"], s["out"]
        if b - a < 1:
            return None, ("Select at least two frames \u2014 VACE needs a "
                          "first and a last to generate between.")
        return (a, b, a, b, b - a + 1), ""

    def _vace_pick(self, n_want, n_gen):
        """Map the n_want output frames onto the n_gen generated frames.

        The generation spans the range evenly, so output frame i takes
        generated frame round(i/(n_want-1) * (n_gen-1)) — the ends map to
        the first and last generated frame, the rest spread between.
        """
        if n_want <= 1:
            return [0]
        return [int(round(i / float(n_want - 1) * (n_gen - 1)))
                for i in range(n_want)]

    def _vace_plan(self, seg, n_gen=None):
        """The whole plan for one segment's range, including any Tether
        padding: extra real, untouched frames sent alongside the
        selection so VACE has genuine motion to anchor to, beyond a
        single static first/last still. The padding is clamped to
        whatever real footage actually exists outside the selection --
        it can't run past the start or end of the sequence.

        d0/d1, r0/r1, a/b, gap all keep their EXISTING meaning: the
        core selection the user actually marked, exactly as before
        Tether existed -- this is what gets replaced in the final
        splice (_vace_apply calls _vace_gap directly and never sees
        Tether at all). send0/send1/send_gap are the padded range
        actually encoded and sent to VACE; core_start/core_end are
        send0/send1-relative positions marking where the core selection
        sits within that padded clip, for the mask/clip builders'
        core_start/core_end parameters.
        """
        gap, why = self._vace_gap(seg)
        if gap is None:
            return {"ok": False, "reason": why, "gap": 0, "request": 0}
        d0, d1, a, b, g = gap
        n_total = len(self.ip_src_frames or self.ip_frames)
        # Tether is Mask-method only: it works by sending extra frames
        # with an EMPTY mask (keep, don't regenerate) alongside the
        # selection. Depth and Full image have no mask mechanism at
        # all -- the whole frame is always regenerated -- so there's no
        # way to include extra context frames without also asking the
        # model to regenerate them, defeating the point. No padding for
        # either.
        method = (self.ip_vace_method_var.get()
                  if getattr(self, "ip_vace_method_var", None) is not None
                  else "inpainting")
        tether = 0
        if method not in ("depth", "full"):
            tether = max(0, min(10, int(getattr(
                self, "ip_vace_tether_var", None).get()
                if getattr(self, "ip_vace_tether_var", None) is not None
                else 0)))
        send0 = max(0, a - tether)
        send1 = min(max(0, n_total - 1), b + tether)
        send_gap = send1 - send0 + 1
        n = int(n_gen or self.VACE_MIN_GEN)
        n = max(self.VACE_MIN_GEN, min(self.VACE_MAX_GEN, n))
        return {"ok": True, "reason": "", "d0": d0, "d1": d1,
                "r0": d0, "r1": d1, "a": a, "b": b, "gap": g,
                "send0": send0, "send1": send1, "send_gap": send_gap,
                "core_start": a - send0, "core_end": b - send0,
                "tether_l": a - send0, "tether_r": send1 - b,
                "request": n, "pick": self._vace_pick(g, n)}

    # Per VIDEO SECOND (16fps), from fal's pricing for
    # wan-22-vace-fun-a14b. The output matches the input length, so cost
    # scales with the range, not a flat per-generation fee. This is
    # roughly 25% more per second than the older wan-vace-14b endpoint
    # ($0.08/720p) it replaced.
    VACE_RATE = {"480p": 0.05, "580p": 0.075, "720p": 0.10}

    def _vace_cost(self, plan, res):
        """Cost estimate: rate-per-second x the range's duration at 16fps
        (fal computes video seconds at 16fps regardless of the clip fps).

        Uses send_gap (the padded range actually sent, including any
        Tether frames), not the core selection alone -- VACE bills for
        every second it actually processes, and Tether frames are real
        seconds sent to it even though they're discarded afterward.

        In Depth mode this adds the depth-estimation pass
        (fal-ai/depth-anything-video, DEPTH_ANYTHING_RATE/s) on top of
        the VACE generation itself -- a real second cost, not just a
        quality trade-off.
        """
        secs = max(1, plan.get("send_gap", plan.get("gap", 1))) / 16.0
        method = (self.ip_vace_method_var.get()
                  if getattr(self, "ip_vace_method_var", None) is not None
                  else "inpainting")
        cost = self.VACE_RATE.get(res, 0.08) * secs
        if method == "depth":
            cost += self.DEPTH_ANYTHING_RATE * secs
        return cost

    # ── the damage range: which frames VACE actually repaints ─────────
    # VACE inpainting regenerates the WHITE region of the mask and
    # PRESERVES the black. So the segment is the context we send, and the
    # damage range inside it is what gets repainted. An all-white mask
    # would throw the control video away and leave us with plain
    # text-to-video.
    def _interp_dmg(self, s):
        """The frames a segment replaces: the WHOLE segment.

        The first and last frame are the anchors (kept), and VACE fills
        everything between. There is no separate damage range any more —
        marking the segment is the whole interaction.
        """
        return s["in"], s["out"]

    def _interp_dmg_frames(self, s):
        return s["out"] - s["in"] + 1


    # ── the hosted endpoint ──────────────────────────────────────────
    # ── progress reporting ───────────────────────────────────────────
    # The honest problem: while fal is rendering we have no real progress
    # signal, only a queue position and an elapsed clock. So we do NOT
    # fake a smooth bar. Each phase owns a slice; inside the render phase
    # the bar PULSES (which says "working, duration unknown") and the
    # label carries the facts we do have: queue position, elapsed time,
    # and fal's own log lines.
    VACE_PHASES = [
        ("prep",     "Reading the anchor frames", 0.00, 0.10),
        ("upload",   "Uploading",          0.10, 0.30),
        ("queue",    "Queued at fal",      0.30, 0.35),
        ("render",   "Generating the gap", 0.35, 0.80),
        ("download", "Downloading",        0.80, 0.90),
        ("decode",   "Decoding",           0.90, 0.96),
        ("pick",     "Filling the gap",    0.96, 1.00),
    ]

    def _vace_phase_at(self, key):
        for i, (k, label, a, b) in enumerate(self.VACE_PHASES):
            if k == key:
                return i, label, a, b
        return 0, key, 0.0, 1.0

    def _vace_say(self, key, detail="", frac=None, pulse=False):
        """One place that owns the button, the status line and the global
        bar, so they can never disagree with each other."""
        i, label, a, b = self._vace_phase_at(key)
        n = len(self.VACE_PHASES)
        el = ""
        if getattr(self, "_ip_vace_t0", None):
            s = int(time.time() - self._ip_vace_t0)
            el = f"{s // 60}:{s % 60:02d}"
        head = f"{i + 1}/{n}  {label}"
        line = head + (f"  \u2014  {detail}" if detail else "")
        if el:
            line += f"   [{el}]"
        try:
            self.ip_vace_stat.configure(text=line)
            self.ip_vace_btn.configure(
                text=f"\u2026  {label}  (click to cancel)",
                progress=(a if frac is None else a + (b - a) * frac))
        except Exception:
            pass
        # A pulsing bar is the truthful shape for "we cannot know how long
        # this will take"; a creeping fake bar would be a lie.
        try:
            if pulse:
                self.progress(None, f"ADW-Interpolate \u2014 {label}")
            else:
                self.progress(a if frac is None else a + (b - a) * frac,
                              f"ADW-Interpolate \u2014 {label}")
        except Exception:
            pass

    def _vace_tick(self):
        """Keep the elapsed clock moving while we wait on fal, so the UI
        never looks hung."""
        if not self._ip_vace_busy:
            self._ip_vace_ticker = None
            return
        if self._ip_vace_phase:
            self._vace_say(self._ip_vace_phase, self._ip_vace_detail,
                           pulse=(self._ip_vace_phase in ("render", "queue")))
        self._ip_vace_ticker = self.after(1000, self._vace_tick)

    CAPTION_ENDPOINT = "fal-ai/florence-2-large/more-detailed-caption"

    def _interp_motion_words(self, r0, r1):
        """Motion descriptors for the range, from the analysis we already
        have. Free and local -- no model, no network, no cost.

        ip_motion is normalised across whatever was scanned, so a high
        value means "busy relative to this shot", not an absolute speed.
        The wording stays comparative for that reason.
        """
        vals = [self.ip_motion[i] for i in range(r0, r1 + 1)
                if i in self.ip_motion]
        if not vals:
            return []
        avg = sum(vals) / len(vals)
        peak = max(vals)
        words = []
        if avg >= 0.66:
            words += ["fast motion", "motion blur"]
        elif avg >= 0.33:
            words += ["steady movement"]
        else:
            words += ["slow, subtle movement"]
        # a peak well above the average means the motion is uneven across
        # the range, which is worth telling the model about
        if peak - avg >= 0.35:
            words.append("a sudden burst of movement")
        return words

    def _vace_caption_frame(self, png_path, on_log=None):
        """One frame -> a text description, via a small vision model on
        fal. Costs a fraction of a cent, which is why it sits behind an
        explicit button rather than inside the free local analysis."""
        key = self._vace_key()
        if not key:
            raise RuntimeError("No fal.ai key. Set one up on the Setup tab.")
        os.environ["FAL_KEY"] = key
        if on_log:
            on_log("Uploading a reference frame for captioning\u2026")
        url = self._fal_call_with_watchdog(
            lambda: self._fal_client(key).upload_file(png_path),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label="the captioning reference upload")
        if on_log:
            on_log("Describing the shot\u2026")
        res = self._fal_call_with_watchdog(
            lambda: self._fal_client(key).subscribe(self.CAPTION_ENDPOINT,
                                         arguments={"image_url": url}),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label="fal (captioning)")
        txt = (res or {}).get("results") or ""
        return txt.strip()

    def _interp_compose_prompt(self, caption, words):
        """Fold the caption and the motion words into one VACE prompt.

        Florence tends to open with "The image shows ..." which is not
        useful to a video model, so that is trimmed. The tail keeps VACE
        anchored to the existing shot rather than reinterpreting it.
        """
        c = (caption or "").strip()
        for lead in ("The image shows ", "This image shows ",
                     "The image is ", "The image depicts ",
                     "This is ", "The video shows "):
            if c.lower().startswith(lead.lower()):
                c = c[len(lead):]
                break
        c = c.strip().rstrip(".")
        if c:
            c = c[0].lower() + c[1:] if len(c) > 1 else c.lower()
        parts = [p for p in ([c] + list(words or [])) if p]
        parts.append("same scene, same content, continuous natural motion")
        return ", ".join(parts)

    def _fal_client(self, key=None):
        """A fal client bound to the key we actually mean.

        NOT fal_client.upload_file / .subscribe, which are bound to a
        module-level SyncClient whose credentials are a
        @cached_property: it resolves FAL_KEY once, on first use, and
        caches it for the life of the process. Setting
        os.environ["FAL_KEY"] afterwards changes nothing, so a key saved
        or replaced mid-session is ignored and every call keeps using
        whatever was in the environment at startup -- which is how a
        valid key produces 401 Unauthorized on the storage token.

        Verified against fal_client: after setting FAL_KEY twice, the
        module client still reports the first value while an explicit
        SyncClient(key=...) reports the second."""
        import fal_client
        k = key or self._vace_key()
        if not k:
            raise RuntimeError("No API key. Set one up on the Setup tab.")
        return fal_client.SyncClient(key=k)

    @staticmethod
    def _fal_explain_error(ex):
        """A readable line for a fal failure, or None to re-raise.

        The library raises httpx errors, so an expired key surfaces as
        a 401 on a storage-token URL with a link to MDN's page about
        HTTP status codes -- accurate, and no help at all in working
        out that the key needs replacing."""
        txt = str(ex)
        if "401" in txt or "Unauthorized" in txt:
            return ("fal rejected the key (401). It has been revoked, "
                    "mistyped, or replaced. Open Setup \u2192 fal.ai, remove "
                    "the key and paste a fresh one from "
                    "fal.ai/dashboard/keys.\n"
                    "Note that an ADMIN key reads billing but is not "
                    "always accepted for generation \u2014 if you swapped one "
                    "in for the balance readout, put the API key back.")
        if "403" in txt or "Forbidden" in txt:
            return ("fal refused the request (403). The key is valid but "
                    "lacks permission for this endpoint.")
        if "402" in txt or "insufficient" in txt.lower():
            return ("fal reports insufficient credit. Check the balance "
                    "in Setup \u2192 fal.ai.")
        if "429" in txt:
            return "fal rate-limited the request; try again shortly."
        return None

    def _vace_key(self):
        """The key lives on the Setup tab now, with the other credentials."""
        return self._fal_get_key() or ""

    def _vace_payload(self, plan, urls, prompt_override=None):
        """The request body for VACE inpainting. Pure, so the contract is
        pinned by tests without a network.

        The source video is the REAL footage of the range, so the model
        follows the true motion. The mask says which pixels to regenerate
        (white) vs keep (black). first/last_frame_url pin the ends to the
        good plate frames. match_input_num_frames makes the output match
        the clip length exactly, so no frame-picking is needed.

        prompt_override, when given, wins over the Prompt field -- this is
        how per-segment auto-prompt reaches the request without clobbering
        what the person typed in while a batch is still running.
        """
        prompt = (prompt_override if prompt_override is not None
                  else self.ip_vace_prompt_var.get()).strip()
        body = {
            "prompt": prompt
                      or "same scene, same content, continuous natural "
                         "motion, no changes",
            "negative_prompt": self.ip_vace_neg_var.get().strip(),
            "video_url": urls.get("video"),
            "mask_video_url": urls.get("mask"),
            "first_frame_url": urls.get("first"),
            "last_frame_url": urls.get("last"),
            "match_input_num_frames": True,
            "match_input_frames_per_second": True,
            "resolution": self.ip_vace_res_var.get(),
            "num_inference_steps": self._vace_steps(),
            "preprocess": False,
        }
        try:
            sd = int(self.ip_vace_seed_var.get())
            if sd >= 0:
                body["seed"] = sd
        except Exception:
            pass
        return {k: v for k, v in body.items() if v not in (None, "")}

    def _vace_depth_payload(self, plan, urls, prompt_override=None):
        """The request body for VACE's depth-endpoint task. Pure, like
        _vace_payload. Shared by both the Depth and Full image methods
        -- the request shape is identical either way, only WHICH video
        urls["video"] points at differs (a real depth map for Depth, or
        the plain untouched plate clip for Full image), decided by the
        caller before this function ever sees it.

        There is no mask in this task at all, so there is no partial-
        coverage regeneration: the whole frame is regenerated, guided
        by whatever structure the conditioning video carries.
        first/last_frame_url are still the real plate stills, same as
        inpainting, pinning the ends.
        """
        prompt = (prompt_override if prompt_override is not None
                  else self.ip_vace_prompt_var.get()).strip()
        body = {
            "prompt": prompt
                      or "same scene, same content, continuous natural "
                         "motion, no changes",
            "negative_prompt": self.ip_vace_neg_var.get().strip(),
            "video_url": urls.get("video"),
            "first_frame_url": urls.get("first"),
            "last_frame_url": urls.get("last"),
            "match_input_num_frames": True,
            "match_input_frames_per_second": True,
            "resolution": self.ip_vace_res_var.get(),
            "num_inference_steps": self._vace_steps(),
            "preprocess": False,
        }
        try:
            sd = int(self.ip_vace_seed_var.get())
            if sd >= 0:
                body["seed"] = sd
        except Exception:
            pass
        return {k: v for k, v in body.items() if v not in (None, "")}

    def _vace_build_plain_clip(self, folder, names, r0, r1, out_mp4, fps):
        """Encode the range's real frames straight to mp4 -- no grey box,
        no mask, nothing painted over.

        Used only by the Depth method, as the input to the depth-
        estimation pass (fal-ai/depth-anything-video): that model needs
        to actually see the real footage to estimate structure from it,
        unlike inpainting's control clip which deliberately hides the
        area to be regenerated.
        """
        import subprocess as _sp, tempfile, shutil as _sh
        stage = tempfile.mkdtemp(prefix="vace_plain_")
        try:
            for j, i in enumerate(range(r0, r1 + 1)):
                im = self._ip_pv_frame(os.path.join(folder, names[i])).convert("RGB")
                im.save(os.path.join(stage, "%05d.png" % j))
            r = _sp.run(["ffmpeg", "-y", "-framerate", "%g" % fps,
                "-i", os.path.join(stage, "%05d.png"),
                "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "16",
                # Explicit bt709, not left to ffmpeg's own guess. With
                # no matrix specified, libswscale's RGB<->YUV conversion
                # picks bt601 or bt709 from a RESOLUTION heuristic --
                # and if this encode and the eventual decode land on
                # opposite sides of that threshold (very plausible: the
                # source can be 2K/4K while whatever comes back is not),
                # the round trip silently shifts colour on anything with
                # real chroma, while leaving neutral greys untouched --
                # exactly the shape of the shift measured on a real
                # repaired frame (R/G darker than B on a blue sky, nothing
                # on flat grey).
                "-color_primaries", "bt709", "-color_trc", "bt709",
                "-colorspace", "bt709",
                out_mp4], capture_output=True)
            if r.returncode != 0 or not os.path.exists(out_mp4):
                raise RuntimeError("plain clip encode failed: "
                    + r.stderr.decode("utf-8", "replace")[-200:])
        finally:
            _sh.rmtree(stage, ignore_errors=True)
        return out_mp4

    def _vace_mask_for_range(self, size, coverage, custom_mask=None):
        """The boolean regenerate mask (h, w) for the whole range --
        either a painted brush mask (resized to fit) or the auto-centred
        box, as one array so both builders can treat them identically.

        Position-independent: the same mask is used on every frame of
        the range. (Feathering the edges of the CUT happens separately,
        at Apply time -- this is only about where each frame gets
        regenerated, not how the splice reads.)
        """
        import numpy as np
        w, h = size
        if custom_mask is not None:
            import cv2
            m = custom_mask
            if m.shape != (h, w):
                m = cv2.resize(m.astype(np.uint8), (w, h),
                               interpolation=cv2.INTER_NEAREST) > 0
            return m
        box = self._vace_mask_box(size, coverage)
        arr = np.zeros((h, w), dtype=bool)
        if box is not None:
            x0, y0, x1, y1 = box
            arr[y0:y1, x0:x1] = True
        return arr

    def _vace_build_source_clip(self, folder, names, r0, r1, out_mp4, fps,
                                coverage=1.0, custom_mask=None,
                                core_start=0, core_end=None):
        """Encode the range's frames into the VACE control clip.

        VACE inpainting reads the control video like this: pixels it should
        KEEP stay as the real footage; pixels it should SYNTHESISE must be
        painted GRAY (128). Handing it clean footage in the masked area is
        the bug that made the output equal the input -- the model just
        copies the answer it was given.

        coverage is the fraction of each frame (a centred box) to
        regenerate. 1.0 greys the whole frame; a smaller value keeps a
        real border that carries motion and context, which is what VACE
        inpainting actually does well.

        custom_mask, when given (a painted brush mask), REPLACES the
        auto-centred box entirely, on every frame of the range.

        core_start/core_end are LOCAL positions (0-indexed within this
        clip, i.e. relative to r0) marking which frames actually get the
        configured mask -- default to the whole range (no Tether).
        Frames inside [r0, r1] but OUTSIDE [core_start, core_end] are
        Tether context: real, untouched footage, mask forced empty
        regardless of coverage/custom_mask, so VACE sees genuine motion
        leading into and out of the region it's asked to regenerate.
        Those frames are never part of the final splice -- only the
        core range is -- they exist purely to anchor the generation.
        """
        import subprocess as _sp, tempfile, shutil as _sh
        from PIL import Image
        g = r1 - r0 + 1
        if core_end is None:
            core_end = g - 1
        stage = tempfile.mkdtemp(prefix="vace_src_")
        try:
            size = self._ip_pv_frame(os.path.join(folder, names[r0])).size
            mask = self._vace_mask_for_range(size, coverage,
                custom_mask=custom_mask)
            mimg = (Image.fromarray((mask * 255).astype("uint8"), "L")
                    if mask.any() else None)
            grey = Image.new("RGB", size, (128, 128, 128))
            for j, i in enumerate(range(r0, r1 + 1)):
                im = self._ip_pv_frame(os.path.join(folder, names[i])).convert("RGB")
                if mimg is not None and core_start <= j <= core_end:
                    im.paste(grey, (0, 0), mimg)
                im.save(os.path.join(stage, "%05d.png" % j))
            r = _sp.run(["ffmpeg", "-y", "-framerate", "%g" % fps,
                "-i", os.path.join(stage, "%05d.png"),
                "-c:v", "libx264", "-pix_fmt", "yuv420p", "-crf", "16",
                # See the sibling "plain clip" branch above for why:
                # forcing bt709 removes ffmpeg's own resolution-based
                # guess from this side of the round trip entirely.
                "-color_primaries", "bt709", "-color_trc", "bt709",
                "-colorspace", "bt709",
                out_mp4], capture_output=True)
            if r.returncode != 0 or not os.path.exists(out_mp4):
                raise RuntimeError("source clip encode failed: "
                    + r.stderr.decode("utf-8", "replace")[-200:])
        finally:
            _sh.rmtree(stage, ignore_errors=True)
        return out_mp4

    def _vace_mask_box(self, size, coverage):
        """The centred rectangle to regenerate, or None for a full frame.

        coverage is a 0-1 fraction of each dimension. 1.0 -> whole frame
        (None sentinel, callers fill everything); < 1.0 -> a centred box
        leaving a real border.
        """
        coverage = max(0.05, min(1.0, float(coverage)))
        w, h = size
        if coverage >= 0.999:
            return (0, 0, w, h)
        bw, bh = int(w * coverage), int(h * coverage)
        x0, y0 = (w - bw) // 2, (h - bh) // 2
        return (x0, y0, x0 + bw, y0 + bh)

    def _vace_build_mask_clip(self, n_frames, size, out_mp4, fps,
                              coverage=1.0, custom_mask=None,
                              core_start=0, core_end=None):
        """The mask clip: WHITE where VACE should regenerate, BLACK where
        it should keep the real footage. Matches the grey painted into
        the control clip exactly, so the two agree.

        core_start/core_end (0-indexed, default the whole range -- no
        Tether) mark which frames get the configured mask; frames
        outside that range get an empty (all-black, keep-everything)
        mask, matching _vace_build_source_clip's Tether zones exactly.

        With no Tether the mask is identical on every frame, so one
        frame is enough and ffmpeg loops it -- cheap. With a Tether,
        two zones need two different masks, so each frame is rendered
        individually.
        """
        import subprocess as _sp, tempfile, shutil as _sh
        from PIL import Image
        if core_end is None:
            core_end = n_frames - 1
        no_tether = (core_start == 0 and core_end == n_frames - 1)
        stage = tempfile.mkdtemp(prefix="vace_mask_")
        try:
            mask = self._vace_mask_for_range(size, coverage,
                custom_mask=custom_mask)
            if no_tether:
                frame = Image.fromarray(
                    (mask * 255).astype("uint8"), "L").convert("RGB")
                # one frame is enough; ffmpeg loops it to n_frames
                frame.save(os.path.join(stage, "m.png"))
                r = _sp.run(["ffmpeg", "-y", "-loop", "1", "-framerate",
                    "%g" % fps, "-i", os.path.join(stage, "m.png"),
                    "-frames:v", str(max(1, n_frames)),
                    "-c:v", "libx264", "-pix_fmt", "yuv420p", out_mp4],
                    capture_output=True)
            else:
                import numpy as np
                empty = np.zeros_like(mask)
                for j in range(n_frames):
                    m = mask if core_start <= j <= core_end else empty
                    frame = Image.fromarray(
                        (m * 255).astype("uint8"), "L").convert("RGB")
                    frame.save(os.path.join(stage, "%05d.png" % j))
                r = _sp.run(["ffmpeg", "-y", "-framerate", "%g" % fps,
                    "-i", os.path.join(stage, "%05d.png"),
                    "-c:v", "libx264", "-pix_fmt", "yuv420p", out_mp4],
                    capture_output=True)
            if r.returncode != 0 or not os.path.exists(out_mp4):
                raise RuntimeError("mask clip encode failed: "
                    + r.stderr.decode("utf-8", "replace")[-200:])
        finally:
            _sh.rmtree(stage, ignore_errors=True)
        return out_mp4

    # ── Topaz Hyperion (SDR -> HDR, fal) ───────────────────────────────
    # A whole different JOB from VACE: one video in, one already-graded
    # video out, no mask, no prompt. Topaz decides its own tone curve
    # internally, so this is an ALTERNATIVE to this app's own analytic
    # expansion for the frames it processes -- not a peer of the VACE
    # highlight step, which still runs afterward if wanted, since it
    # only cares about whatever scene-referred float comes out of
    # whichever stage produced it.

    # Internal values, not displayed directly any more -- the three
    # expansion-mode buttons carry the cost distinction visually now
    # (a smooth curve for free/local, the pixel robot for paid/
    # external), so these no longer need an emoji or a cost note baked
    # into the string itself. _usc_hdr_provider() is the one place that
    # maps a value here back to "local"/"topaz" for switching on.
    HDR_PROVIDERS = ("local", "Topaz Hyperion")

    TOPAZ_ENDPOINT = "topaz/sdr-to-hdr/video"
    TOPAZ_FORMATS = {
        # ProRes by default, on Topaz's OWN stated recommendation for
        # grading and mastering -- and measured here: a quick synthetic
        # test round-tripped default-CRF HEVC about 3% off at 1000 nits,
        # purely from the compression, where a near-lossless pass came
        # back within noise. ProRes is intra-frame and far higher
        # bitrate, so it keeps far more of what Topaz actually computed.
        "ProRes 422 HQ (.mov)": "prores",
        "H.265 HDR10 (.mp4)": "mp4",
    }
    TOPAZ_DEFAULT_FORMAT = "ProRes 422 HQ (.mov)"

    def _topaz_submit(self, video_path, output_format, on_log=None,
                      on_phase=None):
        """Submit one SDR video to Topaz's SDR->HDR endpoint and return
        the local path of the downloaded, graded result.

        A leaner sibling of _vace_submit rather than a fit through it:
        routing this through VACE's source+mask upload and its
        wan-2.2-specific payload builder would try to send a mask and a
        prompt into a schema that has fields for neither."""
        key = self._vace_key()
        if not key:
            raise RuntimeError("No API key. Set one up on the Setup tab.")

        def _ph(phase, detail=""):
            if on_phase:
                on_phase(phase, detail)

        sz = os.path.getsize(video_path) / 1e6
        _ph("upload", f"{os.path.basename(video_path)} ({sz:.1f} MB)")
        if on_log:
            on_log(f"Uploading {os.path.basename(video_path)} "
                   f"({sz:.1f} MB)\u2026")
        url = self._fal_call_with_watchdog(
            lambda: self._fal_client(key).upload_file(video_path),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            timeout_s=self.VACE_FAL_UPLOAD_TIMEOUT_S,
            label=f"the upload of {os.path.basename(video_path)}")

        _ph("queue", "submitting")
        seen = set()

        def _on_update(update):
            if self._ip_vace_cancel:
                return
            name = type(update).__name__
            if "Queued" in name:
                pos = getattr(update, "position", None)
                _ph("queue", f"position {pos}" if pos is not None
                    else "waiting")
            else:
                _ph("render", "")
            for lg in (getattr(update, "logs", None) or []):
                m = lg.get("message") if isinstance(lg, dict) else str(lg)
                if m and m not in seen:
                    seen.add(m)
                    if on_log:
                        on_log(f"topaz: {m}")

        os.environ["FAL_KEY"] = key
        result = self._fal_call_with_watchdog(
            lambda: self._fal_client(key).subscribe(
                self.TOPAZ_ENDPOINT,
                arguments={"video_url": url,
                          "output_format": self.TOPAZ_FORMATS.get(
                              output_format, output_format)},
                with_logs=True, on_queue_update=_on_update),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label=f"fal ({self.TOPAZ_ENDPOINT})")

        vid = (result or {}).get("video") or {}
        out_url = vid.get("url") if isinstance(vid, dict) else vid
        if not out_url:
            raise RuntimeError(f"No video in response: {str(result)[:300]}")

        _ph("download", "")
        if on_log:
            on_log("Downloading result\u2026")
        import urllib.request
        fmt = self.TOPAZ_FORMATS.get(output_format, output_format)
        ext = ".mov" if fmt == "prores" else ".mp4"
        dst = os.path.join(self._vace_work_dir(), "topaz_out" + ext)
        self._fal_call_with_watchdog(
            lambda: urllib.request.urlretrieve(out_url, dst),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label="the Topaz result download")
        return dst

    def _topaz_decode(self, video_path, out_dir):
        """Topaz's graded result back to 16-bit PNG frames.

        NOT _vace_decode: that call's ffmpeg command writes 8-bit PNG
        by default, which would throw away the extra precision that is
        the entire point of an HDR pass. -pix_fmt rgb48be forces a real
        16-bit write -- confirmed at the PNG chunk level, bit depth 16,
        colour type 2."""
        import shutil as _sh
        _sh.rmtree(out_dir, ignore_errors=True)
        os.makedirs(out_dir, exist_ok=True)
        r = subprocess.run(
            ["ffmpeg", "-y", "-i", video_path, "-pix_fmt", "rgb48be",
             os.path.join(out_dir, "%05d.png")], capture_output=True)
        got = sorted(f for f in os.listdir(out_dir) if f.endswith(".png"))
        if r.returncode != 0 or not got:
            raise RuntimeError(
                "could not decode the Topaz result: "
                + r.stderr.decode("utf-8", "replace")[-300:])
        return [os.path.join(out_dir, f) for f in got]

    @classmethod
    def _topaz_frame_to_scene(cls, png_path):
        """One decoded 16-bit PNG frame -> scene-referred BT.709 float,
        1.0 = diffuse white, matching the convention this app's own
        analytic expansion already writes.

        NOT PIL: Image.open + np.array on a 16-bit PNG reports mode
        "RGB" -- Pillow's 8-bit-per-channel name -- and silently hands
        back uint8, quietly discarding the extra 8 bits with no error
        and no warning. Confirmed directly: the same file read via
        cv2.imread(..., IMREAD_UNCHANGED) comes back uint16 as it
        should. This is not a hypothetical -- it is the exact failure
        this function exists to avoid.

        The chain: PQ code -> nits in BT.2020 -> nits in BT.709 ->
        divided by the same 100-nit white this app anchors everything
        else to. Verified end to end against known input nits at
        1, 18, 100 and 1000, through a real HEVC encode/decode, not
        just the pure maths in isolation."""
        import numpy as np
        import cv2
        a = cv2.imread(png_path, cv2.IMREAD_UNCHANGED)
        if a is None:
            raise RuntimeError(f"could not read {png_path}")
        a = cv2.cvtColor(a, cv2.COLOR_BGR2RGB)
        code = a.astype(np.float32) / 65535.0
        nits_2020 = cls._hdr_pq_decode(code)
        nits_709 = cls._bt2020_to_709(nits_2020)
        return np.clip(nits_709, 0.0, None) / cls.HDR_SDR_WHITE

    def _vace_upload(self, path, key):
        """Upload a local file to fal's CDN via the official client and
        return its URL. fal_client is required -- the only raw endpoint
        that returns a CDN URL a model can read is the one it wraps."""
        os.environ["FAL_KEY"] = key
        return self._fal_call_with_watchdog(
            lambda: self._fal_client(key).upload_file(path),
            cancel_check=lambda: getattr(self, "_ip_vace_cancel", False),
            label=f"the upload of {os.path.basename(path)}")

    def _vace_depth_map(self, video_path, key, out_mp4, on_log=None,
                        model="VDA-Large"):
        """Run the range's real footage through depth estimation
        (fal-ai/depth-anything-video) and download the resulting depth
        video to out_mp4.

        This is a SEPARATE, second fal call the Depth method makes before
        the actual VACE generation -- grayscale depth (near/far as
        brightness), temporally consistent across the clip rather than
        estimated frame-by-frame (which would flicker). Costs on top of
        the generation itself; see DEPTH_ANYTHING_RATE.

        model picks Video Depth Anything's size (VDA-Small/Base/Large):
        Small is fastest/cheapest to run, Large is the most accurate.
        """
        import urllib.request
        os.environ["FAL_KEY"] = key
        if on_log:
            on_log("Uploading the range for depth estimation\u2026")
        url = self._fal_call_with_watchdog(
            lambda: self._fal_client(key).upload_file(video_path),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label="the depth-range upload")
        if on_log:
            on_log(f"Estimating depth ({model})\u2026")
        result = self._fal_call_with_watchdog(
            lambda: self._fal_client(key).subscribe(self.DEPTH_ANYTHING_ENDPOINT,
                arguments={"video_url": url, "colormap": "grayscale",
                          "model": model},
                with_logs=False),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label="fal (depth estimation)")
        vid = (result or {}).get("video") or {}
        depth_url = vid.get("url") if isinstance(vid, dict) else vid
        if not depth_url:
            raise RuntimeError(
                f"No depth video in response: {str(result)[:300]}")
        self._fal_call_with_watchdog(
            lambda: urllib.request.urlretrieve(depth_url, out_mp4),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label="the depth video download")
        return out_mp4

    # How long a single fal call is allowed to sit with zero response
    # before this app gives up and raises a clear error, rather than
    # blocking forever. fal's own on_queue_update is the only progress
    # signal we get, and it can go completely silent for a long stretch
    # with no exception at all -- a dropped connection or a queue with
    # no position updates looks EXACTLY like "still working" from here.
    # 30 minutes is generous for a real, busy queue; it is not generous
    # enough to explain an hour of total silence with no error.
    VACE_FAL_TIMEOUT_S = 30 * 60
    # Uploads get their own, much shorter budget. 30 minutes is right
    # for a render that genuinely takes that long; for pushing a file of
    # a few megabytes it means a broken upload looks identical to a slow
    # one for half an hour. A minute-and-a-half per megabyte is
    # generous on any connection this app is usable on.
    VACE_FAL_UPLOAD_TIMEOUT_S = 6 * 60
    VACE_FAL_HEARTBEAT_S = 60   # how often to reassure the person we're
                                # still waiting, once fal's own logs stop
    VACE_FAL_POLL_S = 5         # how often cancellation is re-checked

    def _fal_call_with_watchdog(self, fn, on_log=None, cancel_check=None,
                                timeout_s=None,
                                label="fal"):
        """Run a blocking call (fal_client.subscribe or similar) on a
        background thread and poll for its result, instead of blocking
        the caller directly on it. This exists because on_queue_update
        (fal's own progress callback) is the ONLY hook we get inside a
        bare subscribe() call, and if it stops firing -- a dropped
        connection, a queue that never emits another position update --
        subscribe() itself just blocks with no exception, no log
        output, and, since our cancel flag was only ever checked INSIDE
        that same callback, no way to cancel from the UI either. Aron
        hit exactly this: uploads completed, then total silence for
        over an hour with no error.

        cancel_check() is polled every VACE_FAL_POLL_S seconds -- so
        cancellation now works even if fal's callback never fires
        again. on_log gets a heartbeat at most every
        VACE_FAL_HEARTBEAT_S seconds while waiting, so "still working"
        and "silently stuck" no longer look identical. Past
        VACE_FAL_TIMEOUT_S with nothing back, this raises a clear
        RuntimeError instead of waiting forever.

        fn is called with no arguments -- wrap args with a lambda.
        Returns fn's result, or re-raises whatever fn itself raised
        (via a daemon thread + Queue, so an abandoned call doesn't
        block process exit and can't corrupt this thread's stack).
        """
        # The bar shows fal's mark and stands still for as long as this
        # call is out -- on the Tk thread, wherever this one is.
        try:
            self.after(0, self._fal_hold_begin)
        except Exception:
            pass
        try:
            return self._fal_call_with_watchdog_inner(
                fn, on_log, cancel_check, timeout_s, label)
        finally:
            try:
                self.after(0, self._fal_hold_end)
            except Exception:
                pass

    def _fal_call_with_watchdog_inner(self, fn, on_log, cancel_check,
                                      timeout_s, label):
        import threading, queue, time
        start = time.time()
        last_heartbeat = [start]
        q = queue.Queue(maxsize=1)

        def _run():
            try:
                q.put(("ok", fn()))
            except Exception as ex:
                q.put(("err", ex))

        threading.Thread(target=_run, daemon=True).start()
        while True:
            if cancel_check is not None and cancel_check():
                if on_log:
                    on_log(f"Cancelled \u2014 no longer waiting on "
                          f"{label} (the request may still finish on "
                          "their end; this app just stops waiting "
                          "for it).")
                raise RuntimeError(f"Cancelled while waiting for {label}.")
            try:
                kind, val = q.get(timeout=self.VACE_FAL_POLL_S)
            except queue.Empty:
                now = time.time()
                elapsed = now - start
                if elapsed > (timeout_s or self.VACE_FAL_TIMEOUT_S):
                    raise RuntimeError(
                        f"Timed out after {elapsed / 60:.0f} min with no "
                        f"response from {label}. It may still be running "
                        "on their end -- check their dashboard, or try "
                        "again.")
                if on_log and now - last_heartbeat[0] >= self.VACE_FAL_HEARTBEAT_S:
                    last_heartbeat[0] = now
                    on_log(f"Still waiting on {label} "
                          f"({elapsed / 60:.1f} min elapsed)\u2026")
                continue
            if kind == "err":
                raise val
            return val

    def _vace_submit(self, files, plan, on_log, on_phase=None,
                     prompt_override=None, endpoint=None, payload_fn=None,
                     on_panel=None):
        """The only function that touches the network. Isolated so the rest
        of the pipeline is testable offline and the provider can be swapped
        without touching it. Returns the local path of the returned mp4.

        Requires the official fal_client. It uploads the anchor stills to
        fal's CDN, submits, and polls the queue in one call. We do NOT roll
        our own uploader: the only raw endpoint that returns a usable CDN
        URL for model inputs is the one fal_client wraps -- the platform
        file-upload API uploads to project storage and hands back a
        boolean, not a URL a model can read.

        endpoint/payload_fn let a caller target a different VACE task
        (e.g. depth instead of inpainting) without duplicating the
        upload/poll machinery -- payload_fn(urls, prompt_override) builds
        the request body once the upload URLs are known. Both default to
        the inpainting path, so existing callers are unaffected.

        on_panel, if given, is called with request-id/queue-position
        updates for a standing status panel. This call is shared by
        several tabs and does not know which one of them, if any, has a
        panel open -- so it never assumes one exists. A caller with no
        panel simply omits this and gets the same behaviour as before.
        """
        _ph = on_phase or (lambda k, d="": None)
        key = self._vace_key()
        if not key:
            raise RuntimeError("No API key. Set one up on the Setup tab.")

        try:
            # Presence check only -- importlib rather than a plain
            # import so there is no unused name for the linter to flag.
            # The client itself is built in _fal_client, which is the
            # only place allowed to construct one.
            import importlib
            importlib.import_module("fal_client")
        except ImportError:
            import sys as _sys
            raise RuntimeError(
                "The fal client library is required and is not installed in "
                "the Python that runs this app. Install it with:\n\n"
                f"    {_sys.executable} -m pip install fal-client\n\n"
                "then restart. (Running 'pip install fal-client' in a "
                "different environment will not work -- it must be the one "
                "above.)")

        os.environ["FAL_KEY"] = key

        # 1 — upload the source video, mask, and anchor stills
        urls = {}
        n_files = len(files)
        for i, (tag, path) in enumerate(files.items()):
            sz = os.path.getsize(path) / 1e6
            _ph("upload", f"{os.path.basename(path)} ({sz:.1f} MB), "
                          f"{i+1} of {n_files}")
            on_log(f"Uploading {os.path.basename(path)} ({sz:.1f} MB)\u2026")
            urls[tag] = self._fal_call_with_watchdog(
                lambda p=path: self._fal_client(key).upload_file(p),
                on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
                timeout_s=self.VACE_FAL_UPLOAD_TIMEOUT_S,
                label=f"the upload of {os.path.basename(path)}")

        # 2 — submit + poll via subscribe. on_queue_update gives us fal's
        #     own logs, the only real progress signal there is.
        _ph("queue", "submitting")
        seen = set()

        app_id_src = endpoint or self._vace_active_endpoint()
        app_id = app_id_src.rsplit("/fal-ai/", 1)[-1]
        app_id = "fal-ai/" + app_id if not app_id.startswith("fal-ai/") \
            else app_id
        state = {"phase": None, "pos": None, "req": None}

        def _pfeed(**kw):
            """Reaches whichever tab's standing panel is open, via the
            caller-supplied on_panel -- this function serves three tabs
            and does not itself know which one, if any, has a panel."""
            if on_panel is None:
                return
            try:
                self.after(0, lambda k=kw: on_panel(**k))
            except Exception:
                pass

        def _on_update(update):
            if self._ip_vace_cancel:
                return
            name = type(update).__name__
            # The request id is the only handle fal support can act on,
            # so it is worth saying once rather than being buried in a
            # traceback if something goes wrong later.
            rid = (getattr(update, "request_id", None)
                   or getattr(update, "requestId", None))
            if rid and rid != state["req"]:
                state["req"] = rid
                on_log(f"fal request {rid}")
                _pfeed(req=rid)
            if "Queued" in name:
                pos = getattr(update, "position", None)
                # Only when it MOVES. Repeating "position 3" every poll
                # buries fal's own log lines and makes a queue that is
                # advancing look identical to one that is stuck.
                if pos != state["pos"]:
                    state["pos"] = pos
                    on_log(f"Queued at position {pos}"
                           if pos is not None else "Queued")
                _ph("queue", f"position {pos}" if pos is not None
                    else "waiting")
            else:
                if state["phase"] != "render":
                    state["phase"] = "render"
                    on_log(f"Rendering {plan['request']} frames on "
                           f"{app_id}\u2026")
                _ph("render", f"{plan['request']} frames")
            for lg in (getattr(update, "logs", None) or []):
                m = lg.get("message") if isinstance(lg, dict) else str(lg)
                if m and m not in seen:
                    seen.add(m)
                    on_log(f"fal: {m}")

        body = (payload_fn(urls, prompt_override) if payload_fn is not None
                else self._vace_payload(plan, urls,
                                       prompt_override=prompt_override))
        result = self._fal_call_with_watchdog(
            lambda: self._fal_client(key).subscribe(app_id, arguments=body,
                with_logs=True, on_queue_update=_on_update),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label=f"fal ({app_id})")

        vid = result.get("video") or result.get("output") or {}
        url = vid.get("url") if isinstance(vid, dict) else vid
        if not url:
            raise RuntimeError(f"No video in response: {str(result)[:300]}")
        import urllib.request
        dst = os.path.join(self._vace_work_dir(), "vace_out.mp4")
        _ph("download", "")
        on_log("Downloading result\u2026")
        # urlretrieve has no timeout of its own -- a stalled download
        # would hang exactly like the subscribe() call did.
        self._fal_call_with_watchdog(
            lambda: urllib.request.urlretrieve(url, dst),
            on_log=on_log, cancel_check=lambda: self._ip_vace_cancel,
            label="the result download")
        return dst


    def _esrgan_bin(self):
        """The Real-ESRGAN binary, or None if it is not installed."""
        p = os.path.expanduser(
            "~/RifeApp/realesrgan-ncnn-vulkan/realesrgan-ncnn-vulkan")
        return p if os.path.exists(p) else None

    def _vace_upscale_dir(self, src_dir, files, target, on_log=None):
        """Upscale a folder of frames to the plate size with Real-ESRGAN.

        VACE caps at 720p, so on a 2K plate everything comes back small.
        A plain resize just makes soft pixels bigger; ESRGAN reconstructs
        detail, which is the difference between a usable rebuild and an
        obviously soft patch in the middle of a sharp shot.

        Folder mode in one call, not per frame -- the binary reloads its
        model on every invocation, so per-frame is several times slower.
        Returns True if ESRGAN did the work, False to fall back.
        """
        import subprocess as _sp, tempfile, shutil as _sh
        from PIL import Image
        exe = self._esrgan_bin()
        if not exe:
            if on_log:
                on_log("Real-ESRGAN not installed \u2014 falling back to a "
                       "plain resize. Install it on the Setup tab for a "
                       "sharper upscale.")
            return False
        pw, ph = target
        gw, gh = Image.open(os.path.join(src_dir, files[0])).size
        # the binary only does integer scales; take the next one up and
        # trim back to the exact plate size afterwards
        scale = max(2, min(4, int(-(-pw // max(1, gw)))))
        tmp = tempfile.mkdtemp(prefix="vace_up_")
        try:
            if on_log:
                on_log(f"Real-ESRGAN x{scale}: {gw}x{gh} \u2192 {pw}x{ph} "
                       f"({len(files)} frames)\u2026")
            r = _sp.run([exe, "-i", src_dir, "-o", tmp,
                         "-n", "realesrgan-x4plus", "-s", str(scale),
                         "-f", "png"],
                        capture_output=True, timeout=1800)
            done = sorted(f for f in os.listdir(tmp) if f.endswith(".png"))
            if r.returncode != 0 or len(done) != len(files):
                if on_log:
                    on_log("Real-ESRGAN did not complete \u2014 falling back "
                           "to a plain resize. "
                           + r.stderr.decode("utf-8", "replace")[-160:])
                return False
            for f in done:
                im = Image.open(os.path.join(tmp, f))
                if im.size != (pw, ph):
                    im = im.resize((pw, ph), Image.LANCZOS)
                im.save(os.path.join(src_dir, f))
            if on_log:
                on_log("Real-ESRGAN upscale done.")
            return True
        except Exception as ex:
            if on_log:
                on_log(f"Real-ESRGAN failed ({type(ex).__name__}) \u2014 "
                       "falling back to a plain resize.")
            return False
        finally:
            _sh.rmtree(tmp, ignore_errors=True)

    def _vace_decode(self, mp4, out_dir, plate_size=None, on_log=None,
                     upscale=False):
        """Decode the returned clip, and bring it back to the PLATE's
        exact resolution.

        The endpoint caps out at 720p, so on a 2K plate every generated
        frame comes back smaller — and possibly at a different aspect.
        Splicing those in unresized leaves a sequence of mixed resolutions,
        which is what put a black band down the side of the result.

        With upscale=True the enlargement goes through Real-ESRGAN, which
        reconstructs detail rather than just interpolating it.

        The colour tags below force bt709 on read, closing the one gap
        on THIS side of the round trip that was left to ffmpeg's own
        resolution-based guess. What they cannot do is verify or
        correct whatever colour handling VACE itself applies
        internally -- that is a black box this app has no way to
        inspect or control from here, and any residual shift after
        this fix may still trace back to it rather than to anything
        in this function.
        """
        import subprocess as _sp, shutil as _sh
        from PIL import Image
        _sh.rmtree(out_dir, ignore_errors=True); os.makedirs(out_dir, exist_ok=True)
        # Forced to bt709 on the way IN, not trusted from whatever tag
        # (or lack of one) the returned clip carries: the encode side
        # of this round trip now tags bt709 explicitly, and this input
        # override makes sure the decode side reads it back under the
        # SAME assumption rather than ffmpeg's own resolution-based
        # guess -- which is free to disagree with the encode side of a
        # round trip that changes resolution in between, which this one
        # always does.
        r = _sp.run(["ffmpeg", "-y",
                     "-color_primaries", "bt709", "-color_trc", "bt709",
                     "-colorspace", "bt709",
                     "-i", mp4,
                     os.path.join(out_dir, "%05d.png")], capture_output=True)
        got = sorted(f for f in os.listdir(out_dir) if f.endswith(".png"))
        if r.returncode != 0 or not got:
            raise RuntimeError("could not decode the returned clip: "
                + r.stderr.decode("utf-8", "replace")[-300:])
        if plate_size:
            gw, gh = Image.open(os.path.join(out_dir, got[0])).size
            pw, ph = plate_size
            if (gw, gh) != (pw, ph):
                if on_log:
                    fac = pw / float(gw)
                    on_log(f"VACE returned {gw}x{gh}, the plate is {pw}x{ph}"
                           f" \u2014 bringing it back ({fac:.2f}x).")
                ga, pa = gw / float(gh), pw / float(ph)
                aspect_off = abs(ga - pa) > 0.005
                if aspect_off and on_log:
                    on_log(f"\u26a0 Aspect changed: {ga:.3f} \u2192 "
                           f"{pa:.3f} \u2014 letterboxing rather than "
                           "stretching, so shapes stay correct.")
                done = False
                if upscale and pw > gw and not aspect_off:
                    done = self._vace_upscale_dir(out_dir, got, (pw, ph),
                                                  on_log=on_log)
                if not done:
                    for f in got:
                        p = os.path.join(out_dir, f)
                        if aspect_off:
                            # NOT a plain stretch-to-fill: that silently
                            # distorts geometry exactly the amount the
                            # aspect ratios disagree by -- a round
                            # ferris wheel comes back oval, a vertical
                            # tower leans. Fit the generated frame's OWN
                            # aspect inside (pw, ph) and pad the
                            # remainder, so every shape VACE actually
                            # drew keeps its true proportions.
                            img = Image.open(p).convert("RGB")
                            scale = min(pw / gw, ph / gh)
                            fw, fh = max(1, round(gw * scale)), \
                                max(1, round(gh * scale))
                            fitted = img.resize((fw, fh), Image.LANCZOS)
                            canvas = Image.new("RGB", (pw, ph))
                            x0 = (pw - fw) // 2
                            y0 = (ph - fh) // 2
                            canvas.paste(fitted, (x0, y0))
                            # Edge-replicated padding, not a flat/black
                            # border: a hard black band is its own new,
                            # obviously-wrong artefact right at the
                            # frame edge, where a repair's neighbouring
                            # context is least likely to hide it.
                            if x0 > 0:
                                left = fitted.crop((0, 0, 1, fh)) \
                                    .resize((x0, fh))
                                right = fitted.crop((fw - 1, 0, fw, fh)) \
                                    .resize((pw - fw - x0, fh))
                                canvas.paste(left, (0, y0))
                                canvas.paste(right, (x0 + fw, y0))
                            if y0 > 0:
                                top = fitted.crop((0, 0, fw, 1)) \
                                    .resize((fw, y0))
                                bot = fitted.crop((0, fh - 1, fw, fh)) \
                                    .resize((fw, ph - fh - y0))
                                canvas.paste(top, (x0, 0))
                                canvas.paste(bot, (x0, y0 + fh))
                            canvas.save(p)
                        else:
                            Image.open(p).resize((pw, ph),
                                                 Image.LANCZOS).save(p)
        return got

    def _vace_work_dir(self):
        """Scratch for the returned clip.

        Beside ADW-Interpolate's input when that tab is driving. Other
        tabs call _vace_submit too, and there ip_folder is None -- which
        reached os.path.abspath(None) and failed with a TypeError
        thirteen minutes into a generation that had already succeeded,
        losing the paid-for result at the last step. Falls back to the
        system temp directory, which is what the scratch is for."""
        root = getattr(self, "ip_folder", None)
        if root and os.path.isdir(str(root)):
            base = self._adw_output_root(root)
        else:
            base = tempfile.gettempdir()
        d = os.path.join(base, "ADW-Interpolate_VACE")
        os.makedirs(d, exist_ok=True)
        return d

    # ── the VACE pipeline: generate slow -> retime to speed -> splice ──

    def _interp_autoprompt(self):
        """Fill the VACE prompt from the shot itself.

        Two halves: the motion words come free from the analysis already
        on screen, the scene description comes from one small vision-model
        call on fal. Threaded, because the caption is a network round trip.
        """
        import threading
        if getattr(self, "_ip_prompting", False):
            return
        seg = self._interp_active_seg()
        if seg is None:
            self.log(self.ip_log_txt, "Select a range first.", "err")
            return
        gap = self._vace_gap(seg)[0]
        if gap is None:
            self.log(self.ip_log_txt,
                     "That range is too short to describe.", "err")
            return
        r0, r1 = gap[0], gap[1]
        folder = self.ip_src_folder or self.ip_folder
        names = list(self.ip_src_frames or self.ip_frames)
        mid = (r0 + r1) // 2

        words = self._interp_motion_words(r0, r1)
        if not words:
            self.log(self.ip_log_txt,
                "No motion data for this range \u2014 run Analyse Motion "
                "for motion wording as well as the description.", "dim")

        self._ip_prompting = True
        self.ip_prompt_btn.configure(text="\u2026  Describing")
        self.log(self.ip_log_txt,
            f"Describing frame {mid + 1} of the range (a fraction of a "
            "cent on fal)\u2026", "dim")

        def _ui(fn):
            try: self.after(0, fn)
            except Exception: pass

        def go():
            tmp = None
            try:
                import tempfile
                tf = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
                tmp = tf.name; tf.close()
                self._ip_pv_frame(os.path.join(folder, names[mid])).save(tmp)
                cap = self._vace_caption_frame(
                    tmp, on_log=lambda m: _ui(
                        lambda mm=m: self.log(self.ip_log_txt, mm, "dim")))
                if not cap:
                    raise RuntimeError("the model returned no description")
                prompt = self._interp_compose_prompt(cap, words)
                def _done():
                    self.ip_vace_prompt_var.set(prompt)
                    self.log(self.ip_log_txt,
                        f"\u2713 Prompt set: {prompt[:110]}"
                        + ("\u2026" if len(prompt) > 110 else "")
                        + "  Edit it if it missed anything.", "ok")
                _ui(_done)
            except Exception as ex:
                _ui(lambda e=ex: self.log(self.ip_log_txt,
                    f"Auto-prompt failed: {type(e).__name__}: {e}", "err"))
            finally:
                if tmp:
                    try: os.unlink(tmp)
                    except OSError: pass
                _ui(lambda: (setattr(self, "_ip_prompting", False),
                             self.ip_prompt_btn.configure(
                                 text="\u2728  Describe shot")))

        threading.Thread(target=go, daemon=True).start()

    def _vace_generate(self):
        """Regenerate every range on the timeline in one pass, not just
        the active segment. Each range is built, uploaded and generated
        in turn; ranges that are too short or otherwise invalid are
        skipped with a reason rather than aborting the whole batch.
        """
        import threading, shutil as _sh
        if self._ip_vace_busy:
            self._ip_vace_cancel = True
            self.log(self.ip_log_txt,
                "Cancelling after the current range finishes\u2026", "dim")
            return
        if not self.ip_frames:
            self.log(self.ip_log_txt, "Load a sequence first.", "err"); return
        if not self.ip_segments:
            self.log(self.ip_log_txt, "Add a range first (+).", "err"); return
        if not self._vace_key():
            self.log(self.ip_log_txt,
                "No fal.ai key. Set one up on the Setup tab.", "err")
            return

        # Validate every range up front. One bad range should not block
        # the rest of the batch, so it is skipped and reported, not fatal.
        queue, skipped = [], []
        for seg in list(self.ip_segments):
            plan = self._vace_plan(seg, self.ip_vace_frames_var.get())
            (queue if plan["ok"] else skipped).append((seg, plan))
        if not queue:
            for seg, plan in skipped:
                self.log(self.ip_log_txt,
                    f"{seg['name']}: {plan['reason']}", "err")
            self.ip_vace_stat.configure(
                text="\u2716 No range is ready to generate.", fg="#CC4444")
            return
        for seg, plan in skipped:
            self.log(self.ip_log_txt,
                f"Skipping {seg['name']}: {plan['reason']}", "err")

        folder = self.ip_src_folder or self.ip_folder
        names = list(self.ip_src_frames or self.ip_frames)
        res = self.ip_vace_res_var.get()
        method = self.ip_vace_method_var.get()
        depth_model = self.ip_depth_model_var.get()
        coverage = max(5, min(100, int(self.ip_vace_coverage_var.get()))) / 100.0
        do_upscale = bool(self.ip_vace_upscale_var.get())
        autoprompt = bool(self.ip_autoprompt_var.get())
        n_total = len(queue)

        self._ip_vace_busy = True
        self._ip_vace_cancel = False
        self._ip_vace_t0 = time.time()
        self._ip_vace_phase = "prep"
        self._ip_vace_detail = ""
        if self._ip_vace_ticker is None:
            self._vace_tick()

        total_cost = sum(self._vace_cost(p, res) for _, p in queue)
        self.log(self.ip_log_txt,
            f"VACE: generating {n_total} range(s)"
            + (f" ({len(skipped)} skipped)" if skipped else "") +
            f". ~${total_cost:.2f} total"
            + (" \u2014 plus a small captioning call per range (auto-"
               "prompt is on)." if autoprompt else "."), "hi")

        def _ui(fn):
            try: self.after(0, fn)
            except Exception: pass

        def go():
            n_ok = 0
            n_fail = 0
            cancelled = False
            for idx, (seg, plan) in enumerate(queue):
                if self._ip_vace_cancel:
                    cancelled = True
                    break
                seg_name = seg["name"]
                tag = self._interp_safe_name(seg_name)
                a, b, g = plan["a"], plan["b"], plan["gap"]
                # send0/send1/send_g are the padded range actually sent
                # to VACE (includes Tether context, Mask method only --
                # equal to a/b/g whenever Tether is 0 or method is
                # depth); core_start/core_end are a/b's position within
                # that padded clip, for stripping the Tether frames back
                # out of whatever VACE returns before the splice.
                send0, send1 = plan["send0"], plan["send1"]
                send_g = plan["send_gap"]
                core_start, core_end = plan["core_start"], plan["core_end"]
                tether_l, tether_r = plan["tether_l"], plan["tether_r"]
                prefix = f"[{idx + 1}/{n_total}] {seg_name}"

                def _log(m, _p=prefix):
                    _ui(lambda mm=m: self.log(self.ip_log_txt,
                                              f"{_p}: {mm}", "dim"))
                def _phase(key, detail="", _p=prefix):
                    self._ip_vace_phase = key
                    self._ip_vace_detail = detail
                    _ui(lambda kk=key, dd=detail, pp=_p: self._vace_say(
                        kk, f"{pp} \u2014 {dd}" if dd else pp,
                        pulse=(kk in ("render", "queue"))))

                if method == "depth":
                    _log(f"regenerating {g} frame(s), whole frame, guided "
                         f"by a depth map; ends {a + 1} and {b + 1} "
                         f"anchor it. ~${self._vace_cost(plan, res):.2f} "
                         "(includes the depth pass)")
                elif method == "full":
                    _log(f"regenerating {g} frame(s), whole frame, guided "
                         f"by the real plate footage directly (no depth "
                         f"pass); ends {a + 1} and {b + 1} anchor it. "
                         f"~${self._vace_cost(plan, res):.2f}")
                else:
                    _log(f"regenerating {g} frame(s) at {int(coverage * 100)}% "
                         f"of frame; ends {a + 1} and {b + 1} anchor it"
                         + (f", with {tether_l}+{tether_r} tether "
                            "frame(s) for context"
                            if tether_l or tether_r else "") + ". "
                         f"~${self._vace_cost(plan, res):.2f}")
                try:
                    work = self._vace_work_dir()
                    fps = self._interp_fps()
                    # 1 — the control input. Inpainting: real footage
                    #     where VACE should KEEP, grey where it should
                    #     synthesise. Depth: the range's real footage run
                    #     through a separate depth-estimation fal call,
                    #     since VACE's depth task conditions on a depth
                    #     video, not the raw footage. Inpainting sends
                    #     send0..send1 (the CORE selection padded with
                    #     Tether context on each side); Depth is
                    #     untouched by Tether and still just sends a..b.
                    plate = self._ip_pv_frame(os.path.join(folder,
                        names[a])).size
                    if method in ("depth", "full"):
                        pa = self._ip_pv_frame(os.path.join(folder, names[a]))
                        _phase("prep", f"real clip, frames {a+1}\u2013{b+1}")
                        plain_mp4 = os.path.join(work, tag + "_plain.mp4")
                        self._vace_build_plain_clip(folder, names, a, b,
                            plain_mp4, fps)
                        if method == "depth":
                            _phase("prep", "depth estimation")
                            depth_mp4 = os.path.join(work, tag + "_depth.mp4")
                            self._vace_depth_map(plain_mp4, self._vace_key(),
                                depth_mp4, on_log=_log, model=depth_model)
                        else:
                            # Full image: no depth pass -- the plain,
                            # untouched clip IS the conditioning video.
                            depth_mp4 = plain_mp4
                    else:
                        pa = self._ip_pv_frame(os.path.join(folder,
                            names[send0]))
                        # 1a — the control clip: real footage where VACE
                        #     should KEEP, grey where it should synthesise
                        _phase("prep",
                              f"control clip, frames {send0+1}"
                              f"\u2013{send1+1}"
                              + (f" (selection {a+1}\u2013{b+1})"
                                 if tether_l or tether_r else ""))
                        src_mp4 = os.path.join(work, tag + "_src.mp4")
                        brush_mask = seg.get("brush_mask")
                        self._vace_build_source_clip(folder, names,
                            send0, send1, src_mp4, fps, coverage=coverage,
                            custom_mask=brush_mask,
                            core_start=core_start, core_end=core_end)

                        # 1b — the mask: white where the control is grey
                        _phase("prep", "mask clip")
                        mask_mp4 = os.path.join(work, tag + "_mask.mp4")
                        self._vace_build_mask_clip(send_g, plate, mask_mp4,
                                                   fps, coverage=coverage,
                                                   custom_mask=brush_mask,
                                                   core_start=core_start,
                                                   core_end=core_end)

                    # 2 — the anchor stills pin the ends of whatever was
                    #     actually sent (send0/send1 for Mask, a/b for
                    #     Depth/Full image, identical to send0/send1
                    #     when Tether is 0)
                    first = os.path.join(work, tag + "_A.png")
                    last = os.path.join(work, tag + "_B.png")
                    pa.save(first)
                    self._ip_pv_frame(os.path.join(folder,
                        names[b if method in ("depth", "full") else send1])
                                  ).save(last)

                    # auto-prompt: a fresh description of THIS range, not
                    # one shared prompt reused across every range in the
                    # batch. Falls back to the Prompt field on any failure
                    # (missing key, network) rather than stalling the run.
                    prompt_override = None
                    if autoprompt:
                        _phase("prep", "describing this range")
                        try:
                            words = self._interp_motion_words(a, b)
                            mid = (a + b) // 2
                            import tempfile
                            tf = tempfile.NamedTemporaryFile(
                                suffix=".png", delete=False)
                            tmp_path = tf.name; tf.close()
                            self._ip_pv_frame(os.path.join(
                                folder, names[mid])).save(tmp_path)
                            cap = self._vace_caption_frame(tmp_path,
                                                           on_log=_log)
                            try: os.unlink(tmp_path)
                            except OSError: pass
                            prompt_override = self._interp_compose_prompt(
                                cap, words)
                            _log("prompt: " + prompt_override[:100]
                                 + ("\u2026" if len(prompt_override) > 100
                                    else ""))
                        except Exception as pex:
                            _log("auto-prompt failed "
                                 f"({type(pex).__name__}: {pex}); using "
                                 "the Prompt field instead.")

                    # 3 — generate: inpainting sends video+mask+anchors
                    #     at the inpainting endpoint; depth and full
                    #     image both send just a video (no mask) at the
                    #     depth endpoint -- depth_mp4 is either the real
                    #     depth-estimation output (Depth) or the plain
                    #     untouched clip standing in for it (Full image)
                    if method in ("depth", "full"):
                        mp4 = self._vace_submit(
                            {"video": depth_mp4, "first": first,
                             "last": last},
                            plan, _log, on_phase=_phase,
                            prompt_override=prompt_override,
                            endpoint=self.VACE_ENDPOINT_DEPTH,
                            payload_fn=lambda urls, po:
                                self._vace_depth_payload(plan, urls,
                                                         prompt_override=po))
                    else:
                        mp4 = self._vace_submit(
                            {"video": src_mp4, "mask": mask_mp4,
                             "first": first, "last": last},
                            plan, _log, on_phase=_phase,
                            prompt_override=prompt_override)

                    _phase("decode", "")
                    raw = os.path.join(work, tag + "_gen")
                    got = self._vace_decode(mp4, raw, plate_size=plate,
                                            on_log=_log, upscale=do_upscale)
                    if len(got) < 1:
                        raise RuntimeError("VACE returned no frames.")

                    # 5 — match_input_num_frames should give exactly
                    #     send_g frames (the padded request, including
                    #     any Tether context); if the count differs,
                    #     resample by index first so positions still
                    #     line up with the padded timeline
                    _phase("pick", f"{send_g} frames")
                    if len(got) == send_g:
                        pick_idx = list(range(send_g))
                    else:
                        _log(f"VACE returned {len(got)} frames for a "
                             f"{send_g}-frame request; resampling to "
                             "match.")
                        pick_idx = self._vace_pick(send_g, len(got))

                    # 6 — strip the Tether frames: only
                    #     [core_start, core_end] (local to the padded
                    #     clip) is the actual selection. The rest was
                    #     real context sent to help VACE anchor motion,
                    #     never meant to be spliced back in.
                    core_pick_idx = pick_idx[core_start:core_end + 1]
                    out = os.path.join(work, tag + "_fill")
                    _sh.rmtree(out, ignore_errors=True)
                    os.makedirs(out, exist_ok=True)
                    for j, k_ in enumerate(core_pick_idx):
                        _sh.copy(os.path.join(raw, got[k_]),
                                 os.path.join(out, "%05d.png" % j))
                    _log(f"rebuilt {g} frames."
                         + (f" ({tether_l}+{tether_r} tether frame(s) "
                            "discarded)" if tether_l or tether_r else ""))
                    _ui(lambda sn=seg_name, oo=out, gg=g:
                        self._vace_fill_done(sn, oo, gg, reset=False))
                    n_ok += 1
                except Exception as ex:
                    n_fail += 1
                    _ui(lambda e=ex, p=prefix: self.log(self.ip_log_txt,
                        f"{p} failed: {type(e).__name__}: {e}", "err"))

            summary = f"{n_ok}/{n_total} range(s) generated"
            if skipped:
                summary += f", {len(skipped)} skipped"
            if n_fail:
                summary += f", {n_fail} failed"
            if cancelled:
                summary += " \u2014 cancelled"
            summary += "."
            tone = "ok" if n_fail == 0 and n_ok else (
                "err" if n_ok == 0 else "hi")
            mark = "\u2713 " if tone == "ok" else (
                "\u2716 " if tone == "err" else "")
            _ui(lambda: self.log(self.ip_log_txt, summary, tone))
            _ui(lambda: self._vace_reset_btn(mark + summary))

        threading.Thread(target=go, daemon=True).start()

    def _vace_fill_done(self, seg_name, out_dir, g, reset=True):
        n = len([f for f in os.listdir(out_dir) if f.endswith(".png")]) \
            if os.path.isdir(out_dir) else 0
        took = ""
        if self._ip_vace_t0:
            s = int(time.time() - self._ip_vace_t0)
            took = f" in {s // 60}m {s % 60}s"
        if n == g:
            self._ip_vace_result[seg_name] = out_dir
            self.log(self.ip_log_txt,
                f"\u2713 {seg_name}: {n} replacement frame(s) ready"
                f"{took} \u2014 already visible when scrubbing the "
                "timeline. Export/Run ADW-Interpolate when ready to "
                "write the final sequence to disk.", "ok")
            if reset:
                self._vace_reset_btn(
                    f"\u2713 {seg_name} \u2014 {n} frame(s) generated{took}, "
                    "showing on the timeline now.")
        else:
            self.log(self.ip_log_txt,
                f"Expected {g} frames, got {n}.", "err")
            if reset:
                self._vace_reset_btn(f"\u2716 Expected {g} frames, got {n}.")
        self._interp_segments_changed()

    def _vace_reset_btn(self, msg=""):
        self._ip_vace_busy = False
        self._ip_vace_cancel = False
        self._ip_vace_phase = None
        self._ip_vace_detail = ""
        if self._ip_vace_ticker is not None:
            try: self.after_cancel(self._ip_vace_ticker)
            except Exception: pass
            self._ip_vace_ticker = None
        self._ip_vace_t0 = None
        if hasattr(self, "ip_vace_btn"):
            self.ip_vace_btn.configure(progress=0.0)
            # let the button report the segment's state rather than
            # snapping back to a generic label
            self._interp_refresh_vace_btn()
        if hasattr(self, "ip_vace_stat"):
            self.ip_vace_stat.configure(text=msg,
                fg=("#CC4444" if msg.startswith("\u2716") else "#66CC66"))
        try:
            self.progress(-1)
        except Exception:
            pass


    def _vace_check_disk_space(self, total, plate, sample_png_path,
                              out_dir, on_log=None):
        """Best-effort guard against filling the disk mid-write.

        EXR frames here are 32-bit float with no compression flag set, so
        they can be an order of magnitude bigger than the source footage
        -- a long range on a 2K+ plate can need far more room than it
        looks like it should, and running out mid-encode wastes the time
        already spent and leaves a half-written sequence behind.

        Estimated from ONE real staged frame, so it is a heads-up, not a
        promise -- content-dependent PNG compression means the true
        number can differ.
        """
        import shutil as _sh_mod
        w, h = plate

        def _gb(n):
            return f"{n / (1024 ** 3):.1f} GB"

        try:
            png_bytes = os.path.getsize(sample_png_path)
        except OSError:
            png_bytes = w * h * 3          # a safe-ish fallback guess
        # gbrpf32le with no -compression flag is effectively uncompressed:
        # 3 channels x 4 bytes/channel.
        exr_bytes = w * h * 3 * 4
        need = total * (png_bytes + exr_bytes)
        stage_dir = os.path.dirname(sample_png_path)
        free = min(_sh_mod.disk_usage(stage_dir).free,
                   _sh_mod.disk_usage(out_dir).free)
        if need > free * 0.9:
            raise RuntimeError(
                f"This needs roughly {_gb(need)} (staged PNGs plus an "
                f"uncompressed EXR sequence at {w}x{h}, {total} frames) "
                f"but only {_gb(free)} is free. Free up space, output to "
                "a drive with more room, or switch Output to MOV \u2014 "
                "ProRes is far smaller than 32-bit EXR.")
        if on_log and need > free * 0.5:
            on_log(f"This will use roughly {_gb(need)} of the "
                   f"{_gb(free)} free \u2014 worth keeping an eye on.")

    def _vace_apply(self):
        """Splice every rebuilt segment into the sequence and write a fresh
        versioned output: rebuilt frames inside the segments, untouched
        source everywhere else. Then make the result playable, because
        "did that work" is a question you answer by WATCHING it."""
        import threading
        if self._ip_applying:
            return
        if not self.ip_frames:
            self.log(self.ip_log_txt, "Load a sequence first.", "err"); return
        have = {s["name"]: self._ip_vace_result.get(s["name"])
                for s in self.ip_segments
                if self._ip_vace_result.get(s["name"])}
        if not have:
            self.log(self.ip_log_txt,
                "Nothing rebuilt yet — generate a segment first.", "err")
            self.ip_vace_stat.configure(
                text="\u2716 Nothing rebuilt yet.", fg="#CC4444")
            return
        out_dir = self._adw_versioned_output_dir(self.ip_folder,
                                                 "ADW-Interpolate")
        os.makedirs(out_dir, exist_ok=True)
        out_fmt = self.ip_out_fmt_var.get()
        out_fps = self._interp_fps()
        folder = self.ip_src_folder or self.ip_folder
        names = list(self.ip_src_frames or self.ip_frames)
        segs = [dict(s) for s in self.ip_segments if s["name"] in have]
        total = len(names)
        done_names = [s["name"] for s in segs]

        self._ip_applying = True
        self.ip_vace_apply_btn.configure(text="\u2026  RUNNING", progress=0.0)
        self.ip_vace_stat.configure(
            text=f"Splicing {len(segs)} segment(s) into {total} frames\u2026",
            fg="#66CC66")
        self.log(self.ip_log_txt,
            f"Inserting VACE frames from {len(segs)} segment(s) into "
            f"{total} frames. Copying the plate and dropping the generated "
            f"frames into the gaps \u2014 a sharp cut at each edge, no "
            f"blend. Output: {os.path.basename(out_dir)}/", "hi")
        def _ui(fn):
            try: self.after(0, fn)
            except Exception: pass

        def go():
            from PIL import Image
            stage = None
            try:
                # the generated frames replace the DAMAGE range, not the
                # whole segment: only the broken frames were deleted.
                # Any Tether context frames VACE was given never appear
                # here at all -- _vace_gap returns only the core
                # selection, exactly what the person marked.
                repl = {}
                for s in segs:
                    d = have[s["name"]]
                    fs = sorted(f for f in os.listdir(d)
                                if os.path.splitext(f)[1].lower()
                                in (".png", ".exr", ".jpg"))
                    gap, _ = self._vace_gap(s)
                    if gap is None:
                        continue
                    r0, r1, _a, _b, _n = gap
                    for j, idx in enumerate(range(r0, r1 + 1)):
                        if j < len(fs):
                            repl[idx] = os.path.join(d, fs[j])

                import tempfile, subprocess as _sp, shutil as _sh4

                def _encode_err(prefix, r):
                    msg = r.stderr.decode("utf-8", "replace")
                    if "No space left on device" in msg:
                        free = _sh4.disk_usage(out_dir).free
                        return (f"{prefix}: ran out of disk space "
                                f"({free / (1024 ** 3):.1f} GB was free when "
                                "it failed). Free up space, output to a "
                                "drive with more room, or switch Output to "
                                "MOV, which is far smaller than 32-bit EXR.")
                    return f"{prefix}: " + msg[-300:]

                checked_space = [False]

                def _check_space_once(sample_path, plate_size):
                    if checked_space[0]:
                        return
                    checked_space[0] = True
                    self._vace_check_disk_space(total, plate_size,
                        sample_path, out_dir, on_log=lambda m: _ui(
                            lambda mm=m: self.log(self.ip_log_txt,
                                                  mm, "hi")))

                if out_fmt == "MOV":
                    # MOV is one continuous review file, so every frame has
                    # to be staged and assembled together regardless -- real
                    # frames go through the same tonemapped preview decode
                    # used on-screen, which is the right call for a review
                    # copy that's meant to look reasonable on a display, not
                    # carry the plate's original data untouched.
                    stage = tempfile.mkdtemp(prefix="ip_stage_")
                    plate = None
                    for i, nm in enumerate(names):
                        src = repl.get(i)
                        if src:
                            pil = Image.open(src).convert("RGB")
                            if plate and pil.size != plate:
                                pil = pil.resize(plate, Image.LANCZOS)
                        else:
                            pil = self._ip_pv_frame(os.path.join(folder, nm))
                            plate = pil.size
                        dst = os.path.join(stage, f"{i:05d}.png")
                        pil.save(dst)
                        _check_space_once(dst, pil.size)
                        if i % 3 == 0:
                            _ui(lambda p=0.6 * (i + 1) / total:
                                (self.progress(p, "ADW-Interpolate — staging"),
                                 self.ip_vace_apply_btn.configure(progress=p)))
                    mov_path = os.path.join(out_dir, "ADW-Interpolate.mov")
                    _ui(lambda: self.progress(0.7, "ADW-Interpolate — MOV"))
                    # ProRes 4444 so a review copy is still gradeable
                    r = _sp.run(["ffmpeg", "-y", "-framerate", "%g" % out_fps,
                        "-i", os.path.join(stage, "%05d.png"),
                        "-vf", "format=yuv444p10le",
                        "-c:v", "prores_ks", "-profile:v", "4",
                        mov_path], capture_output=True)
                    _sh4.rmtree(stage, ignore_errors=True)
                    if r.returncode != 0:
                        raise RuntimeError(_encode_err("MOV encode failed", r))
                else:
                    # EXR: untouched frames are COPIED DIRECTLY from the
                    # source whenever it's already EXR -- no restaging, no
                    # tonemap round-trip, byte-for-byte the original data.
                    #
                    # This fixes a real bug: untouched frames were being
                    # read back through _pv_frame's Reinhard tonemap
                    # preview decode (built for on-screen display, where an
                    # 8-bit approximation is fine) and that lossy,
                    # HDR-compressing pass was getting permanently baked
                    # into what was supposed to be an untouched copy --
                    # scene values around 0.7 coming back around 0.45,
                    # which is almost exactly what Reinhard's L/(1+L) does
                    # to a value in that range. Only the generated ranges
                    # actually need encoding, since they exist only as
                    # VACE's 8-bit PNG output -- so only those get staged
                    # and run through ffmpeg, per segment, landing at the
                    # right frame numbers via -start_number.
                    _ui(lambda: self.progress(0.05,
                        "ADW-Interpolate — copying plate"))
                    n_copied = 0
                    n_converted = 0
                    for i, nm in enumerate(names):
                        if i in repl:
                            continue
                        src_path = os.path.join(folder, nm)
                        dst_path = os.path.join(out_dir,
                            f"ADW-Interpolate.{i:05d}.exr")
                        if os.path.splitext(nm)[1].lower() == ".exr":
                            if not checked_space[0]:
                                _check_space_once(src_path,
                                    self._ip_pv_frame(src_path).size)
                            _sh4.copy(src_path, dst_path)
                            n_copied += 1
                        else:
                            # Rare: a non-EXR source frame. A real
                            # sRGB->linear conversion of the file itself,
                            # not a display tonemap -- this is the
                            # deliverable, not a preview.
                            if not checked_space[0]:
                                _check_space_once(src_path,
                                    self._ip_pv_frame(src_path).size)
                            r = _sp.run(["ffmpeg", "-y", "-i", src_path,
                                "-vf", "zscale=tin=iec61966-2-1:t=linear:range=full",
                                "-pix_fmt", "gbrpf32le", dst_path],
                                capture_output=True)
                            if r.returncode != 0:
                                r = _sp.run(["ffmpeg", "-y", "-i", src_path,
                                    "-pix_fmt", "gbrpf32le", dst_path],
                                    capture_output=True)
                            if r.returncode != 0 or not os.path.exists(dst_path):
                                raise RuntimeError(_encode_err(
                                    f"Copying frame {i + 1}", r))
                            n_converted += 1
                        if i % 5 == 0:
                            _ui(lambda p=0.05 + 0.55 * (i + 1) / total:
                                (self.progress(p,
                                    "ADW-Interpolate — copying plate"),
                                 self.ip_vace_apply_btn.configure(progress=p)))

                    _ui(lambda: self.progress(0.7, "ADW-Interpolate — EXR"))
                    for s in segs:
                        gap, _ = self._vace_gap(s)
                        if gap is None:
                            continue
                        r0, r1, _a, _b, _n = gap
                        if r0 not in repl:
                            continue   # nothing generated for this range
                        seg_stage = tempfile.mkdtemp(prefix="ip_stage_seg_")
                        try:
                            seg_plate = None
                            for j, idx in enumerate(range(r0, r1 + 1)):
                                src = repl.get(idx)
                                if not src:
                                    continue
                                pil = Image.open(src).convert("RGB")
                                if seg_plate and pil.size != seg_plate:
                                    pil = pil.resize(seg_plate, Image.LANCZOS)
                                else:
                                    seg_plate = pil.size
                                pil.save(os.path.join(seg_stage,
                                                      f"{j:05d}.png"))
                            exr_pat = os.path.join(out_dir,
                                                   "ADW-Interpolate.%05d.exr")
                            base_cmd = ["ffmpeg", "-y", "-i",
                                os.path.join(seg_stage, "%05d.png")]
                            tail = ["-pix_fmt", "gbrpf32le",
                                    "-start_number", str(r0), exr_pat]
                            r = _sp.run(base_cmd
                                + ["-vf",
                                   "zscale=tin=iec61966-2-1:t=linear:range=full"]
                                + tail, capture_output=True)
                            if (r.returncode != 0
                                    and b"No space" not in r.stderr):
                                _ui(lambda: self.log(self.ip_log_txt,
                                    "zscale colour transform unavailable "
                                    "in this ffmpeg; writing EXR without "
                                    "the sRGB\u2192linear step.", "hi"))
                                r = _sp.run(base_cmd + tail,
                                           capture_output=True)
                            if r.returncode != 0:
                                raise RuntimeError(
                                    _encode_err("EXR encode failed", r))
                        finally:
                            _sh4.rmtree(seg_stage, ignore_errors=True)
                    _ui(lambda n=n_copied, c=n_converted: self.log(
                        self.ip_log_txt,
                        f"{n} untouched frame(s) copied directly from "
                        "source, unaltered"
                        + (f"; {c} non-EXR frame(s) converted" if c else "")
                        + ".", "dim"))
                _ui(lambda: self.progress(-1))
                _ui(lambda r=len(repl): self._vace_apply_done(
                    out_dir, total, r, done_names))
            except Exception as ex:
                # out_dir is always a freshly minted version for this run
                # (see _adw_versioned_output_dir), so a half-written
                # sequence left behind after a failure is pure waste and
                # could be mistaken for a real, complete render.
                import shutil as _sh_mod3
                if stage:
                    _sh_mod3.rmtree(stage, ignore_errors=True)
                _sh_mod3.rmtree(out_dir, ignore_errors=True)
                _ui(lambda e=ex: self.log(self.ip_log_txt,
                    f"Apply failed: {type(e).__name__}: {e}", "err"))
                _ui(lambda e=ex: self._vace_apply_reset(
                    f"\u2716 Apply failed: {type(e).__name__}: {e}"))
                _ui(lambda: self.progress(-1))

        threading.Thread(target=go, daemon=True).start()

    def _vace_apply_reset(self, msg=""):
        self._ip_applying = False
        if hasattr(self, "ip_vace_apply_btn"):
            self.ip_vace_apply_btn.configure(progress=0.0)
            self._interp_refresh_vace_btn()

        if msg and hasattr(self, "ip_vace_stat"):
            self.ip_vace_stat.configure(text=msg,
                fg=("#CC4444" if msg.startswith("\u2716") else "#66CC66"))

    def _vace_apply_done(self, out_dir, total, n_repl, done_names):
        """Finished. Say so loudly, mark the segments, and offer the
        result for playback — the old version left you guessing on all
        three counts."""
        for s in self.ip_segments:
            if s["name"] in done_names:
                s["applied"] = True
        self.ip_result_dir = out_dir
        self._ip_result_dir_cached = None      # rebuild the index map
        # the wipe's cached "out" side was source-vs-source until now
        self._pp_stop("ip", quiet=True)
        self._pp_state("ip")["cache"] = None
        self._interp_refresh_view_btn()
        self._vace_apply_reset()
        _is_mov = self.ip_out_fmt_var.get() == "MOV"
        self.ip_vace_stat.configure(
            text=f"\u2713 Done \u2014 {total} frames "
                 f"({n_repl} rebuilt) in {os.path.basename(out_dir)}/.  "
                 + ("MOV written; uncheck Out .MOV if you want the "
                    "wipe/diff compare." if _is_mov
                    else "Switch to Result to play it back."),
            fg="#66CC66")
        if _is_mov:
            self.log(self.ip_log_txt,
                "MOV is a flat movie, so there are no frames for the "
                "wipe/diff compare to read. Render EXR to compare in the "
                "viewer.", "hi")
        self.log(self.ip_log_txt,
            f"\u2713 Spliced \u2192 {os.path.basename(out_dir)}/  "
            f"{total} frames, {n_repl} rebuilt. "
            f"Switch the view to Result to play it back.", "ok")
        self._interp_segments_changed()

    # ── viewing the result ───────────────────────────────────────────
    def _interp_frame_rebuilt(self, i):
        """Was this frame actually replaced?

        Gap fill only replaces the DAMAGE range, not the whole segment.
        This used to test the segment bounds, so 31 frames claimed to be
        rebuilt when 6 actually were — which is exactly why toggling to
        Result looked like it changed nothing.
        """
        for s in self.ip_segments:
            if s.get("applied") and s["in"] <= i <= s["out"]:
                return True
        return False

    def _interp_first_rebuilt(self):
        """The first frame the splice actually changed — where the Result
        view should land you, rather than on a passthrough frame that
        looks identical and makes it seem like nothing happened."""
        best = None
        for s in self.ip_segments:
            if s.get("applied"):
                d0, _ = self._interp_dmg(s)
                if best is None or d0 < best:
                    best = d0
        return best

    def _interp_set_view(self, which, jump=True):
        """Swap the frames under the viewer between the source plate and
        the spliced result, WITHOUT touching the segments — the whole
        point is to A/B the same ranges."""
        if which == "Result" and not (self.ip_result_dir
                                      and os.path.isdir(self.ip_result_dir)):
            self.log(self.ip_log_txt,
                "No result yet — Apply first.", "err")
            self.ip_view_var.set("Source")
            return
        if which == self._ip_view:
            return
        self._pp_stop("ip", quiet=True)
        self._pp_state("ip")["cache"] = None      # the frames changed
        if which == "Result":
            d = self.ip_result_dir
            fs = sorted(f for f in os.listdir(d)
                        if os.path.splitext(f)[1].lower() in
                        {".png", ".exr", ".tif", ".tiff", ".jpg", ".jpeg"})
            if not fs:
                self.log(self.ip_log_txt, "The result folder is empty.", "err")
                self.ip_view_var.set("Source")
                return
            self.ip_folder = d
            self.ip_frames = fs
        else:
            self.ip_folder = self.ip_src_folder
            self.ip_frames = list(self.ip_src_frames)
        self._ip_view = which
        self.ip_idx = max(0, min(len(self.ip_frames) - 1, self.ip_idx))
        # If we would land on a passthrough frame, jump to the first frame
        # the splice actually changed. Otherwise Result looks identical to
        # Source and it seems like nothing happened.
        jumped = False
        if jump and which == "Result" \
                and not self._interp_frame_rebuilt(self.ip_idx):
            fr = self._interp_first_rebuilt()
            if fr is not None:
                self.ip_idx = min(len(self.ip_frames) - 1, fr)
                jumped = True
        self.ip_frame_cb.set_frames(self.ip_frames)
        self.ip_frame_cb.select(self.ip_idx)
        self._interp_refresh_view_btn()
        self._interp_show_frame(self.ip_idx)   # reloads from the new folder
        try:
            self.ip_canvas.update_idletasks()
        except Exception:
            pass
        msg = f"Viewing: {which} \u2014 {os.path.basename(self.ip_folder)} " \
              f"({len(self.ip_frames)} frames)."
        if which == "Result":
            if jumped:
                msg += (f" Jumped to frame {self.ip_idx + 1}, the first one "
                        "that was rebuilt.")
            msg += (" Only frames inside an applied segment differ \u2014 "
                    "the rest are the untouched plate. Press Play to watch "
                    "the whole shot.")
        else:
            msg += " Back on the source plate."
        self.log(self.ip_log_txt, msg, "hi")

    def _interp_toggle_wipe(self):
        """Wipe is a toggle, like the other ADW modules: on -> off -> on."""
        if not self.ip_result_dir:
            self.log(self.ip_log_txt, "Insert a result first.", "err"); return
        if self._ip_cmp_mode == "wipe":
            self._ip_cmp_mode = "off"
        else:
            self._ip_cmp_mode = "wipe"
        self._interp_refresh_cmp_btns()
        self._interp_ensure_result_view()

    def _interp_toggle_diff(self):
        if not self.ip_result_dir:
            self.log(self.ip_log_txt, "Insert a result first.", "err"); return
        if self._ip_cmp_mode == "diff":
            self._ip_cmp_mode = "off"
        else:
            self._ip_cmp_mode = "diff"
        self._interp_refresh_cmp_btns()
        self._interp_ensure_result_view()

    def _interp_refresh_cmp_btns(self):
        if not hasattr(self, "ip_wipe_btn"):
            return
        m = self._ip_cmp_mode
        self.ip_wipe_btn.configure(bg=("#252525" if m == "wipe" else "#0D0D0D"),
                                   fg=W)
        self.ip_diff_btn.configure(
            bg=("#252525" if m == "diff" else "#0D0D0D"),
            fg=("#CC4444" if m == "diff" else G))

    def _interp_ensure_result_view(self):
        """A compare needs the Result frames loaded under the viewer."""
        if self.ip_result_dir and self._ip_view != "Result":
            self.ip_view_var.set("Result")
            self._interp_set_view("Result", jump=False)
        else:
            self._interp_render()

    def _interp_refresh_view_btn(self):
        if not hasattr(self, "ip_view_lbl"):
            return
        ready = bool(self.ip_result_dir
                     and os.path.isdir(self.ip_result_dir))
        if ready:
            self.ip_view_lbl.configure(
                text=f"Result: {os.path.basename(self.ip_result_dir)}",
                fg=GR)
        else:
            self.ip_view_lbl.configure(text="No result yet", fg=G)

    @staticmethod
    def _interp_safe_name(name):
        """Segment name -> a safe folder name."""
        keep = "".join(ch if (ch.isalnum() or ch in " -_") else "_"
                       for ch in str(name)).strip()
        return keep.replace(" ", "_") or "Segment"


