        row2tl = tk.Frame(_smtb, bg=BG); row2tl.pack(fill="x")
        # Frame boxes: default dark red; cached frames = brighter red;
        # a light-blue bar on top of any frame with unsaved edits.
        # (Selected / hover outlines are still drawn by the widget.)
        def _sm_frame_color(i):
            # Tinted by MOTION whenever it's been analysed -- no longer
            # tied to being RAM-cached, since Analyse Motion scores the
            # whole sequence on its own: the ramp goes from the same red
            # as an unanalysed frame, through orange, to bright yellow
            # at peak motion. Cached-but-unanalysed frames (shouldn't
            # normally happen now, but possible right after a Clear)
            # fall back to plain red.
            m = self.sm_motion.get(i)
            if m is not None:
                return self._motion_tint_color(m)
            if i in self.sm_ram_cache:
                return "#CC4444"
            return None                    # default dark red
        self.sm_frame_cb = self._timeline(row2tl,
            lambda i: self._smudge_timeline_frame(i), fill=True,
            get_frame_color=_sm_frame_color,
            get_frame_marker=lambda i: i in self.sm_edits,
            taller=True, show_numbers=True)

        def _info_popup(tip):
            """Hover tooltip (same pattern as the other tabs)."""
            def _attach(widget):
                _pop = [None]
                def _show(e):
                    if _pop[0]:
                        try: _pop[0].destroy()
                        except Exception: pass
                    pop = tk.Toplevel(self)
                    pop.overrideredirect(True)
                    pop.configure(bg=BD)
                    pop.attributes("-topmost", True)
                    tk.Label(pop, text=tip, font=FM, bg=BD, fg=W,
                             justify="left", padx=12, pady=10,
                             wraplength=280).pack()
                    pop.update_idletasks()
                    x = min(e.x_root+4,
                            self.winfo_screenwidth()-pop.winfo_width()-8)
                    pop.geometry(f"+{x}+{e.y_root+16}")
                    _pop[0] = pop
                def _hide(e=None):
                    if _pop[0]:
                        try: _pop[0].destroy()
                        except Exception: pass
                    _pop[0] = None
                widget.bind("<Enter>", _show)
                widget.bind("<Leave>", _hide)
                widget.bind("<Button-1>", _hide, add="+")
            return _attach

        c2 = self._card(lf, "Brush")
        # Tool icons: custom artwork Aron supplied as two matching
        # sheets -- a "normal" (gold frame/red glyph) and a "selected"
        # (red frame/gold glyph) state for each of the six tools plus
        # the colour picker. Mask uses the "stencil" piece specifically,
        # since a stencil's cutout-shape/hold-out concept is exactly
        # what Mask does; the sheet itself never says "Mask" anywhere.
        # This second sheet also finally gives Blur its own artwork,
        # so all six tools use custom icons now, none left on emoji.
        import base64, io
        from PIL import Image as _PILImage, ImageTk as _PILImageTk
        self._sm_icon_imgs = {}
        for _name, _b64 in self._SM_ICON_B64.items():
            _im = _PILImage.open(io.BytesIO(base64.b64decode(_b64)))
            self._sm_icon_imgs[_name] = _PILImageTk.PhotoImage(_im)
        self._sm_mode_icon_names = {
            "stamp": "stencil", "smudge": "smudge", "blur": "blur",
            "paint": "paint", "warp": "warp", "erase": "erase",
        }
        rowm = tk.Frame(c2, bg=S); rowm.pack(fill="x", pady=2)
        self.sm_mode_icon_lbls = {}
        for _mkey in ("paint", "smudge", "blur", "erase", "stamp", "warp"):
            _iname = self._sm_mode_icon_names[_mkey]
            # Default (unselected) state is the RED-frame/gold-glyph
            # artwork -- inverted from the first pass at this, where
            # the gold-frame/red-glyph state was the default and the
            # red-frame one only appeared for the active tool.
            _lbl = tk.Label(rowm,
                            image=self._sm_icon_imgs[f"{_iname}_selected"],
                            bg=S, cursor="hand2")
            _lbl.pack(side="left", padx=2, expand=True)
            _lbl.bind("<Button-1>",
                lambda e, k=_mkey: self._smudge_set_mode(k))
            self.sm_mode_icon_lbls[_mkey] = _lbl
        def _refresh_mode_icons(active_mode):
            for _mkey, _lbl in self.sm_mode_icon_lbls.items():
                _iname = self._sm_mode_icon_names[_mkey]
                # inverted vs before: active tool shows the gold-glyph
                # ("normal") state, every other tool shows the red-
                # frame ("selected") state, which is now the default
                _state = "normal" if _mkey == active_mode else "selected"
                _lbl.configure(image=self._sm_icon_imgs[f"{_iname}_{_state}"])
        self._sm_refresh_mode_icons = _refresh_mode_icons
        _refresh_mode_icons("smudge")

        # Contextual parameter groups: only the groups relevant to the
        # active tool are shown at once (see _smudge_refresh_tool_params),
        # rather than every parameter for every tool being visible all
        # the time regardless of whether it applies. Built as plain
        # frames here (not yet packed -- _smudge_refresh_tool_params
        # packs whichever ones are relevant once mode-switching is
        # wired up further down), so any slider/button created against
