        # first refresh actually shows it.
        self._sm_group_size_hardness = tk.Frame(c2, bg=S)
        self._sm_group_strength = tk.Frame(c2, bg=S)
        self._sm_group_paint = tk.Frame(c2, bg=S)
        self._sm_group_blur = tk.Frame(c2, bg=S)
        self._sm_group_stamp = tk.Frame(c2, bg=S)
        # which groups each mode shows, and in what order top-to-bottom
        self._sm_tool_param_groups = {
            "mask":   ["size_hardness"],
            "smudge": ["size_hardness", "strength"],
            "blur":   ["size_hardness", "blur"],
            "paint":  ["paint", "size_hardness", "strength"],
            "erase":  ["size_hardness", "strength"],
            "stamp":  ["size_hardness", "blur", "stamp"],
        }

        # Mask: its own always-visible card, not tied to any one tool
        # and not part of the show/hide-by-mode system above -- every
        # brush mode (Smudge, Blur, Paint, Erase, Stamp) respects the
        # hold-out mask, so its controls stay reachable no matter
        # which tool is active, rather than living nested inside just
        # one of them.
        c_mask = self._card(lf, "Mask")
        self._sm_group_mask_only = c_mask
        # Icon + 2x2 action grid row: Aron supplied dedicated Masking
        # artwork (active/inactive states, same red/gold convention as
        # every other tool icon) -- it sits on the left as a clickable
        # toggle into Mask mode, with Snap Edge/Soften/Invert/Clear
        # tiled 2x2 to its right, rather than the icon and a separate
        # text button both competing for the same space.
        self._sm_masking_icon_imgs = {}
        for _key in ("masking_active", "masking_inactive"):
            _im = _PILImage.open(io.BytesIO(
                base64.b64decode(self._SM_ICON_B64[_key])))
            self._sm_masking_icon_imgs[_key] = _PILImageTk.PhotoImage(_im)
        rowmi = tk.Frame(c_mask, bg=S); rowmi.pack(fill="x", pady=(0, 4))
        self.sm_paint_mask_btn = tk.Label(rowmi,
            image=self._sm_masking_icon_imgs["masking_inactive"],
            bg=S, cursor="hand2")
        self.sm_paint_mask_btn.pack(side="left", padx=(0, 8))
        self.sm_paint_mask_btn.bind("<Button-1>",
            lambda e: self._smudge_set_mode("mask"))
        grid2 = tk.Frame(rowmi, bg=S); grid2.pack(side="left", fill="both",
                                                   expand=True)
        for i in range(2): grid2.columnconfigure(i, weight=1)
