        for idx, (txt, fn) in enumerate((
                ("Snap Edge", self._smudge_snap_edges),
                ("Soften",    self._smudge_soften),
                ("Invert",    self._smudge_invert),
                ("Clear",     self._smudge_clear))):
            b = self._mkbtn(grid2, txt, fn, bg="#0D0D0D", fg=W)
            tk.Label.configure(b._lbl, width=0, pady=0)
            b.grid(row=idx // 2, column=idx % 2, sticky="nsew",
                   padx=1, pady=1)
            if txt == "Soften":
                self.sm_soften_btn = b
        # Soften has no slider any more -- Aron: "just set the soften
        # to a number like 2 and every time soften is pressed increase
        # it by doubling it. That way we can remove the slider and
        # save UI space." The button's own label shows the amount the
        # NEXT press will apply (2px, then 4px, 8px, 16px...), so the
        # doubling progression stays visible without a slider taking
