        def _refresh_soften_label(*_):
            self.sm_soften_btn._lbl.configure(
                text=f"Soften ({int(self.sm_soft_var.get())}px)")
        self.sm_soft_var.trace_add("write", _refresh_soften_label)
        _refresh_soften_label()

        # Paint colour picker row
        rowpc = tk.Frame(self._sm_group_paint, bg=S); rowpc.pack(fill="x", pady=(2, 0))
        tk.Label(rowpc, text="Paint Colour", font=FSM, bg=S, fg=G,
                 width=11, anchor="w").pack(side="left")
        self.sm_paint_swatch = tk.Label(rowpc, text="   ",
            bg=self.sm_paint_color_var.get(), relief="flat",
            cursor="hand2", width=4)
        self.sm_paint_swatch.pack(side="left", padx=(4, 6))
        def _pick_paint_color():
            from tkinter import colorchooser
