    # The four effects, in stack order, each with the parameter key(s)
    # that gate it inside _organic_apply_stack. Bypassing an effect
    # means zeroing its gate -- not adding a parallel "enabled" branch
    # to the stack, which would give the preview path and the render
    # path two different definitions of "off" to drift apart.
    _ORGANIC_FX = (
        # Front-element contamination comes first: it is physically the
        # outermost surface, so its scatter then travels through the rest
        # of the optics. Putting it last would mean a lit scratch never
        # blooms, which is the main thing that sells one.
        ("smudge",  "Lens Smudge",    ("smudge_amount",)),
        ("scratch", "Lens Scratches", ("scratch_amount",)),
        # The glass forms the image here: softness first, then the
        # lateral colour shift, both being failures of the same optics.
        ("soft",  "Lens Softness",  ("soft_amount",)),
        ("ca",    "Chromatic Aberration", ("ca",)),
        ("bloom", "Bloom",                ("bloom_intensity",)),
        ("vig",   "Vignette",             ("vig",)),
        # Its own effect, not a sub-group of Bloom. They are different
        # physics -- scatter in the glass on the way in versus charge
        # bleeding across the sensor once the light has landed -- and
        # sharing Bloom's mute meant the veil could not be soloed to
        # tune against the plate, which is the whole point of having it.
        # Listed where it runs: after the lens, before grain.
        ("veil",  "Sensor Veil",          ("veil_intensity",)),
        ("grain", "Grain",                ("grain",)),
    )

    @classmethod
    def _organic_mask_field(cls, rgb, p, key, px_scale=1.0):
        """Black-and-white field for one control, float32 (H,W) in
        0..1. `px_scale` maps a pixel-unit parameter (bloom radius)
        into the resolution the mask is being computed at, so a mask
        previewed on a downsampled frame still shows the true shape
        rather than a proportionally wider one."""
        import numpy as np
        h, w = rgb.shape[:2]
        if key == "ca_edge":
            return cls._organic_ca_ramp(h, w, p.get("ca_falloff", 2.0))
        if key == "bloom_thresh":
            # Deliberately hard, not a soft ramp: the question this
            # preview answers is "where exactly is the cut landing",
            # and a gradient hides the edge that is being placed.
            # Strictly greater, matching _organic_bloom_over: a pixel
            # sitting exactly ON the threshold contributes zero energy,
            # so it must read black or the mask overstates the effect.
            over = cls._organic_bloom_over(rgb, p.get("bloom_thresh", 0.9))
            return (over > 0.0).astype(np.float32)
        if key == "bloom_kernel":
            # Returned at its own shape and in COLOUR, not the frame's
            # shape and not greyscale: the three dispersed kernels are
            # the whole point of the Dispersion control, and a mono
            # preview could not show them separating.
            #
            # Built at FULL resolution, ignoring px_scale. That scale
            # exists so a FRAME-SPACE mask computed on the downsampled
            # preview copy still describes the right shape; the kernel
            # is not frame-space -- it is its own small image, fitted to
            # the canvas afterwards. Passing the scale in shrank the
            # very thing being inspected: on a 4K plate the preview
            # built a 21px kernel instead of a 61px one, putting the
            # star's arms at 0.83px half-width. Thinner than a sample,
            # so they dropped out of the picture while still rendering
            # perfectly. The star was not broken; its preview was.
            kr, kg, kb = cls._organic_bloom_kernel_rgb(p)
            return np.stack((kr, kg, kb), axis=2).astype(np.float32)
        if key == "veil_thresh":
            over = np.clip(rgb.max(axis=2)
                           - float(p.get("veil_thresh", 0.8)), 0.0, None)
            return (over > 0.0).astype(np.float32)
        if key == "bloom_spill":
            over = cls._organic_bloom_over(rgb, p.get("bloom_thresh", 0.9))
            k = cls._organic_bloom_kernel(p, px_scale)
            ksum = float(k.sum())
            if ksum > 1e-9:
                over = np.maximum(cls._organic_convolve(over, k / ksum), 0.0)
            peak = float(over.max())
            return (over / peak) if peak > 1e-9 else over
        if key == "vignette":
            return cls._organic_vignette_mask(h, w, p.get("vig", 0.0),
                                              p.get("vig_falloff", 2.0))
        if key == "grain_resp":
            return cls._organic_grain_response(rgb, p.get("grain_shadow", 1.5))
        if key == "soft_field":
            # Normalised to its own peak so the shape is readable even
            # at a low Amount -- this preview answers "where is it
            # soft", and Amount is a separate question.
            f = cls._organic_soft_field(h, w, dict(p, soft_amount=1.0))
            pk = float(f.max())
            return (f / pk) if pk > 1e-6 else f
        if key == "smudge":
            # The soft-thresholded patch mask, i.e. exactly the weight
            # _organic_smudge diffuses by -- not the raw fBm, which would
            # make Coverage and Edge look like they do nothing.
            m = cls._organic_lens_field(h, w, p.get("smudge_scale", 4),
                                        p.get("smudge_detail", 3),
                                        p.get("smudge_seed", 1))
            cover = min(1.0, max(0.0, float(p.get("smudge_coverage", 0.45))))
            edge = max(0.02, float(p.get("smudge_softness", 0.35)))
            return np.clip((m - (1.0 - cover)) / edge,
                           0.0, 1.0).astype(np.float32)
        if key == "scratch":
            return cls._organic_scratch_mask(h, w, p)
        raise KeyError(f"unknown organic mask: {key}")

    @classmethod
    def _organic_chromatic(cls, rgb, amount, falloff=2.0, region=None):
        """Lateral chromatic aberration: red and blue are scaled
        very slightly in opposite directions about the optical
        centre, green left alone (green is conventionally the
        reference channel). Real lateral CA grows toward the frame
        edge and is ~zero dead centre, which the falloff exponent
        controls -- a plain uniform channel offset looks like a
        registration error instead, not like glass."""
        import numpy as np, cv2
        if amount <= 0:
            return rgb
        h, w = rgb.shape[:2]
        out = np.empty_like(rgb)
        out[:, :, 1] = rgb[:, :, 1]
        # amount is in pixels of displacement at the frame corner, so it
        # is normalised against the FULL plate. Using the array's own
        # size would make a region-of-interest update compute a
        # different scale factor from the full render -- measured at
        # 6.9e-02 of error before this was threaded through, against
        # 1.9e-06 for the bloom's DFT rounding.
        if region is None:
            ref = min(h, w)
        else:
            ref = min(region[2], region[3])
        max_disp = amount / max(1.0, float(ref)) * 100.0
        # Blend weight: scaled vs original by normalised radius**falloff,
        # so the centre keeps the untouched channel and the effect ramps
        # in toward the edges. Built once -- it used to be rebuilt inside
        # the loop, i.e. two full-frame mgrids per call for an array that
        # does not vary by channel.
        r = cls._organic_ca_ramp(h, w, falloff, region)
        # The channel scaling is about the FULL frame's optical centre,
        # which for a crop sits outside the array being warped -- often
        # at a negative coordinate. Expressing it in crop space is what
        # keeps a region update's fringing identical to the full render.
        if region is None:
            ccx, ccy = w / 2.0, h / 2.0
        else:
            ry0, rx0, rfh, rfw = region
            ccx, ccy = rfw / 2.0 - rx0, rfh / 2.0 - ry0
        for ci, sgn in ((0, 1.0), (2, -1.0)):
            s = 1.0 + sgn * max_disp * 0.01
            M = np.float32([[s, 0, (1 - s) * ccx],
                            [0, s, (1 - s) * ccy]])
            scaled = cv2.warpAffine(rgb[:, :, ci], M, (w, h),
                flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
            out[:, :, ci] = rgb[:, :, ci] * (1.0 - r) + scaled * r
        return out

    # ── bloom kernel ─────────────────────────────────────────────────
    # Bloom is a convolution, not a blur. The kernel is built from three
    # layers and then convolved over the threshold-clamped image, and
    # the result added back:
    #
    #   lerp(sphere x noise,  star,  Star Gain)
    #                        ->  gamma  ->  peak-normalised
    #
    # The noise multiplies the sphere; the star is then mixed against
    # that result. Star Gain is the mix position, so at 0 you have the
    # noisy sphere and at 1 the star alone.
    #
    # A lerp, not a max and not an add. max only shows whichever layer
    # is locally brighter, which made the noise carve holes in the
    # sphere for the star to appear through -- arms broken up in the
    # shape of the noise instead of their own, and no star at all near
    # the core where the sphere wins everywhere. An add would push the
    # shared centre to 2.0 and then normalising would drag the whole
    # kernel dark. A lerp of two 0..1 layers stays in 0..1, which is
    # also what keeps it directly viewable as a preview.
    #
    # Peak-normalised for display; the convolution divides by the SUM
    # separately, so total energy is conserved and Intensity keeps
    # meaning the same thing when the kernel shape changes underneath
    # it. Peak-normalising into the convolution instead would make a
    # wide kernel silently much brighter than a tight one.

    # Sized so nothing reachable from the sliders is ever clamped:
    # 240 max radius x 6 max anamorph x the 1.18 dispersion pad is about
    # 1700. The guard is still here for a params dict built by hand.
    _ORGANIC_KERNEL_MAX_HALF = 1792

    @classmethod
    def _organic_kernel_grid(cls, p, px_scale=1.0, pad=1.0):
        """(r, theta) for the kernel, with r normalised to 1.0 at the
        nominal radius on each axis. Anamorph widens the kernel in
        pixels while leaving the normalised space square, so every layer
        built on it stretches together.

        `pad` grows the ARRAY without moving where r == 1, which is what
        lets a dispersed red kernel scale up past the nominal radius
        without being clipped by its own canvas."""
        import numpy as np
        radius = max(1, int(round(float(p.get("bloom_radius", 20))
                                  * float(px_scale))))
        aniso = max(1.0, float(p.get("bloom_aniso", 1.0)))
        pad = max(1.0, float(pad))
        unit_y = float(radius)
        unit_x = float(radius) * aniso
        want_h = unit_y * pad
        want_w = unit_x * pad
        over = max(want_h, want_w) / float(cls._ORGANIC_KERNEL_MAX_HALF)
        if over > 1.0:
            # Scale the whole kernel down, both axes and both units, so
            # it keeps its shape. Clamping each axis independently -- as
            # this did -- crops the array without moving where r == 1,
            # which chops an anamorphic streak off mid-flight against a
            # hard canvas edge and quietly flattens the aspect: at
            # radius 120 and Anamorph 3.0 the kernel came out 2.13 wide
            # instead of 3.0, with the arms cut square at the border.
            unit_y /= over
            unit_x /= over
            want_h /= over
            want_w /= over
        hh = max(1, int(round(want_h)))
        hw = max(1, int(round(want_w)))
        yy, xx = np.mgrid[-hh:hh + 1, -hw:hw + 1].astype(np.float32)
        nx = xx / max(unit_x, 1.0)
        ny = yy / max(unit_y, 1.0)
        r = np.sqrt(nx * nx + ny * ny).astype(np.float32)
        theta = np.arctan2(ny, nx).astype(np.float32)
        return r, theta

    @staticmethod
    def _organic_kernel_sphere(r, size, falloff):
        """Generalised Gaussian: exp(-(r/size)**falloff).

        falloff IS the shape control -- 1 gives heavy exponential tails
        that read as halation, 2 is a true Gaussian, 6+ is nearly a hard
        disc. A separate post-gamma on this layer would be pointless:
        exp(-x)**g == exp(-g*x), i.e. indistinguishable from a change of
        size. The composite gamma below is applied after the max, where
        it genuinely reshapes something."""
        import numpy as np
        s = max(1e-4, float(size))
        f = max(0.1, float(falloff))
        return np.exp(-((r / s) ** f)).astype(np.float32)

    @staticmethod
    def _organic_kernel_noise(shape, scale, detail, contrast, seed):
        """fBm value noise in 0..1, at the kernel's own resolution.
        Lattices are clamped to the kernel size so extra octaves
        saturate into flatness instead of aliasing into speckle."""
        import numpy as np, cv2
        h, w = int(shape[0]), int(shape[1])
        rng = np.random.default_rng(int(seed) & 0x7FFFFFFF)
        acc = np.zeros((h, w), np.float32)
        amp, total = 1.0, 0.0
        base = max(2, int(scale))
        for o in range(max(1, int(detail))):
            gh = min(max(2, int(base * (2 ** o))), max(2, h))
            gw = min(max(2, int(round(gh * w / max(h, 1)))), max(2, w))
            g = rng.random((gh, gw)).astype(np.float32)
            acc += cv2.resize(g, (w, h), interpolation=cv2.INTER_CUBIC) * amp
            total += amp
            amp *= 0.5
        n = np.clip(acc / max(total, 1e-6), 0.0, 1.0)
        return App._organic_noise_contrast(n, contrast).astype(np.float32)

    @staticmethod
    def _organic_noise_contrast(n, contrast):
        """Push a 0..1 field toward black and white about its midpoint.
        One definition, shared by the cartesian and polar layers, so
        the Contrast slider means the same thing to all three."""
        import numpy as np
        c = float(contrast)
        if abs(c - 1.0) <= 1e-6:
            return n
        return np.clip((n - 0.5) * c + 0.5, 0.0, 1.0)

    @staticmethod
    def _organic_noise_1d(n, freq, detail, seed, periodic):
        """1D fBm in 0..1, smoothstep-interpolated.

        `periodic` wraps the lattice so the last cell meets the first.
        That is not cosmetic for the angular layer: without it the ray
        pattern has a visible seam along the theta = pi ray, which on a
        symmetric flare reads as one arm being wrong."""
        import numpy as np
        n = int(n)
        rng = np.random.default_rng(int(seed) & 0x7FFFFFFF)
        acc = np.zeros(n, np.float32)
        amp, total = 1.0, 0.0
        for o in range(max(1, int(detail))):
            cells = max(2, int(freq) * (2 ** o))
            g = rng.random(cells + 1).astype(np.float32)
            if periodic:
                g[-1] = g[0]
            x = np.linspace(0.0, cells, n, endpoint=False).astype(np.float32)
            i0 = np.floor(x).astype(np.int64)
            f = (x - i0).astype(np.float32)
            f = f * f * (3.0 - 2.0 * f)          # smoothstep
            acc += (g[i0] * (1.0 - f) + g[i0 + 1] * f) * amp
            total += amp
            amp *= 0.5
        return np.clip(acc / max(total, 1e-6), 0.0, 1.0).astype(np.float32)

    @staticmethod
    def _organic_sample_lut(lut, u, wrap):
        """Linear lookup of a 1D table at normalised positions `u`."""
        import numpy as np
        n = lut.shape[0]
        x = np.asarray(u, np.float32) * n
        i0 = np.floor(x).astype(np.int64)
        f = (x - i0).astype(np.float32)
        if wrap:
            i0 = np.mod(i0, n)
            i1 = np.mod(i0 + 1, n)
        else:
            i0 = np.clip(i0, 0, n - 1)
            i1 = np.clip(i0 + 1, 0, n - 1)
        return (lut[i0] * (1.0 - f) + lut[i1] * f).astype(np.float32)

    @classmethod
    def _organic_kernel_polar_noise(cls, r, theta, p):
        """Multiplier in 0..1 carrying the flare's polar structure, or
        None when both layers are off.

        Two layers, both built as 1D noise and swept around the centre
        rather than as 2D fields:

          rings  varies with radius, constant in angle  -> concentric
                 arcs, the faint shells around a bright source
          rays   varies with angle, constant in radius  -> radial
                 streaks of uneven brightness

        Built in polar space on purpose. A 2D cartesian noise has no
        idea where the centre is, so it mottles a flare into damp
        patches; noise that is a function of r or theta alone inherits
        the flare's own symmetry, which is what makes the result read
        as one optical event rather than as a glow with dirt on it.

        Multiplied against the cartesian layer rather than replacing
        it: rays alone are perfectly straight and even along their
        length, and it is the cartesian field breaking them up that
        gives the uneven, varying-length streaks of a real flare."""
        import numpy as np
        rings = float(p.get("bloom_noi_rings", 0.0))
        rays = float(p.get("bloom_noi_rays", 0.0))
        if rings <= 0 and rays <= 0:
            return None
        detail = p.get("bloom_noi_detail", 3)
        contrast = p.get("bloom_noi_contrast", 1.0)
        seed = int(p.get("bloom_noi_seed", 1))
        out = None
        if rings > 0:
            lut = cls._organic_noise_1d(
                2048, p.get("bloom_noi_ring_freq", 10), detail,
                seed + 101, False)
            lut = cls._organic_noise_contrast(lut, contrast)
            # r reaches sqrt(2) in the kernel corners
            f = cls._organic_sample_lut(
                lut, np.clip(r / 1.4142135, 0.0, 1.0), False)
            out = (1.0 - rings) + rings * f
        if rays > 0:
            lut = cls._organic_noise_1d(
                2048, p.get("bloom_noi_ray_freq", 32), detail,
                seed + 211, True)
            lut = cls._organic_noise_contrast(lut, contrast)
            u = (theta + np.pi) / (2.0 * np.pi)
            g = (1.0 - rays) + rays * cls._organic_sample_lut(lut, u, True)
            out = g if out is None else out * g
        return out.astype(np.float32)

    @staticmethod
    def _organic_kernel_star(r, theta, points, angle, length, width, falloff):
        """`points` arms radiating from the centre, widest where they
        leave the core and closing to a point at the tip.

        Shaped by PERPENDICULAR DISTANCE from each arm's axis, not by
        angle. This used to be abs(cos(n*theta/2))**width -- a purely
        angular profile, constant in theta, which means a constant
        angular width. A constant angle subtends a physical width of
        r*dtheta, so every arm came out a wedge: thin at the base and
        fat at the tip, the exact opposite of a diffraction spike.

        The half-width now shrinks with the same taper that dims the
        arm, so thickness falls off from base to tip. `width` stays
        "higher is thinner" and is read as an inverse half-width in
        normalised-radius units."""
        import numpy as np
        n = max(1, int(points))
        period = 2.0 * np.pi / n
        a = np.mod(theta - np.deg2rad(float(angle)), period)
        dev = np.minimum(a, period - a)        # angle to the nearest arm
        length = max(1e-3, float(length))
        taper = np.clip(1.0 - r / length, 0.0, 1.0)
        # Capped at 90 degrees before the sine: past that, sin turns
        # back down and would fold a phantom arm in on the opposite
        # side of the centre.
        d = r * np.sin(np.minimum(dev, np.pi / 2.0))
        hw = np.maximum((1.0 / max(0.5, float(width))) * taper, 1e-6)
        u = np.clip(d / hw, 0.0, 12.0)
        prof = np.exp(-(u * u))
        return (prof * taper ** max(0.05, float(falloff))).astype(np.float32)

    @classmethod
    def _organic_bloom_kernel(cls, p, px_scale=1.0, disp=1.0, pad=1.0):
        """The composited convolution kernel, peak-normalised to 1.0 and
        therefore directly displayable as the preview.

        `disp` scales the kernel about its centre -- dividing r rather
        than resampling the finished kernel, so the star arms and the
        noise scale cleanly instead of being interpolated. Pass a
        matching `pad` when disp > 1 or the enlarged kernel clips."""
        import numpy as np
        r, theta = cls._organic_kernel_grid(p, px_scale, pad)
        if abs(float(disp) - 1.0) > 1e-6:
            r = (r / max(1e-4, float(disp))).astype(np.float32)
        # Composition, in order:
        #
        #   sphere x noise          -> the broken-up core
        #   lerp(that, star, gain)  -> Star Gain is a MIX, not a level
        #
        # The noise multiplies the SPHERE only, and the star is mixed
        # against the result. This replaced max(sphere*noise, star*gain),
        # which was the cause of the star reading as unrelated debris
        # rather than as a star: max only shows whichever layer is
        # locally brighter, so the noise carved holes in the sphere and
        # the star appeared through those holes. The arms were therefore
        # broken up in the shape of the NOISE rather than following their
        # own geometry, and near the core -- where the sphere is at 1.0
        # and wins everywhere -- the star vanished entirely.
        k = cls._organic_kernel_sphere(r, p.get("bloom_sph_size", 0.35),
                                       p.get("bloom_sph_falloff", 2.0))
        mix = float(p.get("bloom_noi_mix", 0.0))
        if mix > 0:
            n = cls._organic_kernel_noise(
                r.shape, p.get("bloom_noi_scale", 6),
                p.get("bloom_noi_detail", 3),
                p.get("bloom_noi_contrast", 1.0),
                p.get("bloom_noi_seed", 1))
            polar = cls._organic_kernel_polar_noise(r, theta, p)
            if polar is not None:
                n = n * polar
            k = k * (1.0 - mix + mix * n)
        gain = float(p.get("bloom_str_gain", 0.0))
        if gain > 0:
            st = cls._organic_kernel_star(
                r, theta, p.get("bloom_str_points", 6),
                p.get("bloom_str_angle", 0.0),
                p.get("bloom_str_length", 0.9),
                p.get("bloom_str_width", 12.0),
                p.get("bloom_str_falloff", 1.6))
            k = k * (1.0 - gain) + st * gain
        g = float(p.get("bloom_kgamma", 1.0))
        if abs(g - 1.0) > 1e-6:
            k = np.clip(k, 0.0, None) ** max(0.05, g)
        peak = float(k.max())
        if peak > 1e-9:
            k = k / peak
        return np.nan_to_num(k).astype(np.float32)

    # Max +/- kernel scale at Dispersion 1.0. Kept modest: real lateral
    # dispersion in a bloom is a few percent, and beyond ~20% the red
    # halo detaches from the core and reads as three separate glows.
    _ORGANIC_DISPERSION_SPREAD = 0.18

    @classmethod
    def _organic_bloom_kernel_rgb(cls, p, px_scale=1.0):
        """(red, green, blue) kernels. Dispersion scales the kernel per
        channel -- red spreads widest, blue tightest, green is the
        reference -- so a white highlight blooms into a warm outer halo
        with a cool core, the way glass actually splits it.

        Each channel is energy-normalised by its OWN sum at convolution
        time, so a flat field picks up no tint; only the spatial
        distribution differs, which is what puts colour on the edges
        rather than over the whole glow."""
        d = float(p.get("bloom_disp", 0.0))
        if d <= 0:
            k = cls._organic_bloom_kernel(p, px_scale)
            return k, k, k
        sp = cls._ORGANIC_DISPERSION_SPREAD * min(1.0, d)
        pad = 1.0 + sp
        return (cls._organic_bloom_kernel(p, px_scale, 1.0 + sp, pad),
                cls._organic_bloom_kernel(p, px_scale, 1.0, pad),
                cls._organic_bloom_kernel(p, px_scale, 1.0 - sp, pad))

    # ── lens softness (spherical + longitudinal aberration) ───────────
    # Distinct from the Chromatic Aberration effect below, which is
    # LATERAL: it displaces the channels radially and leaves each one
    # sharp. This is the other two ways a cheap or old lens fails.
    #
    #   spherical aberration -- rays through the rim of the element
    #     focus short of the ones through the middle, so the point
    #     spread is a sharp core sitting in a broad halo rather than a
    #     Gaussian blob. Two blur scales mixed together is what gives
    #     that: a plain single blur just reads as out of focus.
    #
    #   longitudinal chromatic aberration -- the glass has a higher
    #     refractive index at short wavelengths, so blue focuses nearest
    #     and red furthest. Focus for green and the other two are both
    #     defocused, blue the more so. That is what puts a soft magenta
    #     or green cast on out-of-focus edges, and it is a per-channel
    #     BLUR, not a per-channel shift.
    #
    # Both worsen off-axis, because field curvature means the focal
    # surface is a bowl and the sensor is flat -- hence the radial term.

    _ORGANIC_SOFT_CHROMA = (1.18, 1.00, 1.38)   # R, G, B blur multipliers
    _ORGANIC_SOFT_WIDE = 4.0                    # far halo, x the radius

    @classmethod
    def _organic_soft_radii(cls, radius, chroma):
        """Per-channel blur radius. Green is the reference -- it is the
        channel a lens is focused on -- so at chroma 0 all three match
        and the effect is achromatic."""
        c = min(1.0, max(0.0, float(chroma)))
        return [float(radius) * (1.0 + (m - 1.0) * c)
                for m in cls._ORGANIC_SOFT_CHROMA]

    @classmethod
    def _organic_soft_field(cls, h, w, p, region=None):
        """How soft each pixel is, 0..1. Uniform at Edge 0, and a bowl
        that is sharp in the middle and soft in the corners as Edge
        rises."""
        import numpy as np
        edge = min(1.0, max(0.0, float(p.get("soft_edge", 0.5))))
        amount = min(1.0, max(0.0, float(p.get("soft_amount", 0.0))))
        if edge <= 0:
            return np.full((h, w), amount, np.float32)
        r = cls._organic_radial_r(h, w, region)
        fall = max(0.1, float(p.get("soft_edge_falloff", 2.0)))
        return (amount * ((1.0 - edge) + edge * r ** fall)).astype(np.float32)

    @classmethod
    def _organic_soften(cls, rgb, p, region=None):
        """Soft-focus from a lens that cannot resolve, rather than from
        being mis-focused."""
        import numpy as np, cv2
        amount = float(p.get("soft_amount", 0.0))
        radius = float(p.get("soft_radius", 8.0))
        if amount <= 0 or radius <= 0:
            return rgb
        h, w = rgb.shape[:2]
        halo = min(1.0, max(0.0, float(p.get("soft_halo", 0.35))))
        chroma = float(p.get("soft_chroma", 0.5))
        radii = cls._organic_soft_radii(radius, chroma)

        def _two_scale(src, rad):
            tight = cv2.GaussianBlur(src, (0, 0), sigmaX=rad, sigmaY=rad)
            if halo <= 0:
                return tight
            wide = cls._organic_wide_blur(src, rad * cls._ORGANIC_SOFT_WIDE)
            return tight * (1.0 - halo) + wide * halo

        if abs(radii[0] - radii[1]) < 1e-6 and abs(radii[2] - radii[1]) < 1e-6:
            # Achromatic: one pass over all three channels at once
            # instead of three, which is most of the cost of this effect.
            blurred = _two_scale(rgb, radii[1])
        else:
            blurred = np.empty_like(rgb)
            for c in range(3):
                blurred[:, :, c] = _two_scale(rgb[:, :, c], radii[c])
        wgt = cls._organic_soft_field(h, w, p, region)[:, :, None]
        return rgb * (1.0 - wgt) + blurred * wgt

    # ── lens surface contamination ────────────────────────────────────
    # Smudge and scratches both live ON the front element, which makes
    # them different from everything else in the stack in one way that
    # matters: they are fixed to the LENS, not to the scene. The pattern
    # must therefore be identical on every frame -- a smudge that
    # reseeds per frame is just coloured grain -- so neither takes the
    # per-frame seed that grain does. Both are also built in absolute
    # frame coordinates and cropped, so a region update lands the same
    # dirt in the same place.

    @classmethod
    def _organic_lens_field(cls, h, w, scale, octaves, seed, region=None):
        """Low-frequency fBm in 0..1, generated in FULL-frame space and
        cropped. Built by upsampling small random lattices, which is
        cheap and -- because the lattice is seeded, not streamed -- gives
        the same field whatever rectangle is asked for."""
        import numpy as np, cv2
        if region is None:
            y0, x0, fh, fw = 0, 0, h, w
        else:
            y0, x0, fh, fw = region
        rng = np.random.default_rng(int(seed) & 0x7FFFFFFF)
        acc = np.zeros((fh, fw), np.float32)
        amp, total = 1.0, 0.0
        cells = max(2, int(scale))
        for o in range(max(1, int(octaves))):
            gh = min(max(2, cells * (2 ** o)), max(2, fh))
            gw = min(max(2, int(round(gh * fw / max(fh, 1)))), max(2, fw))
            g = rng.random((gh, gw)).astype(np.float32)
            acc += cv2.resize(g, (fw, fh),
                              interpolation=cv2.INTER_CUBIC) * amp
            total += amp
            amp *= 0.5
        f = acc / max(total, 1e-6)
        # Stretched to its own full 0..1 range before cropping. Averaging
        # octaves pulls the extremes in towards 0.5, so the raw field
        # rarely exceeded ~0.85 and the bottom third of the Coverage
        # slider did nothing at all. Measured on the FULL field, not the
        # crop, so a region update thresholds against the same numbers.
        lo, hi = float(f.min()), float(f.max())
        if hi - lo > 1e-6:
            f = (f - lo) / (hi - lo)
        return np.clip(f, 0.0, 1.0).astype(np.float32)[y0:y0 + h, x0:x0 + w]

    @classmethod
    def _organic_smudge(cls, rgb, p, region=None):
        """Greasy patches on the glass. Light through a smudge is
        scattered, so this is a LOCAL diffusion plus an optional milky
        lift -- not a uniform blur and not a brightness change. Coverage
        soft-thresholds the field so the frame has clean glass between
        the patches instead of being evenly hazy all over, which is what
        separates a smudge from simple veiling."""
        import numpy as np, cv2
        amount = float(p.get("smudge_amount", 0.0))
        if amount <= 0:
            return rgb
        h, w = rgb.shape[:2]
        m = cls._organic_lens_field(h, w, p.get("smudge_scale", 4),
                                    p.get("smudge_detail", 3),
                                    p.get("smudge_seed", 1), region)
        cover = min(1.0, max(0.0, float(p.get("smudge_coverage", 0.45))))
        edge = max(0.02, float(p.get("smudge_softness", 0.35)))
        m = np.clip((m - (1.0 - cover)) / edge, 0.0, 1.0).astype(np.float32)
        blur = max(0.5, float(p.get("smudge_blur", 12.0)))
        wgt = (m * amount)[:, :, None]
        soft = cv2.GaussianBlur(rgb, (0, 0), sigmaX=blur, sigmaY=blur)
        out = rgb + (soft - rgb) * wgt
        haze = float(p.get("smudge_haze", 0.0))
        if haze > 0:
            # The lift is driven by nearby brightness, so a smudge is
            # invisible on a dark frame and glows over a window -- which
            # is exactly when you notice one on a real lens.
            lift = cv2.GaussianBlur(rgb.max(axis=2), (0, 0),
                                    sigmaX=blur * 3.0, sigmaY=blur * 3.0)
            out = out + wgt * (haze * lift)[:, :, None]
        return out

    @classmethod
    def _organic_scratch_mask(cls, h, w, p, region=None):
        """Procedural scratches, drawn in FULL-frame coordinates and
        cropped. Each is a slightly curved 3-point polyline rather than a
        straight segment: a dead-straight scratch reads as a rendering
        artefact, and real ones follow whatever wiped the glass."""
        import numpy as np, cv2
        if region is None:
            y0, x0, fh, fw = 0, 0, h, w
        else:
            y0, x0, fh, fw = region
        rng = np.random.default_rng(int(p.get("scratch_seed", 1)) & 0x7FFFFFFF)
        canvas = np.zeros((fh, fw), np.float32)
        count = max(0, int(p.get("scratch_count", 12)))
        diag = float(np.hypot(fh, fw))
        length = max(0.01, float(p.get("scratch_length", 0.35)))
        width = max(1, int(round(float(p.get("scratch_width", 2)))))
        bias = float(p.get("scratch_angle", 0.0))
        spread = float(p.get("scratch_angle_var", 180.0))
        for _ in range(count):
            cx = rng.uniform(0, fw)
            cy = rng.uniform(0, fh)
            ang = np.deg2rad(bias + rng.uniform(-spread, spread) * 0.5)
            ln = diag * length * rng.uniform(0.4, 1.0)
            dx, dy = np.cos(ang) * ln * 0.5, np.sin(ang) * ln * 0.5
            # perpendicular bow, a few percent of the length
            bow = rng.uniform(-0.06, 0.06) * ln
            mx, my = -np.sin(ang) * bow, np.cos(ang) * bow
            pts = np.array([[cx - dx, cy - dy],
                            [cx + mx, cy + my],
                            [cx + dx, cy + dy]], np.float32)
            t = np.linspace(0.0, 1.0, 24, dtype=np.float32)[:, None]
            curve = ((1 - t) ** 2 * pts[0] + 2 * (1 - t) * t * pts[1]
                     + t ** 2 * pts[2])
            cv2.polylines(canvas, [np.round(curve).astype(np.int32)],
                          False, 1.0, thickness=width, lineType=cv2.LINE_AA)
        soft = float(p.get("scratch_softness", 1.2))
        if soft > 0.3:
            canvas = cv2.GaussianBlur(canvas, (0, 0), sigmaX=soft, sigmaY=soft)
        peak = float(canvas.max())
        if peak > 1e-6:
            canvas /= peak
        return canvas[y0:y0 + h, x0:x0 + w]

    @classmethod
    def _organic_scratches(cls, rgb, p, region=None):
        """Fine scratches catching light. They ADD, scaled by how much
        light is around them, so they stay invisible on a dark frame and
        flare up when a source is near -- a scratch has no brightness of
        its own, it only scatters what reaches it."""
        import cv2
        amount = float(p.get("scratch_amount", 0.0))
        if amount <= 0 or int(p.get("scratch_count", 0)) <= 0:
            return rgb
        h, w = rgb.shape[:2]
        m = cls._organic_scratch_mask(h, w, p, region)
        spread = max(1.0, float(p.get("scratch_spread", 60.0)))
        glow = cv2.GaussianBlur(rgb.max(axis=2), (0, 0),
                                sigmaX=spread, sigmaY=spread)
        return rgb + (m * amount)[:, :, None] * glow[:, :, None]

    @staticmethod
    def _organic_wide_blur(field, sigma):
        """Gaussian blur that stays affordable at veil-scale sigmas.

        A sigma of 400 on a 4K plate is minutes of work at full
        resolution, and pointless: the result has no detail above the
        blur scale by definition, so it is computed on a downsampled
        copy and scaled back. The copy is halved until sigma lands
        under 24px, which is where OpenCV is still quick."""
        import numpy as np, cv2
        s = max(0.5, float(sigma))
        h, w = field.shape[:2]
        ds = 1
        while s / ds > 24.0 and min(h // (ds * 2), w // (ds * 2)) >= 16:
            ds *= 2
        if ds == 1:
            return cv2.GaussianBlur(field, (0, 0), sigmaX=s, sigmaY=s)
        small = cv2.resize(field, (max(1, w // ds), max(1, h // ds)),
                           interpolation=cv2.INTER_AREA)
        small = cv2.GaussianBlur(small, (0, 0),
                                 sigmaX=s / ds, sigmaY=s / ds)
        return np.asarray(
            cv2.resize(small, (w, h), interpolation=cv2.INTER_LINEAR),
            dtype=np.float32)

    @classmethod
    def _organic_veil(cls, rgb, p):
        """Wide achromatic sensor bloom -- charge bleeding sideways
        across the photosite well, not scatter in the glass.

        Deliberately different in character from the convolution bloom
        above: no kernel, no shape, no anamorphic stretch. It is the
        soft milky lift around a blown window that a flare kernel
        cannot produce, because the thing that causes it happens after
        the light has already landed.

        Two Gaussians rather than one. A single wide blur gives a flat
        featureless wash; a tight one plus a very wide one reproduces
        the real falloff, which is steep close in and then has a long
        low tail across most of the frame.

        Colour is a slider, not a constant. True charge bleed IS
        achromatic -- the well overflows on electrons, which carry no
        wavelength, so a green practical veils white. But almost none of
        the veiling glare on a real frame is charge bleed: modern CMOS
        has anti-blooming drains, and what actually lifts the blacks is
        scatter in the glass and off the sensor stack, which very much
        does keep the source's hue. Colour 0 is the textbook CCD
        behaviour, 1 inherits the source hue the way the kernel bloom
        does, and real footage sits between."""
        import numpy as np
        inten = float(p.get("veil_intensity", 0.0))
        if inten <= 0:
            return rgb
        lum = rgb.max(axis=2)
        over = np.clip(lum - float(p.get("veil_thresh", 0.8)),
                       0.0, None).astype(np.float32)
        if not np.any(over > 0):
            return rgb
        sat = min(1.0, max(0.0, float(p.get("veil_sat", 0.5))))
        if sat > 0:
            # Each channel's share of the over-threshold energy, so the
            # tinted field's per-pixel MAX is still `over` -- both ends
            # of the slider carry the same peak, and only the hue moves.
            with np.errstate(divide="ignore", invalid="ignore"):
                share = np.nan_to_num(rgb / np.maximum(lum[:, :, None], 1e-6))
            src = over[:, :, None] * (1.0 - sat + sat * np.clip(share, 0, 1))
        else:
            src = over
        # Mixed before the blur rather than after. The blur is linear
        # (downsample, Gaussian, upsample are all linear), so the two
        # are identical, and this way a white veil still costs one
        # channel's worth of work instead of three.
        # One trip down and up PER LAYER, not a shared one. Sharing a
        # working resolution looked like a saving -- four full-res
        # resizes down to two -- but the resolution has to be driven by
        # the tighter sigma or that layer aliases into blocks, and with
        # Near at 24 that means no downsampling at all, which then runs
        # the WIDE blur at full 4K. Measured 40s against 5.8s. The
        # resizes were never the cost; the blurs are, and they are only
        # cheap because each layer picks its own resolution.
        mix = min(1.0, max(0.0, float(p.get("veil_mix", 0.5))))
        sa = float(p.get("veil_size_a", 24))
        sb = float(p.get("veil_size_b", 160))

        def _spill(field, scale):
            near = cls._organic_wide_blur(field, sa * scale)
            far = cls._organic_wide_blur(field, sb * scale)
            return near * (1.0 - mix) + far * mix

        # Intensity banding, the same machinery the bloom kernel uses --
        # but here it is the physical answer rather than an artistic
        # one. Charge bleed is genuinely non-linear: a saturated well
        # spills into its neighbours, and the more excess charge there
        # is, the further it travels before it is absorbed. A brighter
        # highlight really does veil WIDER, not merely brighter, which
        # is the one thing a single blur cannot express.
        bands = max(1, int(p.get("veil_bands", 1)))
        if bands <= 1:
            veil = _spill(src, 1.0)
        else:
            spread = max(1.05, float(p.get("veil_band_spread", 2.0)))
            veil = None
            for i, w in enumerate(cls._organic_band_weights(
                    over, bands, p.get("veil_thresh", 0.8))):
                if not np.any(w > 1e-4):
                    continue
                wf = w if src.ndim == 2 else w[:, :, None]
                part = _spill(src * wf, spread ** i)
                veil = part if veil is None else veil + part
            if veil is None:
                return rgb
        veil = np.maximum(veil, 0.0)
        if veil.ndim == 2:
            veil = veil[:, :, None]
        return rgb + veil * inten

    @staticmethod
    def _organic_convolve(src, kernel):
        """Zero-padded linear convolution via DFT.

        One path for every kernel size on purpose. cv2.filter2D switches
        to DFT only above roughly 11x11 and is markedly SLOWER below
        that at plate resolution -- measured on a 4K frame, filter2D
        took 5.4s for a 17x17 kernel and 2.4s for 241x241, while an
        explicit DFT sits flat around 2.5s throughout. A predictable
        cost beats a faster best case with a cliff in the middle of the
        Radius slider's range."""
        import numpy as np, cv2
        arr = np.asarray(src, dtype=np.float32)
        single = (arr.ndim == 2)
        if single:
            arr = arr[:, :, None]
        h, w = arr.shape[:2]
        kh, kw = kernel.shape
        fh = cv2.getOptimalDFTSize(h + kh)
        fw = cv2.getOptimalDFTSize(w + kw)
        # CCS-packed spectra rather than DFT_COMPLEX_OUTPUT. Both inputs
        # are real, so a full complex transform computes and multiplies a
        # conjugate-symmetric half it already knows -- about twice the
        # work for the same answer. Measured on a 4K frame with a 121px
        # kernel: 1.58s complex against 0.70s packed, agreeing to 4e-07,
        # which is float32 rounding. mulSpectrums reads the packed
        # layout directly, so nothing downstream changes.
        kpad = np.zeros((fh, fw), np.float32)
        kpad[:kh, :kw] = kernel
        kf = cv2.dft(kpad)
        out = np.empty_like(arr)
        for c in range(arr.shape[2]):
            pad = np.zeros((fh, fw), np.float32)
            pad[:h, :w] = arr[:, :, c]
            res = cv2.idft(cv2.mulSpectrums(cv2.dft(pad), kf, 0),
                           flags=cv2.DFT_SCALE | cv2.DFT_REAL_OUTPUT)
            out[:, :, c] = res[kh // 2:kh // 2 + h, kw // 2:kw // 2 + w]
        return out[:, :, 0] if single else out

    @classmethod
    def _organic_bloom(cls, rgb, p):
        """Sensor/halation bloom: isolate what's above threshold,
        convolve it with the composited kernel, add it back. Done on
        scene-linear values so a genuine 4.0 highlight blooms four times
        as hard as a 1.0 one -- the same operation on display-referred
        data would clip both to white first and bloom them identically.

        Takes the whole params dict rather than positional arguments:
        the kernel alone has thirteen controls, and threading those
        through a signature is how a caller ends up quietly passing the
        defaults for half of them."""
        import numpy as np
        intensity = float(p.get("bloom_intensity", 0.0))
        if intensity <= 0 or float(p.get("bloom_radius", 0)) <= 0:
            return rgb
        # Threshold 0 turns the gate off rather than disabling bloom:
        # over becomes the luminance itself and the whole frame blooms,
        # which is veiling glare rather than highlight bloom. That is a
        # legitimate look, so it is a valid slider position, not a
        # degenerate one to guard against.
        over = cls._organic_bloom_over(rgb, p.get("bloom_thresh", 0.9))
        if not np.any(over > 0):
            return rgb
        # weight each channel by its share of the over-threshold
        # energy, so a red highlight blooms red rather than white
        lum = rgb.max(axis=2)
        with np.errstate(divide="ignore", invalid="ignore"):
            share = np.nan_to_num(rgb / np.maximum(lum[:, :, None], 1e-6))
        src = share * over[:, :, None]
        bands = max(1, int(p.get("bloom_bands", 1)))
        if bands <= 1:
            spill = cls._organic_bloom_pass(src, p, 1.0)
        else:
            spill = None
            spread = max(1.05, float(p.get("bloom_band_spread", 2.0)))
            for i, w in enumerate(cls._organic_band_weights(
                    over, bands, p.get("bloom_thresh", 0.9))):
                # A band with nothing in it costs a full transform for a
                # black frame, and on a typical plate most of them are
                # empty -- one practical light does not populate four
                # decades of brightness.
                if not np.any(w > 1e-4):
                    continue
                part = cls._organic_bloom_pass(src * w[:, :, None], p,
                                               spread ** i)
                spill = part if spill is None else spill + part
            if spill is None:
                return rgb
        if spill is None:
            return rgb
        return rgb + spill * intensity

    @staticmethod
    def _organic_band_weights(over, bands, threshold):
        """Soft luminance bands over the above-threshold energy, summing
        to exactly 1 at every pixel.

        Triangular basis functions in LOG space, which is the linear
        B-spline partition of unity -- adjacent bands share a pixel
        rather than one of them claiming it. Hard buckets would put a
        visible contour ring wherever a gradient crosses an edge, and
        those rings crawl on moving footage, which is far worse than
        having no banding at all.

        Log space, and anchored to the bloom threshold, because
        brightness is perceived in ratios and because the threshold is
        the exposure decision the user has already made -- absolute
        edges would land somewhere different on every plate."""
        import numpy as np
        anchor = max(0.25, float(threshold))
        stops = 3.0                      # each band is ~8x the last
        u = np.log2(np.maximum(over, 1e-6) / anchor) / stops
        u = np.clip(u, 0.0, bands - 1.0)
        return [np.clip(1.0 - np.abs(u - i), 0.0, 1.0).astype(np.float32)
                for i in range(bands)]

    @classmethod
    def _organic_bloom_pass(cls, src, p, px_scale):
        """One convolution of an already-prepared source against the
        kernel built at `px_scale`. Returns None if the kernel is
        degenerate."""
        import numpy as np
        kr, kg, kb = cls._organic_bloom_kernel_rgb(p, px_scale)
        if kr is kg is kb:
            ksum = float(kg.sum())
            if ksum <= 1e-9:
                return None
            # DFT convolution rings slightly negative around hard edges.
            # The kernel is non-negative everywhere, so any negative in
            # the result is numerical, and bloom must only ADD light.
            return np.maximum(cls._organic_convolve(src, kg / ksum), 0.0)
        out = np.empty_like(src)
        for c, k in enumerate((kr, kg, kb)):
            ksum = float(k.sum())
            if ksum <= 1e-9:
                return None
            out[:, :, c] = np.maximum(
                cls._organic_convolve(src[:, :, c], k / ksum), 0.0)
        return out

    @classmethod
    def _organic_vignette(cls, rgb, amount, falloff=2.0, region=None):
        """Natural cos^4-style barrel falloff rather than a plain
        radial gradient -- real vignetting comes from the light path
        itself, and cos^4 is the classic approximation of it, which
        rolls off far more gently near the centre than a linear or
        simple-radial ramp does."""
        if amount <= 0:
            return rgb
        h, w = rgb.shape[:2]
        mask = cls._organic_vignette_mask(h, w, amount, falloff, region)
        return rgb * mask[:, :, None]

    # Per-layer grain character at Filmic = 1, as R, G, B.
    #
    # Colour negative is three stacked emulsions, and they are not the
    # same emulsion. Silver halide is inherently blue-sensitive, so the
    # top blue layer works without sensitising dyes and is built with
    # the coarsest crystals; the green layer sits behind the yellow
    # filter and is the finest and cleanest, which is why luminance
    # detail is carried mostly by green; red sits between them.
    #
    # Anyone who has cleaned up a film scan knows the consequence: the
    # blue channel is the grainy one and green is the clean one. That
    # ORDERING is the well-established part and is what these encode.
    # The exact ratios are a plausible reading of it, NOT published
    # per-layer figures -- manufacturers quote a single diffuse RMS
    # granularity per stock, not one per layer -- so treat them as a
    # tuned starting point rather than a measurement.
    # Blue runs just over twice green's grain size. That is wider than
    # a cautious reading of the physics would give, and deliberately so:
    # the conservative 1.15/1.00/1.40 was correct in ordering but the
    # separation did not survive being looked at, especially at large
    # Size where every channel is heading toward the same flat field.
    # These are a look control, so they are tuned to read on screen.
    _ORGANIC_FILM_GRAIN_SIZE = (1.45, 1.00, 2.10)
    # Amplitudes average to 1.0 on purpose: Filmic changes the CHARACTER
    # of the grain, not how much of it there is, so it can be dialled in
    # without re-tuning Intensity afterwards.
    # Scaled so they combine to unit power in QUADRATURE, not
    # arithmetically -- noise adds as variance, so a straight mean of
    # 1.0 would still leave the frame measurably grainier.
    _ORGANIC_FILM_GRAIN_AMP = (0.918, 0.676, 1.304)

    @staticmethod
    def _organic_blur_noise_gain(sigma):
        """RMS a unit-variance white field retains after a Gaussian blur
        of this sigma, computed from the kernel rather than from the
        data: sqrt(sum(k**2)), separable so it is the 1-D sum squared.

        Data-independent on purpose. Measuring the actual field's
        deviation would be exact for a full frame and WRONG for a crop,
        which would put a visible seam at the edge of a region update."""
        import numpy as np, cv2
        if sigma <= 0:
            return 1.0
        k = cv2.getGaussianKernel(
            int(2 * int(np.ceil(3.0 * sigma)) + 1), sigma).ravel()
        return float(np.sum(k * k))

    @classmethod
    def _organic_grain_channel(cls, filmic, channel):
        """(size multiplier, amplitude multiplier) for one channel.
        Filmic blends from a single shared emulsion toward the three
        real ones, so 0 leaves every channel identical."""
        f = min(1.0, max(0.0, float(filmic)))
        sz = 1.0 + (cls._ORGANIC_FILM_GRAIN_SIZE[channel] - 1.0) * f
        amp = 1.0 + (cls._ORGANIC_FILM_GRAIN_AMP[channel] - 1.0) * f
        return sz, amp

    @classmethod
    def _organic_grain(cls, rgb, intensity, size=1.0, shadow_weight=1.5,
                       chroma=0.5, seed=None, region=None, filmic=0.0):
        """Per-channel sensor/film grain. Two details keep it from
        reading as flat TV static: it's scaled by a shadow-weighted
        response (real grain is most visible in the mids and shadows
        and gets buried in the highlights), and chroma controls how
        independent the three channels are -- fully-correlated noise
        looks digital, fully-independent looks like colour speckle,
        and real stock sits between the two.

        `filmic` blends from one shared emulsion toward three real ones,
        giving each channel its own grain size and strength -- see
        _ORGANIC_FILM_GRAIN_SIZE for where those numbers come from."""
        import numpy as np, cv2
        if intensity <= 0:
            return rgb
        h, w = rgb.shape[:2]
        if region is None:
            gy0, gx0, gh, gw = 0, 0, h, w
        else:
            gy0, gx0, gh, gw = region
        # Position-addressed, not sequential. numpy's generator produces
        # a stream, so drawing a crop's worth gives a completely
        # different pattern from the same pixels inside a full-frame
        # draw -- which put a visible seam down the side of the ROI box.
        # Generating the whole field and slicing fixed the seam but made
        # a region update cost full-frame work, which defeated the ROI.
        # Hashing the pixel's absolute index gives both: identical to
        # the full render, and O(area of the crop).
        # Padded for the COARSEST channel, so even the widest blur sees
        # real neighbours at the crop edge instead of zeros.
        sizes = [float(size) * cls._organic_grain_channel(filmic, c)[0]
                 for c in range(3)]
        max_size = max(sizes)
        # 4 sigma, not 3. The margin has to cover the widest channel,
        # and once blue went to twice green's size a 3-sigma skirt left
        # a measurable 3e-06 across the whole crop -- small, but it is
        # the difference between a region update matching the full
        # render and merely resembling it.
        pad = int(np.ceil(4.0 * max_size * 0.5)) if max_size > 1.0 else 0
        py0 = max(0, gy0 - pad); px0 = max(0, gx0 - pad)
        py1 = min(gh, gy0 + h + pad); px1 = min(gw, gx0 + w + pad)
        cut = (slice(gy0 - py0, gy0 - py0 + h),
               slice(gx0 - px0, gx0 - px0 + w))

        # Two fields per hash pair, so mono plus three chroma streams
        # cost two pairs rather than four separate draws.
        need = 1 if chroma <= 0 else 4
        fields = cls._organic_hash_normals(gw, py0, px0, py1 - py0,
                                           px1 - px0, seed, 0,
                                           (need + 1) // 2)

        # Filmic must not change how much grain there is, only its
        # character -- otherwise it could not be dialled in without
        # re-tuning Intensity. The existing sz**0.5 rule stays (changing
        # it would move the Size slider under every saved preset); each
        # channel is then corrected by the RATIO of true blur losses
        # between its own size and the base, which cancels the drift
        # exactly while leaving Filmic 0 untouched.
        def _level(sz):
            """The RMS this code path actually leaves a unit field at,
            for a given size. Below 1.0 the blur is skipped entirely, so
            the reference has to skip it too -- computing it as if the
            base were always blurred made Size 1.0 come out 27% quiet."""
            if sz <= 1.0:
                return 1.0
            return cls._organic_blur_noise_gain(sz * 0.5) * sz ** 0.5

        base_level = _level(float(size))

        def _blur(f, sz):
            if sz <= 1.0:
                lvl = 1.0
                g = f
            else:
                # Blurred on a margin, then cut, so the crop's edge sees
                # the same neighbours the full frame would have given it.
                g = cv2.GaussianBlur(f, (0, 0), sigmaX=sz * 0.5)
                g = g * (sz ** 0.5)     # keep amplitude after blurring
                lvl = _level(sz)
            # Bring this channel back to the base channel's level, so
            # Filmic changes character without changing how much grain
            # there is. Cancels both the true blur loss and the sz**0.5
            # rule; correcting only the first left the coarse channels
            # sz**0.5 too loud.
            if lvl > 1e-12 and abs(lvl - base_level) > 1e-12:
                g = g * (base_level / lvl)
            return g[cut]

        # The blur happens PER CHANNEL now, because that is what gives
        # each layer its own grain size. At Filmic 0 all three sigmas are
        # equal and this reduces exactly to the shared field it replaced.
        noise = np.empty((h, w, 3), np.float32)
        for c in range(3):
            _sz, amp = cls._organic_grain_channel(filmic, c)
            base = _blur(fields[0], sizes[c])
            if chroma <= 0:
                f = base
            else:
                f = (base * (1.0 - float(chroma))
                     + _blur(fields[c + 1], sizes[c]) * float(chroma))
            noise[:, :, c] = f * amp
        # never fully silent in highlights -- see _organic_grain_response
        resp = cls._organic_grain_response(rgb, shadow_weight)
        return rgb + noise * (float(intensity) * resp[:, :, None])

    @classmethod
    def _organic_stack_reach(cls, p):
        """Pixels of influence the stack pulls in from outside a crop.

        Bloom and the veil are convolutions: to get the right answer
        inside a box you need the input DILATED by their reach, or the
        light that should have spilled in from just outside is simply
        missing and the box gets a dark border. CA displaces by a pixel
        or two, grain and vignette are per-pixel.

        Deliberately generous on the veil -- a Gaussian's tail is not
        finished at one sigma, and three is the usual working cutoff."""
        # SUMMED, not maxed. The stages run in series: bloom spreads a
        # highlight by its kernel, and the veil then spreads THAT by its
        # own sigma, so the input a correct ROI needs is dilated by the
        # total. Taking the max quietly under-padded every chain with
        # more than one spreading stage in it.
        reach = 2.0
        if float(p.get("smudge_amount", 0.0)) > 0:
            # the haze lift blurs at 3x the diffusion sigma
            reach += 3.0 * 3.0 * float(p.get("smudge_blur", 12.0))
        if float(p.get("scratch_amount", 0.0)) > 0:
            reach += 3.0 * float(p.get("scratch_spread", 60.0))
        if float(p.get("soft_amount", 0.0)) > 0:
            # the far halo blurs at 4x the radius, and the blue channel
            # widest of the three
            reach += (3.0 * float(p.get("soft_radius", 8.0))
                      * cls._ORGANIC_SOFT_WIDE
                      * max(cls._ORGANIC_SOFT_CHROMA))
        if float(p.get("ca", 0.0)) > 0:
            reach += 4.0
        if float(p.get("bloom_intensity", 0.0)) > 0:
            # the widest BAND sets the reach, not the base radius
            _rad = float(p.get("bloom_radius", 0)) * (
                max(1.05, float(p.get("bloom_band_spread", 2.0)))
                ** (max(1, int(p.get("bloom_bands", 1))) - 1))
            reach += (_rad
                      * max(1.0, float(p.get("bloom_aniso", 1.0))) * 1.2)
        if float(p.get("veil_intensity", 0.0)) > 0:
            # 3 sigma: a Gaussian is not finished at one, and the veil's
            # whole job is the long low tail.
            reach += (3.0 * max(float(p.get("veil_size_a", 0)),
                                float(p.get("veil_size_b", 0)))
                      * max(1.05, float(p.get("veil_band_spread", 2.0)))
                      ** (max(1, int(p.get("veil_bands", 1))) - 1))
        return int(round(reach))

    @classmethod
    def _organic_roi_crop(cls, shape, roi, p):
        """(y0, x0, y1, x1) of the padded crop to actually process, or
        None when the padding has eaten so much of the frame that the
        crop is no longer worth taking.

        The threshold is honest arithmetic, not a guess: if the padded
        crop covers most of the plate, a region update costs about what
        a full one does while producing a result that has to be pasted
        back. Below that, it is a real saving."""
        fh, fw = shape[:2]
        if not roi:
            return None
        ry0, rx0, ry1, rx1 = roi
        ry0 = max(0, min(fh - 1, int(ry0)))
        rx0 = max(0, min(fw - 1, int(rx0)))
        ry1 = max(ry0 + 1, min(fh, int(ry1)))
        rx1 = max(rx0 + 1, min(fw, int(rx1)))
        pad = cls._organic_stack_reach(p)
        y0 = max(0, ry0 - pad)
        x0 = max(0, rx0 - pad)
        y1 = min(fh, ry1 + pad)
        x1 = min(fw, rx1 + pad)
        # Declined only when the padded crop is nearly the whole plate.
        # 0.75 was too eager: a 1080p frame with a 180px veil pads to
        # full height and got refused even though the horizontal saving
        # was still real.
        if (y1 - y0) * (x1 - x0) > 0.92 * fh * fw:
            return None
        return y0, x0, y1, x1

    def _organic_apply_stack_roi(self, rgb, p, roi, seed=None,
                                 progress=None):
        """Run the stack over `roi` only, returning (result, box) where
        box is the ROI in frame coordinates -- or (None, None) if a
        region update would not pay for itself and the caller should
        just do the whole frame."""
        crop = self._organic_roi_crop(rgb.shape, roi, p)
        if crop is None:
            return None, None
        cy0, cx0, cy1, cx1 = crop
        fh, fw = rgb.shape[:2]
        sub = rgb[cy0:cy1, cx0:cx1]
        pr = dict(p, region=(cy0, cx0, fh, fw))
        done = self._organic_apply_stack(sub, pr, seed=seed,
                                         progress=progress)
        ry0, rx0, ry1, rx1 = roi
        ry0 = max(cy0, int(ry0)); rx0 = max(cx0, int(rx0))
        ry1 = min(cy1, int(ry1)); rx1 = min(cx1, int(rx1))
        inner = done[ry0 - cy0:ry1 - cy0, rx0 - cx0:rx1 - cx0]
        return inner, (ry0, rx0, ry1, rx1)

    def _organic_apply_stack(self, rgb, p, seed=None, progress=None):
        """Runs the whole stack in optical order. `p` is a plain dict
        of the same keys the presets use, so the preview path, the
        render path and the tests all drive this one function rather
        than each assembling the chain themselves.

        Built as a list of enabled steps rather than a run of ifs so
        the caller can be told how many there are and which one is
        running. The stack is synchronous and a 4K bloom alone is
        seconds, so without that the UI has nothing to say between
        "started" and "finished"."""
        import numpy as np
        out = np.asarray(rgb, dtype=np.float32)
        # (y0, x0, full_h, full_w) when `rgb` is a crop of a larger
        # plate. Everything position-dependent -- the CA ramp, the
        # vignette, the grain field -- reads it so a region-of-interest
        # update is identical to the same pixels in a full render.
        region = p.get("region")
        steps = []
        if p.get("smudge_amount", 0) > 0:
            steps.append(("Lens Smudge",
                          lambda x: self._organic_smudge(x, p, region)))
        if p.get("scratch_amount", 0) > 0:
            steps.append(("Lens Scratches",
                          lambda x: self._organic_scratches(x, p, region)))
        if p.get("soft_amount", 0) > 0:
            steps.append(("Lens Softness",
                          lambda x: self._organic_soften(x, p, region)))
        if p.get("ca", 0) > 0:
            steps.append(("Aberration", lambda x: self._organic_chromatic(
                x, p["ca"], p.get("ca_falloff", 2.0), region)))
        if p.get("bloom_intensity", 0) > 0:
            steps.append(("Bloom", lambda x: self._organic_bloom(x, p)))
        if p.get("vig", 0) > 0:
            steps.append(("Vignette", lambda x: self._organic_vignette(
                x, p["vig"], p.get("vig_falloff", 2.0), region)))
        # Veil comes after the vignette, not before it. Everything above
        # is the lens -- scatter and falloff acting on light that has
        # not reached the sensor yet -- while the veil is charge bleeding
        # across photosites once it has. Running it first let the barrel
        # falloff darken a sensor artefact that physically forms behind
        # it, which put a vignette on the veil's own outer tail.
        if p.get("veil_intensity", 0) > 0:
            steps.append(("Sensor Veil", lambda x: self._organic_veil(x, p)))
        if p.get("grain", 0) > 0:
            steps.append(("Grain", lambda x: self._organic_grain(
                x, p["grain"], p.get("grain_size", 1.0),
                p.get("grain_shadow", 1.5), p.get("grain_chroma", 0.5),
                seed=seed, region=region,
                filmic=p.get("grain_filmic", 0.0))))
        total = len(steps)
        for n, (name, fn) in enumerate(steps):
            if progress is not None:
                progress(n, total, name)
            out = fn(out)
        if progress is not None:
            progress(total, total, "")
        # Wet/dry over the WHOLE chain, applied once at the end rather
        # than folded into each effect. Scaling every effect's own
        # amount would not be the same thing: the stack is not linear --
        # bloom thresholds, grain is weighted by luminance, the veil has
        # its own gate -- so turning them all down changes the character
        # of the look, while this dials the finished look back toward
        # the plate and leaves its character alone.
        gain = float(p.get("global_gain", 1.0))
        if gain < 1.0:
            src = np.asarray(rgb, dtype=np.float32)
            out = src * (1.0 - gain) + out * gain
        return out

    # ── TAB: ADW-ORGANIC ─────────────────────────────────────────────
    def _tab_organic(self):
        """Lens/sensor simulation: chromatic aberration, bloom,
        vignette and grain, applied in real optical order on
        scene-linear values. Same two-column shape, timeline, and
        wipe/diff comparison as CurveLock/AreaLock."""
        f = self._frame("organic")
        # Title and subtitle are built inside the scrolling area rather
        # than passed to _two_col, so they scroll with the controls
        # instead of pinning 60px of header above a cramped list.
        lf, rf = self._two_col(f, "", "", lw=380)
        lf, _obottom = self._scroll_column(lf)
        tk.Label(lf, text="Lens Studio", font=("Futura", 14), bg=BG, fg=W,
                 anchor="w").pack(anchor="w", padx=16, pady=(14, 2))
        tk.Label(lf, text="Break up the clean look — lens and sensor "
                 "artifacts.", font=FSM, bg=BG, fg=G, anchor="w",
                 wraplength=340, justify="left").pack(
                     anchor="w", padx=16, pady=(0, 10))

        self.organic_folder = None
        self.organic_frames = []
        self.organic_img_base = None      # PIL RGB of current frame
        self.organic_lin = None           # scene-linear float of current frame
        self.organic_processed = None     # PIL RGB after the stack
        self.organic_mode = "edit"        # edit | wipe | diff
        self._organic_wipe_t = 0.5
        self._organic_wipe_drag = None
        self._organic_exposure_scale = 1.0
        self._organic_source_encoded = None
        self._organic_cs_reason = "not yet decided"
        # mask preview: which control's mask is on screen (None = off),
        # the P buttons keyed by mask so they can all be lit/dimmed
        # together, the cached downsampled frame masks are derived from,
        # and the coalescing handle for drag updates.
        # viewer transform. Kept separate from the wipe so zooming in to
        # judge grain does not disturb the comparison position.
        # Same model as AreaLock: additive zoom 0.25..8, pan as the
        # image's top-left origin on the canvas rather than an offset
        # from a centred fit.
        self._organic_zoom  = 1.0
        self._organic_pan_x = 0
        self._organic_pan_y = 0
        self._organic_pan_ref = None
        self._organic_scale = 1.0
        self.organic_diff_mult = 6
        self._organic_roi = None          # (y0,x0,y1,x1) in image pixels
        self._organic_roi_mode = False
        self._organic_roi_drag = None
        self._organic_auto_job = None
        self._organic_mask_key  = None
        self._organic_mask_btns = {}
        self._organic_mask_src  = None
        self._organic_mask_job  = None
        # solo / mute, per effect. Solo is additive and beats mute, the
        # same way a mixer does it: with anything soloed, only the
        # soloed effects run, whatever their mute says.
        self._organic_fx_solo = {k: False for k, _l, _g in self._ORGANIC_FX}
        self._organic_fx_mute = {k: False for k, _l, _g in self._ORGANIC_FX}
        self._organic_fx_btns = {}
        self._organic_fx_titles = {}
        self._organic_fx_cards = {}

        # ── source ──
        c_src = self._card(lf, "Source")
        self.organic_src_lbl = tk.Label(c_src, text="No sequence loaded",
            font=FSM, bg=S, fg=G, anchor="w", wraplength=340, justify="left")
        self.organic_src_lbl.pack(fill="x", pady=(0, 6))
        _lrow = tk.Frame(c_src, bg=S); _lrow.pack(fill="x")
        _lrow.columnconfigure(0, weight=3); _lrow.columnconfigure(1, weight=2)
        _b = self._mkbtn(_lrow, "Load Sequence Folder…",
            self._organic_pick_folder, bg="#0D0D0D", fg=W)
        tk.Label.configure(_b._lbl, width=0, pady=6)
        _b.grid(row=0, column=0, sticky="ew", padx=(0, 2))
        # A movie too: Expansion Studio's MOV output is an HDR10 movie,
        # and this is the only way to bring that in.
        _bm = self._mkbtn(_lrow, "Load Movie…",
            self._organic_pick_movie, bg="#0D0D0D", fg=W)
