    def _demo_show(self):
        # Close existing overlay if any
        if hasattr(self, '_demo_overlay') and self._demo_overlay:
            try: self._demo_overlay.destroy()
            except Exception: pass
        if hasattr(self, '_demo_highlight') and self._demo_highlight:
            try: self._demo_highlight.destroy()
            except Exception: pass

        steps = self._demo_steps()
        if self._demo_step >= len(steps):
            self._demo_step = 0
            return

        step = steps[self._demo_step]
        n    = len(steps)
        i    = self._demo_step

        # Switch to the correct tab
        if step.get("tab"):
            self.show(step["tab"])
            self.update_idletasks()

        # ── Overlay panel ─────────────────────────────────────────────
        ov = tk.Toplevel(self)
        ov.overrideredirect(True)
        ov.configure(bg=S)
        ov.attributes("-topmost", True)
        self._demo_overlay = ov

        # Highlight target widget
        self._demo_highlight_widget(step)

        # Position overlay near highlighted widget or centre
        target = self._demo_get_widget(step)
        self.update_idletasks()

        OW, OH = 380, 260
        if target:
            try:
                tx = target.winfo_rootx()
                ty = target.winfo_rooty()
                tw = target.winfo_width()
                th = target.winfo_height()
                arrow = step.get("arrow", "e")
                if arrow == "w":
                    ox = tx + tw + 12
                    oy = ty + th//2 - OH//2
                elif arrow == "e":
                    ox = tx - OW - 12
                    oy = ty + th//2 - OH//2
                elif arrow == "n":
                    ox = tx + tw//2 - OW//2
                    oy = ty + th + 12
                else:
                    ox = tx + tw//2 - OW//2
                    oy = ty - OH - 12
            except Exception:
                ox = self.winfo_rootx() + self.winfo_width()//2 - OW//2
                oy = self.winfo_rooty() + self.winfo_height()//2 - OH//2
        else:
            ox = self.winfo_rootx() + self.winfo_width()//2 - OW//2
            oy = self.winfo_rooty() + self.winfo_height()//2 - OH//2

        # Clamp to screen
        sw = self.winfo_screenwidth()
        sh = self.winfo_screenheight()
        ox = max(8, min(sw - OW - 8, ox))
        oy = max(8, min(sh - OH - 8, oy))
        ov.geometry(f"{OW}x{OH}+{ox}+{oy}")

        # Step indicator
        tk.Label(ov, text=f"Step {i+1} of {n}",
                 font=FM, bg=BD, fg=G,
                 anchor="w").pack(fill="x", padx=0, pady=0, ipady=3,
                                  ipadx=10)

        # Title
        tk.Label(ov, text=step["title"],
                 font=("Futura", 13, "bold"),
                 bg=S, fg=W, anchor="w",
                 wraplength=OW-24).pack(anchor="w", padx=12, pady=(10, 2))

        # Body
        tk.Label(ov, text=step["body"],
                 font=FM, bg=S, fg="#AAAAAA",
                 justify="left", anchor="nw",
                 wraplength=OW-24).pack(anchor="w", padx=12, pady=(2, 8),
                                        fill="both", expand=True)

        # Progress bar
        prog_f = tk.Frame(ov, bg=BD, height=3)
        prog_f.pack(fill="x")
        frac = (i + 1) / n
        prog_fill = tk.Frame(prog_f, bg=R, height=3)
        prog_fill.place(x=0, y=0, relwidth=frac, height=3)

        # Buttons
        btn_row = tk.Frame(ov, bg=S)
        btn_row.pack(fill="x", padx=12, pady=(6, 10))

        skip = self._mkbtn(btn_row, "Skip", self._demo_end, bg="#0D0D0D", fg=G)
        tk.Label.configure(skip._lbl, width=0, pady=5, padx=10)
        skip.pack(side="left")

        if i > 0:
            prev = self._mkbtn(btn_row, "← Prev",
                lambda: self._demo_nav(-1), bg="#0D0D0D", fg=W)
            tk.Label.configure(prev._lbl, width=0, pady=5, padx=10)
            prev.pack(side="left", padx=(6, 0))

        lbl = "Finish ✓" if i == n - 1 else "Next →"
        nxt = self._mkbtn(btn_row, lbl,
            lambda: self._demo_nav(1), bg="#1A0808", fg="#CC4444")
        tk.Label.configure(nxt._lbl, width=0, pady=5, padx=12)
        nxt.pack(side="right")

    def _demo_nav(self, delta):
        self._demo_step += delta
        steps = self._demo_steps()
        if self._demo_step >= len(steps):
            self._demo_end()
        else:
            self._demo_step = max(0, self._demo_step)
            self._demo_show()

    def _demo_end(self):
        for attr in ('_demo_overlay', '_demo_highlight'):
            w = getattr(self, attr, None)
            if w:
                try: w.destroy()
                except Exception: pass
            setattr(self, attr, None)
        self._demo_save_completed()
        # After demo, default to SAM 3
        self.after(300, lambda: self.show("sam"))

    def _demo_highlight_widget(self, step):
        """Draw a bright red highlight border around the target widget."""
        self._demo_highlight = None
        target = self._demo_get_widget(step)
        if not target: return
        try:
            self.update_idletasks()
            x = target.winfo_rootx() - self.winfo_rootx() - 3
            y = target.winfo_rooty() - self.winfo_rooty() - 3
            w = target.winfo_width()  + 6
            h = target.winfo_height() + 6
            hl = tk.Frame(self, bg="#CC4444",
                          highlightthickness=0, bd=0)
            hl.place(x=x, y=y, width=w, height=h)
            hl.lower()   # behind widgets but visible as outline
            # Cut out interior so it's just a border
            inner = tk.Frame(hl, bg=S, bd=0)
            inner.place(x=2, y=2, width=w-4, height=h-4)
            inner.lower()
            self._demo_highlight = hl
        except Exception:
            pass

    def _demo_get_widget(self, step):
        """Map step widget key to an actual tk widget."""
        key = step.get("widget")
        if not key: return None
        mapping = {
            "tab_btns":        self.winfo_children()[0] if self.winfo_children() else None,
            "setup_components": getattr(self, "_setup_comp_frame", None),
            "hf_card":         getattr(self, "_hf_token_entry", None),
            "setup_manual":    getattr(self, "_setup_manual_text", None),
            "exr_toggle":      getattr(self, "exr_f_to_exr", None),
            "exr_cm":          getattr(self, "exr_csp_var", None),
            "exr_hist":        getattr(self, "exr_hist_canvas", None),
            "rife_timeline":   getattr(self, "rife_frame_cb", None),
            "rife_wipe_diff":  getattr(self, "rife_wipe_btn", None),
            "rife_canvas":     getattr(self, "rife_wipe_canvas", None),
            "rife_presets":    getattr(self, "_rife_preset_btn", None),
            "rife_motion_mask": getattr(self, "_mt_preview_chk", None),
            "rife_adv_settings": getattr(self, "_rife_adv_btn", None),
            "sam_server":      getattr(self, "_sam_status_dot", None),
            "sam_prompts":     getattr(self, "sam_prompt_frame", None),
            "sam_canvas":      getattr(self, "sam_canvas", None),
            "rife_output":     getattr(self, "rife_jump", None),
            "exr_output":      getattr(self, "exr_jump", None),
            "sam_output":      getattr(self, "sam_jump", None),
        }
        # For tab_btns highlight the whole tab bar area
        if key == "tab_btns":
            btns = list(self.tab_btns.values())
            return btns[0] if btns else None
        # For exr_cm find the parent frame of the combobox
        if key == "exr_cm":
            v = getattr(self, "exr_csp_var", None)
            if v:
                try: return v.master.master  # inner → card inner → card
                except Exception: pass
            return None
        w = mapping.get(key)
        if w and hasattr(w, "master"):
            return w
        return None


