    # ── TAB: ADW-CURVELOCK ──────────────────────────────────────────────
    def _tab_curve(self):
        p = self._frame("curve")
        self.curve_folder = None
        self.curve_frames = []
        # Analyse Motion + optional Cache to RAM (same feature as
        # ADW-Paint/AreaLock): scores the whole sequence's motion
        # cheaply so the timeline can be tinted by instability, with an
        # opt-in checkbox to also pre-decode the current range into
        # memory for instant playback.
        self.curve_ram_cache = {}
        self.curve_motion = {}
        self._curve_ram_building = False
        self._curve_ram_cancel = False
        self._curve_analysing = False
        self._curve_analyse_cancel = False
        self.curve_cache_to_ram_var = tk.BooleanVar(value=False)
        self.curve_motion_tint_var = tk.BooleanVar(value=True)
        _CURVE_COLORS = ["#CC4444","#44CC88","#4488CC","#CC8844","#CC44CC","#44CCCC"]
        self._curve_colors = _CURVE_COLORS
        _CURVE_DEFAULTS = {
            "points": None,        # Nx2 array, smoothed/straightened result
            "points_raw": None,    # Nx2 array, evenly-spaced but unsmoothed
            "paint_smooth": 35,    # 0-100: moving-average jitter removal only,
                                     # tracks the curve's own arc regardless of value
            "paint_straightness": 0,  # 0-100: separate blend toward a full
                                     # straight-line fit, independent of smoothness
            "search_dist": 15, "smooth_along": 5,
            "feather": 30, "max_corr": 20, "strength": 100,
            "end_falloff": 0,      # px, ramps correction to zero at each
                                     # tip over this arc-length distance --
                                     # 0 disables it (hard cutoff, as before)
            "enabled": True, "anim_range": None, "anim_fade": 3, "_prev_s": None,
            "visible": True,       # show this curve's line/overlay on canvas
            "paint_frame_idx": None,  # frame index this curve was traced on
            "brush_size": 24,       # px diameter of the search-mask brush
            "mask_opacity": 35,     # 0-100, translucency of the mask overlay
            "brush_path": None,     # raw centerline as painted, pre-snap
                                     # (kept separate from points_raw, which
                                     # holds the snapped/refined result)
            "keyframes": None,      # {frame_idx: raw_points_array} -- every
                                     # frame this curve has been traced on,
                                     # used to interpolate the actual edge
                                     # shape between them on frames in between
            "search_bias_keyframes": None,  # {frame_idx: bias -100..100}
                                     # which side of the curve the search
                                     # favors -- set automatically whenever
                                     # the slider is adjusted on some frame,
                                     # linearly interpolated/held between
                                     # entries like any other keyframed
                                     # value; 0 (symmetric) if never touched
        }
        self._curve_defaults = _CURVE_DEFAULTS
        self.curve_list = [{"name": "C1",
            "color": _CURVE_COLORS[0], **_CURVE_DEFAULTS}]
        self.curve_active = 0
        self.curve_img_tk   = None
        self.curve_img_base = None
        self.curve_scale    = 1.0
        self._curve_zoom    = 1.0
        self._curve_pan_x   = 0
        self._curve_pan_y   = 0
        self._curve_paint_pts = None
        self._curve_cancel  = False
        self._curve_proc_running = False
        self.curve_mode = "edit"            # "edit", "wipe", or "diff"
        self._curve_loading = False   # guards against re-entrant save-current
                                       # while load_current is setting vars
        self.curve_diff_mult = 8
        self._curve_wipe_t = 0.5
        self._curve_wipe_corrected_base = None
        self._curve_wipe_drag_start = None
        self.curve_wipe_tk = None
        self._curve_preview_overlay = None  # (target_pts, detected_pts) for current frame
        self._curve_show_search_band = False  # transient, shown while adjusting Search Dist
        self._curve_nudge_mode = False
        self._curve_nudge_origin = None
        self._curve_nudge_pos = None

        lf, rf = self._two_col(p, "", "", lw=500)

        _curve_btn_strip = tk.Frame(lf, bg=BG)
        _curve_btn_strip.pack(side="bottom", fill="x")

        _curve_cv  = tk.Canvas(lf, bg=BG, highlightthickness=0)
        _curve_vsb = self._mk_scrollbar(lf, _curve_cv, width=10)
        _curve_vsb.pack(side="right", fill="y")
        _curve_cv.pack(side="left", fill="both", expand=True)

        _curve_inner = tk.Frame(_curve_cv, bg=BG)
        _curve_cv_win = _curve_cv.create_window((0,0), window=_curve_inner, anchor="nw")

        def _curve_cv_resize(e):
            _curve_cv.itemconfig(_curve_cv_win, width=e.width)
        def _curve_cv_scroll_update(e):
            _curve_cv.configure(scrollregion=_curve_cv.bbox("all"))
        _curve_cv.bind("<Configure>", _curve_cv_resize)
        _curve_inner.bind("<Configure>", _curve_cv_scroll_update)

        def _curve_mouse_scroll(e):
            wx=_curve_cv.winfo_rootx(); wy=_curve_cv.winfo_rooty()
            ww=_curve_cv.winfo_width(); wh=_curve_cv.winfo_height()
            if wx <= e.x_root <= wx+ww and wy <= e.y_root <= wy+wh:
                _curve_cv.yview_scroll(int(-1*(e.delta/120)), "units")
        _curve_cv.bind_all("<MouseWheel>", _curve_mouse_scroll, add="+")

        lf = _curve_inner

        # ── Title row ───────────────────────────────────────────────────
        hdr = tk.Frame(lf, bg=BG)
        hdr.pack(fill="x", padx=16, pady=(14, 0))
        tk.Label(hdr, text="ADW-CurveLock", font=("Futura", 14),
                 bg=BG, fg=W).pack(side="left")
        _curve_hdr_info = tk.Label(hdr, text=" ⓘ", font=("Futura", 13),
            bg=BG, fg="#555555", cursor="hand2")
        _curve_hdr_info.pack(side="left", padx=(4,0))

        self.curve_path_lbl = self._path_bar(lf)
        c = self._card(lf, "Input Sequence Folder")
        pf, self.curve_lbl = self._picker(c, "📁  Click to select sequence folder")
        pf.bind("<Button-1>", self._curve_pick)
        self.curve_lbl.bind("<Button-1>", self._curve_pick)
        self.curve_info = tk.Label(c, text="", font=FSM, bg=S, fg=G, anchor="w")
        self.curve_info.pack(anchor="w", pady=(3, 0))

        ccache = self._card(lf, "Analyse Motion")
        self.curve_cache_btn = self._mkbtn(ccache, "\u2295  Analyse Motion",
            self._curve_analyse_motion_toggle, bg="#0D0D0D", fg=W)
        tk.Label.configure(self.curve_cache_btn._lbl, width=0, pady=8)
        self.curve_cache_btn.pack(fill="x")
        tk.Checkbutton(ccache, text="Cache to RAM (also pre-decode "
            "the current range for instant playback)",
            variable=self.curve_cache_to_ram_var, bg=S, fg=W,
            activebackground=S, activeforeground=W, selectcolor=R,
            font=FSM, highlightthickness=0, bd=0).pack(anchor="w",
                pady=(4, 0))
        _ccrow = tk.Frame(ccache, bg=S); _ccrow.pack(fill="x", pady=(4, 0))
        self.curve_cache_info = tk.Label(_ccrow, text="Not analysed",
            font=FSM, bg=S, fg=G, anchor="w")
        self.curve_cache_info.pack(side="left")
        self.curve_cache_clear_btn = self._mkbtn(_ccrow, "Clear",
            self._curve_cache_ram_clear, bg="#0D0D0D", fg=W)
        tk.Label.configure(self.curve_cache_clear_btn._lbl, width=0,
                           pady=4, padx=10)
        self.curve_cache_clear_btn.pack(side="right")
        tk.Checkbutton(ccache, text="Tint timeline by motion "
            "(red \u2192 orange \u2192 yellow)",
            variable=self.curve_motion_tint_var, bg=S, fg=W,
            activebackground=S, activeforeground=W, selectcolor=R,
            font=FSM, highlightthickness=0, bd=0,
            command=lambda: (hasattr(self, "curve_frame_cb")
                and self.curve_frame_cb.refresh())).pack(anchor="w",
                pady=(4, 0))

        # ── Tooltip helper ──────────────────────────────────────────────
        def _info_popup(tip):
            def _attach(widget):
                _pop = [None]
                def _show(e):
                    if _pop[0]:
                        try: _pop[0].destroy()
                        except: pass
                    pop = tk.Toplevel(self)
                    pop.overrideredirect(True)
                    pop.configure(bg=BD)
                    pop.attributes("-topmost", True)
                    tk.Label(pop, text=tip, font=FM, bg=BD, fg=W,
                             justify="left", padx=12, pady=10,
                             wraplength=300).pack()
                    pop.update_idletasks()
                    x = min(e.x_root+4, self.winfo_screenwidth()-pop.winfo_width()-8)
                    pop.geometry(f"+{x}+{e.y_root+16}")
                    _pop[0] = pop
                def _hide(e=None):
                    if _pop[0]:
                        try: _pop[0].destroy()
                        except: pass
                        _pop[0] = None
                widget.bind("<Enter>", _show)
                widget.bind("<Leave>", _hide)
                widget.bind("<Button-1>", _hide)
            return _attach

        _info_popup(
            "Paint a curve along where the edge SHOULD be, instead of\n"
            "drawing a search box and hoping an algorithm finds it.\n\n"
            "Each frame, the software searches perpendicular to your\n"
            "painted curve for the actual edge nearby, then the\n"
            "Strength slider blends the image toward that painted\n"
            "shape — 0% leaves the frame untouched, 100% pulls the\n"
            "edge fully onto your curve.\n\n"
            "Unlike LineLock/EdgeLock there's no inferred target — you\n"
            "are the target, so this works for curves as well as\n"
            "straight lines. Curve Smoothness removes hand-tremor\n"
            "wobble while tracking whatever shape you drew; Curve\n"
            "Straightness separately blends toward a true straight\n"
            "line, so a genuinely curved edge can be de-jittered\n"
            "without being flattened. Both apply once, at paint time —\n"
            "the resulting shape is then the FIXED target every frame\n"
            "gets pulled toward, which is what actually removes\n"
            "frame-to-frame wobble; smoothing each frame's detection\n"
            "separately wouldn't, since they'd still drift apart.\n\n"
            "Two lines on the canvas, on purpose: the solid one is\n"
            "that fixed, smoothed target (what the output becomes);\n"
            "the dashed yellow one is the live per-frame detection —\n"
            "where the real, still-wobbly edge sits on THIS frame\n"
            "before correction. They're meant to differ; that gap is\n"
            "the wobble being removed.\n\n"
            "1. Paint a curve over the wobbling edge\n"
            "2. Step through frames, watch Wipe/Diff\n"
            "3. Dial in Strength, then Run on the sequence"
        )(_curve_hdr_info)

        # ── Curve tabs ──────────────────────────────────────────────────
        _curve_outer = tk.Frame(lf, bg=S,
            highlightthickness=1, highlightbackground=BD)
        _curve_outer.pack(fill="x", padx=16, pady=(4,0))

        _ctab_bar = tk.Frame(_curve_outer, bg=BG)
        _ctab_bar.pack(fill="x")
        self._curve_tab_btns = []

        def _curve_rebuild_tabs():
            for w in list(_ctab_bar.winfo_children()): w.destroy()
            self._curve_tab_btns = []
            cur_idx = self.curve_frame_cb.current() if hasattr(self,"curve_frame_cb") else -1
            if cur_idx is None: cur_idx = -1
            for ci, cv_ in enumerate(self.curve_list):
                is_active = (ci == self.curve_active)
                enabled = cv_.get("enabled", True)
                rng = cv_.get("anim_range")
                active_now = self._curve_active_at(cv_, cur_idx) if cur_idx>=0 else enabled
                col = cv_["color"]
                item_bg = S if is_active else BG
                if not enabled:
                    dot_sym, dot_col = "○", "#444444"
                elif rng is not None and not active_now:
                    dot_sym, dot_col = "◐", "#777733"
                else:
                    dot_sym, dot_col = "●", col
                _item = tk.Frame(_ctab_bar, bg=item_bg)
                _item.pack(side="left")
                _dot = tk.Label(_item, text=dot_sym, font=FSM,
                    bg=item_bg, fg=dot_col, pady=4)
                _dot.pack(side="left", padx=(8,2))
                _info_popup(
                    "● active right now   ◐ animated, off on this frame\n"
                    "○ off\n\n"
                    "Status readout for this curve — use the E and O\n"
                    "tickboxes above (Paint Curve row) to change it,\n"
                    "after selecting this curve's tab."
                )(_dot)
                _name = cv_["name"]
                if not enabled: _name += "  (off)"
                elif rng is not None: _name += f"  [{rng[0]+1}\u2013{rng[1]+1 if rng[1] is not None else '…'}]"
                _tb = tk.Label(_item, text=_name, font=FSM,
                    bg=item_bg,
                    fg=(col if is_active else "#888888") if enabled else "#444444",
                    pady=4, cursor="hand2", relief="flat")
                _tb.pack(side="left", padx=(2,10))
                _tb.bind("<Button-1>", lambda e,i=ci: _curve_switch(i))
                _tb.bind("<Double-Button-1>", lambda e,i=ci: _curve_rename(i))
                _tb.bind("<Button-3>", lambda e,i=ci: _curve_menu(e,i))
                _tb.bind("<Button-2>", lambda e,i=ci: _curve_menu(e,i))
                self._curve_tab_btns.append(_tb)
            _add = tk.Label(_ctab_bar, text=" + ", font=("Futura", 16, "bold"),
                bg=BG, fg="#CC4444", padx=8, pady=3, cursor="hand2")
            _add.pack(side="left")
            _add.bind("<Button-1>", lambda e: _curve_add())
            _add.bind("<Enter>", lambda e: _add.configure(fg="#FF4444"))
            _add.bind("<Leave>", lambda e: _add.configure(fg="#CC4444"))
        self._curve_rebuild_tabs_fn = _curve_rebuild_tabs

        def _curve_enabled_changed():
            if getattr(self, "_curve_loading", False): return
            i = self.curve_active
            cv_ = self.curve_list[i]
            val = self.curve_enabled_var.get()
            cv_["enabled"] = val
            _curve_rebuild_tabs()
            self._curve_preview(silent=True)
            if self.curve_mode in ("wipe","diff"):
                self._curve_recompute_wipe(); self._curve_redraw()
            self.log(self.curve_log_txt,
                f"{cv_['name']}: {'enabled' if val else 'disabled'}", "dim")

        def _curve_visible_changed():
            if getattr(self, "_curve_loading", False): return
            i = self.curve_active
            cv_ = self.curve_list[i]
            val = self.curve_visible_var.get()
            cv_["visible"] = val
            _curve_rebuild_tabs()
            self._curve_redraw()
            self.log(self.curve_log_txt,
                f"{cv_['name']}: overlay {'shown' if val else 'hidden'}", "dim")

        def _curve_save_current():
            cur = self.curve_active
            cv_ = self.curve_list[cur]
            if hasattr(self, "curve_search_var"):
                cv_["search_dist"]   = self.curve_search_var.get()
                cv_["search_dir"]    = self.curve_searchdir_var.get()
                cv_["smooth_along"]  = self.curve_smoothalong_var.get()
                cv_["feather"]       = self.curve_feather_var.get()
                cv_["max_corr"]      = self.curve_maxcorr_var.get()
                cv_["strength"]      = self.curve_strength_var.get()
            if hasattr(self, "curve_endfalloff_var"):
                cv_["end_falloff"]   = self.curve_endfalloff_var.get()
            if hasattr(self, "curve_fade_var"):
                cv_["anim_fade"]     = self.curve_fade_var.get()
            if hasattr(self, "curve_paintsmooth_var"):
                cv_["paint_smooth"]  = self.curve_paintsmooth_var.get()
            if hasattr(self, "curve_straightness_var"):
                cv_["paint_straightness"] = self.curve_straightness_var.get()
            if hasattr(self, "curve_brushsize_var"):
                cv_["brush_size"]    = self.curve_brushsize_var.get()
                cv_["mask_opacity"]  = self.curve_maskopacity_var.get()
            if hasattr(self, "curve_enabled_var"):
                cv_["enabled"]       = self.curve_enabled_var.get()
                cv_["visible"]       = self.curve_visible_var.get()

        def _curve_load_current():
            self._curve_loading = True
            try:
                cv_ = self.curve_list[self.curve_active]
                if hasattr(self, "curve_search_var"):
                    self.curve_search_var.set(cv_.get("search_dist",15))
                    self.curve_searchdir_var.set(cv_.get("search_dir",0))
                    if hasattr(self, "_curve_dir_sync_ui_fn"):
                        self._curve_dir_sync_ui_fn()
                    self.curve_smoothalong_var.set(cv_.get("smooth_along",5))
                    self.curve_feather_var.set(cv_.get("feather",30))
                    self.curve_maxcorr_var.set(cv_.get("max_corr",20))
                    self.curve_strength_var.set(cv_.get("strength",100))
                if hasattr(self, "curve_endfalloff_var"):
                    self.curve_endfalloff_var.set(cv_.get("end_falloff",0))
                if hasattr(self, "curve_fade_var"):
                    self.curve_fade_var.set(cv_.get("anim_fade",3))
                if hasattr(self, "curve_paintsmooth_var"):
                    self.curve_paintsmooth_var.set(cv_.get("paint_smooth",35))
                if hasattr(self, "curve_straightness_var"):
                    self.curve_straightness_var.set(cv_.get("paint_straightness",0))
                if hasattr(self, "curve_brushsize_var"):
                    self.curve_brushsize_var.set(cv_.get("brush_size",24))
                    self.curve_maskopacity_var.set(cv_.get("mask_opacity",35))
                if hasattr(self, "curve_enabled_var"):
                    self.curve_enabled_var.set(cv_.get("enabled",True))
                    self.curve_visible_var.set(cv_.get("visible",True))
                if hasattr(self, "_curve_bias_sync_ui_fn"):
                    self._curve_bias_sync_ui_fn()
            finally:
                self._curve_loading = False
        self._curve_load_current_fn = _curve_load_current

        def _curve_switch(i):
            _curve_save_current()
            self.curve_active = i
            _curve_load_current()
            _curve_rebuild_tabs()
            _curve_update_len_lbl()
            _curve_update_anim_lbl()
            self._curve_preview(silent=True)

        def _curve_add():
            idx = len(self.curve_list)
            col = self._curve_colors[idx % len(self._curve_colors)]
            self.curve_list.append({"name": f"C{idx+1}",
                "color": col, **self._curve_defaults})
            _curve_switch(idx)

        def _curve_menu_toggle_enabled(i):
            cv_ = self.curve_list[i]
            cv_["enabled"] = not cv_.get("enabled", True)
            if i == self.curve_active and hasattr(self, "curve_enabled_var"):
                self._curve_loading = True
                try:
                    self.curve_enabled_var.set(cv_["enabled"])
                finally:
                    self._curve_loading = False
                self._curve_preview(silent=True)
                if self.curve_mode in ("wipe","diff"):
                    self._curve_recompute_wipe(); self._curve_redraw()
            _curve_rebuild_tabs()
            self.log(self.curve_log_txt,
                f"{cv_['name']}: {'enabled' if cv_['enabled'] else 'disabled'}", "dim")

        def _curve_menu(e, i):
            m = tk.Menu(self, tearoff=0, bg=S, fg=W,
                activebackground=BD, activeforeground=W, font=FM)
            _en = self.curve_list[i].get("enabled", True)
            m.add_command(label="Disable" if _en else "Enable",
                command=lambda: _curve_menu_toggle_enabled(i))
            m.add_command(label="Rename…", command=lambda: _curve_rename(i))
            if len(self.curve_list) > 1:
                m.add_command(label="Delete", command=lambda: _curve_remove(i))
            try: m.tk_popup(e.x_root, e.y_root)
            finally: m.grab_release()

        def _curve_rename(i):
            import tkinter.simpledialog as sd
            name = sd.askstring("Rename", "Curve name:",
                initialvalue=self.curve_list[i]["name"], parent=self)
            if name:
                self.curve_list[i]["name"] = name
                _curve_rebuild_tabs()

        def _curve_remove(i):
            self.curve_list.pop(i)
            self.curve_active = min(self.curve_active, len(self.curve_list)-1)
            _curve_load_current()
            _curve_rebuild_tabs()
            self._curve_redraw()

        _curve_rebuild_tabs()

        # ── Paint controls ─────────────────────────────────────────────
        _paint_row = tk.Frame(_curve_outer, bg=S)
        _paint_row.pack(fill="x", padx=10, pady=(8,4))
        self.curve_paint_btn = self._mkbtn(_paint_row, "Paint Curve",
            lambda: self._curve_set_paint_mode(True), bg="#1A3A1A", fg="#66CC66")
        tk.Label.configure(self.curve_paint_btn._lbl, width=14, pady=6)
        self.curve_paint_btn.pack(side="left", padx=(0,6))
        self.curve_nudge_btn = self._mkbtn(_paint_row, "Nudge to Fix",
            lambda: self._curve_set_nudge_mode(True), bg="#2A2A14", fg="#CCAA44")
        tk.Label.configure(self.curve_nudge_btn._lbl, width=12, pady=6)
        self.curve_nudge_btn.pack(side="left", padx=(0,6))
        _curve_nudge_info = tk.Label(_paint_row, text="ⓘ", font=FSM, bg=S,
            fg="#555555", cursor="hand2")
        _curve_nudge_info.pack(side="left", padx=(0,6))
        _info_popup(
            "When tracking has drifted on this frame: drag the\n"
            "crosshair from where the curve currently sits onto\n"
            "where it should actually be — doesn't need to be exact,\n"
            "the whole curve shifts with you as a preview. Release to\n"
            "lock that shifted shape in as a fresh trace keyframe on\n"
            "this frame, so tracking has a solid anchor again --\n"
            "much quicker than repainting the whole curve from scratch."
        )(_curve_nudge_info)
        _clear_btn = self._mkbtn(_paint_row, "Clear",
            lambda: self._curve_clear(), bg="#0D0D0D", fg=G)
        tk.Label.configure(_clear_btn._lbl, width=8, pady=6)
        _clear_btn.pack(side="left")
        _clear_info = tk.Label(_paint_row, text="ⓘ", font=FSM, bg=S,
            fg="#555555", cursor="hand2")
        _clear_info.pack(side="left", padx=(2,0))
        _info_popup(
            "Removes only the trace keyframe at the frame you're\n"
            "currently on, so you can repaint just that one. Other\n"
            "keyframes elsewhere on this curve are untouched."
        )(_clear_info)

        self.curve_enabled_var = tk.BooleanVar(value=True)
        _e_cb = tk.Checkbutton(_paint_row, text="E", variable=self.curve_enabled_var,
            command=lambda: _curve_enabled_changed(),
            bg=S, fg=W, selectcolor="#222222",
            activebackground=S, activeforeground=W,
            font=(FSM[0], FSM[1], "bold"), bd=0, padx=1, highlightthickness=0)
        _e_cb.pack(side="left", padx=(12,1))
        _info_popup(
            "Turn this curve's correction fully on or off, regardless\n"
            "of the active range — the quickest way to A/B it: toggle\n"
            "this and watch Wipe/Diff to confirm it's actually making\n"
            "a positive change."
        )(_e_cb)

        self.curve_visible_var = tk.BooleanVar(value=True)
        _o_cb = tk.Checkbutton(_paint_row, text="O", variable=self.curve_visible_var,
            command=lambda: _curve_visible_changed(),
            bg=S, fg=W, selectcolor="#222222",
            activebackground=S, activeforeground=W,
            font=(FSM[0], FSM[1], "bold"), bd=0, padx=1, highlightthickness=0)
        _o_cb.pack(side="left", padx=(0,8))
        _info_popup(
            "Show or hide this curve's painted line, detected overlay,\n"
            "and brush mask on the canvas. Purely visual — doesn't\n"
            "affect whether its correction runs."
        )(_o_cb)

        self.curve_autotrace_var = tk.BooleanVar(value=True)
        tk.Checkbutton(_paint_row, text="Auto-trace to edge",
            variable=self.curve_autotrace_var,
            bg=S, fg=W, selectcolor="#222222",
            activebackground=S, activeforeground=W,
            font=FSM, bd=0).pack(side="left", padx=(14,0))
        _autotrace_info = tk.Label(_paint_row, text="ⓘ", font=FSM, bg=S,
            fg="#555555", cursor="hand2")
        _autotrace_info.pack(side="left", padx=(4,0))
        _info_popup(
            "On — draw with a wide brush rather than hand-tracing\n"
            "precisely. What matters is roughly the right place and,\n"
            "more importantly, the right direction; the tool snaps each\n"
            "point to the actual nearby edge, but only searches inside\n"
            "the brush stroke's own width (shown as a translucent\n"
            "overlay) — a competing edge just outside it physically\n"
            "can't be picked, no matter how much stronger it is.\n\n"
            "Off — your stroke is used exactly as drawn, no snapping.\n"
            "Use this if you're deliberately defining a target shape\n"
            "that doesn't follow an existing edge."
        )(_autotrace_info)

        _brush_row = tk.Frame(_curve_outer, bg=S)
        _brush_row.pack(fill="x", padx=10, pady=(2,4))

        def _mini_slider(parent, label, var, from_, to, res, fmt, width_lbl=11):
            tk.Label(parent, text=label, font=FSM, bg=S, fg=G,
                     width=width_lbl, anchor="w").pack(side="left")
            _val_lbl = tk.Label(parent, text=fmt(var.get()), font=FM, bg=S, fg=W,
                                 width=5, anchor="e")
            _val_lbl.pack(side="right")
            def _upd(*_): _val_lbl.configure(text=fmt(var.get()))
            var.trace_add("write", _upd)
            tk.Scale(parent, variable=var, from_=from_, to=to, resolution=res,
                     orient="horizontal", bg=S, fg=W, troughcolor=BD,
                     highlightthickness=0, bd=0, showvalue=False,
                     activebackground=R).pack(side="left", fill="x",
                     expand=True, padx=(6,8))

        self.curve_brushsize_var = tk.IntVar(value=24)
        _mini_slider(_brush_row, "Brush Size", self.curve_brushsize_var,
                     4, 80, 2, lambda v: f"{int(v)}px")
        self.curve_maskopacity_var = tk.IntVar(value=35)
        _mini_slider(_brush_row, "Mask Opacity", self.curve_maskopacity_var,
                     0, 100, 5, lambda v: f"{int(v)}%")

        def _curve_brushparams_changed(*_):
            if getattr(self, "_curve_loading", False): return
            cv_ = self.curve_list[self.curve_active]
            cv_["brush_size"] = self.curve_brushsize_var.get()
            cv_["mask_opacity"] = self.curve_maskopacity_var.get()
            self._curve_redraw()
        self.curve_brushsize_var.trace_add("write", _curve_brushparams_changed)
        self.curve_maskopacity_var.trace_add("write", _curve_brushparams_changed)

        self.curve_len_lbl = tk.Label(_curve_outer, text="No curve painted yet.",
            font=FM, bg=S, fg=G, anchor="w")
        self.curve_len_lbl.pack(anchor="w", padx=10, pady=(0,8))

        def _curve_update_len_lbl():
            cv_ = self.curve_list[self.curve_active]
            pts = cv_.get("points")
            if pts is not None and len(pts) >= 2:
                import numpy as np
                length = float(np.sum(np.hypot(*np.diff(pts, axis=0).T)))
                self.curve_len_lbl.configure(
                    text=f"Curve: {len(pts)} points, {length:.0f} px long", fg=GR)
            else:
                self.curve_len_lbl.configure(text="No curve painted yet.", fg=G)
        self._curve_update_len_lbl_fn = _curve_update_len_lbl

        _smooth_row = tk.Frame(_curve_outer, bg=S)
        _smooth_row.pack(fill="x", padx=10, pady=(0,2))
        tk.Label(_smooth_row, text="Curve Smoothness", font=FSM, bg=S, fg=G,
                 width=14, anchor="w").pack(side="left")
        self.curve_paintsmooth_var = tk.IntVar(value=35)
        _ps_val_lbl = tk.Label(_smooth_row, text="35%", font=FM, bg=S, fg=W,
                                width=5, anchor="e")
        _ps_val_lbl.pack(side="right")
        _ps_info = tk.Label(_smooth_row, text="ⓘ", font=FSM, bg=S,
                             fg="#555555", cursor="hand2")
        _ps_info.pack(side="right", padx=(0,6))
        tk.Scale(_smooth_row, variable=self.curve_paintsmooth_var,
                 from_=0, to=100, resolution=5, orient="horizontal",
                 bg=S, fg=W, troughcolor=BD, highlightthickness=0, bd=0,
                 showvalue=False, activebackground=R).pack(
                 side="left", fill="x", expand=True, padx=(8,8))
        _info_popup(
            "Hand-drawn curves always have a bit of mouse tremor. This\n"
            "removes that fine wobble with a moving-average pass along\n"
            "the curve's own arc — it tracks whatever shape you drew,\n"
            "including a genuine curve (wheel arch, fender line), and\n"
            "never pulls it toward a straight line by itself.\n\n"
            "For that, see Curve Straightness below — the two are\n"
            "independent now, so a deliberately curved edge can be\n"
            "fully de-jittered without being flattened.\n\n"
            "Re-applies immediately when changed — no need to repaint."
        )(_ps_info)

        _straight_row = tk.Frame(_curve_outer, bg=S)
        _straight_row.pack(fill="x", padx=10, pady=(0,8))
        tk.Label(_straight_row, text="Curve Straightness", font=FSM, bg=S, fg=G,
                 width=14, anchor="w").pack(side="left")
        self.curve_straightness_var = tk.IntVar(value=0)
        _st_val_lbl = tk.Label(_straight_row, text="0%", font=FM, bg=S, fg=W,
                                width=5, anchor="e")
        _st_val_lbl.pack(side="right")
        _st_info = tk.Label(_straight_row, text="ⓘ", font=FSM, bg=S,
                             fg="#555555", cursor="hand2")
        _st_info.pack(side="right", padx=(0,6))
        tk.Scale(_straight_row, variable=self.curve_straightness_var,
                 from_=0, to=100, resolution=5, orient="horizontal",
                 bg=S, fg=W, troughcolor=BD, highlightthickness=0, bd=0,
                 showvalue=False, activebackground=R).pack(
                 side="left", fill="x", expand=True, padx=(8,8))
        _info_popup(
            "Separate from Curve Smoothness above — this blends the\n"
            "smoothed shape toward a full straight-line least-squares\n"
            "fit through what you painted.\n\n"
            "0 — keeps the smoothed curve's actual shape.\n\n"
            "100 — treats the stroke as an attempted straight line and\n"
            "snaps fully to it. Use this for body panel lines that\n"
            "should be dead straight even if your hand wasn't.\n\n"
            "Re-applies immediately when changed — no need to repaint."
        )(_st_info)

        def _curve_reapply_shape():
            cv_ = self.curve_list[self.curve_active]
            sm_val = self.curve_paintsmooth_var.get()
            st_val = self.curve_straightness_var.get()
            cv_["paint_smooth"] = sm_val
            cv_["paint_straightness"] = st_val
            if cv_.get("points_raw") is not None:
                cv_["points"] = self._curve_apply_smooth(
                    cv_["points_raw"], sm_val, st_val)
                cv_["_prev_s"] = None
                _curve_update_len_lbl()
                self._curve_preview(silent=True)

        def _curve_paintsmooth_changed(*_):
            if getattr(self, "_curve_loading", False): return
            _ps_val_lbl.configure(text=f"{self.curve_paintsmooth_var.get()}%")
            _curve_reapply_shape()
        self.curve_paintsmooth_var.trace_add("write", _curve_paintsmooth_changed)

        def _curve_straightness_changed(*_):
            if getattr(self, "_curve_loading", False): return
            _st_val_lbl.configure(text=f"{self.curve_straightness_var.get()}%")
            _curve_reapply_shape()
        self.curve_straightness_var.trace_add("write", _curve_straightness_changed)

        _anim_row = tk.Frame(_curve_outer, bg=S)
        _anim_row.pack(fill="x", padx=10, pady=(0,2))
        self.curve_anim_on_btn = self._mkbtn(_anim_row, "Animate On",
            lambda: _curve_animate_on(), bg="#1A2A1A", fg="#66CC88")
        tk.Label.configure(self.curve_anim_on_btn._lbl, width=0, pady=4, padx=8)
        self.curve_anim_on_btn.pack(side="left")
        self.curve_anim_off_btn = self._mkbtn(_anim_row, "Animate Off",
            lambda: _curve_animate_off(), bg="#0D0D0D", fg=G)
        tk.Label.configure(self.curve_anim_off_btn._lbl, width=0, pady=4, padx=8)
        self.curve_anim_off_btn.pack(side="left", padx=(6,0))
        self.curve_anim_lbl = tk.Label(_anim_row, text="Active: all frames",
            font=FM, bg=S, fg=G, anchor="w")
        self.curve_anim_lbl.pack(side="left", padx=(10,0))
        _anim_info = tk.Label(_anim_row, text="ⓘ", font=FSM, bg=S,
            fg="#555555", cursor="hand2")
        _anim_info.pack(side="left", padx=(6,0))
        _info_popup(
            "Step to the frame where this curve should start correcting\n"
            "and click Animate On — that frame becomes a green keyframe\n"
            "on the main timeline below, and frames after it (shown\n"
            "bright red once fully ramped in) get corrected. Painting a\n"
            "fresh curve sets this automatically, at the frame you\n"
            "painted it on.\n\n"
            "Painting a trace keyframe anywhere outside the current\n"
            "active range — earlier OR later — automatically extends\n"
            "the range to cover it. So if you trace the curve in the\n"
            "middle of where you need it first, then step earlier and\n"
            "trace again, the active range stretches back to include\n"
            "that frame too — no need to manually move the on-keyframe.\n\n"
            "Step to a later frame and click Animate Off to set a green\n"
            "off-keyframe there — frames after that (dark red) stop\n"
            "being corrected. Animate On/Off remain there for deliberately\n"
            "repositioning either end by hand.\n\n"
            "The correction doesn't cut in/out instantly at these\n"
            "keyframes — see the Fade parameter below, which ramps it\n"
            "in/out over a few frames instead, shown on the timeline as\n"
            "bright red gradually growing out of dark red around each\n"
            "keyframe."
        )(_anim_info)

        def _curve_update_anim_lbl():
            cv_ = self.curve_list[self.curve_active]
            rng = cv_.get("anim_range")
            if rng is None:
                self.curve_anim_lbl.configure(text="Active: all frames", fg=G)
            elif rng[1] is None:
                self.curve_anim_lbl.configure(
                    text=f"Active: frame {rng[0]+1} onward", fg=GR)
            else:
                self.curve_anim_lbl.configure(
                    text=f"Active: frames {rng[0]+1}\u2013{rng[1]+1}", fg=GR)
            if hasattr(self, "curve_frame_cb"):
                self.curve_frame_cb.refresh()
        self._curve_update_anim_lbl_fn = _curve_update_anim_lbl

        def _curve_animate_on():
            cur_idx = (self.curve_frame_cb.current()
                       if hasattr(self,"curve_frame_cb") else -1)
            if cur_idx is None or cur_idx < 0:
                self.log(self.curve_log_txt,
                    "Load a sequence and step to a frame first.", "err")
                return
            cv_ = self.curve_list[self.curve_active]
            rng = cv_.get("anim_range")
            existing_off = rng[1] if rng is not None else None
            if existing_off is not None and cur_idx > existing_off:
                existing_off = None
                self.log(self.curve_log_txt,
                    f"{cv_['name']}: cleared the off-keyframe — it was "
                    f"before the new on-keyframe", "dim")
            cv_["anim_range"] = (cur_idx, existing_off)
            _curve_update_anim_lbl(); _curve_rebuild_tabs()
            self._curve_recompute_wipe(); self._curve_redraw()
            self.log(self.curve_log_txt,
                f"{cv_['name']}: on-keyframe set at frame {cur_idx+1}", "ok")

        def _curve_animate_off():
            cur_idx = (self.curve_frame_cb.current()
                       if hasattr(self,"curve_frame_cb") else -1)
            if cur_idx is None or cur_idx < 0:
                self.log(self.curve_log_txt,
                    "Load a sequence and step to a frame first.", "err")
                return
            cv_ = self.curve_list[self.curve_active]
            rng = cv_.get("anim_range")
            if rng is None:
                self.log(self.curve_log_txt,
                    "Click Animate On first to set a starting frame.", "err")
                return
            lo = rng[0]
            if cur_idx < lo:
                self.log(self.curve_log_txt,
                    f"Off-keyframe must be at or after the on-keyframe "
                    f"(frame {lo+1}).", "err")
                return
            cv_["anim_range"] = (lo, cur_idx)
            _curve_update_anim_lbl(); _curve_rebuild_tabs()
            self._curve_recompute_wipe(); self._curve_redraw()
            self.log(self.curve_log_txt,
                f"{cv_['name']}: off-keyframe set at frame {cur_idx+1}", "ok")

        # ── Detection + Correction mini-cards ──────────────────────────
        tk.Frame(lf, bg=BD, height=1).pack(fill="x", padx=16, pady=(10,4))
        _params_row = tk.Frame(lf, bg=BG)
        _params_row.pack(fill="x", padx=16, pady=(0,4))
        _params_row.columnconfigure(0, weight=1, uniform="crow")
        _params_row.columnconfigure(1, weight=1, uniform="crow")
        _params_row.rowconfigure(0, weight=1)

        def _mini_card(col, title, tip=None):
            f = tk.Frame(_params_row, bg=S,
                         highlightthickness=1, highlightbackground=BD)
            f.grid(row=0, column=col, sticky="nsew",
                   padx=(0,3) if col==0 else (3,0), pady=0)
            hdr2 = tk.Frame(f, bg=S); hdr2.pack(fill="x", padx=6, pady=(4,2))
            tk.Label(hdr2, text=title, font=FSM, bg=S, fg="#666666").pack(side="left")
            if tip:
                _i = tk.Label(hdr2, text="ⓘ", font=FSM, bg=S, fg="#555555", cursor="hand2")
                _i.pack(side="left", padx=(4,0))
                self._tooltip(tip)(_i)
            inner = tk.Frame(f, bg=S); inner.pack(fill="x", padx=4, pady=(0,6))
            return inner

        _dc = _mini_card(0, "Detection",
            tip=(
                "For each point along your painted curve, the software\n"
                "searches perpendicular to the curve for the strongest\n"
                "edge nearby, biased toward continuity with the previous\n"
                "frame's result so it doesn't jump to unrelated clutter.\n\n"
                "Search Distance — how far perpendicular to search.\n"
                "Widen if the wobble is larger than the default catches.\n\n"
                "Smooth Along Curve — averages the detected position\n"
                "with nearby points along the curve's own length, to\n"
                "calm point-to-point jitter in the detection itself."))
        _cc = _mini_card(1, "Correction",
            tip=(
                "Feather — distance from the curve over which the\n"
                "correction fades back to untouched.\n\n"
                "Max Correction — per-point clamp, so one bad frame\n"
                "can't push a huge warp through.\n\n"
                "Straighten — blends between the original (0%) and the\n"
                "edge fully snapped onto your painted curve (100%)."))

        def _cs(parent, label, var, from_, to, res, fmt, tip=""):
            outer = tk.Frame(parent, bg=S); outer.pack(fill="x", pady=1)
            row = tk.Frame(outer, bg=S); row.pack(fill="x")
            tk.Label(row, text=label, font=FSM, bg=S, fg=G,
                     width=12, anchor="w").pack(side="left")
            if tip:
                _cs_info = tk.Label(row, text="ⓘ", font=FSM, bg=S,
                    fg="#555555", cursor="hand2")
                _cs_info.pack(side="left", padx=(2,0))
                _info_popup(tip)(_cs_info)
            val_lbl = tk.Label(row, text=fmt(var.get()), font=FM,
                               bg=S, fg=W, width=5, anchor="e")
            val_lbl.pack(side="right")
            def _upd(*_): val_lbl.configure(text=fmt(var.get()))
            var.trace_add("write", _upd)
            tk.Scale(row, variable=var, from_=from_, to=to, resolution=res,
                     orient="horizontal", bg=S, fg=W, troughcolor=BD,
                     highlightthickness=0, bd=0, showvalue=False,
                     activebackground=R).pack(side="left", fill="x", expand=True)

        self.curve_search_var     = tk.IntVar(value=15)
        self.curve_searchdir_var  = tk.IntVar(value=0)
        self.curve_smoothalong_var= tk.IntVar(value=5)
        self.curve_feather_var    = tk.IntVar(value=30)
        self.curve_maxcorr_var    = tk.IntVar(value=20)
        self.curve_strength_var   = tk.IntVar(value=100)
        self.curve_endfalloff_var = tk.IntVar(value=0)
        self.curve_fade_var       = tk.IntVar(value=3)

        _cs(_dc, "Search Dist", self.curve_search_var, 3, 100, 1, lambda v: f"{int(v)}px")
        _cs(_dc, "Smooth Along", self.curve_smoothalong_var, 1, 25, 2, lambda v: f"{int(v)}pt")

        # ── Search Bias snap-slider (auto-keyframed per frame) ──────────
        _bias_row = tk.Frame(_dc, bg=S); _bias_row.pack(fill="x", pady=(6,0))
        tk.Label(_bias_row, text="Search Bias", font=FSM, bg=S, fg=G,
            width=11, anchor="w").pack(side="left")
        _bias_info = tk.Label(_bias_row, text="ⓘ", font=FSM, bg=S,
            fg="#555555", cursor="hand2")
        _bias_info.pack(side="left", padx=(0,6))
        _info_popup(
            "Which side of the curve the search favors, instead of\n"
            "looking equally both ways. Center is symmetric, the\n"
            "default. Toward L or R shifts the whole search window\n"
            "to that side, so a decoy edge on the other side becomes\n"
            "unreachable instead of just being out-scored.\n\n"
            "Automatically keyframed: dragging this sets the value\n"
            "starting at THIS frame, interpolating to whatever you\n"
            "set the next time you touch it on a different frame --\n"
            "so it can be dialed in differently wherever a decoy\n"
            "actually shows up, frame by frame, without one fix\n"
            "disturbing frames that never needed it."
        )(_bias_info)
        self.curve_bias_var = tk.DoubleVar(value=0.0)
        _bias_lbl = tk.Label(_bias_row, text="Center", font=FM, bg=S,
            fg="#888888", width=8, anchor="e")
        _bias_lbl.pack(side="right")
        _bias_cv = tk.Canvas(_bias_row, height=38, bg=S,
            highlightthickness=1, highlightbackground=BD, cursor="hand2")
        _bias_cv.pack(side="left", fill="x", expand=True, padx=(0,4))

        def _bias_color(v):
            if v > 0.4: return "#CC4444"
            if v < -0.4: return "#4488CC"
            return "#888888"
        def _bias_label_text(v):
            if abs(v) < 0.5: return "Center"
            return f"{'R' if v > 0 else 'L'} {abs(v):.0f}%"
        def _bias_draw(*_):
            _bias_cv.delete("all")
            W2 = _bias_cv.winfo_width() or 200
            cur = self.curve_bias_var.get()
            TY = 13; L_X, R_X = 8, W2-8
            def sx(v): return int((v+100)/200.0*(R_X-L_X))+L_X
            _bias_cv.create_line(L_X,TY,R_X,TY,fill="#333333",width=2)
            zx = sx(0); cx = sx(cur)
            if cx != zx:
                _bias_cv.create_line(min(zx,cx),TY,max(zx,cx),TY,
                    fill=_bias_color(cur), width=3)
            _bias_cv.create_line(zx,TY-8,zx,TY+8,fill="#888888",width=2)
            _bias_cv.create_text(L_X,TY+11,text="L",
                font=("Helvetica",9,"bold"),fill="#4488CC",anchor="nw")
            _bias_cv.create_text(R_X,TY+11,text="R",
                font=("Helvetica",9,"bold"),fill="#CC4444",anchor="ne")
            _bias_cv.create_oval(cx-6,TY-7,cx+6,TY+7,
                fill=_bias_color(cur), outline="#888888", width=1)
        def _bias_keyframe_current(v):
            cv_ = self.curve_list[self.curve_active]
            cur_idx = (self.curve_frame_cb.current()
                       if hasattr(self,"curve_frame_cb") else -1)
            if cur_idx is None or cur_idx < 0:
                self.log(self.curve_log_txt,
                    "Load a sequence and step to a frame first.", "err")
                return
            if cv_.get("search_bias_keyframes") is None:
                cv_["search_bias_keyframes"] = {}
            cv_["search_bias_keyframes"][cur_idx] = v
            if hasattr(self, "_curve_rebuild_tabs_fn"):
                self._curve_rebuild_tabs_fn()
        def _bias_set_from_event(ex):
            W2 = _bias_cv.winfo_width() or 200
            L_X, R_X = 8, W2-8
            t = max(0.0, min(1.0, (ex-L_X)/max(1,R_X-L_X)))
            v = round((t*200.0-100.0)/2.0)*2.0
            v = max(-100.0, min(100.0, v))
            self.curve_bias_var.set(v)
            _bias_lbl.configure(text=_bias_label_text(v),
                fg=_bias_color(v) if abs(v)>=0.5 else "#888888")
            _bias_draw()
            _bias_keyframe_current(v)
            _curve_search_overlay_show()
            if self.curve_mode in ("wipe","diff"):
                self._curve_recompute_wipe(); self._curve_redraw()
            else:
                self._curve_preview(silent=True)
        _bias_cv.bind("<Button-1>",  lambda e: _bias_set_from_event(e.x))
        _bias_cv.bind("<B1-Motion>", lambda e: _bias_set_from_event(e.x))
        _bias_cv.bind("<Configure>", _bias_draw)

        # ── Search Direction dial strip (bias-style widget) ─────────
        # Rotates the per-point search axis away from the default
        # perpendicular. 0° = perpendicular (classic); 90°/270° = along
        # the curve's length; anything between for diagonal drift.
        # Same visual language as Search Bias: click/drag the strip,
        # and the viewport shows the actual (rotated) search band.
        _dir_row = tk.Frame(_dc, bg=S); _dir_row.pack(fill="x", pady=(6,0))
        tk.Label(_dir_row, text="Search Dir", font=FSM, bg=S, fg=G,
            width=11, anchor="w").pack(side="left")
        _dir_info = tk.Label(_dir_row, text="ⓘ", font=FSM, bg=S,
            fg="#555555", cursor="hand2")
        _dir_info.pack(side="left", padx=(0,6))
        _info_popup(
            "Rotation of the search axis relative to the curve's\n"
            "perpendicular. 0° searches straight across the edge\n"
            "(default). 90° or 270° searches along the curve's own\n"
            "length — for edges that slide lengthwise. The full 360°\n"
            "covers every diagonal in between. Search Bias keeps\n"
            "working, shifting the window along whichever axis is\n"
            "set here. The blue band in the viewport shows the\n"
            "actual search area while adjusting."
        )(_dir_info)
        _dir_lbl = tk.Label(_dir_row, text="Perp", font=FM, bg=S,
            fg="#888888", width=8, anchor="e")
        _dir_lbl.pack(side="right")
        _dir_cv = tk.Canvas(_dir_row, width=64, height=64, bg=S,
            highlightthickness=1, highlightbackground=BD, cursor="hand2")
        _dir_cv.pack(side="left", padx=(0,4))

        def _dir_label_text(v):
            v = int(v) % 360
            if v == 0: return "Perp"
            if v in (90, 270): return f"Along {v}\u00b0"
            return f"{v}\u00b0"
        def _dir_color(v):
            return "#888888" if int(v) % 360 == 0 else "#CC8833"
        def _dir_draw(*_):
            import math as _dm
            _dir_cv.delete("all")
            cur = self.curve_searchdir_var.get() % 360
            CX, CY, R = 32, 32, 24
            # dial face + degree ticks
            _dir_cv.create_oval(CX-R, CY-R, CX+R, CY+R,
                outline="#333333", width=2)
            for tv in range(0, 360, 30):
                a = _dm.radians(tv)
                dx, dy = _dm.sin(a), -_dm.cos(a)
                major = tv % 90 == 0
                r0 = R - (6 if major else 3)
                _dir_cv.create_line(CX+dx*r0, CY+dy*r0,
                    CX+dx*R, CY+dy*R,
                    fill="#666666" if major else "#3A3A3A",
                    width=2 if major else 1)
            _dir_cv.create_text(CX, CY-R-0, text="0",
                font=("Helvetica",7), fill="#666666", anchor="s")
            # short horizontal reference line = the curve itself, so
            # the needle reads as "search axis relative to the curve"
            _dir_cv.create_line(CX-R+7, CY, CX+R-7, CY,
                fill="#555555", width=2)
            # needle (double-ended: the search goes both ways along
            # the axis; bias picks the side)
            a = _dm.radians(cur)
            dx, dy = _dm.sin(a), -_dm.cos(a)
            col = _dir_color(cur)
            _dir_cv.create_line(CX-dx*(R-8), CY-dy*(R-8),
                CX+dx*(R-8), CY+dy*(R-8),
                fill=col, width=2, arrow="last", arrowshape=(6,7,2))
            _dir_cv.create_oval(CX-3, CY-3, CX+3, CY+3,
                fill=col, outline="")
        def _dir_set_from_event(ex, ey):
            import math as _dm
            CX, CY = 32, 32
            dx, dy = ex - CX, ey - CY
            if dx*dx + dy*dy < 9: return
            v = int(round(_dm.degrees(_dm.atan2(dx, -dy)) / 5.0) * 5) % 360
            self.curve_searchdir_var.set(v)
            self.curve_list[self.curve_active]["search_dir"] = v
            _dir_lbl.configure(text=_dir_label_text(v), fg=_dir_color(v))
            _dir_draw()
            _curve_search_overlay_show()
            if self.curve_mode in ("wipe","diff"):
                self._curve_recompute_wipe(); self._curve_redraw()
            else:
                self._curve_preview(silent=True)
        _dir_cv.bind("<Button-1>",  lambda e: _dir_set_from_event(e.x, e.y))
        _dir_cv.bind("<B1-Motion>", lambda e: _dir_set_from_event(e.x, e.y))
        _dir_cv.bind("<Configure>", _dir_draw)
        self._curve_dir_sync_ui_fn = lambda: (
            _dir_lbl.configure(
                text=_dir_label_text(self.curve_searchdir_var.get()),
                fg=_dir_color(self.curve_searchdir_var.get())),
            _dir_draw())

        def _curve_bias_sync_ui():
            """Update the slider's display to match the CURRENT
            frame's interpolated/held bias -- called on frame change,
            never keyframes (it's a read, not an edit)."""
            cv_ = self.curve_list[self.curve_active]
            cur_idx = (self.curve_frame_cb.current()
                       if hasattr(self,"curve_frame_cb") else -1)
            v = self._curve_bias_at(cv_, cur_idx if cur_idx is not None and cur_idx>=0 else None)
            self.curve_bias_var.set(v)
            _bias_lbl.configure(text=_bias_label_text(v),
                fg=_bias_color(v) if abs(v)>=0.5 else "#888888")
            _bias_draw()
        self._curve_bias_sync_ui_fn = _curve_bias_sync_ui

        _cs(_cc, "Feather", self.curve_feather_var, 4, 100, 1, lambda v: f"{int(v)}px")
        _cs(_cc, "Max Corr", self.curve_maxcorr_var, 1, 80, 1, lambda v: f"{int(v)}px",
            tip="Caps how far any single point can actually be pulled, "
                "regardless of how far the search detects it — a safety "
                "limit so a bad detection can't warp the image wildly. "
                "If the detected edge is farther than this, a white "
                "dashed line shows where the correction will actually "
                "land instead; raise this if you want the full "
                "distance pulled in.")
        _cs(_cc, "Strength", self.curve_strength_var, 0, 100, 5, lambda v: f"{int(v)}%")
        _cs(_cc, "End Falloff", self.curve_endfalloff_var, 0, 150, 1, lambda v: f"{int(v)}px",
            tip="Ramps the correction to zero at each tip of the curve, "
                "over this distance — 0 keeps a hard cutoff right at "
                "the end, which can visibly warp something else that "
                "crosses there.")
        _cs(_cc, "Fade", self.curve_fade_var, 0, 15, 1, lambda v: f"{int(v)}fr",
            tip="Animate On/Off switch the correction fully on or off "
                "at a single frame by default, which can pop visibly "
                "if there's much offset to begin with. Fade ramps it "
                "in/out linearly over this many frames either side of "
                "the on/off keyframe instead — 0 keeps the instant "
                "on/off cut. Shown on the timeline as the bright red "
                "fading into dark red around each keyframe.")

        _curve_after_id = [None]
        def _curve_debounced(*_):
            if getattr(self, "_curve_loading", False): return
            _curve_save_current()
            if _curve_after_id[0]:
                try: self.after_cancel(_curve_after_id[0])
                except: pass
            def _do():
                if self.curve_mode in ("wipe","diff"):
                    self._curve_recompute_wipe(); self._curve_redraw()
                else:
                    self._curve_preview(silent=True)
                # Same story as area: parameter change → active
                # playback loop is now stale, restart it against the
                # new parameters (see _pp_invalidate).
                self._pp_invalidate("curve")
            _curve_after_id[0] = self.after(150, _do)
        for _v in (self.curve_search_var, self.curve_smoothalong_var,
                   self.curve_feather_var, self.curve_maxcorr_var,
                   self.curve_strength_var, self.curve_endfalloff_var,
                   self.curve_fade_var):
            _v.trace_add("write", _curve_debounced)

        # Show the search band briefly while the user is actively
        # adjusting it -- without this, the slider is a black box:
        # you can't see how far it's actually searching on either
        # side of the curve, so its effect feels arbitrary.
        self._curve_search_overlay_id = [None]
        def _curve_search_overlay_show(*_):
            self._curve_show_search_band = True
            self._curve_redraw()
            if self._curve_search_overlay_id[0]:
                try: self.after_cancel(self._curve_search_overlay_id[0])
                except: pass
            def _hide():
                self._curve_show_search_band = False
                self._curve_redraw()
            self._curve_search_overlay_id[0] = self.after(1400, _hide)
        self.curve_search_var.trace_add("write", _curve_search_overlay_show)

        # ── Output options ────────────────────────────────────────────
        c3 = self._card(lf, "Output")
        _out_row = tk.Frame(c3, bg=S); _out_row.pack(fill="x")
        tk.Label(_out_row, text="Format", font=FSM, bg=S, fg=G,
                 width=8, anchor="w").pack(side="left")
        tk.Label(_out_row, text="matches source  (EXR stays EXR, PNG stays PNG)",
                 font=FSM, bg=S, fg="#555555").pack(side="left")
        _mov_row = tk.Frame(c3, bg=S); _mov_row.pack(fill="x", pady=(4,0))
        self.curve_out_mov_var = tk.BooleanVar(value=False)
        tk.Checkbutton(_mov_row, text="Out .MOV", variable=self.curve_out_mov_var,
            bg=S, fg=W, selectcolor="#222222",
            activebackground=S, activeforeground=W,
            font=FSM, bd=0).pack(side="left")
        self.curve_range_only_var = tk.BooleanVar(value=False)
        tk.Checkbutton(_mov_row, text="Render range-slider only",
            variable=self.curve_range_only_var,
            bg=S, fg=W, selectcolor="#222222",
            activebackground=S, activeforeground=W,
            font=FSM, bd=0).pack(side="left", padx=(14,0))

