        self.curve_canvas.bind("<MouseWheel>",      self._curve_canvas_scroll)
        self.curve_canvas.bind("<Button-4>",        self._curve_canvas_scroll)
        self.curve_canvas.bind("<Button-5>",        self._curve_canvas_scroll)
        self.curve_canvas.bind("<Option-Button-1>",  self._curve_pan_start_ev)
        self.curve_canvas.bind("<Option-B1-Motion>", self._curve_pan_move)
        self.curve_canvas.bind("<Alt-Button-1>",     self._curve_pan_start_ev)
